window.QUAL_POOL_G = [{"id":"g8-01","exam":"g","unit":"g-u8","keyword":"平均","type":"choice","syllabus_ref":"8.1","stem":"次のデータの平均はどれか。2, 4, 6, 8, 15","choices":["6","7","35","8.75"],"answer":1,"explanation":"合計は 2+4+6+8+15=35。平均は 35÷5=7。なお、このデータの中央値は6であり、平均とは異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-02","exam":"g","unit":"g-u8","keyword":"中央値","type":"choice","syllabus_ref":"8.1","stem":"次のデータの中央値はどれか。3, 7, 8, 10, 12, 20","choices":["8","10","9","12"],"answer":2,"explanation":"データは6個（偶数）なので、中央値は小さい順に3番目と4番目の値の平均である。(8+10)÷2=9。なお、このデータの平均は10である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-03","exam":"g","unit":"g-u8","keyword":"分散","type":"choice","syllabus_ref":"8.1","stem":"次のデータの分散はどれか（分散は、平均からの偏差の二乗の平均とする）。2, 4, 4, 4, 5, 5, 7, 9","choices":["2","5","32","4"],"answer":3,"explanation":"平均は (2+4+4+4+5+5+7+9)÷8=5。偏差の二乗は 9, 1, 1, 1, 0, 0, 4, 16 で、合計は32。分散は 32÷8=4（なお標準偏差は2）。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-04","exam":"g","unit":"g-u8","keyword":"標準偏差","type":"choice","syllabus_ref":"8.1","stem":"A組とB組のテストの平均点はともに60点で、標準偏差はA組が3点、B組が12点だった。この結果の説明として、正しいものはどれか。","choices":["A組の方が点数のばらつきが大きい","B組の方が点数のばらつきが大きい","B組の方が平均的に出来がよい","標準偏差だけでは、ばらつきの大小は比べられない"],"answer":1,"explanation":"標準偏差は、平均のまわりへのデータの散らばり（ばらつき）の大きさを表す。平均が同じなら、標準偏差が大きいB組の方が点数の散らばりが大きい。出来の良し悪しを比べるのは平均の役割であり、この条件では両組とも同じである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-05","exam":"g","unit":"g-u8","keyword":"期待値","type":"choice","syllabus_ref":"8.1","stem":"確率変数Xが、確率0.5で0、確率0.3で1、確率0.2で2の値をとるとき、Xの期待値はどれか。","choices":["0.7","1.0","0.5","0"],"answer":0,"explanation":"期待値は、とる値とその確率の積の合計である。0×0.5+1×0.3+2×0.2=0+0.3+0.4=0.7。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-06","exam":"g","unit":"g-u8","keyword":"条件付き確率","type":"choice","syllabus_ref":"8.1","stem":"ある病気にかかっている人の割合が1%の集団がある。この病気の検査は、病気の人を99%の確率で陽性と判定し、病気でない人を5%の確率で誤って陽性と判定する。無作為に選んだ1人が陽性と判定されたとき、その人が実際に病気である確率はおよそどれか。","choices":["約99%","約50%","約5%","約17%"],"answer":3,"explanation":"条件付き確率（ベイズの定理）で計算する。病気で陽性になる割合は 0.01×0.99=0.0099。病気でなく陽性になる割合は 0.99×0.05=0.0495。求める確率は 0.0099÷(0.0099+0.0495)=0.0099÷0.0594≈0.167、すなわち約17%。検査の感度が高くても、病気の人の割合自体が小さいと、陽性でも実際に病気である確率はそれほど大きくならない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-07","exam":"g","unit":"g-u8","keyword":"二項分布","type":"choice","syllabus_ref":"8.1","stem":"公平なコインを3回投げて、表が出る回数は二項分布に従う。表がちょうど2回出る確率はどれか。","choices":["1/8","3/8","1/4","1/2"],"answer":1,"explanation":"表がちょうど2回出る並び方は C(3,2)=3通り。1つの並び方が起こる確率は (1/2)^3=1/8 なので、求める確率は 3×(1/8)=3/8。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-08","exam":"g","unit":"g-u8","keyword":"相関係数","type":"choice","syllabus_ref":"8.1","stem":"変数XとYの共分散が6、Xの標準偏差が2、Yの標準偏差が6のとき、XとYの相関係数はどれか。","choices":["3.0","0.25","0.5","0.05"],"answer":2,"explanation":"相関係数は、共分散を2変数の標準偏差の積で割ったものである。6÷(2×6)=6÷12=0.5。相関係数は −1 から 1 の範囲の値をとる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-09","exam":"g","unit":"g-u8","keyword":"ユークリッド距離","type":"choice","syllabus_ref":"8.1","stem":"座標平面上の2点 (1, 2) と (4, 6) の間のユークリッド距離はどれか。","choices":["5","7","25","3"],"answer":0,"explanation":"ユークリッド距離は √((4−1)²+(6−2)²)=√(9+16)=√25=5。なお、座標差の絶対値の合計 3+4=7 はマンハッタン距離である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-10","exam":"g","unit":"g-u8","keyword":"コサイン類似度","type":"choice","syllabus_ref":"8.1","stem":"ベクトル a = (1, 0) と b = (1, 1) のコサイン類似度はおよそどれか。","choices":["0.5","1","0","約0.71"],"answer":3,"explanation":"コサイン類似度は、内積をベクトルの大きさの積で割ったものである。内積は 1×1+0×1=1。|a|=1、|b|=√2 なので、1÷√2≈0.71。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-11","exam":"g","unit":"g-u8","keyword":"正規分布","type":"choice","syllabus_ref":"8.1","stem":"あるテストの得点が、平均50点・標準偏差10点の正規分布に従うとする。無作為に選んだ1人の得点が70点以上である確率はおよそどれか。","choices":["約16%","約5%","約2.5%","約0.1%"],"answer":2,"explanation":"70点は、平均50点から標準偏差10点の2つ分（+2σ）上にあたる。正規分布では、平均+2σ以上の範囲に全体の約2.3%が入るので、およそ2.5%。なお、+1σ以上は約16%である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g8-12","exam":"g","unit":"g-u8","keyword":"帰無仮説","type":"choice","syllabus_ref":"8.1","stem":"仮説検定において、有意水準5%で帰無仮説が棄却された。この結果の解釈として、正しいものはどれか。","choices":["帰無仮説が正しいと仮定したときに、観測されたデータ以上に極端な結果が得られる確率が5%以下だった、ということ","対立仮説が正しいことが証明された、ということ","帰無仮説が正しい確率が5%以下である、ということ","同じ実験を繰り返せば、95%の確率で同じ結論になる、ということ"],"answer":0,"explanation":"棄却とは、帰無仮説が正しいと仮定したときに、観測されたデータ以上に極端な結果が得られる確率（p値）が有意水準以下だった、という意味である。対立仮説が「証明」されたわけでも、帰無仮説が正しい確率が5%以下なわけでもない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目8「AIに必要な数理・統計知識」中項目37「AIに必要な数理・統計知識」"},{"id":"g4-01","exam":"g","unit":"g-u4","keyword":"単純パーセプトロン","type":"choice","syllabus_ref":"4.1","stem":"単純パーセプトロンの説明として、正しいものはどれか。","choices":["複数の入力に重みを付けた合計と閾値を比べ、0か1のいずれかを出力する、ニューラルネットワークの基本的な単位である","隠れ層を複数持つことで、直線では分けられないデータも分類できる","入力された値をそのまま出力するだけの、学習を行わない素子である","画像の特徴を抽出するために、畳み込み演算を行う素子である"],"answer":0,"explanation":"単純パーセプトロンは、入力に重みを掛けた総和が閾値を超えるかどうかで0か1を決める、ニューラルネットワークの基本単位である。隠れ層は持たず、直線（超平面）で分けられる問題しか解けない。重みは学習によって更新される。畳み込み演算を行うのは畳み込み層である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-02","exam":"g","unit":"g-u4","keyword":"単純パーセプトロン","type":"choice","syllabus_ref":"4.1","stem":"単純パーセプトロンが、入力 x1=1、x2=1、重み w1=0.6、w2=0.3、バイアス b=−0.5 を受け取ったとする。重み付き和にバイアスを加えた値が0より大きいとき1、そうでないとき0を出力するとき、出力はどれか。","choices":["0","0.4","1","0.9"],"answer":2,"explanation":"重み付き和にバイアスを加えると 0.6×1+0.3×1+(−0.5)=0.4 となる。0.4は0より大きいので、出力は1である。なお0.9はバイアスを加える前の重み付き和、0.4は0/1に変換する前の値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-03","exam":"g","unit":"g-u4","keyword":"多層パーセプトロン","type":"choice","syllabus_ref":"4.1","stem":"多層パーセプトロンの説明として、正しいものはどれか。","choices":["入力層と出力層だけで構成され、隠れ層を持たないニューラルネットワークである","入力層と出力層の間に1つ以上の隠れ層を持ち、層の間が全結合したニューラルネットワークである","時系列データを扱うため、層の出力が同じ層へ戻る再帰構造を持つニューラルネットワークである","畳み込み層とプーリング層を組み合わせた、画像認識専用のニューラルネットワークである"],"answer":1,"explanation":"多層パーセプトロンは、入力層と出力層の間に隠れ層を持ち、隣り合う層の間が全結合したニューラルネットワークである。再帰構造を持つのは回帰型ニューラルネットワーク（RNN）、畳み込み層を組み合わせるのは畳み込みニューラルネットワーク（CNN）である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-04","exam":"g","unit":"g-u4","keyword":"多層パーセプトロン","type":"choice","syllabus_ref":"4.1","stem":"入力層4ユニット、隠れ層3ユニット、出力層2ユニットの多層パーセプトロンがある。隣り合う層の間は全結合で、隠れ層と出力層の各ユニットにはバイアスがあるとする。学習対象のパラメータ（重みとバイアス）の総数はどれか。","choices":["18","20","28","23"],"answer":3,"explanation":"重みは、入力層から隠れ層へ 4×3=12 本、隠れ層から出力層へ 3×2=6 本で、合計18個。バイアスは隠れ層に3個、出力層に2個で、合計5個。パラメータの総数は 18+5=23 個である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-05","exam":"g","unit":"g-u4","keyword":"隠れ層・入力層・出力層","type":"choice","syllabus_ref":"4.1","stem":"ニューラルネットワークの各層の役割として、正しいものはどれか。","choices":["出力層は、外部からのデータを受け取って最初の変換を行う層である","入力層は、重みによる計算を行って特徴を抽出する層である","隠れ層は、入力層と出力層の間にあって、入力の特徴を段階的に変換・抽出する層である","隠れ層は、ネットワークの利用者が中身を直接読み取るための層である"],"answer":2,"explanation":"入力層は外部からのデータを受け取る層で、通常は重みによる計算を行わない。隠れ層は入力層と出力層の間にあり、入力の特徴を段階的に変換・抽出する。最終的な結果を出すのは出力層である。隠れ層の中身は利用者が直接読み取るものではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-06","exam":"g","unit":"g-u4","keyword":"隠れ層・入力層・出力層","type":"choice","syllabus_ref":"4.1","stem":"隠れ層の層数やユニット数を増やしてネットワークを大きくすることについて、正しいものはどれか。","choices":["より複雑な特徴を表現できるようになる一方、学習に必要なデータ量や計算量が増え、過学習のリスクも高まる","表現できる特徴は複雑になるが、学習に必要なデータ量や計算量は変わらない","層を増やすほど、少ないデータでも必ず精度が上がる","隠れ層を増やしても、表現できる特徴の複雑さには影響しない"],"answer":0,"explanation":"ネットワークを大きくすると表現力は高まるが、その分だけ学習に必要なデータ量と計算量が増え、訓練データに過剰に適合する過学習のリスクも高まる。データが少なければ、大きなネットワークでも精度が上がるとは限らない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-07","exam":"g","unit":"g-u4","keyword":"CPU","type":"choice","syllabus_ref":"4.1","stem":"CPUの特徴として、正しいものはどれか。","choices":["数千個の単純な演算器を持ち、同じ演算を大量のデータへ並列に適用することが得意である","行列演算に特化した専用回路だけで構成され、汎用的な処理は行えない","機械学習専用に設計されたプロセッサで、OSの実行には使えない","少数の高性能な演算コアを持ち、複雑な制御や逐次処理を含む汎用的な処理が得意である"],"answer":3,"explanation":"CPUは、少数の高性能な演算コアで、複雑な制御や逐次処理を含む汎用的な処理を担う。多数の演算器による並列処理が得意なのはGPU、行列演算に特化した機械学習専用のプロセッサはTPUである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-08","exam":"g","unit":"g-u4","keyword":"GPU","type":"choice","syllabus_ref":"4.1","stem":"GPUがディープラーニングの学習に適している理由として、正しいものはどれか。","choices":["クロック周波数がCPUより大幅に高いため、逐次処理が速いから","多数の演算ユニットを持ち、行列演算のような単純な演算の大量の並列実行が得意だから","メモリを持たないため、データの読み書きが速いから","学習データを自動で生成する機能を持っているから"],"answer":1,"explanation":"ディープラーニングの学習では、行列演算を中心とする単純な演算を大量に行う。GPUは多数の演算ユニットでこれらを並列に実行できるため適している。逐次処理の速さはCPUの強みであり、GPUにもメモリは搭載されている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-09","exam":"g","unit":"g-u4","keyword":"TPU","type":"choice","syllabus_ref":"4.1","stem":"TPUの説明として、正しいものはどれか。","choices":["学習済みモデルの保管に使う、大容量のストレージデバイスである","NVIDIAが開発した、画像表示のためのグラフィックス専用プロセッサである","Googleが開発した、テンソル（行列）演算を中心とする機械学習の処理に特化したプロセッサである","CPUの一種で、特に逐次処理の速度を高めたプロセッサである"],"answer":2,"explanation":"TPUは、Googleが開発した機械学習専用のプロセッサで、テンソル（行列）演算の高速な実行に特化している。画像表示のためのプロセッサはGPUであり、TPUはストレージではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-10","exam":"g","unit":"g-u4","keyword":"隠れ層・入力層・出力層","type":"choice","syllabus_ref":"4.1","stem":"ニューラルネットワークとディープラーニングの関係として、正しいものはどれか。","choices":["ディープラーニングは、ニューラルネットワークとは無関係に発展した、ルールベースの手法である","ニューラルネットワークは、ディープラーニングを構成する1つの層の名称である","ディープラーニングでは隠れ層を使わず、入力を直接出力へ変換する","ディープラーニングは、ニューラルネットワークの隠れ層を多層化し、特徴の学習を深い階層で行う手法である"],"answer":3,"explanation":"ディープラーニングは、ニューラルネットワークの隠れ層を何層にも重ね（深くし）、データの特徴を階層的に学習する手法である。ルールベースの手法ではなく、隠れ層を使うこと自体が要点である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-11","exam":"g","unit":"g-u4","keyword":"CPU・GPU・TPU","type":"choice","syllabus_ref":"4.1","stem":"CPU、GPU、TPUの使い分けとして、最も適切なものはどれか。","choices":["学習も推論も、汎用性の高いCPUだけで行うのが常に最適である","複雑な制御を含む汎用処理はCPUが担い、大量の行列演算を伴う学習には、並列処理が得意なGPUや、機械学習に特化したTPUを用いることが多い","大規模な学習にはGPUが使われるが、TPUは画像表示に使われる","TPUは汎用プロセッサなので、OSやアプリケーションの実行全般を担う"],"answer":1,"explanation":"CPUは制御を含む汎用処理、GPUは大量の並列演算、TPUは機械学習の行列演算に特化、という役割の違いがある。大規模な学習では、行列演算を高速に処理できるGPUやTPUを用いることが多い。TPUは画像表示用でも汎用プロセッサでもない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-12","exam":"g","unit":"g-u4","keyword":"GPU","type":"choice","syllabus_ref":"4.1","stem":"1000行×1000列の行列同士の積を計算すると、結果の各要素は1000回の乗算の和になる。乗算の回数の合計はおよそどれか。なお、このような大量の単純な演算の並列処理が、GPUの得意分野である。","choices":["約10億回（10の9乗）","約100万回（10の6乗）","約1000回","約200万回"],"answer":0,"explanation":"結果の行列は 1000×1000=100万個の要素を持ち、各要素の計算に1000回の乗算が要る。したがって乗算の合計は 100万×1000=10億回（10の9乗）におよぶ。この規模の単純演算を並列にさばけることが、GPUが学習に適する理由である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目11「ニューラルネットワークとディープラーニング」"},{"id":"g4-13","exam":"g","unit":"g-u4","keyword":"シグモイド関数","type":"choice","syllabus_ref":"4.2","stem":"シグモイド関数の説明として、正しいものはどれか。","choices":["任意の実数を0から1の間の値に変換する、S字型の関数である","入力が負のとき0、正のとき入力そのものを出力する関数である","任意の実数を−1から1の間の値に変換する関数である","複数の出力の合計が1になるよう、正規化する関数である"],"answer":0,"explanation":"シグモイド関数は、任意の実数を0から1の間の値へなめらか（S字型）に変換する関数で、二値分類の出力などで確率のように解釈できる。正の入力をそのまま出すのはReLU関数、−1から1へ変換するのはtanh関数、合計が1になるよう正規化するのはソフトマックス関数である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-14","exam":"g","unit":"g-u4","keyword":"シグモイド関数","type":"choice","syllabus_ref":"4.2","stem":"シグモイド関数 σ(x)=1/(1+e^(−x)) に x=2 を入力したときの出力はおよそどれか。なお e^(−2)≒0.14 とする。","choices":["約0.14","約0.50","約0.88","約2.00"],"answer":2,"explanation":"σ(2)=1/(1+e^(−2))≒1/(1+0.14)≒0.88 である。シグモイド関数の出力は0から1の間に収まるため、2.00にはならない。入力が0のとき出力は0.50になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-15","exam":"g","unit":"g-u4","keyword":"tanh 関数","type":"choice","syllabus_ref":"4.2","stem":"tanh関数（双曲線正接関数）の説明として、正しいものはどれか。","choices":["任意の実数を0から1の間の値に変換し、出力の平均は0.5付近になる","任意の実数を−1から1の間の値に変換し、入力0のとき出力も0になる","入力が負のとき常に0を出力する","出力は確率分布として解釈され、合計は常に1になる"],"answer":1,"explanation":"tanh関数は任意の実数を−1から1の間の値に変換し、入力0のとき出力は0になる。出力が0を中心に分布するため、0から1の間に収まるシグモイド関数より学習が進みやすい場面がある。負の入力で0を出すのはReLU関数、合計が1になるのはソフトマックス関数である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-16","exam":"g","unit":"g-u4","keyword":"tanh 関数","type":"choice","syllabus_ref":"4.2","stem":"tanh関数と勾配消失問題の関係として、正しいものはどれか。","choices":["tanh関数の微分は常に1なので、勾配消失問題とは無関係である","tanh関数は負の値を出力しないため、勾配が消失することはない","tanh関数を使えば、層をいくら深くしても勾配消失問題は起きない","tanh関数の微分は入力0の付近で最大（1）になるが、入力の絶対値が大きい所では0に近づくため、深いネットワークでは勾配消失問題が起こり得る"],"answer":3,"explanation":"tanh関数の微分は、入力が0の付近では最大で1になるが、入力の絶対値が大きくなると0に近づく（飽和する）。深いネットワークでこの小さな微分が何層にもわたって掛け合わされると、勾配がほぼ0になり、勾配消失問題が起こり得る。シグモイド関数でも同じ仕組みで勾配消失が起きる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-17","exam":"g","unit":"g-u4","keyword":"ReLU 関数","type":"choice","syllabus_ref":"4.2","stem":"ReLU関数の説明として、正しいものはどれか。","choices":["入力を0から1の間の値に変換する、S字型の関数である","入力の絶対値を出力する関数である","入力が負のとき0、正のとき入力そのものを出力する関数である","入力を−1から1の間の値に変換する関数である"],"answer":2,"explanation":"ReLU関数は f(x)=max(0, x) と定義され、負の入力では0、正の入力では入力そのものを出力する。正の範囲では微分が1で一定のため、シグモイド関数などに比べて勾配消失問題が起きにくく、深いネットワークの隠れ層で広く使われる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-18","exam":"g","unit":"g-u4","keyword":"ReLU 関数","type":"choice","syllabus_ref":"4.2","stem":"ReLU関数に、入力として −3、0、2.5 をそれぞれ与えたときの出力の組み合わせとして、正しいものはどれか。","choices":["0、0、2.5","−3、0、2.5","0、0、0","3、0、2.5"],"answer":0,"explanation":"ReLU関数は f(x)=max(0, x) であるため、負の入力 −3 に対しては0、入力0に対しては0、正の入力2.5に対しては2.5そのものを出力する。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-19","exam":"g","unit":"g-u4","keyword":"ReLU 関数","type":"choice","syllabus_ref":"4.2","stem":"ニューラルネットワークに活性化関数が必要とされる理由として、最も適切なものはどれか。","choices":["活性化関数がなければ計算量が増えすぎるため","活性化関数が非線形な変換を担うため。活性化関数が線形だけだと、層を重ねても全体は1つの線形変換と等しくなり、複雑な関係を表現できない","活性化関数が出力の合計を常に1に保つため","活性化関数が学習データの量を自動で増やすため"],"answer":1,"explanation":"活性化関数の役割は、層の出力に非線形な変換を加えることにある。もし全ての層が線形変換だけなら、何層重ねても全体は1つの線形変換にまとめられてしまい、直線では表せない複雑な関係を学習できない。ReLU関数のような非線形の活性化関数を挟むことで、深いネットワークの表現力が生まれる。出力の合計を1にするのはソフトマックス関数の働きである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-20","exam":"g","unit":"g-u4","keyword":"Leaky ReLU 関数","type":"choice","syllabus_ref":"4.2","stem":"Leaky ReLU関数の説明として、正しいものはどれか。","choices":["ReLU関数の正の範囲に、小さな傾きを持たせた関数である","出力の合計が1になるよう正規化する関数である","入力が負のとき完全に0になるため、ReLU関数より勾配が流れやすい","入力が負の範囲でも小さな傾き（例えば0.01）を持たせることで、負の入力を受けたユニットが学習されなくなる問題（死んだReLU）を避けるための関数である"],"answer":3,"explanation":"Leaky ReLU関数は、ReLU関数の負の範囲に小さな傾き（0.01など）を持たせた関数である。ReLU関数では、入力が負になるユニットは出力も微分も0になり、学習が進まなくなることがある（死んだReLU）。負の範囲にも傾きを持たせることで、この状態でも勾配が流れ、学習が続けられる。傾きを持たせるのは負の範囲であり、正の範囲はReLU関数と同じ傾き1である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-21","exam":"g","unit":"g-u4","keyword":"Leaky ReLU 関数","type":"choice","syllabus_ref":"4.2","stem":"負の範囲の傾きを0.01とするLeaky ReLU関数に、入力として −2 と 3 を与えたときの出力は、それぞれどれか。","choices":["0 と 3","−0.02 と 3","−2 と 3","−0.02 と 0.03"],"answer":1,"explanation":"Leaky ReLU関数では、正の入力はそのまま出力されるため、入力3に対しては3が出力される。負の入力に対しては傾き0.01が掛かるため、入力 −2 に対しては −2×0.01=−0.02 が出力される。完全に0になるのは通常のReLU関数である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-22","exam":"g","unit":"g-u4","keyword":"ソフトマックス関数","type":"choice","syllabus_ref":"4.2","stem":"ソフトマックス関数の説明として、正しいものはどれか。","choices":["入力が負のとき0を出力し、正のとき入力そのものを出力する関数である","入力を−1から1の間の値に変換する関数である","多クラス分類の出力層で使われ、各クラスの出力が0から1の間になり、合計が1になるため、確率として解釈できる関数である","二値分類の出力層専用で、出力は常に1つだけである"],"answer":2,"explanation":"ソフトマックス関数は、各クラスのスコアを、合計が1になる0から1の間の値に変換するため、各出力を「そのクラスである確率」として解釈できる。多クラス分類の出力層で用いられる。二値分類ではシグモイド関数が使われることも多い。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-23","exam":"g","unit":"g-u4","keyword":"ソフトマックス関数","type":"choice","syllabus_ref":"4.2","stem":"3クラス分類の出力層で、各クラスへのスコアが 1、2、3 であった。ソフトマックス関数を適用したとき、スコア3のクラスに対する出力はおよそどれか。なお e^1≒2.72、e^2≒7.39、e^3≒20.09 とする。","choices":["約0.09","約0.24","約0.33","約0.67"],"answer":3,"explanation":"ソフトマックス関数は、各スコアの指数を取って合計で割る。指数の合計は 2.72+7.39+20.09=30.20 で、スコア3のクラスの出力は 20.09÷30.20≒0.67 である。なお約0.09はスコア1、約0.24はスコア2のクラスの出力に当たる。3つの出力の合計は1になる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-24","exam":"g","unit":"g-u4","keyword":"勾配消失問題","type":"choice","syllabus_ref":"4.2","stem":"シグモイド関数の微分は、最大でも0.25である。シグモイド関数を使う深いネットワークで誤差逆伝播を行うと、入力側の層へ伝わる勾配は、4層分で最大でも 0.25 の4乗≒0.004 倍にまで小さくなる。このことが勾配消失問題と呼ばれる理由として、正しいものはどれか。","choices":["勾配がほぼ0になるため、入力側の層の重みがほとんど更新されず、学習が進まなくなるから","勾配が小さくなると、学習率を上げられなくなるから","勾配が0になると、推論時の計算ができなくなるから","勾配が小さいほど過学習が起きやすくなるから"],"answer":0,"explanation":"誤差逆伝播では、勾配は層をさかのぼるごとに活性化関数の微分と掛け合わされる。シグモイド関数の微分は最大0.25しかないため、層が深いほど勾配は指数的に小さくなり、入力側の層では重みがほとんど更新されなくなって学習が進まない。これが勾配消失問題である。正の範囲で微分が1のReLU関数が広く使われる背景の1つでもある。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目12「活性化関数」"},{"id":"g4-25","exam":"g","unit":"g-u4","keyword":"平均二乗誤差関数","type":"choice","syllabus_ref":"4.3","stem":"平均二乗誤差関数（MSE）の説明として、正しいものはどれか。","choices":["正解の確率分布と予測の確率分布の間のずれを、対数を使って測る関数である","モデルの予測値と正解値の差を二乗したものの平均であり、主に回帰タスクで使われる関数である","似たデータ同士の埋め込みの距離を近づけるための関数である","2つの確率分布の違いを測る、非対称な関数である"],"answer":1,"explanation":"平均二乗誤差関数（MSE）は、予測値と正解値の差（誤差）を二乗し、その平均を取ったものである。誤差が小さいほど値が小さくなり、住宅価格のような連続値を予測する回帰タスクで広く使われる。確率分布のずれを対数で測るのは交差エントロピー、埋め込みの距離を近づけるのはContrastive Loss、確率分布の違いを測る非対称な量はカルバック・ライブラー情報量である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-26","exam":"g","unit":"g-u4","keyword":"平均二乗誤差関数","type":"choice","syllabus_ref":"4.3","stem":"ある回帰モデルが、3件のデータに対して予測値 2、4、5 を出力した。正解値はそれぞれ 1、4、3 であった。このときの平均二乗誤差（MSE）はどれか。","choices":["1.00","5.00","約1.67","2.50"],"answer":2,"explanation":"誤差は、2−1=1、4−4=0、5−3=2 である。二乗すると 1、0、4 で、合計は5。これを3件で平均すると 5÷3≒1.67 が平均二乗誤差である。二乗せずに誤差の絶対値を平均した1.00は、平均絶対誤差に当たる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-27","exam":"g","unit":"g-u4","keyword":"平均二乗誤差関数","type":"choice","syllabus_ref":"4.3","stem":"平均二乗誤差関数（MSE）の性質として、正しいものはどれか。","choices":["誤差を二乗するため、大きな誤差（外れ値）を特に強く罰し、外れ値の影響を受けやすい","誤差の大きさにかかわらず、罰の大きさは一定である","分類タスクでのみ使われ、回帰タスクには使えない","誤差の符号によっては、値が負になることがある"],"answer":0,"explanation":"平均二乗誤差関数は誤差を二乗するため、誤差が2倍になると罰は4倍になる。大きく外れた予測（外れ値）が1つあると全体の値が大きく跳ね上がるため、外れ値の影響を受けやすい点が注意点である。二乗した値の平均なので、値が負になることはない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-28","exam":"g","unit":"g-u4","keyword":"交差エントロピー","type":"choice","syllabus_ref":"4.3","stem":"交差エントロピー（クロスエントロピー）の説明として、正しいものはどれか。","choices":["予測値と正解値の差の二乗の平均である","似ていないデータ同士の距離をマージン以上に広げるための関数である","アンカー・正例・負例の3つのデータの距離関係から計算される関数である","正解の分布とモデルが予測した確率分布のずれを測る関数で、分類タスクで広く使われる"],"answer":3,"explanation":"交差エントロピーは、正解の分布（通常は正解クラスが1、それ以外が0の分布）と、モデルが出力した確率分布とのずれを測る関数で、画像分類などの分類タスクの誤差関数として広く使われる。予測した確率が正解クラスで高いほど値は小さくなる。差の二乗の平均は平均二乗誤差関数、距離を広げるのはContrastive Loss、3つのデータの距離関係を使うのはTriplet Lossである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-29","exam":"g","unit":"g-u4","keyword":"交差エントロピー","type":"choice","syllabus_ref":"4.3","stem":"二値分類で、正解ラベルが1であるデータに対して、モデルが「1である確率」を0.25と予測した。この1件に対する交差エントロピーの値はどれか。なお、対数の底は2とし、log2(0.25)=−2 とする。","choices":["0.25","2","1","4"],"answer":1,"explanation":"交差エントロピーは、正解クラスについて −log（予測確率）で計算される。−log2(0.25)=2 である。予測確率が1に近いほど値は0に近づき、正解クラスへの予測確率が低い（外している）ほど値は大きくなる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-30","exam":"g","unit":"g-u4","keyword":"平均二乗誤差関数・交差エントロピー","type":"choice","syllabus_ref":"4.3","stem":"誤差関数の使い分けとして、最も適切なものはどれか。","choices":["住宅価格のような連続値の予測（回帰）には平均二乗誤差関数、画像がどのクラスに属するかの予測（分類）には交差エントロピーを用いるのが一般的である","回帰には交差エントロピー、分類には平均二乗誤差関数を用いるのが一般的である","回帰・分類のどちらにも、常に交差エントロピーを用いるべきである","誤差関数の選択はタスクによらず、どれを使っても学習の進み方は変わらない"],"answer":0,"explanation":"誤差関数は、解くタスクに合わせて選ぶ。連続値を予測する回帰では、予測値と正解値の差を直接測る平均二乗誤差関数が一般的である。クラスへの所属確率を出力する分類では、正解の分布と予測した確率分布のずれを測る交差エントロピーが一般的である。シラバスの目標にもあるとおり、適用するタスクに応じて適切な誤差関数を選択することが求められる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-31","exam":"g","unit":"g-u4","keyword":"カルバック・ライブラー情報量 (KL)","type":"choice","syllabus_ref":"4.3","stem":"カルバック・ライブラー情報量（KLダイバージェンス）の説明として、正しいものはどれか。","choices":["2つの確率分布がどれだけ異なるかを測る量で、2つの分布を入れ替えても値は変わらない（対称である）","値が負になることがあり、分布が似ているほど大きな負の値になる","予測値と正解値の差の二乗の平均である","2つの確率分布の違いを測る量で、0以上の値をとり、2つの分布が完全に一致するとき0になる。ただし、どちらの分布を基準にするかで値が変わる（非対称である）"],"answer":3,"explanation":"カルバック・ライブラー情報量（KLダイバージェンス）は、2つの確率分布の違いを測る量である。常に0以上で、2つの分布が完全に一致するときに0になる。一方で、KL(P||Q) と KL(Q||P) は一般に異なる値になる（非対称）ため、「距離」とは性質が異なる点に注意が要る。差の二乗の平均は平均二乗誤差関数である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-32","exam":"g","unit":"g-u4","keyword":"カルバック・ライブラー情報量 (KL)","type":"choice","syllabus_ref":"4.3","stem":"確率分布 P=(0.25, 0.75) と Q=(0.5, 0.5) がある。カルバック・ライブラー情報量 KL(P||Q) の値はおよそどれか。なお、対数の底は2とし、log2(0.5)=−1、log2(1.5)≒0.58 とする。","choices":["約−0.19","約0","約0.19","約1.19"],"answer":2,"explanation":"KL(P||Q) は、各要素について P の値 × log2(P の値 ÷ Q の値) の合計である。0.25×log2(0.25÷0.5)+0.75×log2(0.75÷0.5)=0.25×(−1)+0.75×0.58=−0.25+0.435≒0.19 となる。2つの分布は一致していないため0にはならず、またKLダイバージェンスが負になることはない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-33","exam":"g","unit":"g-u4","keyword":"カルバック・ライブラー情報量 (KL)","type":"choice","syllabus_ref":"4.3","stem":"正解の分布を P、モデルの予測分布を Q とすると、交差エントロピー H(P,Q) は、P のエントロピー H(P) とカルバック・ライブラー情報量 KL(P||Q) の和に等しい（H(P,Q)=H(P)+KL(P||Q)）。この関係から言えることとして、正しいものはどれか。","choices":["学習で交差エントロピーを最小化しても、予測分布は正解の分布に近づかない","学習の過程で H(P) は変わらないため、交差エントロピーを最小化することは、KL(P||Q) を小さくすること、すなわち予測分布を正解の分布に近づけることと等しい","交差エントロピーを最小化すると、H(P) も同時に小さくなる","KL(P||Q) は、常に交差エントロピー H(P,Q) より大きい"],"answer":1,"explanation":"H(P) は正解の分布 P だけで決まる量であり、モデルの学習では変化しない。したがって、交差エントロピー H(P,Q) を小さくすることは、そのまま KL(P||Q) を小さくすることと等しく、予測分布 Q を正解の分布 P に近づけることに当たる。これが、分類タスクで交差エントロピーを最小化するよう学習する根拠の1つである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-34","exam":"g","unit":"g-u4","keyword":"Contrastive Loss","type":"choice","syllabus_ref":"4.3","stem":"Contrastive Loss（対照損失）の説明として、正しいものはどれか。","choices":["データのペアを対象とし、似ているペアの埋め込み（特徴ベクトル）同士は近づけ、似ていないペアはマージン（一定の距離）以上に遠ざけるよう学習するための誤差関数である","アンカー・正例・負例の3つのデータを必ず必要とする誤差関数である","分類タスクで、正解ラベルと予測確率のずれを測る誤差関数である","予測値と正解値の差の二乗の平均を取る誤差関数である"],"answer":0,"explanation":"Contrastive Loss は、データのペア（2つのデータの組）を対象とする誤差関数である。似ているペアについては埋め込み同士の距離が小さくなるよう、似ていないペアについては距離がマージン以上になるよう学習し、顔認証や類似画像の検索など、データ同士の近さ・遠さ自体を扱う距離学習で使われる。3つのデータを必要とするのはTriplet Loss、正解ラベルと予測確率のずれを測るのは交差エントロピー、差の二乗の平均は平均二乗誤差関数である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-35","exam":"g","unit":"g-u4","keyword":"Triplet Loss","type":"choice","syllabus_ref":"4.3","stem":"Triplet Loss（トリプレット損失）の説明として、正しいものはどれか。","choices":["似ているペアと似ていないペアの、2つのデータだけで計算される誤差関数である","正解の分布と予測の分布のずれを、対数を使って測る誤差関数である","アンカー（基準となるデータ）・正例（アンカーに似たデータ）・負例（アンカーに似ていないデータ）の3点組を対象とし、アンカーと正例の距離が、アンカーと負例の距離よりマージン以上小さくなるよう学習する誤差関数である","各クラスへのスコアを、合計が1になる確率に変換するための誤差関数である"],"answer":2,"explanation":"Triplet Loss は、アンカー・正例・負例の3つのデータの組（トリプレット）を対象とする。アンカーと正例の距離が、アンカーと負例の距離よりもマージン（一定の差）以上小さくなるよう学習することで、似たデータが近く、似ていないデータが遠くに配置される埋め込みが得られる。ペアだけを使うのはContrastive Loss、分布のずれを対数で測るのは交差エントロピーやカルバック・ライブラー情報量である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-36","exam":"g","unit":"g-u4","keyword":"Triplet Loss","type":"choice","syllabus_ref":"4.3","stem":"顔認証のモデルを、埋め込み（特徴ベクトル）の距離で同一人物かどうかを判定できるよう学習させたい。Triplet Loss を使う場合のデータの組み立て方として、最も適切なものはどれか。","choices":["アンカー・正例・負例のすべてに、同じ人物の顔画像を使う","アンカーには顔画像を使い、正例と負例には顔以外の画像を使う","正例には別の人物の顔画像、負例にはアンカーと同じ人物の顔画像を使う","アンカーと正例には同じ人物の顔画像、負例には別の人物の顔画像を使い、アンカーと正例の距離がアンカーと負例の距離より小さくなるよう学習する"],"answer":3,"explanation":"Triplet Loss では、アンカーと正例は「似ている」関係、アンカーと負例は「似ていない」関係でなければならない。顔認証では、アンカーと正例に同じ人物の顔画像、負例に別の人物の顔画像を使うことで、同一人物の埋め込み同士が近づき、別人の埋め込みが遠ざかるよう学習できる。正例と負例を取り違えると、意図と逆の学習になる。なお、ペア単位で近さ・遠さを直接調整するContrastive Loss でも同様の目的の学習は可能である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目13「誤差関数」"},{"id":"g4-37","exam":"g","unit":"g-u4","keyword":"正則化","type":"choice","syllabus_ref":"4.4","stem":"正則化の説明として、正しいものはどれか。","choices":["入力データを0〜1の範囲にそろえる前処理のことである","学習率を自動で調整する仕組みのことである","誤差関数に重みの大きさに対するペナルティ（罰則）項を加え、重みが大きくなりすぎるのを抑えることで、モデルの複雑さを制御する手法である","訓練データをシャッフルして、学習する順序を変える処理のことである"],"answer":2,"explanation":"正則化は、誤差関数に「重みの大きさ」へのペナルティ項を加える手法である。重みが大きくなりすぎるとモデルは訓練データの細部にまで適合しやすくなるため、ペナルティで重みの増大を抑え、モデルの複雑さを制御する。入力データを一定の範囲にそろえるのは正規化（前処理）であり、正則化とは別の処理である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-38","exam":"g","unit":"g-u4","keyword":"正則化","type":"choice","syllabus_ref":"4.4","stem":"正則化の強さ（ペナルティ項にかける係数）を大きくしすぎると、どのような問題が起きやすいか。","choices":["重みが過度に抑えられ、訓練データにも十分に適合できない、未学習（過小適合）の状態になりやすい","必ず過学習が進み、汎化性能が下がる","ペナルティが強いほど、学習の計算は必ず速くなる","重みが発散して、際限なく大きくなる"],"answer":0,"explanation":"正則化は強ければよいわけではない。ペナルティを強くしすぎると重みが小さく抑えられすぎて、モデルが訓練データのパターンすら捉えられなくなる（未学習・過小適合）。逆に弱すぎると過学習を抑える効果が不十分になるため、正則化の強さは検証しながら調整する量である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-39","exam":"g","unit":"g-u4","keyword":"L1 正則化","type":"choice","syllabus_ref":"4.4","stem":"L1正則化の説明として、正しいものはどれか。","choices":["重みの二乗の和を、ペナルティとして誤差関数に加える手法である","重みの絶対値の和を、ペナルティとして誤差関数に加える手法である","0でない重みの個数を、ペナルティとして誤差関数に加える手法である","重みの平均値を、ペナルティとして誤差関数に加える手法である"],"answer":1,"explanation":"L1正則化は、重みの絶対値の和（L1ノルム）をペナルティとして誤差関数に加える手法である。重みの二乗の和を使うのはL2正則化、0でない重みの個数を使うのはL0正則化である。ペナルティの形の違いが、学習後の重みの性質の違い（L1では一部の重みが0になる等）につながる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-40","exam":"g","unit":"g-u4","keyword":"L1 正則化","type":"choice","syllabus_ref":"4.4","stem":"L1正則化の特徴として、正しいものはどれか。","choices":["すべての重みが、同じ割合で小さくなる","L1正則化では、重みが0になることは決してない","ペナルティの効果で、重みは元の値より大きくなる","一部の重みが完全に0になるため、実質的に特徴量の選択（不要な特徴量の除外）が行われる"],"answer":3,"explanation":"L1正則化では、絶対値へのペナルティの効き方により、寄与の小さい重みが完全に0まで押し切られる。このため学習後のモデルは、0でない重みを持つ特徴量だけを使う形になり（スパースになる）、特徴量の選択を兼ねることができる。重み全体がなめらかに小さくなるのはL2正則化の傾向である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-41","exam":"g","unit":"g-u4","keyword":"L2 正則化","type":"choice","syllabus_ref":"4.4","stem":"L2正則化の説明として、正しいものはどれか。","choices":["重みの二乗の和を、ペナルティとして誤差関数に加える手法である","重みの絶対値の和を、ペナルティとして誤差関数に加える手法である","0でない重みの個数を、ペナルティとして誤差関数に加える手法である","重みの最大値を、ペナルティとして誤差関数に加える手法である"],"answer":0,"explanation":"L2正則化は、重みの二乗の和（L2ノルムの二乗）をペナルティとして誤差関数に加える手法である。大きな重みほど二乗によって強く罰せられるため、特定の重みだけが突出することが抑えられる。絶対値の和を使うのはL1正則化、0でない重みの個数を使うのはL0正則化である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-42","exam":"g","unit":"g-u4","keyword":"L2 正則化","type":"choice","syllabus_ref":"4.4","stem":"L2正則化を使って学習したモデルの重みの傾向として、正しいものはどれか。","choices":["一部の重みが完全に0になり、残りの重みは大きくなる","重みは、正則化を入れない場合より大きくなる","重み全体が0に近づくようになめらかに小さくなり、特定の重みだけが突出しにくくなる","重みの符号がすべて反転する"],"answer":2,"explanation":"L2正則化は、重みが大きいほど強く罰するため、重み全体をなめらかに小さく保つ働きをする（この働きは重み減衰とも呼ばれる）。ただしL1正則化と違い、重みが完全に0になることは通常はなく、すべての重みが小さい値を持ち続ける。一部の重みが完全に0になるのはL1正則化の特徴である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-43","exam":"g","unit":"g-u4","keyword":"L0 正則化","type":"choice","syllabus_ref":"4.4","stem":"L0正則化の説明として、正しいものはどれか。","choices":["重みの絶対値の和をペナルティとする手法である","0でない重みの個数そのものをペナルティとする手法だが、どの重みを0にするかの組み合わせの問題となり最適化が難しいため、実用上はL1正則化で代替されることが多い","ペナルティを一切加えない手法のことである","重みの二乗の和をペナルティとし、重みは常にすべて0になる手法である"],"answer":1,"explanation":"L0正則化は、0でない重みの個数（L0ノルム）をペナルティとする。「個数」は連続的な量ではないため、勾配を使った最適化が難しく、重みの組み合わせを調べる問題になってしまう。このため実用上は、同じく一部の重みを0にできるL1正則化で代替されることが多い。絶対値の和はL1正則化、二乗の和はL2正則化のペナルティである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-44","exam":"g","unit":"g-u4","keyword":"L1 正則化","type":"choice","syllabus_ref":"4.4","stem":"あるモデルの重みが (0.5, −1.0, 2.0) である。L1正則化のペナルティ項は、係数 λ=0.1 を掛けた「λ ×（重みの絶対値の和）」で計算される。このときペナルティ項の値はどれか。","choices":["3.5","0.15","0.525","0.35"],"answer":3,"explanation":"重みの絶対値の和は、|0.5|+|−1.0|+|2.0|=0.5+1.0+2.0=3.5 である。これに λ=0.1 を掛けて 0.35 がペナルティ項の値になる。なお 3.5 は λ を掛け忘れた値、0.525 は二乗の和（0.25+1+4=5.25）に λ を掛けたL2正則化側の値、0.15 は符号付きの和（0.5−1.0+2.0=1.5）に λ を掛けた値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-45","exam":"g","unit":"g-u4","keyword":"ラッソ回帰","type":"choice","syllabus_ref":"4.4","stem":"ラッソ回帰の説明として、正しいものはどれか。","choices":["線形回帰にL2正則化を組み合わせた手法である","分類タスク専用の手法で、回帰には使えない","線形回帰にL1正則化を組み合わせた手法で、一部の係数（重み）が0になるため、特徴量の選択を兼ねることができる","ドロップアウトを組み合わせた回帰手法である"],"answer":2,"explanation":"ラッソ回帰は、線形回帰の誤差関数にL1正則化を加えた手法である。L1正則化の性質により一部の係数が完全に0になるため、どの特徴量が効いているかが分かりやすく、特徴量の選択を兼ねることができる。線形回帰にL2正則化を組み合わせたものはリッジ回帰である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-46","exam":"g","unit":"g-u4","keyword":"リッジ回帰","type":"choice","syllabus_ref":"4.4","stem":"リッジ回帰の説明として、正しいものはどれか。","choices":["線形回帰にL2正則化を組み合わせた手法で、係数（重み）全体を小さく抑える。係数が完全に0になることは通常はなく、特徴量同士の相関が強い場合でも係数が安定しやすい","線形回帰にL1正則化を組み合わせた手法で、一部の係数が必ず0になる","ロジスティック回帰にドロップアウトを組み合わせた手法である","正則化を入れず、訓練データへの適合だけを最大化する手法である"],"answer":0,"explanation":"リッジ回帰は、線形回帰の誤差関数にL2正則化を加えた手法である。係数全体がなめらかに小さく抑えられ、完全に0には通常ならない。特徴量同士の相関が強い（多重共線性がある）場合でも、係数が極端な値に振れにくく安定する点が利点である。L1正則化を組み合わせ、一部の係数が0になるのはラッソ回帰である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-47","exam":"g","unit":"g-u4","keyword":"ドロップアウト","type":"choice","syllabus_ref":"4.4","stem":"ドロップアウトの説明として、正しいものはどれか。","choices":["重みの大きさへのペナルティを、誤差関数に加える手法である","学習の際に、各ニューロンを一定の確率でランダムに無効化（使わない状態に）しながら学習する手法である","推論（予測）の際に、ニューロンをランダムに無効化する手法である","学習データの一部を、ランダムに削除する手法である"],"answer":1,"explanation":"ドロップアウトは、学習時に隠れ層などのニューロンを一定の確率でランダムに無効化し、その都度異なる構成のネットワークで学習する手法である。特定のニューロン同士の結びつきに依存しすぎることを防ぎ、過学習を抑える。無効化するのはニューロンであり、学習データそのものを削除する手法ではない。重みへのペナルティを加えるのはL1・L2正則化である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-48","exam":"g","unit":"g-u4","keyword":"L0 正則化・L1 正則化","type":"choice","syllabus_ref":"4.4","stem":"「0でない重みの個数を直接罰する手法は、組み合わせの問題になって計算が難しい。実務ではその代替として、連続的なペナルティで一部の重みを完全に0にできる手法がよく使われる。」この代替の手法はどれか。","choices":["L2正則化","ドロップアウト","リッジ回帰","L1正則化"],"answer":3,"explanation":"0でない重みの個数を罰するのはL0正則化で、最適化が難しい。その代替として使われるのが、重みの絶対値の和をペナルティとするL1正則化であり、寄与の小さい重みを完全に0にできる。L2正則化とリッジ回帰（線形回帰＋L2正則化）では重みはなめらかに小さくなるが、通常は0にはならない。ドロップアウトはニューロンをランダムに無効化する手法で、重みのペナルティではない。これはシラバスの目標「獲得したいモデルの特性に応じて、適切な正則化手法を選択できる」に対応する使い分けである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目14「正則化」"},{"id":"g4-49","exam":"g","unit":"g-u4","keyword":"連鎖律","type":"choice","syllabus_ref":"4.5","stem":"合成関数の微分に関する「連鎖律（チェーンルール）」の説明として、正しいものはどれか。","choices":["合成関数の微分は、それを構成する各関数の微分の和に等しい","合成関数の微分は、それを構成する各関数の微分の積で表される","合成関数の微分は、外側の関数の微分だけで決まり、内側の関数の微分は関係しない","合成関数の微分は、関数を合成する順序を入れ替えても、必ず同じ値になる"],"answer":1,"explanation":"連鎖律は、y=f(u)、u=g(x) のように関数が合成されているとき、dy/dx=(dy/du)×(du/dx) のように、各段階の微分の積で全体の微分を表す法則である。誤差逆伝播法では、出力側から入力側へ層をさかのぼりながら、この積の形で各重みに対する勾配を計算する。和ではない点、各段階の微分がすべて掛け合わされる点が要点である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-50","exam":"g","unit":"g-u4","keyword":"連鎖律","type":"choice","syllabus_ref":"4.5","stem":"関数 y=(2x+3)² について、連鎖律を用いて微分し、x=1 における dy/dx の値を求めよ。","choices":["10","25","20","5"],"answer":2,"explanation":"外側の関数を u²（u=2x+3）と見ると、dy/du=2u、du/dx=2 で、連鎖律により dy/dx=2u×2 となる。x=1 では u=5 なので、dy/dx=2×5×2=20 である。10 は内側の微分（du/dx=2）を掛け忘れた値、25 は微分ではなく関数値 (2x+3)² そのもの、5 は u=2x+3 の値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-51","exam":"g","unit":"g-u4","keyword":"連鎖律","type":"choice","syllabus_ref":"4.5","stem":"誤差逆伝播法（バックプロパゲーション）の説明として、正しいものはどれか。","choices":["出力層で得られた誤差をもとに、連鎖律を使って出力側から入力側へさかのぼりながら、各層の重みに対する誤差の勾配を効率よく計算する方法である","入力側から出力側へデータを流す順伝播を繰り返し、重みをランダムに少しずつ変えて、誤差が減る組み合わせを探す方法である","出力層の重みだけを更新し、隠れ層の重みは固定したまま学習する方法である","誤差が大きくなる方向へ重みを更新し、発散しない範囲で学習を進める方法である"],"answer":0,"explanation":"誤差逆伝播法は、順伝播で得た出力と正解との誤差を出発点に、連鎖律を繰り返し適用して、誤差に対する各重みの勾配を出力側から入力側へ効率よく計算する方法である。隠れ層の重みについても、その重みが誤差に与える影響の大きさ（勾配）が得られるため、全層の重みを学習できる。重みをランダムに変えて当たりを探す方法ではなく、勾配という確かな手がかりを使う点が特徴である。なお本問はシラバスの目標「誤差逆伝播法の概要を説明できる」に対応し、キーワードはその計算機構である連鎖律に付けた。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-52","exam":"g","unit":"g-u4","keyword":"連鎖律","type":"choice","syllabus_ref":"4.5","stem":"1つの重みだけを持つ単純な計算を考える。入力 x=3、重み w=2 とし、中間値 a=w×x、誤差 L=(a−t)²（正解 t=4）とする。連鎖律を用いて、誤差 L の重み w に対する勾配 dL/dw を計算せよ。","choices":["4","24","6","12"],"answer":3,"explanation":"連鎖律により dL/dw=(dL/da)×(da/dw) と分解できる。a=2×3=6 だから dL/da=2(a−t)=2×(6−4)=4。また a=w×x だから da/dw=x=3。よって dL/dw=4×3=12 となる。4 は da/dw（=x）を掛け忘れた値、24 は da/dw に a の値を使った場合の値、6 は中間値 a そのものである。このように、誤差逆伝播法では各層の局所的な微分を掛け合わせることで、入力側の重みに対する勾配までたどり着く。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-53","exam":"g","unit":"g-u4","keyword":"勾配消失問題","type":"choice","syllabus_ref":"4.5","stem":"誤差逆伝播法で学習する深いネットワークで「勾配消失問題」が起きる仕組みとして、正しいものはどれか。","choices":["出力側の層に誤差が集中し、出力層の重みだけが過剰に更新されるため、学習が不安定になる現象である","勾配は連鎖律により各層の微分などの積として入力側へ伝わるが、その因子の絶対値が1より小さいと、層をさかのぼるたびに積が小さくなり、入力側の層では勾配がほぼ0になって重みがほとんど更新されなくなる","訓練データが多すぎると勾配の計算が追いつかず、古い勾配がそのまま使われ続ける現象である","勾配が層をさかのぼるたびに大きくなるため、入力側の層の重みが発散してしまう現象である"],"answer":1,"explanation":"誤差逆伝播法では、入力側の層の勾配は、出力側からそこまでの各層の微分などの積として得られる。因子の絶対値が1より小さい場合、その積は層の数だけ掛け合わされることで急速に小さくなり、入力側の層では勾配がほぼ消えてしまう。これが勾配消失問題であり、入力側の層ほど学習が進まなくなる。逆に、因子の絶対値が1より大きい場合は勾配が増幅する勾配爆発問題になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-54","exam":"g","unit":"g-u4","keyword":"勾配消失問題","type":"choice","syllabus_ref":"4.5","stem":"勾配消失問題について、ネットワークの深さとの関係を述べたものとして、正しいものはどれか。","choices":["層が深くなるほど勾配の伝わる経路は短くなるため、勾配消失は起きにくくなる","勾配消失は層の深さとは無関係で、訓練データの量だけで決まる","層が深くなるほど、勾配を構成する積の因子の数が増えるため、勾配消失は起きやすくなる。入力側の層が誤差への寄与に応じて重みを調整できなくなる点で、信用割当の問題としても現れる","勾配消失は出力層でのみ起きる現象であり、深さが増えても影響範囲は変わらない"],"answer":2,"explanation":"入力側の層の勾配は、出力層からその層までの経路上の因子の積である。層が深くなると因子の数が増え、絶対値が1より小さい因子の積はますます小さくなるため、勾配消失は深いネットワークほど深刻になる。結果として入力側の層は「自分の重みが誤差にどれだけ影響したか」という情報を受け取れず、寄与に応じた調整ができなくなる。これは信用割当の観点から見た勾配消失の一面である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-55","exam":"g","unit":"g-u4","keyword":"勾配爆発問題","type":"choice","syllabus_ref":"4.5","stem":"勾配爆発問題の説明として、正しいものはどれか。","choices":["勾配がほぼ0になり、重みが更新されなくなって学習が進まなくなる現象である","訓練データに過剰に適合し、未知のデータに対する性能が下がる現象である","誤差関数の値が、学習の途中で一時的に大きく跳ね上がる現象である","誤差を逆伝播させる過程で勾配が指数的に大きくなり、重みの更新量が過大になって学習が不安定化・発散する現象である"],"answer":3,"explanation":"勾配爆発問題は、逆伝播の過程で勾配が層をさかのぼるたびに増幅され、非常に大きな値になる現象である。重みの更新は勾配に基づいて行われるため、勾配が過大だと重みが大きく振れ、学習が不安定になったり発散したりする。勾配がほぼ0になるのは勾配消失問題、訓練データへの過剰な適合は過学習であり、いずれも別の現象である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-56","exam":"g","unit":"g-u4","keyword":"勾配爆発問題","type":"choice","syllabus_ref":"4.5","stem":"あるネットワークでは、勾配が1層さかのぼるごとに2倍に増幅されるとする。出力側の層の勾配が1のとき、10層さかのぼった入力側の層では、勾配は出力側の何倍になるか。","choices":["1024倍","20倍","100倍","512倍"],"answer":0,"explanation":"1層ごとに2倍になるため、10層では2の10乗、すなわち 2^10=1024 倍になる。20倍は「2倍×10層」を和で考えた誤り、512倍は 2^9 で1層分少ない値である。このように、1層あたりの増幅がわずかでも、層の数が増えると勾配は指数的に膨らむことが、勾配爆発問題の深刻さにつながる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-57","exam":"g","unit":"g-u4","keyword":"勾配爆発問題","type":"choice","syllabus_ref":"4.5","stem":"勾配爆発問題への代表的な対策として用いられる「勾配クリッピング」の説明として、正しいものはどれか。","choices":["勾配が小さすぎる場合に、一定の倍率で引き上げてから重みを更新する方法である","重みの初期値をすべて0にそろえ、勾配の増幅を防ぐ方法である","勾配の大きさ（ノルム）があらかじめ定めた閾値を超えた場合に、閾値以下になるよう勾配を縮小してから重みを更新する方法である","学習の途中でニューロンをランダムに無効化し、勾配の流れを分散させる方法である"],"answer":2,"explanation":"勾配クリッピングは、勾配のノルムが閾値を超えたときに、方向は保ったまま大きさだけを閾値以下に縮小する対策である。これにより、勾配が異常に大きいステップでも重みの更新量が抑えられ、学習の発散を防げる。ニューロンをランダムに無効化するのはドロップアウト（正則化の手法）であり、勾配爆発への対策ではない。また、重みの初期値をすべて0にすると各ニューロンが同じ更新を受けて区別がつかなくなり、学習自体がうまく進まない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-58","exam":"g","unit":"g-u4","keyword":"信用割当問題","type":"choice","syllabus_ref":"4.5","stem":"「信用割当問題（クレジットアサインメント問題）」の説明として、正しいものはどれか。","choices":["複数の計算機に学習の処理を分担させる際、どの計算機にどのデータを割り当てるかを決める問題である","ネットワークの出力の誤差に対して、内部のどのニューロンや重みが、どれだけの責任（寄与）を持つかを決める問題である","分類タスクで、入力データにどのクラスラベルを割り当てるかを決める問題である","学習に使う計算資源の量に応じて、利用料金を各部門に割り当てる問題である"],"answer":1,"explanation":"信用割当問題は、最終的な出力の良し悪し（誤差）に対して、内部の各要素がどれだけ寄与したか、つまり「手柄や責任をどう割り当てるか」の問題である。隠れ層の重みは正解との誤差に直接は現れないため、その寄与をどう測るかが学習の核心になる。誤差逆伝播法は、連鎖律によって各重みの勾配を求めることで、この割り当てを計算可能にした方法である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-59","exam":"g","unit":"g-u4","keyword":"信用割当問題","type":"choice","syllabus_ref":"4.5","stem":"誤差逆伝播法が信用割当問題にどう答えているかを述べたものとして、正しいものはどれか。","choices":["各重みの勾配は「その重みをわずかに変えたとき誤差がどれだけ変わるか」を表すため、誤差への寄与の大きさに応じて各重みに責任を割り当て、その大きさに基づいて重みを調整できる","すべての重みに誤差を均等に割り当て、同じ量だけ更新することで公平に学習する","誤差の責任は出力層の重みにのみ割り当て、隠れ層の重みはランダムに調整する","誤差が大きい学習データほど信用を高く割り当て、そのデータだけを繰り返し学習する"],"answer":0,"explanation":"誤差逆伝播法で得られる各重みの勾配は、その重みの変化が誤差に与える影響の大きさそのものである。したがって、誤差への寄与が大きい重みほど大きく、寄与が小さい重みほど小さく調整でき、信用（責任）の割り当てが計算として実現される。均等な割り当てや出力層だけへの割り当てでは、隠れ層の各重みの寄与の違いを反映できない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-60","exam":"g","unit":"g-u4","keyword":"勾配消失問題・勾配爆発問題","type":"choice","syllabus_ref":"4.5","stem":"誤差逆伝播法の適用時に生じる問題と、その主たる原因の組み合わせとして、正しいものはどれか。","choices":["勾配消失問題 ― 訓練データの量が多すぎることが主たる原因である","勾配爆発問題 ― 活性化関数の出力範囲が0〜1に制限されることが主たる原因である","勾配消失問題 ― 勾配を構成する因子の絶対値が1より大きいことが主たる原因である","勾配爆発問題 ― 勾配を構成する因子の絶対値が1より大きい値の積が、層をさかのぼるごとに重なることが主たる原因である"],"answer":3,"explanation":"逆伝播の勾配は各層の因子の積で表されるため、因子の絶対値が1より大きければ積は増幅し（勾配爆発問題）、1より小さければ積は縮小する（勾配消失問題）。選択肢にある「勾配消失問題 ― 因子の絶対値が1より大きい」は、消失と爆発の原因を取り違えたものである。訓練データの量そのものは、これらの問題の主たる原因ではない。これはシラバスの目標「誤差逆伝播法の適用時に生じる問題とその主たる原因について説明できる」に対応する。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目15「誤差逆伝播法」"},{"id":"g4-61","exam":"g","unit":"g-u4","keyword":"勾配降下法","type":"choice","syllabus_ref":"4.6","stem":"勾配降下法による重み w の更新方法として、正しいものはどれか。","choices":["誤差関数の勾配（微分）の符号と逆向きに、学習率と勾配の積の分だけ重みを移動させる","誤差関数の勾配の向きに、学習率と勾配の積の分だけ重みを移動させる","勾配を使わず、重みをランダムに少しずつ変えながら誤差が最も小さくなる組み合わせを探す","誤差関数の値そのものを重みから差し引いて更新する"],"answer":0,"explanation":"勾配降下法は、重みを w ← w − η×(∂L/∂w) の形で更新する方法である（η は学習率、L は誤差関数）。勾配は誤差が増える向きと大きさを表すため、その逆向きへ進むことで誤差が減る。重みをランダムに変えて当たりを探す方法ではなく、勾配という確かな手がかりを使う点が特徴である。また、差し引くのは誤差関数の値そのものではなく、その勾配である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-62","exam":"g","unit":"g-u4","keyword":"学習率","type":"choice","syllabus_ref":"4.6","stem":"勾配降下法で重み w を更新する。現在の w=1.0、誤差関数の w に対する勾配が 0.4、学習率が 0.1 のとき、更新後の w の値を求めよ。","choices":["1.04","0.6","0.96","0.996"],"answer":2,"explanation":"更新式は w ← w − 学習率×勾配 であるため、1.0 − 0.1×0.4 = 1.0 − 0.04 = 0.96 となる。1.04 は符号を取り違えて勾配の向きに進んだ値、0.6 は学習率を掛け忘れた値（1.0 − 0.4）、0.996 は学習率を 0.01 と取り違えた場合の値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-63","exam":"g","unit":"g-u4","keyword":"学習率","type":"choice","syllabus_ref":"4.6","stem":"勾配降下法における学習率の設定について、正しいものはどれか。","choices":["学習率は大きいほど、常に速く大域最適解に到達できる","学習率が大きすぎると、最適解の周りを行き過ぎて振動したり発散したりする。逆に小さすぎると、収束が遅くなったり、局所最適解から抜け出せなくなったりする","学習率は、学習の途中で重みと一緒に自動的に最適化されるパラメータである","学習率は、誤差関数の値に応じて符号が変わる量である"],"answer":1,"explanation":"学習率は1回の更新で重みをどれだけ動かすかを決める量で、学習の前に人が設定するハイパーパラメータである。大きすぎると最適解を通り過ぎて振動・発散し、小さすぎると収束までに非常に多くの更新が必要になり、浅い局所最適解に留まりやすくなる。適切な値は問題やモデルによって異なるため、調整の対象になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-64","exam":"g","unit":"g-u4","keyword":"確率的勾配降下法 (SGD)","type":"choice","syllabus_ref":"4.6","stem":"確率的勾配降下法（SGD）の説明として、正しいものはどれか。","choices":["全訓練データを使って勾配の平均を取り、重みを1回だけ更新する方法である","勾配を確率分布からサンプリングし、重み自体を確率的に決める方法である","誤差関数の2階微分を使って、最適解を一気に求める方法である","訓練データからランダムに選んだ一部のデータ（1件、または小さいまとまり）ごとに勾配を計算して重みを更新するため、1回あたりの計算が軽く、更新の回数を多くできる方法である"],"answer":3,"explanation":"確率的勾配降下法（SGD）は、データ全体ではなく、ランダムに選んだ1件（またはミニバッチと呼ばれる小さいまとまり）から勾配を推定して、その都度重みを更新する方法である。1回あたりの計算が軽く更新回数を稼げる反面、勾配の推定にはばらつき（ノイズ）が含まれる。ただし、その揺らぎが局所最適解からの脱出に役立つこともある。全データで勾配を平均して更新するのはバッチ学習（最急降下法）側の方法である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-65","exam":"g","unit":"g-u4","keyword":"バッチ学習・ミニバッチ学習・オンライン学習","type":"choice","syllabus_ref":"4.6","stem":"学習データの使い方による学習方式の説明として、正しいものはどれか。","choices":["バッチ学習は全データを使って勾配を計算し重みを1回更新し、ミニバッチ学習はデータを小さいまとまりに分けてその都度更新し、オンライン学習はデータが1件得られるたびに更新する","バッチ学習はデータを1件ずつ処理する方式であり、オンライン学習は全データをまとめて処理する方式である","ミニバッチ学習は、ミニバッチのサイズを全データ数と同じに設定する学習方式である","オンライン学習では、新しいデータが来るたびに過去のデータをすべて保持し直し、毎回最初から学習し直す必要がある"],"answer":0,"explanation":"3つの方式の違いは、1回の重みの更新に使うデータの量である。バッチ学習は全データ、ミニバッチ学習は数十〜数百件程度の小さいまとまり、オンライン学習は1件ずつを使う。ミニバッチ学習は、バッチ学習の安定性とオンライン学習の更新頻度のバランスがよく、現在の実務で最も広く使われる。オンライン学習はデータを逐次処理するため、全データを保持し直す必要はない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-66","exam":"g","unit":"g-u4","keyword":"エポック・イテレーション","type":"choice","syllabus_ref":"4.6","stem":"訓練データが10,000件、ミニバッチのサイズが100件のとき、1エポックあたりのイテレーション回数を求めよ。ただし、1イテレーションはミニバッチ1つ分の学習（重みの更新1回）を指すものとする。","choices":["10回","100回","1,000回","10,000回"],"answer":1,"explanation":"エポックは、訓練データ全体を1通り学習し終える単位である。1エポックでは全データを使うため、イテレーション回数は 10,000 ÷ 100 = 100 回になる。イテレーションは重みの更新1回を指し、エポック数×イテレーション回数が総更新回数になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-67","exam":"g","unit":"g-u4","keyword":"モーメンタム","type":"choice","syllabus_ref":"4.6","stem":"最適化手法における「モーメンタム」の説明として、正しいものはどれか。","choices":["学習率をパラメータごとに自動調整し、更新量を均一化する仕組みである","勾配の絶対値が大きいパラメータほど学習率を大きくし、収束を加速する仕組みである","過去の更新の向きを「速度」として蓄積し、同じ向きの勾配が続けば更新を加速し、向きが交互に変わる方向では更新同士が打ち消し合って振動を抑える仕組みである","誤差が増えたステップでは更新を取り消し、重みを1つ前の状態に戻す仕組みである"],"answer":2,"explanation":"モーメンタムは、物理学の慣性（運動量）の考え方を取り入れた手法で、前回までの更新方向を速度として保持し、今回の勾配と合わせて更新方向を決める。なだらかで一方向に続く斜面では加速し、谷底を横切るように勾配の向きが振動する方向では打ち消し合って振動が抑えられるため、通常の勾配降下法より速く安定して収束しやすい。パラメータごとに学習率を調整するのは AdaGrad などの適応的手法である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-68","exam":"g","unit":"g-u4","keyword":"AdaGrad","type":"choice","syllabus_ref":"4.6","stem":"AdaGrad の説明として、正しいものはどれか。","choices":["すべてのパラメータに共通の学習率を使い、イテレーションごとに学習率を指数的に減衰させる手法である","過去の勾配の符号だけを使って、更新量の大きさを決める手法である","勾配の指数移動平均を速度として蓄積し、慣性によって更新を滑らかにする手法である","パラメータごとに学習率を調整する手法で、過去の勾配の二乗和を蓄積し、よく更新されてきたパラメータほど実効的な学習率を小さくする。ただし、学習が進むと学習率が単調に小さくなり続け、途中で更新がほぼ止まってしまうことがある"],"answer":3,"explanation":"AdaGrad は、パラメータごとに、それまでの勾配の二乗和の蓄積に応じて学習率を調整する適応的手法である。頻繁に現れる特徴の重みは少しずつ、まれにしか現れない特徴の重みは大きめに更新されるため、疎なデータに有効とされる。一方で、二乗和は増え続けるため学習率は単調に減少し、学習の後半では更新がほぼ止まることがある。この欠点を和らげる方向で RMSprop が、さらに学習率自体の設定を不要にする方向で AdaDelta が提案された。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-69","exam":"g","unit":"g-u4","keyword":"RMSprop・Adam","type":"choice","syllabus_ref":"4.6","stem":"RMSprop と Adam に関する説明として、正しいものはどれか。","choices":["RMSprop は、AdaGrad の「学習率が単調に小さくなり続ける」問題を、勾配の二乗の指数移動平均を使うことで緩和した手法であり、Adam はこれにモーメンタムの考え方（勾配の指数移動平均）を組み合わせた手法である","RMSprop は勾配を使わずに重みを更新する手法であり、Adam はその計算を並列化したものである","Adam は、学習率をすべてのパラメータで同じ値に固定する手法である","RMSprop と Adam は、いずれも誤差関数の2階微分を直接計算して更新量を決める手法である"],"answer":0,"explanation":"RMSprop は、勾配の二乗和を全期間で蓄積する代わりに、直近の勾配を重視する指数移動平均を使うことで、実効的な学習率が一方的に小さくなり続ける問題を緩和した。Adam は、勾配の指数移動平均（モーメンタムに相当）と、勾配の二乗の指数移動平均（RMSprop に相当）の両方を使い、学習の初期に生じる偏りを補正しながらパラメータごとに更新量を調整する手法で、現在広く使われる。Adam の学習率の振る舞いを抑える改良として AdaBound や AMSBound も提案されている。いずれも使うのは1階微分（勾配）であり、2階微分は直接は計算しない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-70","exam":"g","unit":"g-u4","keyword":"局所最適解・大域最適解・鞍点","type":"choice","syllabus_ref":"4.6","stem":"最適化における局所最適解・大域最適解・鞍点の説明として、正しいものはどれか。","choices":["局所最適解は、誤差関数の全体の中で最も小さい値を取る点であり、大域最適解はその近傍でのみ最小になる点である","鞍点は、ある方向では最小だが別の方向では最大になる点で、勾配が0になるため勾配降下法では停留してしまうことがある。高次元の問題では、局所最適解よりも鞍点の方が学習の妨げになることが多いとされる","鞍点では勾配が最大になるため、勾配降下法は鞍点を自動的に避けて進むことができる","大域最適解に到達すれば、未知のデータに対する性能（汎化性能）も必ず最良になる"],"answer":1,"explanation":"大域最適解は全体での最小点、局所最適解は近傍でのみ最小の点であり、両者の説明を取り違えてはいけない。鞍点は方向によって最小にも最大にも見える点で、勾配が0になるため、勾配だけを手がかりにする勾配降下法では長く停留することがある。パラメータの数が多い高次元の問題では、すべての方向で最小になる局所最適解よりも、一部の方向で最大になる鞍点の方がはるかに多く存在し、学習の妨げの中心は鞍点だと考えられている。なお、大域最適解への到達は訓練データ上の話であり、汎化性能の良さとは別の問題である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-71","exam":"g","unit":"g-u4","keyword":"ハイパーパラメータ・グリッドサーチ・ランダムサーチ","type":"choice","syllabus_ref":"4.6","stem":"ハイパーパラメータとその調整方法について、正しいものはどれか。","choices":["ハイパーパラメータは学習によってデータから自動的に決まる値であり、学習率や層の数も重みと一緒に最適化される","グリッドサーチは候補値をランダムに選んで試す方法であり、ランダムサーチは候補値の全組み合わせを試す方法である","学習率やバッチサイズは、学習の前に人が設定するハイパーパラメータである。グリッドサーチは候補値の組み合わせを総当たりで試し、ランダムサーチは候補の範囲からランダムに選んで試すため、試せる回数が限られる場合は、ランダムサーチの方が有望な領域を広く探れることがある","ハイパーパラメータの調整では、テストデータに対する性能が最大になるよう直接選び取るのが正しい手順である"],"answer":2,"explanation":"ハイパーパラメータは、学習率・バッチサイズ・層の数など、学習の前に人が設定する値であり、学習で自動的に決まる重み（パラメータ）とは区別される。グリッドサーチは候補値の格子状の全組み合わせを試す方法、ランダムサーチは範囲から無作為に選んで試す方法であり、両者の説明を取り違えてはいけない。調整の良し悪しは検証データで測るのが原則で、テストデータで選び取ると評価の公正さが損なわれる。なお、ノーフリーランチの定理が示すように、あらゆる問題で最良となる最適化手法や設定は存在しないため、問題に応じた調整が欠かせない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-72","exam":"g","unit":"g-u4","keyword":"早期終了","type":"choice","syllabus_ref":"4.6","stem":"早期終了（アーリーストッピング）の説明として、正しいものはどれか。","choices":["学習率があらかじめ決めた値以下になったら、学習を打ち切る方法である","訓練データに対する誤差が0になった時点で、学習を打ち切る方法である","計算資源を節約するため、あらかじめ決めた時刻になったら学習を打ち切る方法である","学習の途中で検証データに対する誤差を監視し、それが改善しなくなった（悪化し始めた）時点で学習を止めることで、過学習を防ぐ方法である"],"answer":3,"explanation":"早期終了は、訓練データへの適合が進みすぎて未知のデータへの性能が落ちる過学習を防ぐため、検証データに対する誤差が最も小さくなった時点のモデルを採用し、それ以上は学習を続けない方法である。学習を打ち切る判断材料は時刻や学習率ではなく、検証データに対する誤差の推移である。なお、二重降下現象のように、学習をさらに続けることで再び性能が改善する場合もあることが知られており、早期終了が常に最善とは限らない点には注意が要る。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-73","exam":"g","unit":"g-u4","keyword":"二重降下現象","type":"choice","syllabus_ref":"4.6","stem":"二重降下現象（ダブルディセント）の説明として、正しいものはどれか。","choices":["学習率を一度下げてから再び上げると、誤差が2回にわたって大きく下がる現象である","モデルの複雑さ（パラメータ数）を増やしていくと、テスト誤差は一度下がってから上がるが、訓練データをほぼ完全に再現できる規模を超えたあたりから、再び下がり始める現象である","訓練誤差とテスト誤差が、学習の途中で交互に下がり続ける現象である","訓練データを2倍に増やすと、テスト誤差がちょうど半分になる現象である"],"answer":1,"explanation":"二重降下現象は、モデルの規模に対するテスト誤差の振る舞いを指す。古典的な見方では、モデルを複雑にしていくとテスト誤差は一度下がった後に過学習で上がり続ける（U字）とされてきた。しかし実際には、訓練誤差がほぼ0になる規模（補間に達する点）を超えてさらにモデルを大きくすると、テスト誤差がもう一度下がり始めることが確認されている。現代の大規模なニューラルネットワークが、過学習で破綻せず高い性能を示す理由の一つとして注目されている現象である。学習率の操作やデータ量の話ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-74","exam":"g","unit":"g-u4","keyword":"二重降下現象","type":"choice","syllabus_ref":"4.6","stem":"ある実験で、モデルのパラメータ数を少しずつ増やしながらテスト誤差を測定したところ、誤差はいったん上昇した後、パラメータ数をさらに増やすと再び低下に転じた。この結果の解釈として、正しいものはどれか。","choices":["古典的なバイアスとバリアンスのトレードオフ（U字の曲線）だけではこの振る舞いは説明できず、過剰にパラメータ化された領域では「複雑なモデルほど汎化が悪くなる」という従来の直感がそのままでは成り立たないことを示している","テスト誤差が再び下がったのは測定の誤りであり、モデルは小さいほど常に汎化性能が良い","この現象は正則化を一切行わない場合にだけ起こり、正則化をすれば必ず古典的なU字の曲線に戻る","訓練誤差がほぼ0になった時点でそれ以上モデルを大きくしてもテスト誤差は変わらないはずであり、この結果は再現性のない偶然である"],"answer":0,"explanation":"パラメータ数を増やす過程でテスト誤差が「下がる→上がる→再び下がる」という二度の降下を示すのが二重降下現象であり、古典的なバイアス・バリアンスのトレードオフから描かれるU字の曲線では、2度目の降下は説明できない。この現象は再現性のある知見として報告されており、測定誤りや偶然ではない。また、正則化を行った場合でも観察され得るもので、「正則化をすれば必ずU字に戻る」とは言えない。過剰にパラメータ化された領域では、モデルの複雑さと汎化の関係について従来とは異なる理解が必要になる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-75","exam":"g","unit":"g-u4","keyword":"ノーフリーランチの定理","type":"choice","syllabus_ref":"4.6","stem":"ノーフリーランチの定理の内容として、正しいものはどれか。","choices":["計算資源を無限に使えば、あらゆる問題で最適な解が得られるという定理である","優れたアルゴリズムは無料では手に入らないため、商用の手法が常に優れているという定理である","考えられるすべての問題について平均を取ると、どの探索・最適化アルゴリズムも平均的な性能は同じになり、あらゆる問題で最良となる万能のアルゴリズムは存在しないという定理である","訓練データを増やせば、あらゆる種類の問題で性能が必ず向上するという定理である"],"answer":2,"explanation":"ノーフリーランチの定理は、探索や最適化のアルゴリズムについての定理である。ある問題の集合で他より優れるアルゴリズムは、別の問題ではその分だけ劣るため、考えられるすべての問題で平均を取ると、どのアルゴリズムの平均性能も同じになる。つまり、問題の性質について何の前提も置かなければ、アルゴリズムの間に優劣はつけられない。性能の差が生まれるのは、アルゴリズムの前提（問題の構造への仮定）が対象の問題に合っている場合に限る、という点が本質である。「無料の昼食はない」という比喩は、商用・無償の話ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-76","exam":"g","unit":"g-u4","keyword":"ノーフリーランチの定理","type":"choice","syllabus_ref":"4.6","stem":"ノーフリーランチの定理を踏まえた、機械学習における手法や設定の選び方として、正しいものはどれか。","choices":["最も新しい手法を選べば、問題の性質によらず最良の結果が得られる","アルゴリズムの比較は定理によって無意味とされているため、手法は無作為に選ぶのが最善である","ベンチマークの平均成績が最良だった手法は、あらゆる未知の問題でも最良になる","万能の手法は存在しないため、手法の優劣は問題の性質に依存する。対象の問題の構造やデータの特性に合った手法や設定を選ぶことが重要になる"],"answer":3,"explanation":"ノーフリーランチの定理が示すのは、あらゆる問題で最良となる手法や設定は存在しないということであり、比較そのものが無意味になるわけではない。むしろ、手法の優劣は「その手法の前提が、対象の問題の構造にどれだけ合っているか」で決まるため、問題やデータの特性を見て手法やハイパーパラメータを選ぶ作業が重要になる。ベンチマークでの平均成績は、そのベンチマークに含まれる問題の範囲での話であり、性質の異なる未知の問題への保証にはならない。新しさも優劣の根拠にはならない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-77","exam":"g","unit":"g-u4","keyword":"AdaDelta","type":"choice","syllabus_ref":"4.6","stem":"AdaDelta の説明として、正しいものはどれか。","choices":["モーメンタムに学習率の動的な上限と下限を設け、学習の進行に合わせて通常の勾配降下法へ移行させる手法である","勾配の符号だけを使って、すべてのパラメータを一定の大きさで更新する手法である","AdaGrad の発展で、勾配の二乗の移動平均に加えてパラメータの更新量の二乗の移動平均も使うことで、学習率をあらかじめ設定しなくても更新量を決められるようにした手法である","エポックが進むごとに学習率を指数的に減衰させるだけの手法である"],"answer":2,"explanation":"AdaDelta は AdaGrad の改良として提案された適応的手法である。AdaGrad には、勾配の二乗和を全期間にわたって蓄積するため実効的な学習率が単調に小さくなり続ける欠点があった。AdaDelta は、蓄積を直近の勾配を重視する移動平均に改め、さらにパラメータの更新量自体の二乗の移動平均も使って更新量を決める。これにより、更新量の大きさの単位がパラメータに合う形になり、初期の学習率をあらかじめ設定する必要がなくなった。学習率に動的な上限・下限を設けるのは AdaBound の発想であり、勾配の符号だけを使う方法とも異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g4-78","exam":"g","unit":"g-u4","keyword":"モーメンタム","type":"choice","syllabus_ref":"4.6","stem":"モーメンタムによる更新で、速度 v を「v ← 0.9×v − 0.1×勾配」という規則で更新するものとする。前回の速度が 2.0、今回の勾配が 1.0 のとき、新しい速度 v の値を求めよ。","choices":["1.9","1.7","2.1","-1.7"],"answer":1,"explanation":"規則に数値を当てはめると、v ← 0.9×2.0 − 0.1×1.0 = 1.8 − 0.1 = 1.7 となる。1.9 は勾配の項の符号を取り違えた値（1.8 + 0.1）、2.1 は前回の速度への減衰（0.9倍）を掛け忘れて符号も取り違えた値（2.0 + 0.1）、-1.7 は全体の符号を取り違えた値である。モーメンタムでは、前回の速度を減衰させて引き継ぐことで過去の更新の向きが蓄積され、今回の勾配による修正が加わる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目4「ディープラーニングの概要」中項目16「最適化手法」"},{"id":"g5-01","exam":"g","unit":"g-u5","keyword":"重み","type":"choice","syllabus_ref":"5.1","stem":"全結合層の説明として、正しいものはどれか。","choices":["前の層のすべてのユニットと次の層のすべてのユニットが結合し、それぞれの結合に重みが割り当てられる層である","前の層の一部のユニットだけが、次の層のユニットと結合する層である","入力データをそのまま次の層へ渡し、重みによる計算を行わない層である","すべての結合で同じ1つの重みを共有し、結合ごとに異なる重みを持たない層である"],"answer":0,"explanation":"全結合層は、隣り合う層のユニットがすべて結ばれ、各結合に固有の重みが割り当てられる層である。一部のユニットだけと結ぶのは部分結合であり、重みを共有する仕組みは畳み込み層などで使われるもので、全結合層の特徴ではない。重みによる計算を行わない層でもない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-02","exam":"g","unit":"g-u5","keyword":"線形関数","type":"choice","syllabus_ref":"5.1","stem":"全結合層が行う計算として、正しいものはどれか。","choices":["入力の中から最大値を取り出す計算である","各入力に、入力ごとの重みを掛けて合計し、バイアスを加えるという線形関数の計算である","入力同士を掛け合わせた値を合計する計算である","入力を小さい順に並べ替える計算である"],"answer":1,"explanation":"全結合層の各出力は、y = w1x1 + w2x2 + … + b という線形関数で表される。各入力に重みを掛けた和にバイアスを加えたものであり、入力同士の積のような非線形な項は含まれない。最大値の取り出しはプーリング層の操作である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-03","exam":"g","unit":"g-u5","keyword":"重み","type":"choice","syllabus_ref":"5.1","stem":"入力が4ユニット、出力が3ユニットの全結合層がある。この層の重みの総数はどれか。","choices":["7個","4個","12個","3個"],"answer":2,"explanation":"全結合層では、入力の各ユニットと出力の各ユニットの組み合わせすべてに重みが1つずつあるため、4×3＝12個になる。7個は入力と出力のユニット数を足した値であり、全結合の数え方ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-04","exam":"g","unit":"g-u5","keyword":"線形関数","type":"choice","syllabus_ref":"5.1","stem":"全結合層の1つの出力ユニットが、2つの入力 x1=4、x2=1 に対して重み w1=0.5、w2=3、バイアス b=−2 を持つとする。このユニットの出力（線形関数の値）はどれか。","choices":["5","7","1","3"],"answer":3,"explanation":"出力は w1×x1 + w2×x2 + b = 0.5×4 + 3×1 − 2 = 2 + 3 − 2 = 3 である。5はバイアスを加えなかった値、7はバイアスの符号を取り違えた値、1はバイアスを2回引いた値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-05","exam":"g","unit":"g-u5","keyword":"重み","type":"choice","syllabus_ref":"5.1","stem":"入力が100ユニット、出力が10ユニットの全結合層がある。出力の各ユニットにバイアスがあるとき、この層の学習対象パラメータ（重みとバイアス）の総数はどれか。","choices":["1,010個","1,000個","110個","100個"],"answer":0,"explanation":"重みは入力と出力の組み合わせの数だけあり 100×10＝1,000個、バイアスは出力ユニットごとに1つずつで10個ある。合計は1,010個である。1,000個はバイアスを数え忘れた値、110個はユニット数を足した値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-06","exam":"g","unit":"g-u5","keyword":"線形関数","type":"choice","syllabus_ref":"5.1","stem":"全結合層の計算にバイアスを加える理由として、正しいものはどれか。","choices":["バイアスを加えることで、重みの総数を減らすことができるから","バイアスがないと、入力がすべて0のとき出力も必ず0になり、表せる関係が原点を通るものに限られてしまう。バイアスによって出力全体をずらすことができ、表せる関係の幅が広がるから","バイアスを加えることで、計算を非線形にできるから","バイアスは重みの初期値を決めるための値であり、学習では更新されないから"],"answer":1,"explanation":"バイアスは線形関数の定数項であり、出力全体を上下にずらす働きをする。バイアスがなければ、入力がすべて0のとき出力も0になる関係しか表せない。なお、バイアスを加えても計算は線形のままである。また、バイアスも重みと同じく学習によって更新されるパラメータである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-07","exam":"g","unit":"g-u5","keyword":"重み","type":"choice","syllabus_ref":"5.1","stem":"入力784ユニットから、隠れ層128ユニット、出力10ユニットへと、全結合層を2つ重ねたネットワークがある。各層の出力ユニットにバイアスがあるとき、学習対象パラメータの総数はどれか。","choices":["100,480個","101,632個","101,770個","101,908個"],"answer":2,"explanation":"1つ目の層は、重みが 784×128＝100,352個、バイアスが128個で、合計100,480個。2つ目の層は、重みが 128×10＝1,280個、バイアスが10個で、合計1,290個。全体では 100,480 + 1,290 = 101,770個になる。101,632個はバイアスを数え忘れた値、100,480個は1つ目の層だけを数えた値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-08","exam":"g","unit":"g-u5","keyword":"重み","type":"choice","syllabus_ref":"5.1","stem":"ニューラルネットワークにおける「重み」の説明として、正しいものはどれか。","choices":["重みは、学習の前に人が1つずつ決める値であり、学習では変わらない","重みは、訓練データそのものを数値化したものである","重みは、ネットワークの層の数を表す値である","重みは、結合ごとに割り当てられた数値で、各入力が次のユニットの値にどれだけ影響するかを表し、学習によってデータから自動的に調整される"],"answer":3,"explanation":"重みは、あるユニットの値が次のユニットの値に影響する強さを表す数値で、結合ごとに存在する。学習では、誤差が小さくなるよう重みが自動的に調整されていく。人が学習前に設定するのは、学習率のようなハイパーパラメータである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-09","exam":"g","unit":"g-u5","keyword":"線形関数","type":"choice","syllabus_ref":"5.1","stem":"全結合層（線形関数の計算）だけを何層も重ねたネットワークについて、正しいものはどれか。","choices":["線形関数の合成は、全体として1つの線形関数にまとめられるため、層を重ねても入力と出力の線形な関係しか表せず、複雑なパターンを表すには活性化関数のような非線形な処理が必要になる","層を重ねるごとに表せる関係が複雑になり、線形関数のままでも曲線的な境界を表せるようになる","線形関数を重ねると、重みの総数が層の数に応じて減っていく","線形関数だけのネットワークは、学習そのものができない"],"answer":0,"explanation":"線形関数を合成した結果は、再び1つの線形関数になる（重み行列同士の積にまとめられる）。そのため、全結合層だけをどれだけ重ねても、全体としては1層の線形関数と同じ範囲の関係しか表せない。深いネットワークで複雑なパターンを表せるのは、層の間に非線形な活性化関数が挟まるためである。なお、線形な関係の学習自体は可能であり、「学習できない」わけではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-10","exam":"g","unit":"g-u5","keyword":"重み","type":"choice","syllabus_ref":"5.1","stem":"100×100ピクセルの画像を、ピクセルを並べた10,000個の入力として、出力1,000ユニットの全結合層に直接入力する。この層の重みの総数はどれか。","choices":["11,000個","1,000万個","100万個","10,000個"],"answer":1,"explanation":"全結合層の重みの数は、入力の数×出力の数で決まるため、10,000×1,000＝1,000万個にもなる。全結合層は入力が大きくなるほどパラメータが膨らむ性質があり、高次元の入力をそのまま扱うとパラメータ数が膨大になる点が課題になる。11,000個は入力と出力の数を足した値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-11","exam":"g","unit":"g-u5","keyword":"線形関数","type":"choice","syllabus_ref":"5.1","stem":"画像分類のニューラルネットワークで、最後に置かれる全結合層の役割として、正しいものはどれか。","choices":["画像の解像度を上げて、細部を補うこと","訓練データ全体を保持し、新しい入力と照らし合わせること","それまでの層が抽出した特徴をすべて組み合わせ、各クラス（分類先）に対応するスコアを計算して、最終的な分類の判断材料を作ること","学習率を自動的に調整すること"],"answer":2,"explanation":"全結合層は、前の層のすべての出力を受け取り、それらを重み付きで組み合わせて次の値を計算する。分類を行うネットワークの最後では、クラスごとのスコアを出す層として置かれ、それまでの層が抽出した特徴を最終的な判断へ統合する役割を担う。学習率の調整は最適化手法の役割である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-12","exam":"g","unit":"g-u5","keyword":"線形関数","type":"choice","syllabus_ref":"5.1","stem":"連続した数値を予測する回帰タスクのニューラルネットワークについて、正しいものはどれか。","choices":["回帰タスクでは、出力層に全結合層を使うことはできない","回帰タスクの出力層では、予測値を必ず0か1のどちらかに丸める必要がある","回帰タスクでは重みを使わず、バイアスだけで予測値を決める","出力層の全結合層は、入力の重み付き和にバイアスを加えた線形関数の値を、そのまま予測値として出すことができ、連続した数値の予測に向く"],"answer":3,"explanation":"全結合層の出力は線形関数の値であり、連続した数値をそのまま表せる。そのため回帰タスクでは、出力層の全結合層が計算した値を予測値として直接使う形が基本になる。値を0か1に丸めるのは分類タスク側の扱いであり、回帰では行わない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目17「全結合層」"},{"id":"g5-13","exam":"g","unit":"g-u5","keyword":"畳み込み操作","type":"choice","syllabus_ref":"5.2","stem":"畳み込み層で行われる「畳み込み操作」の説明として、正しいものはどれか。","choices":["小さな重みのまとまり（フィルタ）を入力の上で少しずつずらしながら重ねていき、各位置で、重なった入力の値と重みの積の和を計算して、出力の1つの値を得る操作である","入力のすべての要素に、それぞれ異なる重みを1回だけ掛けて合計し、出力全体を一度に計算する操作である","入力の中から、一定の範囲ごとに最大値を取り出す操作である","入力の値を大きい順に並べ替える操作である"],"answer":0,"explanation":"畳み込み操作は、フィルタを入力の上でずらしながら、各位置で局所的な積和（重み付きの合計）を計算する操作である。最大値を取り出すのはプーリング層の操作である。また、入力の位置ごとに異なる重みを使うのは全結合層の計算であり、畳み込み操作では同じフィルタをすべての位置で使い回す点が異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-14","exam":"g","unit":"g-u5","keyword":"フィルタ","type":"choice","syllabus_ref":"5.2","stem":"畳み込み層における「フィルタ」の説明として、正しいものはどれか。","choices":["フィルタは、入力データのノイズを取り除くために、学習の前に人が固定する値である","フィルタは、入力の中から特定のパターン（画像の輪郭など）が現れているかを検出するための重みのまとまりであり、その値は学習によって調整される","フィルタは、出力の大きさを決めるためだけの値であり、学習では変化しない","フィルタは、入力データを圧縮して保存するための形式である"],"answer":1,"explanation":"フィルタは、畳み込み操作で入力に重ねる重みのまとまりで、輪郭のような特定の特徴に反応するよう、学習を通じて値が調整されていく。出力の大きさを決めるのはカーネルサイズやストライド、パディングの設定であり、フィルタそのものではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-15","exam":"g","unit":"g-u5","keyword":"特徴マップ","type":"choice","syllabus_ref":"5.2","stem":"畳み込み層の出力である「特徴マップ」の説明として、正しいものはどれか。","choices":["特徴マップは、入力画像そのものを縮小したものである","特徴マップは、フィルタの重みの値を並べた表である","特徴マップは、1つのフィルタを入力の各位置に適用した結果を並べたもので、入力のどの位置に、そのフィルタが検出する特徴が現れたかを示す。フィルタ1つにつき1枚の特徴マップが得られる","特徴マップは、学習に使う画像の一覧表である"],"answer":2,"explanation":"特徴マップは、畳み込み操作の出力であり、フィルタが検出する特徴が入力の各位置にどれだけ現れたかを表す。フィルタの数だけ特徴マップが得られ、それらが次の層への入力になる。フィルタの重みそのものや、入力画像の縮小版ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-16","exam":"g","unit":"g-u5","keyword":"畳み込みニューラルネットワーク (CNN)","type":"choice","syllabus_ref":"5.2","stem":"畳み込みニューラルネットワーク（CNN）の説明として、正しいものはどれか。","choices":["時系列データを扱うために、過去の出力を再び入力に戻す構造を持つネットワークである","すべての層が全結合層で構成され、画像を1列に並べて入力するネットワークである","文章の生成だけに使われるネットワークである","畳み込み層を中心に構成され、画像の局所的な特徴を段階的に捉えていくことで、画像認識などで高い性能を発揮するネットワークである"],"answer":3,"explanation":"CNNは、畳み込み層やプーリング層を組み合わせて構成されるネットワークで、画像の輪郭のような局所的な特徴から、より全体的な特徴へと段階的に捉えていく。過去の出力を入力に戻す構造はリカレントニューラルネットワーク（RNN）のものである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-17","exam":"g","unit":"g-u5","keyword":"カーネル","type":"choice","syllabus_ref":"5.2","stem":"畳み込み層における「カーネルサイズ」の説明として、正しいものはどれか。","choices":["カーネルサイズは、畳み込み層で使うフィルタの個数を表す","カーネルサイズは、入力データ全体の大きさを表す","カーネルサイズは、1回の畳み込み操作で一度に見る入力の範囲の大きさ（縦×横）を表す。例えば3×3のカーネルでは、ある位置を中心とする3×3の範囲の入力と重みから、出力の1つの値が計算される","カーネルサイズは、学習を行う回数を表す"],"answer":2,"explanation":"カーネルは、フィルタを構成する重みの行列であり、その縦×横の大きさがカーネルサイズである。カーネルサイズが大きいほど、1回の操作で見渡す入力の範囲は広くなる。フィルタの個数は、得られる特徴マップの枚数を決めるものであり、カーネルサイズとは別の設定である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-18","exam":"g","unit":"g-u5","keyword":"ストライド","type":"choice","syllabus_ref":"5.2","stem":"8×8の入力に、3×3のカーネルを、パディングなし、ストライド2で適用する。出力（特徴マップ）の一辺の大きさはどれか。なお、割り切れない場合は切り捨てる。","choices":["6","4","2","3"],"answer":3,"explanation":"ストライドは、カーネルをずらす間隔である。出力の一辺の大きさは、（入力の一辺 − カーネルサイズ）をストライドで割って切り捨て、1を加えたものになるため、（8 − 3）÷ 2 = 2.5 を切り捨てた2に1を加えて3になる。6はストライドを1として計算した値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-19","exam":"g","unit":"g-u5","keyword":"パディング","type":"choice","syllabus_ref":"5.2","stem":"5×5の入力に、3×3のカーネルを、ストライド1で適用する。入力の周囲に幅1のゼロパディング（値0で縁を埋める）を加えた場合、出力の一辺の大きさはどれか。","choices":["5","3","7","4"],"answer":0,"explanation":"ゼロパディングを幅1で加えると、入力は7×7として扱われるため、出力の一辺は 7 − 3 + 1 = 5 となり、元の入力と同じ大きさに保たれる。3はパディングをしなかった場合の大きさである。パディングには、出力の大きさを保つ働きのほか、入力の縁の部分もカーネルの中心に来られるようにする働きがある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-20","exam":"g","unit":"g-u5","keyword":"畳み込みニューラルネットワーク (CNN)","type":"choice","syllabus_ref":"5.2","stem":"画像を入力する場合の、全結合層と畳み込み層の違いとして、正しいものはどれか。","choices":["畳み込み層は、入力の位置ごとに異なる重みを使うため、全結合層よりパラメータ数が多くなる","畳み込み層は、同じフィルタ（重みのまとまり）を入力のすべての位置で共有し、局所的な範囲だけを見るため、全結合層に比べてパラメータ数が大幅に少なく、特徴が現れる位置のずれにも対応しやすい","全結合層は画像の局所的な特徴を捉えるのに向いており、畳み込み層は画像全体を一度に見る","畳み込み層では重みが学習されず、全結合層でのみ重みが学習される"],"answer":1,"explanation":"全結合層は、入力のすべての要素と出力のすべての要素の組み合わせごとに重みを持つため、画像のような大きな入力ではパラメータ数が膨大になる。畳み込み層は、1つのフィルタをすべての位置で共有し（重み共有）、局所的な範囲だけを見るため、パラメータ数が大幅に少なくなる。また、同じフィルタで全体を走査するため、特徴の位置が多少ずれても検出できる。畳み込み層の重みも、全結合層と同じく学習される。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-21","exam":"g","unit":"g-u5","keyword":"Atrous Convolution","type":"choice","syllabus_ref":"5.2","stem":"Atrous Convolution の説明として、正しいものはどれか。","choices":["入力のチャンネルごとに分離して畳み込みを行う手法である","カーネルを圧縮して、重みの数を減らす手法である","Dilated Convolution の別名であり、カーネルの要素の間に間隔（穴）を空けて入力に重ねることで、重みの数を増やさずに、一度に見渡せる範囲（受容野）を広げる手法である","パディングの一種であり、入力の周囲を0で埋める手法である"],"answer":2,"explanation":"Atrous Convolution は Dilated Convolution とも呼ばれ、カーネルの要素間に間隔を空けることで、重みの数や計算の対象を増やさずに受容野を広げる。画像の細部を保ったまま広い文脈を捉えられるため、セマンティックセグメンテーション（画像の領域分割）などで使われる。チャンネルごとに分離する手法は Depthwise Convolution である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-22","exam":"g","unit":"g-u5","keyword":"フィルタ","type":"choice","syllabus_ref":"5.2","stem":"入力が3チャンネル（RGB画像）で、3×3のカーネルを持つフィルタを16個使う畳み込み層がある。各フィルタにバイアスが1つずつあるとき、この層の学習対象パラメータの総数はどれか。","choices":["432個","448個","144個","28個"],"answer":1,"explanation":"フィルタは、入力のチャンネルごとにカーネルを持つため、1つのフィルタの重みは 3×3×3 = 27個で、バイアス1個を合わせて28個になる。フィルタが16個あるため、全体では 28 × 16 = 448個である。432個はバイアスを数え忘れた値、144個は入力チャンネル数を掛け忘れた値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-23","exam":"g","unit":"g-u5","keyword":"Dilated Convolution","type":"choice","syllabus_ref":"5.2","stem":"Dilated Convolution で、カーネルサイズ3×3、膨張率（dilation rate）を2として適用する。このカーネルが実際に見渡す範囲（実効的なカーネルサイズ）の一辺はどれか。","choices":["3","6","7","5"],"answer":3,"explanation":"膨張率2では、カーネルの隣り合う要素の間に1つずつ間隔が入るため、実効的な一辺の大きさは、（カーネルサイズ − 1）× 膨張率 + 1 = （3 − 1）× 2 + 1 = 5 になる。重みの数そのものは3×3 = 9個のままで増えていない。6はカーネルサイズに膨張率をそのまま掛けた値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-24","exam":"g","unit":"g-u5","keyword":"Depthwise Separable Convolution","type":"choice","syllabus_ref":"5.2","stem":"Depthwise Separable Convolution の説明として、正しいものはどれか。","choices":["通常の畳み込みを、入力のチャンネルごとに空間方向の畳み込みを行う Depthwise Convolution と、1×1の畳み込みでチャンネル方向を混ぜ合わせる Pointwise Convolution の2段階に分けることで、計算量とパラメータ数を大幅に削減する手法である","カーネルの要素の間に間隔を空けて、受容野を広げる手法である","複数の異なる大きさのカーネルを、並列に適用する手法である","畳み込みの後にプーリングを必ず組み合わせる手法である"],"answer":0,"explanation":"Depthwise Separable Convolution は、空間方向の畳み込みとチャンネル方向の混合を分離することで、通常の畳み込みより計算量とパラメータ数を大幅に減らす手法であり、MobileNet のような軽量なモデルで使われる。カーネルに間隔を空けるのは Dilated Convolution である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目18「畳み込み層」"},{"id":"g5-25","exam":"g","unit":"g-u5","keyword":"バッチ正規化","type":"choice","syllabus_ref":"5.3","stem":"バッチ正規化（Batch Normalization）の説明として、正しいものはどれか。","choices":["入力データを学習の前に一度だけ、平均0・分散1に変換しておく前処理である","学習の過程で、各層への入力（中間層の出力）をミニバッチごとに平均0・分散1になるよう正規化し、さらに学習可能なパラメータによってスケールとシフトを行う手法である","重みの大きさを小さく抑えることで、過学習を防ぐ手法である","勾配の大きさが一定の値を超えたら切り取ることで、勾配爆発を防ぐ手法である"],"answer":1,"explanation":"バッチ正規化は、学習の過程で、層への入力をミニバッチ単位で正規化し、スケール（γ）とシフト（β）という学習可能なパラメータで表現力を調整する手法である。学習前に一度だけ行う標準化（前処理）とは異なり、学習中、各層で行われる。重みの大きさを抑えるのは正則化、勾配を切り取るのは勾配クリッピングである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-26","exam":"g","unit":"g-u5","keyword":"バッチ正規化","type":"choice","syllabus_ref":"5.3","stem":"バッチ正規化では、ある特徴について、ミニバッチ内の値の平均を引き、その特徴の標準偏差で割ることで正規化する。ミニバッチ内のある特徴の値が 1 と 5 の2つだけであるとき、値 5 を正規化した結果はどれか。なお、標準偏差は、平均からのずれの二乗の平均（分散）の平方根とする。","choices":["2","0.5","1","-1"],"answer":2,"explanation":"平均は (1 + 5) ÷ 2 = 3、分散は ((1 − 3)² + (5 − 3)²) ÷ 2 = 4 となり、標準偏差は2である。よって、値5を正規化した結果は (5 − 3) ÷ 2 = 1 になる。2は標準偏差で割り忘れた値、-1は値1を正規化した結果である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-27","exam":"g","unit":"g-u5","keyword":"バッチ正規化","type":"choice","syllabus_ref":"5.3","stem":"バッチ正規化について、学習時と推論時（予測時）の扱いの違いとして、正しいものはどれか。","choices":["学習時はそのミニバッチの平均と分散を使って正規化するが、推論時は、学習の過程で蓄積した平均と分散の移動平均（データ全体の統計量の推定値）を使って正規化する","学習時も推論時も、常に入力されたミニバッチの平均と分散を使って正規化する","推論時には正規化は行わず、スケールとシフトだけを行う","学習時はデータ全体の統計量を使い、推論時はそのミニバッチの統計量を使う"],"answer":0,"explanation":"推論時は、1件だけの予測などミニバッチが組めない場合もあり、そのミニバッチの統計量を使うと予測が入力の組み合わせに左右されてしまう。そのため、推論時には学習時に蓄積した移動平均（平均と分散）を使って正規化する。これが、バッチ正規化の学習時と推論時で動作が異なる点である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-28","exam":"g","unit":"g-u5","keyword":"バッチ正規化","type":"choice","syllabus_ref":"5.3","stem":"バッチ正規化をはじめとする正規化層が、ディープラーニングの学習にもたらす効果として、正しいものはどれか。","choices":["学習データの量を増やすことで、過学習を防ぐ","パラメータの数を減らすことで、計算量を削減する","誤差逆伝播の計算そのものを省略することで、学習を高速化する","各層への入力の分布が、学習の進行とともに大きくずれていくのを抑えて分布を安定させることで、学習を安定させ、速く進められるようにする"],"answer":3,"explanation":"学習が進むと下の層のパラメータが変わり、上の層への入力の分布もずれていく。正規化層は各層の入力を正規化して分布を安定させるため、学習が安定し、より大きな学習率を使うなど学習を速く進めやすくなる。学習データを増やすのはデータ拡張、パラメータ数を減らすのは軽量化の手法であり、正規化層の役割ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-29","exam":"g","unit":"g-u5","keyword":"バッチ正規化","type":"choice","syllabus_ref":"5.3","stem":"バッチ正規化では、正規化した値に対して、特徴（チャンネル）ごとにスケール（γ）とシフト（β）という2種類の学習可能なパラメータを適用する。特徴数が32である層にバッチ正規化を適用する場合、スケールとシフトのパラメータの総数はどれか。","choices":["32個","64個","96個","1,024個"],"answer":1,"explanation":"スケール（γ）とシフト（β）は特徴ごとに1つずつあるため、32 × 2 = 64個になる。32個は、どちらか一方だけを数えた値である。なお、推論時に使う平均と分散の移動平均も保持されるが、これらは学習で更新されるパラメータではなく、学習対象のパラメータには数えない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-30","exam":"g","unit":"g-u5","keyword":"レイヤー正規化","type":"choice","syllabus_ref":"5.3","stem":"レイヤー正規化（Layer Normalization）の説明として、正しいものはどれか。","choices":["ミニバッチ全体について、特徴ごとに平均と分散を求めて正規化する手法である","すべての層の重みを、1つの同じ値にそろえる手法である","1つのデータ（サンプル）について、その特徴の方向（その層のニューロン全体）にわたって平均と分散を求め、正規化する手法である","学習率を層ごとに自動で調整する手法である"],"answer":2,"explanation":"レイヤー正規化は、1つのサンプルごとに、そのサンプルの特徴全体（層のニューロンの出力全体）から平均と分散を求めて正規化する。そのため、ミニバッチ内の他のサンプルに依存しない。ミニバッチ全体で特徴ごとに統計量を取るのはバッチ正規化である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-31","exam":"g","unit":"g-u5","keyword":"レイヤー正規化","type":"choice","syllabus_ref":"5.3","stem":"バッチ正規化とレイヤー正規化の違いとして、正しいものはどれか。","choices":["バッチ正規化は学習が必要だが、レイヤー正規化には学習される要素が一切ない","バッチ正規化は画像にしか使えず、レイヤー正規化は文章にしか使えない","レイヤー正規化はミニバッチの平均を使い、バッチ正規化はサンプルごとの平均を使う","バッチ正規化は、同じ特徴を複数のサンプルにわたって統計量を取り、レイヤー正規化は、1つのサンプルの特徴の方向に統計量を取る。そのため、レイヤー正規化はバッチサイズの大きさに影響されない"],"answer":3,"explanation":"2つの手法の本質的な違いは、平均と分散をどの方向に取るかである。バッチ正規化はミニバッチの方向に統計量を取るため、バッチサイズが小さいと統計量が不安定になる。レイヤー正規化はサンプル内の特徴の方向に取るため、バッチサイズに依存せず、系列データを扱うモデル（RNNやTransformer）でも使いやすい。レイヤー正規化にも、スケールとシフトの学習可能なパラメータはある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-32","exam":"g","unit":"g-u5","keyword":"グループ正規化","type":"choice","syllabus_ref":"5.3","stem":"グループ正規化（Group Normalization）の説明として、正しいものはどれか。","choices":["チャンネルをいくつかのグループに分け、1つのサンプルについて、グループごとに、グループ内のチャンネルと空間方向にわたって平均と分散を求めて正規化する手法である","複数のモデルを1つのグループとしてまとめて学習する手法である","学習データをグループに分けて、グループごとに別のモデルを学習する手法である","重みをグループごとに同じ値に固定する手法である"],"answer":0,"explanation":"グループ正規化は、チャンネルをグループに分けて統計量を取る、バッチ正規化とレイヤー正規化の中間的な手法である。グループの数を極端に変えると、すべてのチャンネルを1グループにした場合はレイヤー正規化に近づき、1チャンネルずつのグループに分けた場合はインスタンス正規化と一致する。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-33","exam":"g","unit":"g-u5","keyword":"グループ正規化","type":"choice","syllabus_ref":"5.3","stem":"グループ正規化が提案された背景と利点として、正しいものはどれか。","choices":["バッチ正規化は計算量が多すぎるため、それを削減することが目的である","バッチ正規化は画像に適用できないため、その代替として提案された","バッチ正規化は、バッチサイズが小さいとミニバッチの統計量が不安定になり、精度が落ちるという問題がある。グループ正規化はバッチの方向に統計量を取らないため、バッチサイズが小さくても安定して使える","グループ正規化には、学習データを自動的に増やす効果がある"],"answer":2,"explanation":"物体検出やセマンティックセグメンテーションでは、画像が大きくメモリの制約が厳しいため、バッチサイズを大きくできないことが多い。そのような場面ではバッチ正規化の統計量が不安定になる。グループ正規化はバッチ方向に依存しないため、小さいバッチサイズでもバッチ正規化の代替として安定して使える。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-34","exam":"g","unit":"g-u5","keyword":"インスタンス正規化","type":"choice","syllabus_ref":"5.3","stem":"インスタンス正規化（Instance Normalization）の説明として、正しいものはどれか。","choices":["ミニバッチ全体の平均と分散を求めて正規化する手法である","1つのサンプル・1つのチャンネルごとに、その空間方向（画像なら縦×横の位置全体）にわたって平均と分散を求めて正規化する手法である","画像の中のインスタンス（物体）ごとに領域を切り出して学習する手法である","重みの初期値をサンプルごとに変える手法である"],"answer":1,"explanation":"インスタンス正規化は、サンプルごと・チャンネルごとに統計量を取る最も細かい単位の正規化であり、グループ正規化でチャンネルを1つずつのグループに分けた場合と一致する。ミニバッチ全体で統計量を取るのはバッチ正規化である。「インスタンス」は物体検出のインスタンスではなく、個々のデータ（サンプル）を指す。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-35","exam":"g","unit":"g-u5","keyword":"インスタンス正規化","type":"choice","syllabus_ref":"5.3","stem":"インスタンス正規化が、スタイル変換（画風変換）のような画像生成のタスクでよく使われる理由として、正しいものはどれか。","choices":["サンプルごと・チャンネルごとに正規化することで、各画像のコントラストのような、見た目の統計的な特徴（スタイル）の影響を取り除くため、内容を保ったまま画風を変えやすくなる","計算が最も速いため、画像の生成速度を上げることができる","バッチサイズが必ず1になるため、学習が安定する","生成される画像の解像度を、自動的に上げることができる"],"answer":0,"explanation":"画像のコントラストなどの見た目の特徴は、各チャンネルの平均や分散といった統計量に現れる。インスタンス正規化はサンプルごとにそれらを取り除くため、画像の内容とスタイルを分離しやすくなり、スタイル変換で使われる。バッチサイズを1に固定する仕組みではなく、解像度を上げる働きもない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-36","exam":"g","unit":"g-u5","keyword":"バッチ正規化・レイヤー正規化・グループ正規化・インスタンス正規化","type":"choice","syllabus_ref":"5.3","stem":"バッチ正規化、レイヤー正規化、グループ正規化、インスタンス正規化の使い分けとして、正しいものはどれか。","choices":["バッチサイズを十分に大きくできる画像分類ではレイヤー正規化が標準であり、系列データを扱うモデルではバッチ正規化が標準である","4つの手法は正規化する方向がすべて同じであり、計算速度の速さだけで選べばよい","グループ正規化は、バッチサイズが大きい場合にのみ有効であり、小さい場合には使えない","バッチサイズを大きくできる場合はバッチ正規化、バッチサイズに依存させたくない場合や系列データではレイヤー正規化、バッチサイズが小さい画像タスクではグループ正規化、というように、統計量を取る方向とバッチサイズへの依存の違いによって使い分ける"],"answer":3,"explanation":"4つの手法の違いは、平均と分散をどの範囲で取るか（バッチ方向／サンプル内の特徴方向／チャンネルのグループ内／サンプル・チャンネルごと）にある。バッチ正規化はバッチサイズが十分に大きい場合に有効で、レイヤー正規化はバッチサイズに依存しないため系列データのモデルで広く使われる。グループ正規化は、バッチサイズが小さい画像タスクでバッチ正規化の代替になる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目19「正規化層」"},{"id":"g5-37","exam":"g","unit":"g-u5","keyword":"最大値プーリング","type":"choice","syllabus_ref":"5.4","stem":"最大値プーリング（Max Pooling）の説明として、正しいものはどれか。","choices":["特徴マップ全体の中で最も大きい値を1つだけ取り出す操作である","特徴マップを小さな領域（窓）に区切り、各領域の中で最も大きい値を取り出して、その領域の代表値とする操作である","特徴マップの各領域について、値の平均を代表値とする操作である","重みの中で最も大きいものを選んで残し、それ以外を0にする操作である"],"answer":1,"explanation":"最大値プーリングは、特徴マップを2×2などの小さな領域に区切り、領域ごとの最大値を代表値として取り出すことで、特徴マップを縮小する操作である。各領域の平均を取るのは平均値プーリング、特徴マップ全体を1つの値に集約するのはグローバルプーリングである。重みを対象とする操作ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-38","exam":"g","unit":"g-u5","keyword":"最大値プーリング","type":"choice","syllabus_ref":"5.4","stem":"次の4×4の特徴マップに、2×2の最大値プーリングをストライド2（窓を2ずつずらす）で適用する。出力される2×2の値を、左上・右上・左下・右下の順に並べたものはどれか。特徴マップの値は、1行目が「1, 3, 2, 0」、2行目が「5, 2, 1, 4」、3行目が「0, 1, 6, 2」、4行目が「2, 0, 3, 7」である。","choices":["3, 4, 2, 7","5, 2, 2, 7","5, 4, 2, 7","5, 4, 2, 6"],"answer":2,"explanation":"2×2の窓ごとの最大値を取る。左上（1, 3, 5, 2）の最大値は5、右上（2, 0, 1, 4）の最大値は4、左下（0, 1, 2, 0）の最大値は2、右下（6, 2, 3, 7）の最大値は7である。よって出力は 5, 4, 2, 7 となる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-39","exam":"g","unit":"g-u5","keyword":"最大値プーリング","type":"choice","syllabus_ref":"5.4","stem":"32×32の特徴マップに、プールサイズ2×2、ストライド2、パディングなしの最大値プーリングを適用する。出力の特徴マップの一辺の大きさはどれか。","choices":["16","32","30","8"],"answer":0,"explanation":"出力の一辺は (入力の一辺 − プールサイズ) ÷ ストライド + 1 で求められ、(32 − 2) ÷ 2 + 1 = 16 になる。プールサイズとストライドがともに2の場合、縦・横はそれぞれ半分になり、面積は4分の1になる。30はストライドで割り忘れた値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-40","exam":"g","unit":"g-u5","keyword":"平均値プーリング","type":"choice","syllabus_ref":"5.4","stem":"平均値プーリング（Average Pooling）の説明として、正しいものはどれか。","choices":["特徴マップ全体の平均を計算し、1つの値に集約する操作である","特徴マップの各領域について、中央値を代表値とする操作である","特徴マップの各領域について、最も大きい値を代表値とする操作である","特徴マップを小さな領域（窓）に区切り、各領域の値の平均を、その領域の代表値とする操作である"],"answer":3,"explanation":"平均値プーリングは、領域ごとの平均を代表値として特徴マップを縮小する操作である。特徴マップ全体を1つの値に集約するのはグローバルアベレージプーリング、領域の最大値を取るのは最大値プーリングである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-41","exam":"g","unit":"g-u5","keyword":"平均値プーリング","type":"choice","syllabus_ref":"5.4","stem":"次の4×4の特徴マップに、2×2の平均値プーリングをストライド2で適用する。右下の領域（3〜4行目、3〜4列目）について出力される値はどれか。特徴マップの値は、1行目が「2, 4, 1, 3」、2行目が「6, 0, 5, 1」、3行目が「1, 2, 4, 8」、4行目が「3, 5, 2, 6」である。","choices":["8","5","4","2.5"],"answer":1,"explanation":"右下の領域の値は 4, 8, 2, 6 であり、その平均は (4 + 8 + 2 + 6) ÷ 4 = 5 になる。8は最大値プーリングを適用した場合の結果、2.5は合計を8で割ってしまった場合の値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-42","exam":"g","unit":"g-u5","keyword":"平均値プーリング","type":"choice","syllabus_ref":"5.4","stem":"平均値プーリングと最大値プーリングの違いとして、正しいものはどれか。","choices":["平均値プーリングは、最も強く反応した特徴だけを残すため、特徴の強調に向いている","平均値プーリングは学習によって更新される重みを持ち、最大値プーリングは持たない","平均値プーリングは、領域全体の値の平均的な傾向を反映するため、突出した1つの値だけに左右されず、領域全体の様子を表す。一方で、強い特徴は平均化で薄まることがある","平均値プーリングは画像にしか使えず、最大値プーリングは文章にしか使えない"],"answer":2,"explanation":"最大値プーリングは領域で最も強い反応を残すため特徴の強調に向き、平均値プーリングは領域全体の平均的な傾向を表す。どちらも学習によって更新される重みは持たない。用途はデータの種類ではなく、残したい情報の性質によって選ばれる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-43","exam":"g","unit":"g-u5","keyword":"グローバルアベレージプーリング (GAP)","type":"choice","syllabus_ref":"5.4","stem":"グローバルアベレージプーリング（GAP）の説明として、正しいものはどれか。","choices":["特徴マップごとに、その空間方向の全体（縦×横のすべての位置）にわたって平均を取り、チャンネルごとに1つの値へ集約する操作である","すべてのチャンネルと空間方向をまとめて平均し、全体で1つの値にする操作である","特徴マップごとに、空間方向全体の中で最も大きい値を取り出す操作である","2×2の領域ごとに平均を取る、通常の平均値プーリングと同じ操作である"],"answer":0,"explanation":"グローバルアベレージプーリングは、プーリングの窓を特徴マップ全体に広げたもので、チャンネル（特徴マップ）ごとに平均を1つ求める。そのため、出力はチャンネル数と同じ個数の値になる。チャンネルの方向まで平均してしまうと、特徴ごとの違いが失われてしまう。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-44","exam":"g","unit":"g-u5","keyword":"グローバルアベレージプーリング (GAP)","type":"choice","syllabus_ref":"5.4","stem":"ある畳み込み層の出力が、チャンネル数128、各特徴マップの大きさ8×8である。この出力にグローバルアベレージプーリング（GAP）を適用すると、得られる値の総数はどれか。","choices":["8,192個","64個","1,024個","128個"],"answer":3,"explanation":"GAPは特徴マップごとに平均を1つ求めるため、出力の値の総数はチャンネル数と等しく、128個になる。8,192個は適用前の値の総数（128 × 8 × 8）、64個は1枚の特徴マップの要素数（8 × 8）である。入力の縦・横の大きさが変わっても、出力はチャンネル数で決まる点がGAPの特徴である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-45","exam":"g","unit":"g-u5","keyword":"グローバルアベレージプーリング (GAP)","type":"choice","syllabus_ref":"5.4","stem":"画像分類のモデルで、畳み込み層の出力を受けて分類を行う部分に、全結合層ではなくグローバルアベレージプーリング（GAP）を用いる利点として、正しいものはどれか。","choices":["GAPは入力画像の解像度を自動的に上げて、細部を復元できる","GAP自体に学習対象のパラメータがなく、全結合層で生じる大量のパラメータを避けられるため、過学習を抑えやすい","GAPを用いると、畳み込み層そのものが不要になる","GAPを用いると、特徴マップのチャンネル数を自動的に増やすことができる"],"answer":1,"explanation":"特徴マップをそのまま全結合層へつなぐと、入力の要素数×出力の要素数だけの重みが必要になり、パラメータが膨大になって過学習の原因になる。GAPは平均を取るだけの操作で学習対象のパラメータを持たず、チャンネル数だけの出力に圧縮できるため、この問題を避けやすい。解像度を上げたりチャンネル数を増やしたりする操作ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-46","exam":"g","unit":"g-u5","keyword":"不変性の獲得","type":"choice","syllabus_ref":"5.4","stem":"プーリングによって得られる「不変性」の説明として、正しいものはどれか。","choices":["入力データの明るさが変化しても、出力がまったく変わらない性質である","学習の過程で、重みの値が変化しなくなる性質である","対象の位置が少しずれても（平行移動しても）、プーリング後の出力がほとんど変わらない性質である","画像を回転させても、出力が完全に同じになる性質である"],"answer":2,"explanation":"プーリングは小さな領域を1つの値に集約するため、特徴が領域の内側のどこにあっても、集約後の値は同じか近いものになる。これにより、対象の位置のわずかなずれに対して出力が変わりにくくなる（平行移動に対する不変性）。回転など大きな変形に対して完全に不変になるわけではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-47","exam":"g","unit":"g-u5","keyword":"不変性の獲得","type":"choice","syllabus_ref":"5.4","stem":"プーリングで位置に対する不変性が得られる仕組みと、その代償の説明として、正しいものはどれか。","choices":["学習データに位置をずらした画像を大量に加えることで得られ、代償はない","畳み込み層の重み共有によって得られ、代償として計算量が増える","プーリング後も、特徴がどこにあったかという位置情報は完全に保持される","小さな領域を1つの値に集約するため、領域の内側での位置の違いが吸収される。その代償として、特徴が正確にどこにあったかという位置情報は失われる"],"answer":3,"explanation":"不変性は、プーリングが領域内の値を1つにまとめること自体から生じる。位置をずらしたデータを加えるのはデータ拡張という別の手法であり、重み共有は畳み込み層の性質である。位置情報を捨てることが不変性の源泉であるため、正確な位置が必要なタスク（物体の位置の特定など）では、プーリングの使い方が課題になる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-48","exam":"g","unit":"g-u5","keyword":"最大値プーリング・平均値プーリング・グローバルアベレージプーリング (GAP)・不変性の獲得","type":"choice","syllabus_ref":"5.4","stem":"プーリング層の役割として、正しいものはどれか。","choices":["特徴マップを縮小（ダウンサンプリング）して後段の計算量を減らし、あわせて特徴の位置のずれに対する不変性を与える層であり、通常、学習によって更新される重みを持たない","重みを学習して、入力から特徴を抽出する層である","学習のたびに一部のニューロンを無効化して、過学習を防ぐ層である","活性化関数の出力を、合計が1になる確率の形に変換する層である"],"answer":0,"explanation":"プーリング層は、畳み込み層で得られた特徴マップを小さくまとめることで、後段の計算量を減らし、位置のずれに強い表現にする。重みを学習して特徴を抽出するのは畳み込み層、一部のニューロンを無効化するのはドロップアウト、確率の形に変換するのはソフトマックス関数である。プーリング自体は値を集約するだけの操作で、学習対象のパラメータを持たない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目20「プーリング層」"},{"id":"g5-49","exam":"g","unit":"g-u5","keyword":"スキップ結合","type":"choice","syllabus_ref":"5.5","stem":"スキップ結合（ショートカット結合）の説明として、正しいものはどれか。","choices":["ネットワークの一部の層を、学習の途中で無効化する仕組みである","隣り合う層どうしで重みを共有し、パラメータ数を減らす仕組みである","ある層の入力を、途中の層を飛び越えて後段へ直接伝え、その段の出力に加える結合である","入力データを一定の割合で捨てて、学習を安定させる仕組みである"],"answer":2,"explanation":"スキップ結合は、層の入力をそのまま後段へ伝える近道の経路を加える仕組みで、通常は後段の出力と入力を要素ごとに加算する。一部の層を無効化するのはドロップアウト、入力の一部を捨てる操作とも異なる。重みの共有は畳み込み層やリカレントネットワークの性質である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-50","exam":"g","unit":"g-u5","keyword":"スキップ結合","type":"choice","syllabus_ref":"5.5","stem":"残差ブロックの出力は、ブロック内の層の出力を F(x)、入力を x として y = F(x) + x と表される。x の各要素が (2, −1, 3)、F(x) の各要素が (0.5, 0.5, −1) のとき、出力 y の各要素はどれか。","choices":["(2.5, −0.5, 2)","(1.5, −1.5, 4)","(1, −0.5, −3)","(0.5, 0.5, −1)"],"answer":0,"explanation":"要素ごとに加算する。2 + 0.5 = 2.5、−1 + 0.5 = −0.5、3 + (−1) = 2 となり、y = (2.5, −0.5, 2) である。(1.5, −1.5, 4) は引き算をした場合、(0.5, 0.5, −1) はスキップ結合を忘れて F(x) だけを答えた場合の値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-51","exam":"g","unit":"g-u5","keyword":"スキップ結合","type":"choice","syllabus_ref":"5.5","stem":"残差ブロックでは、ブロック内の層が学習する対象は、通常どのように表されるか。","choices":["入力 x をそのまま再現すること","目的の変換 H(x) と入力 x との差（残差）F(x) = H(x) − x であり、出力は F(x) + x として得られる","出力と入力の積を最大化すること","重みの合計が常に0になるように保つこと"],"answer":1,"explanation":"残差ブロックでは、層は変換そのもの H(x) ではなく、入力からの差分である残差 F(x) = H(x) − x を学習し、出力は入力を加えて F(x) + x とする。目的の変換が恒等写像（入力そのまま）に近い場合、残差を0に近づける方が学びやすい、という考え方が背景にある。ResNet はこの「残差（residual）」の名の由来でもある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-52","exam":"g","unit":"g-u5","keyword":"スキップ結合","type":"choice","syllabus_ref":"5.5","stem":"深いネットワークにスキップ結合を入れると学習が進みやすくなる理由として、正しいものはどれか。","choices":["スキップ結合によって学習対象のパラメータが増え、表現力が高まるから","スキップ結合が学習率を自動的に調整してくれるから","各層の出力が常に0に近づくため、誤差が安定するから","入力をそのまま後段へ伝える経路があるため、誤差の勾配がその経路を通って浅い層まで届きやすく、層を深く重ねても学習が進みやすいから"],"answer":3,"explanation":"スキップ結合の出力 y = F(x) + x では、勾配の伝わりに「入力をそのまま通す経路」の分が含まれるため、F 側の勾配が小さくても、勾配が浅い層まで届きやすい。スキップ結合の加算自体は学習対象のパラメータを持たず、学習率を調整する仕組みでもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-53","exam":"g","unit":"g-u5","keyword":"スキップ結合","type":"choice","syllabus_ref":"5.5","stem":"入力と出力で特徴マップのチャンネル数や大きさが異なるブロックにスキップ結合を使いたい場合の対処として、正しいものはどれか。","choices":["要素ごとの加算ができないため、そのブロックではスキップ結合は使えない","入力側に1×1畳み込みなどを適用して、チャンネル数や大きさを出力にそろえてから加算する","出力の余分なチャンネルを切り捨ててから加算する","入力を複製してチャンネル数を2倍にしてから加算する"],"answer":1,"explanation":"要素ごとの加算には、入力と出力の形（チャンネル数・大きさ）がそろっている必要がある。形が異なる場合は、入力側に1×1畳み込みなどを適用して次元をそろえる方法（射影ショートカット）が使われる。この場合は、その畳み込みの分のパラメータが増える。切り捨てや複製では情報の対応が崩れてしまう。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-54","exam":"g","unit":"g-u5","keyword":"ResNet","type":"choice","syllabus_ref":"5.5","stem":"ResNet（Residual Network）の説明として、正しいものはどれか。","choices":["スキップ結合を持つ残差ブロックを多数積み重ねた、深いニューラルネットワークである","時系列データを扱うための、回帰結合を持つネットワークである","注意機構だけで構成され、畳み込みを使わないネットワークである","学習データを自動生成するためのネットワークである"],"answer":0,"explanation":"ResNet は、スキップ結合で入力を後段に伝える残差ブロックを積み重ねることで、従来は学習が難しかった深いネットワークを実現したモデルである。回帰結合を持つのはリカレントニューラルネットワーク（RNN）、注意機構を中心とするのは Transformer である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-55","exam":"g","unit":"g-u5","keyword":"ResNet","type":"choice","syllabus_ref":"5.5","stem":"ResNet が提案された当時の位置づけとして、正しいものはどれか。","choices":["層を浅くすることで精度を高めたモデルである","畳み込みを初めて導入したモデルである","学習データを必要としない手法である","従来は難しかった100層を超える深さ（152層）のネットワークの学習を可能にし、画像認識のコンペティション ILSVRC 2015 で優勝したモデルである"],"answer":3,"explanation":"ResNet は2015年に提案され、スキップ結合によって152層という従来より大幅に深いネットワークの学習を可能にし、ILSVRC 2015 の画像分類で優勝した。浅くしたわけではなく、畳み込み自体はそれ以前から使われていた。学習データを必要とする点は通常の教師あり学習と同じである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-56","exam":"g","unit":"g-u5","keyword":"ResNet","type":"choice","syllabus_ref":"5.5","stem":"層を単純に増やした深いネットワークでは、学習（訓練）誤差まで大きくなってしまうことがある（劣化問題）。この現象とスキップ結合の関係として、正しいものはどれか。","choices":["劣化問題は過学習の一種であり、学習データの不足が原因である","劣化問題は、深いネットワークそのものが不可能であることを示している","劣化問題は過学習ではなく最適化の難しさによるものであり、スキップ結合で恒等写像を基準に残差を学習させる形にすると、深くしても学習が進みやすくなる","劣化問題はプーリング層を増やすことで解決できる"],"answer":2,"explanation":"劣化問題は、テスト誤差ではなく学習（訓練）誤差が悪化する現象で、過学習とは別の、最適化の難しさの問題である。余分な層が恒等写像を学ぶのは難しいが、スキップ結合のある残差ブロックでは残差を0に近づければ恒等写像を表せるため、深くしても少なくとも悪化しにくい形になる。ResNet はこの問題への対処として提案された。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-57","exam":"g","unit":"g-u5","keyword":"スキップ結合","type":"choice","syllabus_ref":"5.5","stem":"残差ブロックにスキップ結合（入力と出力の要素ごとの加算）を追加したとき、この加算のために新たに増える学習パラメータの数はどれか。ただし、入力と出力の次元は同じものとする。","choices":["入力の要素数と同じ数","0個（加算だけの操作であり、学習対象の重みを持たない）","チャンネル数と同じ数","入力の要素数×出力の要素数"],"answer":1,"explanation":"スキップ結合の加算は値を足すだけの操作で、学習によって更新される重みを持たないため、増えるパラメータは0個である。入力の要素数×出力の要素数は全結合層の重みの数に当たる。ただし、入力と出力の次元が異なる場合に1×1畳み込みで次元をそろえると、その分のパラメータは増える。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-58","exam":"g","unit":"g-u5","keyword":"スキップ結合","type":"choice","syllabus_ref":"5.5","stem":"残差ブロックの出力は y = F(x) + x と表される。損失 L について dL/dy = 2、ブロック内の変換 F の x に対する勾配 dF/dx = 0.5 のとき、dL/dx はどれか。","choices":["3","1","2.5","1.5"],"answer":0,"explanation":"y = F(x) + x の x に対する勾配は dy/dx = dF/dx + 1 = 0.5 + 1 = 1.5 になる。連鎖律により dL/dx = dL/dy × dy/dx = 2 × 1.5 = 3 である。1は「+1」の経路を忘れて 2 × 0.5 とした場合の値で、この「+1」こそが、F 側の勾配が小さくても勾配が浅い層へ届く理由になっている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-59","exam":"g","unit":"g-u5","keyword":"スキップ結合","type":"choice","syllabus_ref":"5.5","stem":"スキップ結合における入力の伝え方として、正しいものはどれか。","choices":["入力と出力をチャンネル方向に連結するため、チャンネル数は両者の合計に増える","入力を出力で割り算して伝える","入力は学習のときだけ伝え、推論のときは伝えない","入力と出力を要素ごとに加算して伝えるため、加算後のチャンネル数や要素数は出力と変わらない"],"answer":3,"explanation":"スキップ結合は要素ごとの加算であり、形は出力と変わらない。チャンネル方向に連結して増やすのは、DenseNet などで使われる結合の仕方である。加算の経路は学習時だけでなく推論時にも使われる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-60","exam":"g","unit":"g-u5","keyword":"スキップ結合・ResNet","type":"choice","syllabus_ref":"5.5","stem":"スキップ結合と ResNet の役割として、正しいものはどれか。","choices":["学習データを増やすことで、深いネットワークの学習を助ける仕組みである","一部のニューロンを無効化して過学習を防ぐ仕組みである","入力を後段へ直接伝える経路によって、深いネットワークでも勾配が届きやすく学習が進みやすくなり、ResNet はこの仕組みで従来より大幅に深いネットワークを実現した","特徴マップを縮小して計算量を減らす仕組みである"],"answer":2,"explanation":"スキップ結合は、入力を後段へ伝える近道によって勾配の届きにくさを和らげ、深いネットワークの学習を可能にする仕組みであり、ResNet はその代表例である。学習データを増やすのはデータ拡張、一部のニューロンを無効化するのはドロップアウト、特徴マップの縮小はプーリング層の役割である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目21「スキップ結合」"},{"id":"g5-61","exam":"g","unit":"g-u5","keyword":"リカレントニューラルネットワーク (RNN)","type":"choice","syllabus_ref":"5.6","stem":"リカレントニューラルネットワーク (RNN) の説明として、正しいものはどれか。","choices":["画像の局所的な特徴を、重みを共有したフィルタで抽出するネットワークである","注意機構だけで系列を処理し、過去の情報を保持する仕組みを持たないネットワークである","前の時刻の隠れ層の出力などを現在の時刻の計算に取り込む回帰結合を持ち、過去の情報を保ちながら系列データを順に処理するネットワークである","学習データと似たデータを新たに生成するためのネットワークである"],"answer":2,"explanation":"RNN は、時刻をまたいで情報を戻す回帰結合を持つことが特徴で、前の時刻までの処理結果（隠れ状態）を現在の時刻に引き継ぐことで、順序のあるデータを扱う。局所特徴の抽出に重み共有のフィルタを使うのは畳み込みニューラルネットワーク（CNN）、注意機構を中心とするのは Transformer である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-62","exam":"g","unit":"g-u5","keyword":"時系列データ","type":"choice","syllabus_ref":"5.6","stem":"リカレントニューラルネットワーク (RNN) が適したデータの特性として、正しいものはどれか。","choices":["文章や音声、株価のように、要素の並ぶ順序に意味があり、系列の長さがデータごとに異なりうるデータである","要素をどの順序で並べても意味が変わらないデータである","各レコードが互いに独立で、時間の前後関係を持たない表形式のデータだけである","縦と横の大きさが常に固定された画像データだけである"],"answer":0,"explanation":"RNN は過去の情報を保持しながら要素を1つずつ順に処理するため、順序に意味があり長さが一定でない系列データ（時系列データや文章など）に適する。順序を入れ替えても意味が変わらないデータや、互いに独立なレコードの集まりでは、この仕組みの利点は生かしにくい。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-63","exam":"g","unit":"g-u5","keyword":"エルマンネットワーク・ジョルダンネットワーク","type":"choice","syllabus_ref":"5.6","stem":"初期のリカレントニューラルネットワークであるエルマンネットワークとジョルダンネットワークの違いとして、正しいものはどれか。","choices":["エルマンネットワークは出力層の出力を、ジョルダンネットワークは隠れ層の出力を、次の時刻へ戻す","エルマンネットワークは隠れ層の出力を次の時刻の隠れ層へ戻し、ジョルダンネットワークは出力層の出力を次の時刻へ戻す","どちらも隠れ層の出力を戻す点は同じで、違いは学習方法だけである","どちらも出力層の出力を戻す点は同じで、違いは層の数だけである"],"answer":1,"explanation":"両者は「どの出力を次の時刻へ戻すか」が異なる。エルマンネットワークは隠れ層の出力を戻すため、内部状態を引き継ぐ形になる。ジョルダンネットワークは出力層の出力（予測結果）を戻すため、前の時刻の出力が次の入力側に影響する形になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-64","exam":"g","unit":"g-u5","keyword":"リカレントニューラルネットワーク (RNN)","type":"choice","syllabus_ref":"5.6","stem":"あるリカレント型のセルでは、隠れ状態が h_t = 0.5 × h_{t−1} + x_t で更新される（活性化関数は用いない）。初期値 h_0 = 0、入力系列が x_1 = 2、x_2 = 4、x_3 = 0 のとき、h_3 はどれか。","choices":["2","6","5","2.5"],"answer":3,"explanation":"順に計算する。h_1 = 0.5 × 0 + 2 = 2、h_2 = 0.5 × 2 + 4 = 5、h_3 = 0.5 × 5 + 0 = 2.5 である。5 は h_2 で止めた場合、6 は重み 0.5 を掛けずに入力を単純に合計した場合（2 + 4 + 0）の値である。このように、過去の入力の影響は時刻が進むにつれて薄れていく点も読み取れる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-65","exam":"g","unit":"g-u5","keyword":"リカレントニューラルネットワーク (RNN)","type":"choice","syllabus_ref":"5.6","stem":"入力の次元が4、隠れ層の次元が3のリカレント型セル（エルマン型）を考える。重みは入力から隠れ層へのものと、隠れ層から隠れ層への回帰のものの2種類で、すべての時刻で共有される。バイアスは隠れユニットごとに1つずつある。系列の長さが10のとき、このセル全体の学習パラメータの総数はどれか。","choices":["21","24","240","12"],"answer":1,"explanation":"入力から隠れ層への重みは 4 × 3 = 12、回帰の重みは 3 × 3 = 9、バイアスは 3 で、合計は 12 + 9 + 3 = 24 である。重みは全時刻で共有されるため、系列の長さ10を掛けることはしない（240 はそれを誤った場合）。21 はバイアスを数え忘れた場合、12 は入力から隠れ層への重みだけを数えた場合の値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-66","exam":"g","unit":"g-u5","keyword":"BPTT","type":"choice","syllabus_ref":"5.6","stem":"BPTT (Backpropagation Through Time) の説明として、正しいものはどれか。","choices":["各時刻のセルを互いに独立したネットワークとして学習する方法である","未来の時刻の出力を、過去の時刻の入力へコピーして学習する方法である","リカレントネットワークを時間方向に展開し、展開したネットワークに対して誤差逆伝播法を適用して学習する方法である","重みを時刻ごとに別々に用意して、それぞれを学習する方法である"],"answer":2,"explanation":"BPTT は、回帰結合を持つネットワークを時刻の数だけ層を重ねた形に展開し、通常の誤差逆伝播法で勾配を計算する学習方法である。重みは展開した各時刻で共有されたまま扱われ、勾配は時刻をさかのぼって伝わる。各時刻を独立に学習するわけではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-67","exam":"g","unit":"g-u5","keyword":"教師強制","type":"choice","syllabus_ref":"5.6","stem":"教師強制 (Teacher Forcing) の説明として、正しいものはどれか。","choices":["系列を生成するモデルの学習の際、次の時刻への入力として、モデル自身の予測ではなく正解（目標）の値を入力する手法である","教師なし学習で、教師データを自動的に作り出す手法である","推論の際にも正解を入力として与え続ける手法である","学習率を強制的に大きな値に固定する手法である"],"answer":0,"explanation":"教師強制は、学習時にモデル自身の出力ではなく正解の値を次の入力に使う手法で、学習が安定しやすくなる。一方で、推論時には正解が得られず自身の出力を入力に使うため、学習時と推論時で条件がずれる点が課題として知られる。教師あり学習の文脈の手法であり、学習率とは関係しない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-68","exam":"g","unit":"g-u5","keyword":"勾配消失問題・勾配爆発問題","type":"choice","syllabus_ref":"5.6","stem":"単純なリカレントニューラルネットワークで、長い系列の依存関係を学習するのが難しい理由として、正しいものはどれか。","choices":["学習データの量が多すぎて、勾配が平均化されてしまうから","活性化関数を使わないネットワークでのみ起きる問題だから","プーリング層で情報が圧縮されてしまうから","時間方向に展開すると同じ重みによる変換が何度も繰り返し適用されるため、勾配が指数的に小さくなったり大きくなったりしやすく、遠く離れた時刻の情報が学習に反映されにくいから"],"answer":3,"explanation":"BPTT では、勾配は時間方向に同じ重みの影響を繰り返し受けながら伝わるため、系列が長いと勾配消失や勾配爆発が起きやすい。これが長期の依存関係を学びにくい主因であり、対処として、勾配の大きさを制限する勾配クリッピングや、ゲート機構を持つ LSTM・GRU が使われる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-69","exam":"g","unit":"g-u5","keyword":"ゲート機構","type":"choice","syllabus_ref":"5.6","stem":"LSTM や GRU に備わるゲート機構の役割として、正しいものはどれか。","choices":["学習率を時刻ごとに自動調整する仕組みである","0から1の値で情報の通し具合を調整し、保持すべき情報を選んで長く伝えることができるため、勾配が消失しにくくなり、長期の依存関係を学びやすくなる","入力データを一定の割合で間引いて、計算量を減らす仕組みである","重みをすべての時刻で共有するための仕組みである"],"answer":1,"explanation":"ゲート機構は、情報の流れの開き具合を学習によって調整する仕組みである。必要な情報を通し続ける経路が確保されることで、単純な RNN で起きやすかった勾配消失が和らぎ、遠い過去の情報を学習に生かしやすくなる。重みの共有は RNN 全般の性質であり、ゲート機構の役割ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-70","exam":"g","unit":"g-u5","keyword":"LSTM","type":"choice","syllabus_ref":"5.6","stem":"LSTM (Long Short-Term Memory) の説明として、正しいものはどれか。","choices":["ゲートを持たない、最も単純なリカレントニューラルネットワークである","畳み込み層を積み重ねて時系列データを処理するモデルである","情報を蓄えるセル状態と、忘却ゲート・入力ゲート・出力ゲートを持ち、長期の依存関係を保持しやすいリカレントニューラルネットワークである","系列を前方向と後方向の両方から処理するモデルである"],"answer":2,"explanation":"LSTM は、セル状態という情報を運ぶ経路と、それに対する読み書きを制御する3種類のゲート（忘却・入力・出力）を持つことで、単純な RNN では難しかった長期の依存関係の学習をしやすくしたモデルである。前方向と後方向の両方から処理するのは双方向 RNN である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-71","exam":"g","unit":"g-u5","keyword":"GRU","type":"choice","syllabus_ref":"5.6","stem":"GRU (Gated Recurrent Unit) の説明として、正しいものはどれか。","choices":["リセットゲートと更新ゲートの2つのゲートで構成され、セル状態を別に持たないため、LSTM より構造が簡素なリカレントニューラルネットワークである","LSTM のゲートを4つに増やして、より細かく情報を制御するモデルである","どのような系列データでも、常に LSTM より高い精度が得られるモデルである","画像認識のために提案された、回帰結合を持たないモデルである"],"answer":0,"explanation":"GRU は、LSTM の仕組みを簡素化したもので、ゲートはリセットゲートと更新ゲートの2つで、情報を蓄えるセル状態を隠れ状態とは別に持たない。その分パラメータが少なく計算も軽い。精度が常に LSTM を上回るわけではなく、データやタスクによって使い分けられる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-72","exam":"g","unit":"g-u5","keyword":"双方向 RNN (Bidirectional RNN)","type":"choice","syllabus_ref":"5.6","stem":"双方向 RNN (Bidirectional RNN) の説明として、正しいものはどれか。","choices":["同じ RNN に系列を2回繰り返し入力して、精度を上げる仕組みである","学習のときは前方向、推論のときは後方向に処理する仕組みである","2つの異なる系列を同時に入力して、両者の関係を学習する仕組みである","系列を前向きに処理する RNN と後ろ向きに処理する RNN を組み合わせ、各時点について前後の文脈の両方を利用する仕組みである"],"answer":3,"explanation":"双方向 RNN は、時間をさかのぼる方向にも処理を行う RNN を併用することで、ある時点の前後の情報をどちらも使えるようにしたモデルである。文章の穴埋めや分類のように系列全体が見えている場面で有効だが、未来側の入力が必要なため、逐次的に未来を予測する用途にはそのままでは使えない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目22「回帰結合層」"},{"id":"g5-73","exam":"g","unit":"g-u5","keyword":"Attention","type":"choice","syllabus_ref":"5.7","stem":"Attention（注意機構）の説明として、正しいものはどれか。","choices":["入力系列全体を1つの固定長ベクトルに圧縮し、それだけを使って出力を生成する仕組みである","入力の各要素が他の要素とどの程度関連するかを重みとして計算し、その重みで要素の情報を加重して取り出す仕組みである","系列の要素を時刻順に1つずつ処理し、隠れ状態に過去の情報を蓄える仕組みである","画像の局所領域に、重みを共有したフィルタを適用する仕組みである"],"answer":1,"explanation":"Attention は、要素どうしの関連の強さを重みとして計算し、その重みで各要素の情報を加重して集める仕組みである。入力全体を固定長ベクトルに圧縮する形は注意機構を持たない Seq2Seq の基本形で、情報の欠落が課題になった。時刻順に隠れ状態を引き継ぐのは RNN、重み共有のフィルタを使うのは CNN である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-74","exam":"g","unit":"g-u5","keyword":"クエリ・キー・バリュー","type":"choice","syllabus_ref":"5.7","stem":"Attention におけるクエリ、キー、バリューの役割の組合せとして、正しいものはどれか。","choices":["クエリ＝実際に取り出される情報、キー＝探される側の手がかり、バリュー＝何を探しているかを示す検索の要求","クエリ＝何を探しているかを示す検索の要求、キー＝実際に取り出される情報、バリュー＝探される側の手がかり","クエリ＝何を探しているかを示す検索の要求、キー＝探される側の手がかり、バリュー＝実際に取り出される情報","クエリ＝探される側の手がかり、キー＝何を探しているかを示す検索の要求、バリュー＝実際に取り出される情報"],"answer":2,"explanation":"Attention は、クエリ（何を探しているか）と各要素のキー（探される側の手がかり）の類似度から注意の重みを決め、その重みでバリュー（実際に取り出される情報）を加重して取り出す。データベース検索にたとえると、検索条件がクエリ、検索対象の見出しがキー、取り出される中身がバリューに対応する。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-75","exam":"g","unit":"g-u5","keyword":"クエリ・キー","type":"choice","syllabus_ref":"5.7","stem":"ある Attention の計算で、クエリが q = (1, 2)、3つの要素のキーが k_1 = (2, 0)、k_2 = (1, 1)、k_3 = (0, 1) である。注意のスコアをクエリとキーの内積で計算するとき、スコアが最も大きくなる要素はどれか。","choices":["要素2（k_2）","要素1（k_1）","要素3（k_3）","3つの要素すべてで等しい"],"answer":0,"explanation":"内積を計算すると、q・k_1 = 1×2 + 2×0 = 2、q・k_2 = 1×1 + 2×1 = 3、q・k_3 = 1×0 + 2×1 = 2 となる。最も大きいのは要素2で、この要素に最も大きな注意の重みが付く。実際の Attention では、このスコアをもとに重みが決まり、バリューの加重和が取られる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-76","exam":"g","unit":"g-u5","keyword":"バリュー","type":"choice","syllabus_ref":"5.7","stem":"ある Attention の計算で、3つの要素に対する注意の重みが (0.6, 0.3, 0.1)、各要素のバリューが v_1 = (10, 0)、v_2 = (0, 10)、v_3 = (20, 20) であった。出力として得られるベクトルはどれか。","choices":["(10, 10)","(30, 30)","(6, 3)","(8, 5)"],"answer":3,"explanation":"重み付き和を計算する。0.6×(10, 0) = (6, 0)、0.3×(0, 10) = (0, 3)、0.1×(20, 20) = (2, 2) で、合計は (8, 5) である。(10, 10) は重みを付けずに単純に平均した場合、(30, 30) は重みを掛けずに合計した場合、(6, 3) は3つ目の要素を落とした場合の値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-77","exam":"g","unit":"g-u5","keyword":"Self-Attention","type":"choice","syllabus_ref":"5.7","stem":"Self-Attention の説明として、正しいものはどれか。","choices":["同じ系列の中の要素同士が互いに注意を向け合い、各要素が系列内の他の要素との関連を取り込む仕組みである","デコーダがエンコーダの出力列に注意を向ける仕組みである","系列を時刻順に処理しながら隠れ状態を更新していく仕組みである","複数の異なる系列を同時に入力し、系列の間の対応関係だけを学習する仕組みである"],"answer":0,"explanation":"Self-Attention は、クエリ・キー・バリューをすべて同じ系列から作り、系列内の要素どうしの関連を取り込む仕組みである。文章であれば、ある単語が文中の他の単語とどう関係するかを捉える。デコーダがエンコーダの出力に注意を向けるのは Source-Target Attention、時刻順に隠れ状態を更新するのは RNN である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-78","exam":"g","unit":"g-u5","keyword":"Source-Target Attention","type":"choice","syllabus_ref":"5.7","stem":"Source-Target Attention（Encoder-Decoder Attention）の説明として、正しいものはどれか。","choices":["エンコーダの内部で、入力系列の要素同士が注意を向け合う仕組みである","デコーダ側がクエリを出し、エンコーダの出力列をキー・バリューとして注意を向けることで、入力系列の情報を参照しながら出力系列を生成する仕組みである","デコーダの内部で、出力系列の要素同士だけが注意を向け合う仕組みである","エンコーダとデコーダで重みを共有するための仕組みである"],"answer":1,"explanation":"Source-Target Attention では、クエリはデコーダ側から、キーとバリューはエンコーダの出力列から作られる。機械翻訳であれば、訳文の各単語を生成する際に、原文のどの単語に対応するかを参照できる。エンコーダ内部やデコーダ内部で同じ系列の要素どうしが注意を向け合うのは Self-Attention である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-79","exam":"g","unit":"g-u5","keyword":"Seq2Seq","type":"choice","syllabus_ref":"5.7","stem":"Seq2Seq の説明として、正しいものはどれか。","choices":["1枚の画像を入力として、クラスラベルを出力するモデルである","入力も出力も固定長でなければならない、分類専用のモデルである","入力系列の要素を、互いに独立に1つずつ分類するモデルである","エンコーダが入力系列を読み取り、デコーダがそれをもとに出力系列を生成することで、機械翻訳のように長さの異なる系列どうしを変換するモデルである"],"answer":3,"explanation":"Seq2Seq は、系列を入力として系列を出力するモデルの形で、エンコーダ・デコーダ構造を持つ。機械翻訳や対話のように、入力と出力で長さが異なる系列の変換に使われる。基本形では入力全体を固定長の表現に圧縮するため長い系列で情報が欠けやすく、この課題への対処として Attention が組み合わされた。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-80","exam":"g","unit":"g-u5","keyword":"Attention","type":"choice","syllabus_ref":"5.7","stem":"Attention が、系列処理におけるリカレントニューラルネットワーク (RNN) の問題点を解決する仕組みとして、正しいものはどれか。","choices":["系列を時刻順に処理する回数を増やし、隠れ状態に情報をより長く保持させる","入力系列全体を1つの固定長ベクトルに圧縮し、そのベクトルの次元を大きくする","離れた位置にある要素どうしでも、時刻を追って情報を伝える経路を介さずに直接注意を向けられるため、長期の依存関係を捉えやすく、固定長ベクトルへの圧縮による情報の欠落も避けられる","学習データを大量に用意することで、長期の依存関係を覚え込ませる"],"answer":2,"explanation":"RNN は情報を隠れ状態に載せて時刻順に伝えるため、離れた要素どうしの関係を捉えにくく、勾配消失も起きやすい。Seq2Seq の基本形では、入力全体を固定長ベクトルに圧縮する点もボトルネックになった。Attention では、各要素が出力側から直接重みを付けられるため、距離の離れた要素どうしの関係も扱え、圧縮による情報の欠落も避けられる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-81","exam":"g","unit":"g-u5","keyword":"Transformer","type":"choice","syllabus_ref":"5.7","stem":"Transformer の説明として、正しいものはどれか。","choices":["畳み込み層を主体とし、注意機構を持たないモデルである","回帰結合や畳み込みを用いず、Attention を中心に構成されたモデルで、Self-Attention と位置エンコーディングなどを組み合わせ、系列の要素を並列に処理できる","LSTM を多層に積み重ねたモデルである","系列を時刻順に1要素ずつ処理しなければならないモデルである"],"answer":1,"explanation":"Transformer は、回帰結合にも畳み込みにも頼らず、Attention を中心に構成されたモデルである。系列内の関係は Self-Attention で捉え、順序の情報は位置エンコーディングで補う。大規模言語モデルをはじめ、現在の多くのモデルの土台になっている。時刻順の逐次処理が前提になるのは RNN 系のモデルである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-82","exam":"g","unit":"g-u5","keyword":"位置エンコーディング","type":"choice","syllabus_ref":"5.7","stem":"Transformer で位置エンコーディング（位置情報の埋め込み）が必要とされる理由として、正しいものはどれか。","choices":["Attention の計算量を削減するため","各要素に単語の意味の情報を補うため","学習データの不足を補うため","Self-Attention の計算そのものは要素の並び順を区別しないため、位置の情報を別途入力に加えなければ、系列の順序を扱えないから"],"answer":3,"explanation":"Self-Attention は、要素の集合に対して関連の重みを計算する演算であり、要素の並び順そのものは計算に含まれない。このままでは「文の先頭の単語」と「文の末尾の単語」を区別できないため、位置エンコーディングによって各要素に位置の情報を加え、順序を扱えるようにしている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-83","exam":"g","unit":"g-u5","keyword":"Multi-Head Attention","type":"choice","syllabus_ref":"5.7","stem":"Multi-Head Attention の説明として、正しいものはどれか。","choices":["複数のヘッドが、それぞれ異なる観点で Attention を並列に計算し、その結果を組み合わせることで、多様な関係を同時に捉える仕組みである","1つの Attention の計算を、系列の長さの回数だけ繰り返し適用する仕組みである","注意の重みが最大の要素だけを残し、他の要素を捨てる仕組みである","複数の系列を連結して、1つの長い系列として処理する仕組みである"],"answer":0,"explanation":"Multi-Head Attention は、クエリ・キー・バリューを複数の異なる射影に分けたヘッドごとに Attention を計算し、結果を結合する。各ヘッドが異なる関係（例えば文法的なつながりと意味的なつながり）に注意を向けることができ、1つのヘッドで1種類の関連だけを見るよりも表現力が上がる。重みが最大の要素だけを残す処理ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-84","exam":"g","unit":"g-u5","keyword":"Transformer","type":"choice","syllabus_ref":"5.7","stem":"Transformer が RNN と比べて学習を高速化しやすい理由として、正しいものはどれか。","choices":["パラメータの数が RNN より常に少ないから","学習データを間引いて使うから","系列の各要素の計算が前の時刻の結果に依存しないため、系列全体をまとめて並列に処理できるから","勾配の計算が不要になるから"],"answer":2,"explanation":"RNN は時刻 t の計算が時刻 t−1 の結果を待つため、系列をまとめて処理できない。Transformer は要素どうしの注意を一括して計算できるため、系列全体を並列に処理でき、学習を高速化しやすい。ただし、注意の計算量は系列の長さの2乗に比例して増える点は課題として残る。パラメータ数が常に少ないわけではなく、勾配計算も必要である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目23「Attention」"},{"id":"g5-85","exam":"g","unit":"g-u5","keyword":"オートエンコーダ","type":"choice","syllabus_ref":"5.8","stem":"オートエンコーダ（自己符号化器）の説明として、正しいものはどれか。","choices":["入力データに付けられたクラスラベルを予測するよう学習する分類モデルである","入力を低次元の表現に圧縮するエンコーダと、そこから入力を復元するデコーダからなり、出力が入力と一致するよう学習するモデルである","2つのネットワークを競わせて、新しいデータを生成するモデルである","データを似た者同士のグループに分けるクラスタリング専用のモデルである"],"answer":1,"explanation":"オートエンコーダは、エンコーダが入力を低次元の潜在表現に圧縮し、デコーダがそこから元の入力を復元する構造を持ち、復元結果と入力の誤差が小さくなるよう学習する。正解のラベルは使わない教師なし学習のモデルである。2つのネットワークを競わせるのは敵対的生成ネットワーク (GAN) である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-86","exam":"g","unit":"g-u5","keyword":"オートエンコーダ","type":"choice","syllabus_ref":"5.8","stem":"オートエンコーダで、中間の潜在表現の次元を入力より小さくする（ボトルネックを設ける）理由として、正しいものはどれか。","choices":["学習に必要な計算量を増やし、モデルの表現力を高めるため","入力をそのまま写すだけの自明な変換を避け、データの本質的な特徴を潜在表現に抽出させるため","出力層のユニット数を入力層とそろえるため","正解ラベルとの誤差を直接計算できるようにするため"],"answer":2,"explanation":"潜在表現の次元が入力以上に大きいと、ネットワークは入力をそのまま通すだけの変換を覚えてしまい、特徴の抽出が進まない。ボトルネックで情報を絞ることで、再構成に必要な本質的な特徴だけを潜在表現に残すよう学習が進む。出力層の次元は入力とそろえるが、それはボトルネックを設ける理由ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-87","exam":"g","unit":"g-u5","keyword":"オートエンコーダ","type":"choice","syllabus_ref":"5.8","stem":"入力層8ユニット、潜在表現3ユニット、出力層8ユニットのオートエンコーダがある。全結合でつながれ、各ユニットにバイアスを持つとき、学習対象のパラメータ（重みとバイアス）の総数はどれか。","choices":["24","48","51","59"],"answer":3,"explanation":"重みは、入力層→潜在表現が 8×3 = 24、潜在表現→出力層が 3×8 = 24 で、合計48。バイアスは潜在表現の3個と出力層の8個で11。総数は 48 + 11 = 59 である。48 はバイアスを数えていない値、24 はエンコーダ側の重みだけを数えた値、51 は出力層のバイアスを落とした値である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-88","exam":"g","unit":"g-u5","keyword":"次元削減","type":"choice","syllabus_ref":"5.8","stem":"次元削減の手法としてオートエンコーダを用いることの特徴として、正しいものはどれか。","choices":["ボトルネックの潜在表現を圧縮した表現として取り出せ、ネットワークが学習するため、主成分分析のような線形の変換では表せない非線形な圧縮も扱える","次元削減の前に入力データを標準化する必要が一切ない","潜在表現の各次元が、必ず互いに無相関になることが保証される","削減後の次元数を、学習の途中で自動的に決めてくれる"],"answer":0,"explanation":"オートエンコーダのボトルネックの潜在表現は、そのまま圧縮された低次元表現として使える。変換はニューラルネットワークが学習するため非線形な関係も表せる点が、線形の射影である主成分分析との違いである。潜在表現の次元同士が無相関になる保証はなく、削減後の次元数もあらかじめ設計するものである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-89","exam":"g","unit":"g-u5","keyword":"変分オートエンコーダ (VAE)","type":"choice","syllabus_ref":"5.8","stem":"変分オートエンコーダ (VAE) の説明として、正しいものはどれか。","choices":["潜在表現を、離散的なコードブックの要素の番号として表すモデルである","入力を潜在表現の1点に決定的に写すモデルである","分類器の出力に確率の解釈を与えるためのモデルである","エンコーダが潜在変数の分布のパラメータ（平均や分散）を出力し、そこからサンプリングした潜在変数をデコーダで復元することで、学習データに似た新しいデータを生成できるモデルである"],"answer":3,"explanation":"VAE は、エンコーダが入力ごとに潜在変数の確率分布（平均と分散）を出し、そこからサンプリングした潜在変数をデコーダがデータへ戻す。この仕組みにより、潜在空間から点を選んで新しいデータを生成できる。通常のオートエンコーダは入力を潜在表現の1点に決定的に写す。離散的なコードブックを使うのは VQ-VAE である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-90","exam":"g","unit":"g-u5","keyword":"変分オートエンコーダ (VAE)","type":"choice","syllabus_ref":"5.8","stem":"変分オートエンコーダ (VAE) の学習で、再構成の誤差に加えてカルバック・ライブラー情報量 (KLダイバージェンス) の項が損失に入る理由として、正しいものはどれか。","choices":["分類の正解率を損失に反映させるため","エンコーダが出す潜在変数の分布を標準正規分布に近づけ、潜在空間からサンプリングしてデータを生成できるようにするため","重みの絶対値を小さく抑えて過学習を防ぐため","デコーダの出力と入力の次元をそろえるため"],"answer":1,"explanation":"KLダイバージェンスの項は、エンコーダが出す潜在分布を標準正規分布に近づける働きをする。これにより潜在空間が整い、標準正規分布からサンプリングした点をデコーダに通すことで新しいデータを生成できる。再構成誤差だけでは、潜在空間が生成に使える形に整わない。重みを小さく抑えるのは正則化の役割である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-91","exam":"g","unit":"g-u5","keyword":"VQ-VAE・info VAE・β-VAE","type":"choice","syllabus_ref":"5.8","stem":"β-VAE の説明として、正しいものはどれか。","choices":["VAE の損失で KLダイバージェンスの項に β という重みを付け、β を大きくすることで、潜在変数の各次元がデータの独立した要因に対応するような、もつれの解けた表現を促すモデルである","潜在変数を離散的なコードに量子化するモデルである","潜在変数と入力データの相互情報量を最大化する項を加えたモデルである","オートエンコーダを何層も積み重ねたモデルである"],"answer":0,"explanation":"β-VAE は、VAE の損失のうち KLダイバージェンスの項に重み β を掛けたもので、β を 1 より大きくすると潜在表現が要因ごとに分かれた表現（disentangled representation）になりやすいとされる。潜在変数を離散コードに量子化するのは VQ-VAE、相互情報量を保つ項を加えるのは infoVAE、積み重ねるのは積層オートエンコーダである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-92","exam":"g","unit":"g-u5","keyword":"VQ-VAE・info VAE・β-VAE","type":"choice","syllabus_ref":"5.8","stem":"VQ-VAE の説明として、正しいものはどれか。","choices":["潜在変数の分布を標準正規分布に近づけることで生成を可能にするモデルである","KLダイバージェンスの項の重みを大きくし、潜在表現のもつれを解くモデルである","エンコーダの出力を、コードブックにある最も近いベクトルに置き換えることで潜在表現を離散化し、画像や音声などの生成に使われるモデルである","入力と潜在変数の相互情報量を最大化する項を加えたモデルである"],"answer":2,"explanation":"VQ-VAE は、エンコーダの連続的な出力を、学習したコードブックの中の最も近いベクトル（埋め込み）に量子化し、離散的な潜在表現として扱う。離散表現は画像や音声のようなデータの生成モデルと組み合わせやすい。標準正規分布に近づけるのは通常の VAE、KL の重みを大きくするのは β-VAE、相互情報量の項を加えるのは infoVAE である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-93","exam":"g","unit":"g-u5","keyword":"VQ-VAE・info VAE・β-VAE","type":"choice","syllabus_ref":"5.8","stem":"infoVAE の説明として、正しいものはどれか。","choices":["潜在変数を離散的なコードブックの要素に量子化するモデルである","入力データと潜在変数の間の相互情報量を保つ（最大化する）項を目的関数に加え、潜在変数が入力の情報を保持するようにした VAE の亜種である","KLダイバージェンスの項の重みだけを大きくしたモデルである","エンコーダを持たず、デコーダだけでデータを生成するモデルである"],"answer":1,"explanation":"infoVAE は、VAE の目的関数に入力と潜在変数の相互情報量を最大化する項を加えた亜種で、潜在変数が入力の情報を失ってしまう事態を抑え、意味のある潜在表現を保つ狙いがある。量子化を行うのは VQ-VAE、KL の重みを大きくするのは β-VAE である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-94","exam":"g","unit":"g-u5","keyword":"積層オートエンコーダ","type":"choice","syllabus_ref":"5.8","stem":"積層オートエンコーダの説明として、正しいものはどれか。","choices":["1つのオートエンコーダの出力を、そのまま同じオートエンコーダに繰り返し入力するモデルである","複数のオートエンコーダの出力を平均して使うモデルである","変分オートエンコーダを何層も積み重ねたモデルである","オートエンコーダを層ごとに積み重ねたもので、下の層から順に1層ずつ学習していくことで、深いネットワークの特徴表現を段階的に作るモデルである"],"answer":3,"explanation":"積層オートエンコーダは、オートエンコーダを多層に重ねた構造で、各層を下から順に学習し、前の層の潜在表現を次の層の入力として特徴を段階的に抽出する。深いネットワークを一度に学習するのが難しかった時期に、層ごとの事前学習の土台として使われた。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-95","exam":"g","unit":"g-u5","keyword":"事前学習","type":"choice","syllabus_ref":"5.8","stem":"オートエンコーダを用いた事前学習の説明として、正しいものはどれか。","choices":["ラベルなしデータでオートエンコーダを層ごとに学習して重みの初期値を得てから、そのネットワークに分類などのタスクをラベルありデータで学習させる（ファインチューニング）方法である","別のタスクの大量のラベルありデータで学習したモデルを、そのまま評価に使う方法である","学習データの水増しのために、入力にノイズを加えて学習させる方法である","学習の途中で一部のユニットをランダムに無効化して過学習を防ぐ方法である"],"answer":0,"explanation":"事前学習は、ラベルなしデータでオートエンコーダを学習し、得られた重みを深いネットワークの初期値として使う方法である。その後、目的のタスクのラベルありデータで全体を調整する（ファインチューニング）。深いネットワークの学習が難しかった時期に有効だった。ユニットをランダムに無効化するのはドロップアウトである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-96","exam":"g","unit":"g-u5","keyword":"オートエンコーダ","type":"choice","syllabus_ref":"5.8","stem":"オートエンコーダを異常検知に使う方法として、正しいものはどれか。","choices":["異常なデータだけを集めて学習し、異常らしさを分類させる","正常なデータだけで学習しておき、再構成誤差が大きい入力を異常と判断する。再構成誤差は、正常データのパターンを学んだモデルがうまく復元できない入力ほど大きくなる","クラスタリングで最も小さいクラスタに入ったデータを異常と判断する","生成したデータと入力を比べて、見た目の違いを人が判定する"],"answer":2,"explanation":"正常データだけでオートエンコーダを学習すると、モデルは正常なパターンの再構成が得意になる。異常な入力は潜在表現にうまく乗らず再構成誤差が大きくなるため、その誤差の大きさを異常の度合いとして使える。異常データは一般に集めにくいため、正常データだけで学習できる点が実務上の利点である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目24「オートエンコーダ」"},{"id":"g5-97","exam":"g","unit":"g-u5","keyword":"データ拡張","type":"choice","syllabus_ref":"5.9","stem":"データ拡張（Data Augmentation）の説明として、正しいものはどれか。","choices":["テストデータに変換を加えて、評価用のデータを大量に用意する手法である","既存の学習データに反転や回転などの変換を加えて新しい学習データを作り、学習データの量と多様性を増やす手法である","学習データの特徴量の数を減らして、モデルの入力を単純にする手法である","複数のモデルの予測を平均して、予測精度を高める手法である"],"answer":1,"explanation":"データ拡張は、既存の学習データに変換を加えてバリエーションを増やす手法で、限られた学習データでも過学習を抑え、汎化性能を高める狙いがある。変換は学習データに適用するもので、評価に使うテストデータには適用しない。特徴量の数を減らすのは次元削減、複数のモデルの予測を平均するのはアンサンブル学習である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-98","exam":"g","unit":"g-u5","keyword":"Random Flip","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である Random Flip の説明として、正しいものはどれか。","choices":["画像の一部をランダムに切り抜いて使う手法である","画像にランダムなノイズを加える手法である","画像をランダムに左右（または上下）に反転させる手法で、反転しても意味が変わらない画像に対して、向きの違いに強いモデルを学習させる","2枚の画像を一定の比率で混ぜ合わせる手法である"],"answer":2,"explanation":"Random Flip は、学習データの画像を確率的に反転させる手法である。左右反転は多くの自然画像では意味が保たれるため広く使われるが、文字や左右非対称な対象では反転で意味が変わる場合があり、タスクに応じて使うかどうかを選ぶ。一部を切り抜くのは Crop、ノイズを加えるのは noising、2枚を混ぜるのは Mixup である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-99","exam":"g","unit":"g-u5","keyword":"Rotate","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である Rotate の説明として、正しいものはどれか。","choices":["画像をランダムな角度だけ回転させる手法で、被写体の傾きの違いに対する頑健性を高める","画像を上下に反転させる手法である","画像の明るさをランダムに変える手法である","画像の一部を四角く塗りつぶして隠す手法である"],"answer":0,"explanation":"Rotate は画像を回転させる手法で、写真などでは小さな角度の回転が、傾きのばらつきへの頑健性につながる。ただし数字の6と9のように、回転によって意味そのものが変わるデータでは使い方に注意が要る。反転は Random Flip、明るさの変更は Brightness、一部を隠すのは Cutout である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-100","exam":"g","unit":"g-u5","keyword":"Crop","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である Crop（切り抜き）を学習に使う際の説明として、正しいものはどれか。","choices":["切り抜く部分は、必ず画像の中央でなければならない","切り抜くことで画像の解像度が上がり、細部が学習しやすくなる","切り抜きはテスト時にだけ使うもので、学習データには使わない","画像の一部をランダムに切り抜くことで、対象の位置や大きさの見え方が変わった学習データが得られるが、切り抜き方によっては対象が写っていない画像に元のラベルが付く場合がある"],"answer":3,"explanation":"ランダムな切り抜き（ランダムクロップ）は、対象の位置やスケールが変わった見え方の学習データを与え、位置の違いに対する頑健性につながる。一方、対象が写っていない切り抜きにも元のラベルがそのまま残ると、誤った学習信号になるため、切り抜く範囲や大きさの設定には注意が要る。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-101","exam":"g","unit":"g-u5","keyword":"Brightness","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である Brightness の説明として、正しいものはどれか。","choices":["画像の明暗の差（コントラスト）を広げる手法である","画像を一定の角度だけ回転させる手法である","画像全体の明るさをランダムに明るくしたり暗くしたりする手法で、照明条件の違いに対する頑健性を高める","画像の一部を切り取って別の画像に貼る手法である"],"answer":2,"explanation":"Brightness は画像全体の明るさを変更する手法で、明るさの異なる条件で撮影されたデータへの対応力を高める。明暗の差を変えるのは Contrast、回転は Rotate、一部を切り取って貼るのは CutMix である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-102","exam":"g","unit":"g-u5","keyword":"Contrast","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である Contrast の説明として、正しいものはどれか。","choices":["画像全体の明るさを一様に上げ下げする手法である","画像の明暗の差をランダムに強めたり弱めたりする手法で、撮影条件によるコントラストの違いに対する頑健性を高める","画像の一部をランダムな値で塗りつぶす手法である","2つの文を言い換えて学習データを増やす手法である"],"answer":1,"explanation":"Contrast は画像の明暗の差（コントラスト）を調整する手法である。画像全体の明るさを一様に変えるのは Brightness であり、両者は変える対象が異なる。一部をランダムな値で塗りつぶすのは Random Erasing、文の言い換えは paraphrasing である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-103","exam":"g","unit":"g-u5","keyword":"noising","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である noising（ノイズ付加）の説明として、正しいものはどれか。","choices":["学習データのラベルをランダムに付け替える手法である","画像の一部を四角く切り取って隠す手法である","文の表現を同義の表現に言い換える手法である","入力データにランダムなノイズを加える手法で、入力の小さな乱れやばらつきに影響されにくいモデルを学習させる"],"answer":3,"explanation":"noising は入力データ側にノイズを加える手法で、センサーのノイズや入力のばらつきに対する頑健性を高める。ラベルを付け替えるのはラベルノイズと呼ばれる別の事象であり、データ拡張の noising とは異なる。一部を隠すのは Cutout、文の言い換えは paraphrasing である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-104","exam":"g","unit":"g-u5","keyword":"Cutout・Random Erasing","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である Cutout と Random Erasing の説明として、正しいものはどれか。","choices":["どちらも画像の一部の四角い領域を隠す手法で、Cutout は隠した領域を一定の値で塗りつぶし、Random Erasing はランダムな値で置き換える。物体の一部が隠れても認識できるようになる効果が期待できる","どちらも2枚の画像を混ぜ合わせる手法で、混ぜ方の違いだけが異なる","Cutout はテキストの単語を消す手法で、Random Erasing は音声の一部を消す手法である","どちらも学習データではなくテストデータに適用して、評価を厳しくするための手法である"],"answer":0,"explanation":"Cutout と Random Erasing は、画像の一部の領域を隠すことで、モデルが最も特徴的な部分だけに頼らず、物体の一部が隠れた（遮蔽された）条件でも認識できるようにする手法である。両者の違いは隠した領域の埋め方で、Cutout は一定の値、Random Erasing はランダムな値を使う。2枚の画像を混ぜるのは Mixup や CutMix である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-105","exam":"g","unit":"g-u5","keyword":"Mixup","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法 Mixup では、2つの学習データとそのラベルを、同じ比率で線形に混ぜ合わせて新しい学習データを作る。画像Aのある画素の値が100、画像Bの対応する画素の値が200で、Aの重み λ を 0.8 として混ぜ合わせるとき、この画素の値はいくつになるか。","choices":["150","120","180","100"],"answer":1,"explanation":"Mixup の混合は、λ×（Aの値）＋（1−λ）×（Bの値）で計算し、ラベルも同じ λ で混ぜる。0.8×100 ＋ 0.2×200 ＝ 80 ＋ 40 ＝ 120 である。180 は重みの掛け方を逆にした値、150 は λ＝0.5 で単純に平均した値、100 は A をそのまま使った値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-106","exam":"g","unit":"g-u5","keyword":"CutMix","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法 CutMix では、ある画像の一部を別の画像から切り取った領域（パッチ）で置き換え、ラベルは置き換えた面積の割合に応じて2つの画像のラベルを混ぜる。画像の面積の25%を別の画像のパッチで置き換えた場合、ラベルの混ざり方として正しいものはどれか。","choices":["元の画像のラベルをそのまま使う","2つの画像のラベルを半分ずつ混ぜる","元の画像のラベルが0.75、別の画像のラベルが0.25の割合で混ざる","画素値の平均に応じてラベルの割合が決まる"],"answer":2,"explanation":"CutMix のラベルの混合比は、置き換えたパッチの面積比で決まる。面積の25%を置き換えたなら、元の画像のラベル 0.75 と別の画像のラベル 0.25 を混ぜる。画像全体の画素を比率で補間する Mixup と異なり、CutMix は領域ごとに入れ替える点が特徴である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-107","exam":"g","unit":"g-u5","keyword":"paraphrasing","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である paraphrasing（言い換え）の説明として、正しいものはどれか。","choices":["画像を左右に反転させて学習データを増やす手法である","音声の再生速度を変えて学習データを増やす手法である","画像にノイズを加えて学習データを増やす手法である","テキストの文を、意味を保ったまま別の表現に言い換えて学習データを増やす手法で、自然言語処理のタスクで使われる"],"answer":3,"explanation":"paraphrasing はテキストを対象とするデータ拡張で、文の意味とラベルを保ちながら表現を変えることで、表現の多様性に対応できるモデルを学習させる。画像の反転は Random Flip、画像へのノイズ付加は noising であり、いずれも画像を対象とする手法である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-108","exam":"g","unit":"g-u5","keyword":"RandAugument","type":"choice","syllabus_ref":"5.9","stem":"データ拡張の手法である RandAugument の説明として、正しいものはどれか。","choices":["適用する拡張の種類をランダムに選び、決められた強さで適用する自動データ拡張の手法で、拡張の組み合わせや強さを人手で細かく探索・調整する負担を減らす","学習データをランダムに削除してデータ量を減らす手法である","テストデータの中からランダムに選んだデータで追加学習する手法である","ランダムな値で画像の一部を消す手法である"],"answer":0,"explanation":"RandAugment（シラバスのキーワード表記は RandAugument）は、候補となる拡張操作の中からランダムに選んで適用する自動データ拡張の手法で、拡張の組み合わせを人手で探索するコストを大きく減らした。ランダムな値で画像の一部を消すのは Random Erasing である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-109","exam":"g","unit":"g-u5","keyword":"Random Flip","type":"choice","syllabus_ref":"5.9","stem":"道路標識の画像を分類するモデルを学習させる。標識の中には「右折のみ」「左折のみ」のように、左右の向きそのものが意味を持つものが含まれている。このタスクで学習データに適用するデータ拡張の選択として、最も不適切なものはどれか。","choices":["Random Flip で画像を左右に反転させて学習データを増やす","Brightness で明るさを変えて、撮影時刻や天候による明るさの違いに対応できるようにする","Crop で切り抜く位置や大きさを変えて、標識の写る位置や大きさの違いに対応できるようにする","noising で入力にノイズを加えて、撮影時や圧縮による画像の乱れに対応できるようにする"],"answer":0,"explanation":"データ拡張は「変換を加えてもラベルが保たれる」ことが前提であり、タスクの意味構造に合わない変換は選ばない。左右の向きが意味を持つ標識では、左右反転すると「右折のみ」の画像が鏡像になって「左折のみ」に相当する見え方になるのに、元のラベルがそのまま付いた学習データが生まれ、誤った学習信号になる。明るさの変更、切り抜き、ノイズ付加はいずれも標識の意味を変えず、撮影条件のばらつきに対する頑健性を高める方向で適切である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g5-110","exam":"g","unit":"g-u5","keyword":"データ拡張","type":"choice","syllabus_ref":"5.9","stem":"製品の外観検査で不良品を検出するモデルを学習させるが、不良品の画像は良品の画像に比べて極端に少なく、クラス間の数の偏りが大きい。この偏りをデータ拡張で緩和する使い方として、最も適切なものはどれか。","choices":["全ての画像に同じ回数だけ拡張を適用して、データ全体の量を増やす","不良品（少数クラス）の画像に重点的に拡張を適用して数を増やし、クラス間の偏りを小さくする","テストデータにも拡張を適用して、評価に使う不良品の画像を増やす","不良品の画像を間引いて、良品の数に近づける"],"answer":1,"explanation":"クラス間の偏りを緩和するには、少数クラスのデータを相対的に増やす必要がある。不良品の画像に反転や明るさの変更などの拡張を重点的に適用して増やせば、良品と不良品の比率が均等に近づき、モデルが多数クラスに偏って学習する度合いを抑えられる。全ての画像に同じ回数だけ拡張しても比率は変わらず、偏りは緩和されない。拡張は学習データに適用するもので、評価に使うテストデータには適用しない。不良品の画像を間引くのは偏りをさらに大きくする。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目5「ディープラーニングの要素技術」中項目25「データ拡張」"},{"id":"g6-01","exam":"g","unit":"g-u6","keyword":"物体識別","type":"choice","syllabus_ref":"6.1","stem":"画像認識のタスクである物体識別（画像分類）の説明として、正しいものはどれか。","choices":["画像の中の各物体について、種類と位置（矩形の領域）を同時に求めるタスクである","画像の各画素にクラスラベルを割り当てるタスクである","入力画像全体（あるいは画像中の物体）がどのカテゴリに属するかというラベルを割り当てるタスクである","人の関節などのキーポイントの位置を推定するタスクである"],"answer":2,"explanation":"物体識別は、画像が何を表しているかというカテゴリラベルを割り当てるタスクである。日用品や動物など特定の対象に限らない一般の物体を認識する分野は一般物体認識と呼ばれ、物体識別や物体検出などを含む。種類と位置を同時に求めるのは物体検出、各画素にラベルを付けるのはセマンティックセグメンテーション、関節の位置を求めるのは姿勢推定である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-02","exam":"g","unit":"g-u6","keyword":"物体検出","type":"choice","syllabus_ref":"6.1","stem":"画像認識のタスクである物体検出の説明として、正しいものはどれか。","choices":["画像の中に写っている物体それぞれについて、そのクラス（種類）と位置を表す矩形（バウンディングボックス）を求めるタスクで、複数の物体を同時に検出できる","画像全体に対して1つのクラスラベルだけを割り当てるタスクである","画像を画素ごとに領域に分割し、背景も含めた全画素にクラスラベルを付けるタスクである","物体の輪郭を画素単位で切り出すが、クラスは判定しないタスクである"],"answer":0,"explanation":"物体検出は、画像中の物体の「何が（クラス）」と「どこに（位置）」を同時に求めるタスクで、一般物体認識の代表的なタスクの1つである。画像全体に1つのラベルを付けるのは物体識別、全画素にラベルを付けるのはセマンティックセグメンテーションである。物体検出の出力は矩形（バウンディングボックス）であり、画素単位の切り出しはセグメンテーション系のタスクが担う。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-03","exam":"g","unit":"g-u6","keyword":"セマンティックセグメンテーション・インスタンスセグメンテーション・パノプティックセグメンテーション","type":"choice","syllabus_ref":"6.1","stem":"画像認識のセグメンテーション系タスクについて、同じ種類の物体が複数重なって写っている場合でも個体ごとに区別し、さらに空や道路のような背景領域も含めて、画像の全画素にラベルを割り当てるタスクはどれか。","choices":["セマンティックセグメンテーション","パノプティックセグメンテーション","インスタンスセグメンテーション","物体検出"],"answer":1,"explanation":"パノプティックセグメンテーションは、セマンティックセグメンテーションとインスタンスセグメンテーションを統合したタスクである。セマンティックセグメンテーションは全画素にクラスラベルを付けるが、同じクラスの物体は個体として区別しない。インスタンスセグメンテーションは物体を個体ごとに画素単位で区別するが、対象は物体（前景）であり背景の全画素にラベルを付けることは求めない。パノプティックセグメンテーションは、背景も含めた全画素へのラベル付けと、物体の個体区別を同時に行う。物体検出の出力は矩形であり画素単位ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-04","exam":"g","unit":"g-u6","keyword":"姿勢推定・Open Pose","type":"choice","syllabus_ref":"6.1","stem":"画像認識のタスクである姿勢推定と、その代表的な手法 Open Pose の説明として、正しいものはどれか。","choices":["画像中の物体の姿勢（向き）を3次元で復元するタスクで、Open Pose は1人の姿勢だけを対象とする","画像から人の顔の向きだけを推定するタスクで、体の関節は対象としない","画像の各画素に人物か背景かのラベルを付けるタスクで、関節の位置は求めない","画像中の人の肩・肘・膝などの関節（キーポイント）の位置を推定して骨格を捉えるタスクで、Open Pose は複数人の姿勢を同時に推定できる代表的な手法である"],"answer":3,"explanation":"姿勢推定は、画像中の人の関節などのキーポイントの位置を求め、体の骨格や動きを捉えるタスクで、スポーツのフォーム分析や医療・リハビリ、ゲームなどに応用される。Open Pose（OpenPose）は、複数人の2次元姿勢を同時に推定できる代表的な手法として知られる。画素へのラベル付けはセグメンテーション系のタスクであり、姿勢推定とは異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-05","exam":"g","unit":"g-u6","keyword":"AlexNet","type":"choice","syllabus_ref":"6.1","stem":"画像認識モデル AlexNet の説明として、正しいものはどれか。","choices":["画像をパッチに分割し、畳み込みを使わずに Transformer で処理するモデルである","2012年の画像認識コンペティション ILSVRC で、深い畳み込みニューラルネットワークにより従来手法を大きく上回る精度で優勝し、ディープラーニングによる画像認識の転機となったモデルである","3×3の小さな畳み込みフィルタだけを一様に積み重ねた、非常に深いモデルである","層を深くする代わりにチャンネル数を広げることに主眼を置いたモデルである"],"answer":1,"explanation":"AlexNet は2012年の ILSVRC で優勝し、深層の畳み込みニューラルネットワーク（CNN）が画像認識で圧倒的な性能を持つことを示したモデルで、ReLU やドロップアウト、GPU による学習も用いられた。画像をパッチとして Transformer で処理するのは Vision Transformer、3×3フィルタの一様な積み重ねは VGG、チャンネル数を広げる設計は Wide ResNet の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-06","exam":"g","unit":"g-u6","keyword":"VGG","type":"choice","syllabus_ref":"6.1","stem":"画像認識モデル VGG の設計の特徴として、正しいものはどれか。","choices":["異なる大きさのフィルタを並列に組み合わせたモジュールで多様なスケールの特徴を捉える","すべての層がそれ以前の全層の出力を連結して入力として受け取る","3×3の小さな畳み込みフィルタを一様に積み重ねて層を深くする、単純で統一された構成を取る","1×1の畳み込みだけを用い、空間方向の畳み込みを行わない"],"answer":2,"explanation":"VGG は、3×3の小さな畳み込みフィルタを繰り返し積み重ねることで深いネットワークを構成したモデルで、VGG16 や VGG19 のように層の数で表されるバリエーションがある。小さなフィルタの積み重ねは、大きなフィルタと同等の受容野を持ちながらパラメータを抑え、非線形変換の回数を増やせる。異なる大きさのフィルタの並列モジュールは GoogLeNet の Inception、全層の出力を連結するのは DenseNet の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-07","exam":"g","unit":"g-u6","keyword":"GoogLeNet","type":"choice","syllabus_ref":"6.1","stem":"画像認識モデル GoogLeNet の特徴である Inception モジュールの説明として、正しいものはどれか。","choices":["1×1、3×3、5×5の畳み込みやプーリングを並列に組み合わせて多様なスケールの特徴を捉え、1×1畳み込みでチャンネル数を絞ることで計算量を抑えるモジュールである","3×3の畳み込みだけを一直線に積み重ねたモジュールである","入力をそのまま出力に加えることで勾配の伝播を助けるモジュールである","チャンネルごとに畳み込みを分離して計算量を削減するモジュールである"],"answer":0,"explanation":"GoogLeNet は Inception モジュールを積み重ねたモデルで、2014年の ILSVRC で優勝した。Inception モジュールは、異なるサイズの畳み込みとプーリングを並列に配置し、それらの出力を結合することで、複数のスケールの特徴を同時に捉える。1×1畳み込みによる次元の削減で、深くしても計算量とパラメータ数が膨らまないよう工夫されている。入力を出力に加えるのはスキップ結合（ResNet）、チャンネルごとの分離畳み込みは MobileNet などで使われる深さ方向分離畳み込みである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-08","exam":"g","unit":"g-u6","keyword":"DenseNet","type":"choice","syllabus_ref":"6.1","stem":"画像認識モデル DenseNet の結合の仕方の説明として、正しいものはどれか。","choices":["各層は直前の層の出力だけを受け取り、結合は持たない","各層は入力をそのまま出力に加算したものを受け取る","各層はチャンネル方向に絞り込んだ特徴だけを受け取る","各層は、それ以前のすべての層の特徴マップをチャンネル方向に連結（concat）したものを受け取るため、特徴の再利用が進み、比較的少ないパラメータで深いモデルを構成できる"],"answer":3,"explanation":"DenseNet は、各層が先行する全層の特徴マップを連結して受け取る密な結合（dense connection）を持つモデルである。特徴が再利用されるため効率が良く、勾配も伝わりやすい。入力を出力に加算するのは ResNet のスキップ結合であり、DenseNet の連結とは仕組みが異なる。なお ResNet の発展形には、層を深くする代わりにチャンネル数を広げた Wide ResNet がある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-09","exam":"g","unit":"g-u6","keyword":"MobileNet","type":"choice","syllabus_ref":"6.1","stem":"軽量な画像認識モデル MobileNet では、通常の畳み込みを、チャンネルごとに空間方向の畳み込みを行う深さ方向畳み込みと、1×1畳み込みでチャンネルを混ぜる点方向畳み込みに分けた「深さ方向分離畳み込み」で置き換える。入力チャンネル数32、出力チャンネル数64、カーネルサイズ3×3の畳み込みについて、バイアスを考えないとき、通常の畳み込みと深さ方向分離畳み込みのパラメータ数の組み合わせとして正しいものはどれか。","choices":["通常の畳み込み 18,432／深さ方向分離畳み込み 18,432","通常の畳み込み 18,432／深さ方向分離畳み込み 2,336","通常の畳み込み 2,336／深さ方向分離畳み込み 18,432","通常の畳み込み 18,432／深さ方向分離畳み込み 288"],"answer":1,"explanation":"通常の畳み込みのパラメータ数は 3×3×32×64 ＝ 18,432 である。深さ方向分離畳み込みは、深さ方向畳み込みが 3×3×32 ＝ 288、点方向畳み込み（1×1）が 32×64 ＝ 2,048 で、合計 2,336 となり、通常の畳み込みの約8分の1まで減る。MobileNet はこの仕組みで計算量とパラメータ数を大幅に削減し、モバイル端末でも動く軽量な画像認識を実現した。288 は深さ方向畳み込みだけの数で、点方向畳み込みを含めていない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-10","exam":"g","unit":"g-u6","keyword":"SSD・YOLO","type":"choice","syllabus_ref":"6.1","stem":"物体検出モデル SSD と YOLO に共通する特徴として、正しいものはどれか。","choices":["物体の候補領域をまず抽出し、その領域ごとに分類を行う2段階の検出方式である","画像の各画素にクラスラベルを付けるセグメンテーション専用のモデルである","画像を1回だけネットワークに通す処理の中で、物体のクラスと位置（矩形）をまとめて予測する1段階の検出方式で、高速な検出が可能である","画像全体のクラス分類だけを行い、位置は予測しない"],"answer":2,"explanation":"SSD と YOLO はどちらも、候補領域の抽出と分類を分けない1段階（one-stage）の物体検出モデルである。YOLO は画像をグリッドに分け、各セルで物体のクラスと矩形を一度に予測する。SSD は複数のスケールの特徴マップ上で検出を行う。1回の処理で検出まで完結するため高速で、監視カメラや自動運転などのリアルタイム用途に向く。候補領域を抽出してから分類する2段階方式は Faster R-CNN などの R-CNN 系である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-11","exam":"g","unit":"g-u6","keyword":"Faster R-CNN","type":"choice","syllabus_ref":"6.1","stem":"物体検出モデル Faster R-CNN の説明として、正しいものはどれか。","choices":["候補領域を使わず、画像を1回の処理で走査して検出を終える1段階のモデルである","検出ではなく、画像の各画素にラベルを付けるセグメンテーション専用のモデルである","分類専用のモデルで、物体の位置は出力しない","候補領域の抽出を外部の手法に頼っていた Fast R-CNN に対し、候補領域の提案自体をニューラルネットワーク（RPN）が行うようにし、特徴抽出と候補提案を一体化した2段階の検出モデルである"],"answer":3,"explanation":"Faster R-CNN は、物体がありそうな候補領域を提案する RPN（Region Proposal Network）をネットワーク内に組み込んだ2段階の物体検出モデルである。前任の Fast R-CNN は候補領域の抽出にネットワーク外の手法（セレクティブサーチ）を用いており、そこが処理のボトルネックになっていた。Faster R-CNN を拡張し、矩形に加えて画素単位のマスクも出力してインスタンスセグメンテーションを可能にしたものが Mask R-CNN である。また、検出やセグメンテーションでは、異なるスケールの特徴マップを組み合わせる FPN（Feature Pyramid Network）が土台としてよく使われる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-12","exam":"g","unit":"g-u6","keyword":"Vision Transformer","type":"choice","syllabus_ref":"6.1","stem":"画像認識モデル Vision Transformer（ViT）の説明として、正しいものはどれか。","choices":["入力画像を一定の大きさのパッチに分割し、各パッチを単語のようにトークンとして扱って Transformer で処理することで画像を分類するモデルで、畳み込み層を使わない","畳み込み層の後に回帰結合層を接続し、画像の時系列変化を捉えるモデルである","物体の候補領域を提案するネットワークと分類器を組み合わせた検出モデルである","画像を低次元の潜在表現に圧縮し、再構成誤差で異常を検出するモデルである"],"answer":0,"explanation":"Vision Transformer は、自然言語処理で成功した Transformer を画像認識に適用したモデルで、画像をパッチ列として扱い、パッチ同士の関係を Attention で捉える。大規模なデータで事前学習した場合に、畳み込みニューラルネットワークと同等以上の性能が得られることが示された。候補領域の提案と分類の組み合わせは R-CNN 系、潜在表現への圧縮と再構成はオートエンコーダ系の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-13","exam":"g","unit":"g-u6","keyword":"FCN","type":"choice","syllabus_ref":"6.1","stem":"セマンティックセグメンテーションのモデル FCN（Fully Convolutional Network）の説明として、正しいものはどれか。","choices":["分類ネットワークの全結合層を畳み込み層に置き換えて全体を畳み込みだけで構成し、縮小した特徴マップをアップサンプリングして入力と同じ大きさの画素ごとの予測に戻すことで、任意のサイズの入力画像に対応できるようにしたモデルである","プーリングで保存したインデックスを使ってアップサンプリングを行い、疎な特徴マップを密に戻すモデルである","異なる拡張率の畳み込みを並列に適用し、複数のスケールの文脈をまとめて捉えるモデルである","入力画像を複数の解像度で処理し、ピラミッド状に集めた特徴を画素ごとの予測に使うモデルである"],"answer":0,"explanation":"FCN は、画像分類ネットワークの全結合層を畳み込み層に置き換えた「全畳み込み」のネットワークで、セマンティックセグメンテーションの基礎となったモデルである。全結合層を取り除くことで入力サイズの制約がなくなり、畳み込みとプーリングで縮小した特徴マップをアップサンプリング（転置畳み込みなど）して元の解像度に戻すことで、各画素のクラスを予測する。プーリングインデックスを使うのは SegNet、異なる拡張率の並列畳み込みは DeepLab、複数解像度のピラミッド処理は PSPNet の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-14","exam":"g","unit":"g-u6","keyword":"U-Net","type":"choice","syllabus_ref":"6.1","stem":"セマンティックセグメンテーションのモデル U-Net の構造の特徴として、正しいものはどれか。","choices":["全結合層を持たず、畳み込みだけで入力から出力までを一直線に処理する構造である","畳み込みとプーリングで解像度を下げながら特徴を抽出する収縮経路（エンコーダ）と、アップサンプリングで解像度を戻す拡大経路（デコーダ）を対称に配置し、同じ解像度の特徴マップ同士をスキップ結合でつないで位置情報を補う、U字型の構造を持つ","チャンネルごとに特徴マップの重要度を学習し、重み付けによって特徴を強調・抑制する構造である","深さ・幅・解像度を均等な比率で同時に拡大することで精度と効率のバランスを取る構造である"],"answer":1,"explanation":"U-Net は、エンコーダ側の収縮経路とデコーダ側の拡大経路を対称に並べた U字型の構造を持ち、両経路の同じ解像度の特徴マップをスキップ結合（連結）でつなぐことで、圧縮で失われやすい位置の詳細情報をデコーダ側に補う。もともと医療画像のセグメンテーションのために提案され、少ない学習データでも高精度な画素単位の分割ができるモデルとして知られる。全結合層を持たない全畳み込みの発想は FCN、チャンネルごとの重要度の学習は SENet、深さ・幅・解像度の同時拡大は EfficientNet の説明である。なお、ここでのスキップ結合は、バッチ12で扱った残差ブロックの加算とは異なり、特徴マップを連結する形で使われている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-15","exam":"g","unit":"g-u6","keyword":"SegNet","type":"choice","syllabus_ref":"6.1","stem":"セマンティックセグメンテーションのモデル SegNet が、解像度を下げるプーリングの情報を復元の手がかりに使う仕組みとして、正しいものはどれか。","choices":["エンコーダの各段で特徴マップをそのまま保存しておき、デコーダで同じ大きさまで拡大して連結する","畳み込みの間隔を広げることで、プーリングを使わずに受容野を広げる","エンコーダの最大値プーリングで、最大値が現れた位置（インデックス）を記録しておき、デコーダのアップサンプリングでは、そのインデックスの位置にだけ値を戻して疎な特徴マップを作り、学習可能な畳み込みで密な特徴マップに変換する","画像全体の平均特徴を文脈として各画素の予測に加える"],"answer":2,"explanation":"SegNet は、エンコーダで最大値プーリングを行う際に、窓の中で最大値があった位置（プーリングインデックス）を記憶しておき、デコーダ側のアップサンプリングでその位置に値を配置して疎な特徴マップを作る。この仕組みにより、物体の境界の位置情報を保ちながら復元でき、アップサンプリング自体に学習パラメータを持たない分、メモリ効率も良い。エンコーダの特徴マップをそのまま連結して補うのは U-Net、間隔を広げた畳み込みは DeepLab の Atrous 畳み込み、画像全体の文脈の利用は PSPNet のピラミッドプーリングの説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-16","exam":"g","unit":"g-u6","keyword":"DeepLab","type":"choice","syllabus_ref":"6.1","stem":"セマンティックセグメンテーションのモデル DeepLab の特徴である Atrous 畳み込みと ASPP の説明として、正しいものはどれか。","choices":["フィルタの要素の間に間隔（穴）を空けて畳み込むことで、特徴マップの解像度を下げずに受容野を広げられる畳み込みであり、異なる間隔の Atrous 畳み込みを並列に組み合わせた ASPP により、複数のスケールの文脈を同時に捉える","特徴マップを複数回プーリングして段階的に文脈を集約する仕組みである","入力チャンネルごとに独立に畳み込みを行うことで、パラメータ数を削減する仕組みである","ネットワークの構造そのものを自動探索で決める仕組みである"],"answer":0,"explanation":"DeepLab は、Atrous 畳み込み（拡張畳み込み、dilated convolution とも呼ばれる）を中核とするセグメンテーションモデルである。フィルタの要素間に間隔を空けることで、プーリングで解像度を落とさなくても広い範囲の情報を捉えられ、位置の細かさと文脈の広さを両立できる。異なる拡張率の Atrous 畳み込みを並列に配置した ASPP（Atrous Spatial Pyramid Pooling）は、大きさの異なる物体の文脈を同時に扱うための仕組みである。なお Atrous 畳み込みは、バッチ9（畳み込み層）でキーワードとして扱った内容を、セグメンテーションのモデル側から捉え直したものである。複数段階のプーリングによる文脈集約は PSPNet、チャンネルごとの独立畳み込みは深さ方向畳み込み（MobileNet など）、構造の自動探索は NAS の説明である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-17","exam":"g","unit":"g-u6","keyword":"PSPNet","type":"choice","syllabus_ref":"6.1","stem":"セマンティックセグメンテーションのモデル PSPNet が、場面全体の文脈を利用するために用いる仕組みとして、正しいものはどれか。","choices":["特徴マップを複数の異なる大きさの格子にプーリングして、それぞれをアップサンプリングして元の特徴マップと連結するピラミッドプーリングにより、局所的な特徴と場面全体の大域的な文脈を組み合わせる","プーリングのインデックスを再利用して境界の位置を復元する","フィルタに間隔を空けた畳み込みを並列に適用して複数のスケールを捉える","エンコーダとデコーダの特徴マップをスキップ結合でつないで位置情報を補う"],"answer":0,"explanation":"PSPNet は、ピラミッドプーリングモジュールによって、特徴マップを複数のスケール（例えば全体、2×2、3×3、6×6 の格子）にプーリングし、各スケールの文脈情報を集めてから元の特徴マップと組み合わせる。これにより、画素の周囲の局所的な見た目だけでなく、場面全体の状況（どのような場所の画像か）を踏まえた画素ラベル付けができ、部分だけ見ると紛らわしい領域の誤判定を減らせる。プーリングインデックスの再利用は SegNet、間隔を空けた並列畳み込みは DeepLab の ASPP、スキップ結合による位置情報の補完は U-Net の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-18","exam":"g","unit":"g-u6","keyword":"SENet","type":"choice","syllabus_ref":"6.1","stem":"画像認識モデル SENet（Squeeze-and-Excitation Networks）の仕組みの説明として、正しいものはどれか。","choices":["各層がそれ以前の全層の特徴マップを連結して受け取り、特徴を再利用する","特徴マップをチャンネルごとに集約して各チャンネルの重要度を学習し、その重みでチャンネルごとの特徴を強調・抑制する（チャンネル方向の注意機構）ことで、精度を改善する","深さ・幅・入力解像度の3要素を一定の比率で同時にスケーリングする","モバイル端末向けに、計算量の制約の下でネットワーク構造を自動探索する"],"answer":1,"explanation":"SENet は、Squeeze（特徴マップを空間方向に集約してチャンネルごとの代表値を得る）と Excitation（その代表値から各チャンネルの重要度を学習し、重みとして掛け直す）の2段階で、チャンネルごとの特徴の強さを適応的に調整するブロックを導入したモデルである。重要なチャンネルの特徴を強め、不要なチャンネルを弱めることで、ネットワークの構造自体を大きく変えずに精度を高められる。全層の連結は DenseNet、3要素の同時スケーリングは EfficientNet、モバイル向けの自動探索は MnasNet の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-19","exam":"g","unit":"g-u6","keyword":"EfficientNet","type":"choice","syllabus_ref":"6.1","stem":"画像認識モデル EfficientNet がモデルの大きさを拡大する際の方針（複合スケーリング）として、正しいものはどれか。","choices":["層の数（深さ）だけを増やしてモデルを大きくする","チャンネル数（幅）だけを増やしてモデルを大きくする","入力画像の解像度だけを上げてモデルを大きくする","ネットワークの深さ・幅・入力画像の解像度の3つを、固定した比率の関係を保ちながら同時に拡大することで、精度と計算量のバランスを取る"],"answer":3,"explanation":"EfficientNet は、深さ・幅・解像度のどれか1つだけを拡大する従来のやり方に対し、3つを均等な比率（複合係数）で同時に拡大する複合スケーリング（compound scaling）を提案したモデルである。3要素のバランスを保って拡大することで、同じ計算量でもより高い精度が得られることが示された。基準となる小さなモデル EfficientNet-B0 は NAS（ニューラルアーキテクチャ探索）で得られたもので、B0 から B7 までが複合スケーリングで段階的に拡大された系列になっている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-20","exam":"g","unit":"g-u6","keyword":"NAS・MnasNet","type":"choice","syllabus_ref":"6.1","stem":"NAS（Neural Architecture Search）と、それを用いて得られた MnasNet の説明として、正しいものはどれか。","choices":["NAS は学習済みモデルの重みを圧縮して軽量化する手法で、MnasNet はその圧縮済みモデルである","NAS は学習データの量を自動的に増やす手法で、MnasNet はそのデータで学習したモデルである","NAS は人の手で設計した構造を改良する手法で、MnasNet はその手設計の最終形である","NAS は層や結合の組み合わせといったネットワークの構造（アーキテクチャ）そのものを自動的に探索する手法であり、MnasNet は、モバイル端末での実行を想定して精度と実機での推論の遅さ（レイテンシ）の両方を評価に入れて NAS で探索された、モバイル向けの軽量モデルである"],"answer":3,"explanation":"NAS（Neural Architecture Search）は、畳み込みの種類や層のつながり方など、ニューラルネットワークの構造そのものを探索空間として自動的に設計する手法である。人手の設計では試しきれない組み合わせの中から、評価指標の良い構造を探す。MnasNet は NAS の応用例で、モバイル端末での利用を想定し、精度だけでなく実機での推論レイテンシを探索の評価に組み込んで得られた軽量な画像認識モデルである。このように MnasNet は「NAS で探索されたモデル」として定義されるため、両者は結びつけて理解するのが核心になる。重みの圧縮は量子化や蒸留などの軽量化手法、学習データの自動増加はデータ拡張の領域であり、NAS とは異なる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-21","exam":"g","unit":"g-u6","keyword":"画像認識","type":"choice","syllabus_ref":"6.1","stem":"医療機関で、胸部CT画像から病変が疑われる領域を画素単位で塗り分けて医師の読影を支援するシステムを構築することになった。この用途に用いる画像認識のタスクとモデルの組み合わせとして、最も適切なものはどれか。","choices":["物体識別（画像分類）で画像全体に「病変あり／なし」のラベルを付け、AlexNet で分類する","物体検出で病変を矩形（バウンディングボックス）で囲み、Faster R-CNN で検出する","セマンティックセグメンテーションで各画素に病変か否かのラベルを付け、U-Net で領域を抽出する","姿勢推定で病変の位置をキーポイントとして推定し、Open Pose で位置を求める"],"answer":2,"explanation":"求められているのは「画素単位で領域を塗り分ける」ことであり、これは各画素にクラスラベルを割り当てるセマンティックセグメンテーションのタスクである。U-Net はもともと医療画像のセグメンテーションのために提案されたモデルで、少ない学習データでも画素単位の領域抽出ができるため、この用途の代表的な選択肢になる。物体識別は画像全体へのラベル付けであり領域は得られず、物体検出は矩形の位置までで画素単位の形状は得られない。姿勢推定は人の関節などのキーポイントを求めるタスクで、この用途には合わない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目26「画像認識」"},{"id":"g6-22","exam":"g","unit":"g-u6","keyword":"形態素解析・構文解析","type":"choice","syllabus_ref":"6.2","stem":"自然言語処理の解析処理である形態素解析と構文解析の説明として、正しいものはどれか。","choices":["形態素解析は文中の単語どうしの係り受けなどの文の構造を明らかにする処理で、構文解析は文を意味を持つ最小の単位に分割する処理である","形態素解析は、文を形態素（意味を持つ最小の単位）に分割し、各形態素に品詞などの情報を付ける処理で、構文解析は、その結果をもとに単語どうしの係り受けなどの文の構造を解析する処理である","形態素解析と構文解析は、どちらも文書を単語の出現回数で表すための処理である","形態素解析は音声を文字に変換する処理で、構文解析は文字を音声に変換する処理である"],"answer":1,"explanation":"形態素解析は、文を意味を持つ最小の単位である形態素に分割し、品詞などの情報を付ける処理である。日本語のように単語の区切りが明記されない言語では、テキスト処理の最初の段階として必要になる。構文解析は、形態素解析の結果をもとに、主語と述語の関係や係り受けといった文の構造を明らかにする処理である。文書を単語の出現回数で表すのは BoW、音声と文字の変換は音声処理の領域である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-23","exam":"g","unit":"g-u6","keyword":"感情分析・質問応答・情報検索・文書要約","type":"choice","syllabus_ref":"6.2","stem":"自然言語処理のタスクのうち、与えられた質問に対して、文書などの知識源の中から答えとなる語句や文を抽出したり生成したりするタスクはどれか。","choices":["テキストに表れた書き手の感情や評価（肯定的・否定的など）を判定するタスクである","大量の文書の中から、検索のキーワードに関連する文書を探し出すタスクである","文書の要点を保ちながら、短い文に圧縮して表すタスクである","質問文を入力として受け取り、文書などの知識源の中から、答えとなる語句や文を抽出・生成するタスクである"],"answer":3,"explanation":"質問文への答えを知識源から抽出・生成するタスクは質問応答である。書き手の感情や評価を判定するのは感情分析で、SNS の投稿やレビューの分析などに使われる。キーワードに関連する文書を探し出すのは情報検索、文書を要点を保って短くするのは文書要約であり、いずれも自然言語処理の代表的なタスクである。これらのタスクは、検索サービスや対話システムなど実世界の応用に直結している。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-24","exam":"g","unit":"g-u6","keyword":"機械翻訳・統計的機械翻訳","type":"choice","syllabus_ref":"6.2","stem":"機械翻訳と、その代表的な方式であった統計的機械翻訳の説明として、正しいものはどれか。","choices":["機械翻訳は、ある言語の文を別の言語の文へ自動的に変換するタスクで、統計的機械翻訳は、大量の対訳文（対訳コーパス）から文の対応関係を統計モデルとして学習する方式である","統計的機械翻訳は、文法規則と辞書を人手で大量に登録し、その規則だけで翻訳する方式である","機械翻訳は、音声を入力として別言語の音声を出力するタスクに限られる","統計的機械翻訳は、単語を辞書で1語ずつ置き換えるだけで、文の構造は一切扱わない"],"answer":0,"explanation":"機械翻訳は言語間の文の自動変換を行うタスクである。初期の方式は人手で登録した文法規則と辞書に頼るルールベース方式で、その後、大量の対訳コーパスから単語やフレーズの対応と言語の自然さを統計モデルとして学習する統計的機械翻訳が主流になった。統計的機械翻訳は単語の逐語置換ではなく、フレーズ単位の対応や言語モデルを用いて文全体の訳を決める。現在はニューラルネットワークによる方式（Seq2Seq など）が主流になっている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-25","exam":"g","unit":"g-u6","keyword":"ワンホットベクトル","type":"choice","syllabus_ref":"6.2","stem":"単語の特徴表現であるワンホットベクトル（one-hot ベクトル）の説明として、正しいものはどれか。","choices":["単語の意味の近さがベクトルの要素の値に埋め込まれた、密な低次元ベクトルである","文書中での各単語の出現回数をそのまま並べたベクトルである","語彙の数だけの次元を持ち、対象の単語に対応する要素だけが1で、他はすべて0であるベクトルで、単語どうしの意味の近さは表現できない","単語を構成する文字の並びを数値化したベクトルである"],"answer":2,"explanation":"ワンホットベクトルは、語彙数と同じ次元を持ち、対象の単語の位置だけが1、他がすべて0という疎なベクトルである。どの2つの単語の組も同じ距離になってしまうため、意味の近さは表せない。この欠点が、意味をベクトルの近さに反映する分散表現の動機になった。意味の近さが埋め込まれた密なベクトルは分散表現、出現回数を並べたものは BoW による文書表現の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-26","exam":"g","unit":"g-u6","keyword":"分散表現・単語埋め込み","type":"choice","syllabus_ref":"6.2","stem":"単語の分散表現（単語埋め込み）の説明として、正しいものはどれか。","choices":["単語を比較的低次元の密な実数ベクトルで表現するもので、意味の近い単語どうしはベクトルも近くなるように学習される","単語ごとに1つの要素だけが1になる、語彙数次元のベクトルである","文書の中での単語の出現順序を記録したベクトルである","単語を辞書の掲載順に振った番号で表したものである"],"answer":0,"explanation":"分散表現は、単語の意味を低次元の密なベクトルの各要素に分散させて表す表現であり、単語をベクトル空間に埋め込むことから単語埋め込みとも呼ばれる。意味や使われ方の近い単語は近いベクトルになり、ベクトルの演算で意味の関係を捉えられる場合がある（「王」−「男」＋「女」が「女王」に近づく例が知られる）。要素が1つだけ1になるのはワンホットベクトルである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-27","exam":"g","unit":"g-u6","keyword":"BoW・n-gram","type":"choice","syllabus_ref":"6.2","stem":"文書の特徴表現である BoW (Bag-of-Words) と n-gram の説明として、正しいものはどれか。","choices":["BoW は単語の並び順を保持する表現で、n-gram は単語の出現回数を数えない","BoW も n-gram も、単語の意味の近さをベクトルに反映する表現である","n-gram は文書全体を1つのベクトルに圧縮する手法で、BoW は文の構造を解析する手法である","BoW は、文書を単語の出現回数（または有無）の集まりとして表し、単語の並び順は考慮しない表現で、n-gram は、隣り合う n 個の単語（または文字）の並びを単位として数えることで、局所的な並びの情報を取り込む表現である"],"answer":3,"explanation":"BoW は、文書を「どの単語が何回現れたか」の集まりとして表す方法で、単語の並び順の情報は失われる。n-gram は、単語や文字が隣り合う n 個の並びを1つの単位として数える方法で、例えば単語の 2-gram（バイグラム）では隣接する2語の組が特徴になり、局所的な語順の情報を取り込める。どちらも意味の近さをベクトルに反映するものではなく、その点は分散表現と異なる。BoW の各要素には、後述の TF-IDF で重み付けされることが多い。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-28","exam":"g","unit":"g-u6","keyword":"TF-IDF","type":"choice","syllabus_ref":"6.2","stem":"文書集合における単語の重み付け TF-IDF について、tf を「その文書におけるその単語の出現回数」、idf を log10（全文書数 ÷ その単語を含む文書数）と定義する。全1,000件の文書のうち10件にだけ含まれる単語が、ある文書に3回出現した。この単語の、その文書における TF-IDF の値として正しいものはどれか。","choices":["2","6","3","300"],"answer":1,"explanation":"idf は log10（1,000 ÷ 10）＝ log10（100）＝ 2 である。TF-IDF は tf × idf で計算するので、3 × 2 ＝ 6 となる。2 は idf だけの値、3 は tf だけの値、300 は対数を取らずに 1,000 ÷ 10 × 3 と計算した誤りである。TF-IDF は、その文書によく現れ（tf が大きい）、かつ文書集合全体では珍しい（idf が大きい）単語ほど大きな値になり、文書の特徴を表す単語の重み付けとして情報検索や文書分類で使われる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-29","exam":"g","unit":"g-u6","keyword":"word2vec・CBOW・スキップグラム","type":"choice","syllabus_ref":"6.2","stem":"単語の分散表現を学習する word2vec と、その2つのモデル CBOW・スキップグラムの説明として、正しいものはどれか。","choices":["CBOW は中心の単語から周辺の単語を予測し、スキップグラムは周辺の単語から中心の単語を予測する","word2vec は、文書に TF-IDF で重み付けを行う手法である","word2vec は、単語の周辺に現れる単語（文脈）との関係から分散表現を学習する手法で、CBOW は周辺の単語から中心の単語を予測し、スキップグラムは中心の単語から周辺の単語を予測する","CBOW とスキップグラムは、どちらも単語を文字単位に分解して扱う手法である"],"answer":2,"explanation":"word2vec は、大量のテキストで「ある単語の周辺にはどのような単語が現れるか」という予測を学習させ、その過程で得られる内部表現を単語の分散表現として利用する手法である。CBOW（Continuous Bag-of-Words）は周辺の単語から中心の単語を予測し、スキップグラムは中心の単語から周辺の単語を予測する。スキップグラムは出現頻度の低い単語の表現の学習に比較的強いとされる。単語を文字単位に分解して扱うのは fastText である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-30","exam":"g","unit":"g-u6","keyword":"fastText","type":"choice","syllabus_ref":"6.2","stem":"単語の分散表現を得る手法 fastText の特徴として、正しいものはどれか。","choices":["文書全体を1つのベクトルに変換する手法で、単語ごとの表現は持たない","双方向の LSTM を用いて、文脈に応じた単語の表現を作る手法である","出現頻度の高い単語だけを対象とし、学習データに無い単語は扱えない","単語を、その部分文字列である文字 n-gram（サブワード）の集合としても表現するため、学習データに無い単語や活用形についても、サブワードからベクトルを構成できる"],"answer":3,"explanation":"fastText は word2vec を拡張した手法で、単語そのものに加えて、単語を構成する文字 n-gram（サブワード）のベクトルも合わせて単語の表現を作る。そのため、学習時に現れなかった単語でも、知っているサブワードを含んでいればベクトルを構成でき、活用や派生の多い単語にも対応しやすい。文脈に応じて表現が変わるのは ELMo のような文脈依存の埋め込みである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-31","exam":"g","unit":"g-u6","keyword":"BERT","type":"choice","syllabus_ref":"6.2","stem":"自然言語処理モデル BERT の説明として、正しいものはどれか。","choices":["双方向の LSTM を用い、その内部状態を特徴量として別のモデルに渡すモデルである","左から右へ単語を1つずつ予測して文章を生成することに特化したモデルである","Transformer のエンコーダを使い、文の一部の単語をマスクして予測する課題などで事前学習することで、単語の両側の文脈を捉えた表現を学習し、ファインチューニングによって様々なタスクに適用するモデルである","画像をパッチに分割し、畳み込みを使わずに処理するモデルである"],"answer":2,"explanation":"BERT は、Transformer のエンコーダを土台とし、文中の単語の一部をマスクして元を予測する課題（マスク化言語モデル）などで大規模テキストによる事前学習を行うモデルである。左右両方向の文脈を使って単語の表現を作る点が特徴で、事前学習済みモデルをタスクごとにファインチューニングして、質問応答や文書分類などに適用する枠組みを広めた。双方向 LSTM の内部状態を特徴量として使うのは ELMo、画像をパッチで処理するのは Vision Transformer である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-32","exam":"g","unit":"g-u6","keyword":"ELMo","type":"choice","syllabus_ref":"6.2","stem":"自然言語処理モデル ELMo の説明として、正しいものはどれか。","choices":["双方向の LSTM による言語モデルの内部表現を用いることで、同じ単語でも文脈に応じて異なるベクトル（文脈依存の埋め込み）を与えるモデルである","単語ごとに、文脈によらない固定のベクトルを与えるモデルである","Transformer のエンコーダを用い、マスクした単語を予測して事前学習するモデルである","単語を文字 n-gram の集合として表し、未知の単語に対応するモデルである"],"answer":0,"explanation":"ELMo は、前向きと後ろ向きの LSTM 言語モデルの内部表現を組み合わせて単語の表現を作るモデルで、同じ単語でも現れる文脈によって異なるベクトルが得られる（文脈依存の埋め込み）。word2vec などの従来の単語埋め込みは、単語ごとに1つの固定したベクトルしか持たず、多義語の意味の違いを表せなかった。Transformer のエンコーダでマスク予測により事前学習するのは BERT、文字 n-gram を使うのは fastText である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-33","exam":"g","unit":"g-u6","keyword":"大規模言語モデル (LLM)・PaLM","type":"choice","syllabus_ref":"6.2","stem":"大規模言語モデル (LLM) と PaLM の説明として、正しいものはどれか。","choices":["大規模言語モデルは、画像を生成するために学習されたモデルの総称である","大規模言語モデルは、大量のテキストで事前学習された大規模な言語モデルで、翻訳や要約、質問応答など多様なタスクに対応できるもので、PaLM は Google が開発した大規模言語モデルである","PaLM は、単語の分散表現を得るための小規模なモデルである","大規模言語モデルは、形態素解析専用のモデルの総称である"],"answer":1,"explanation":"大規模言語モデル (LLM) は、膨大なテキストデータと大規模なパラメータで事前学習された言語モデルで、文章の生成だけでなく、翻訳・要約・質問応答・対話など多様なタスクに適用され、実世界のサービスにも広く使われている。PaLM は Google が開発した代表的な大規模言語モデルの1つである。単語の分散表現を得る小規模なモデルは word2vec などであり、大規模言語モデルとは規模も役割も異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-34","exam":"g","unit":"g-u6","keyword":"感情分析","type":"choice","syllabus_ref":"6.2","stem":"SNS の投稿や商品レビューなどのテキストを大量に集め、書き手が対象に対して肯定的な評価をしているのか、否定的な評価をしているのかといった、文章に表れた感情や評価の向き（極性）を自動で判定したい。このようなタスクはどれか。","choices":["質問応答 — 質問文を受け取り、文書などの知識源の中から答えとなる語句や文を抽出・生成するタスク","情報検索 — 大量の文書の中から、検索のキーワードに関連する文書を探し出すタスク","感情分析 — テキストに表れた書き手の感情や評価が肯定的か否定的かといった極性を判定するタスク","文書要約 — 文書の要点を保ちながら、短い文に圧縮して表すタスク"],"answer":2,"explanation":"文章に表れた書き手の感情や評価の向きを判定するタスクが感情分析である。肯定・否定の二分だけでなく、中立的な評価を含めた分類や、評価の強さの段階付けとして行われることもある。SNS の投稿や商品レビューの分析による評判の把握などが代表的な用途である。知識源から答えを出すのは質問応答、関連文書を探し出すのは情報検索、文書を短く圧縮するのは文書要約であり、いずれも判定の対象が感情や評価の極性ではない。なおバッチ18の g6-23 では感情分析は誤答の定義文として現れただけであり、本問はタスク自体を主題として、その用途と判定対象を問う点で中心命題が異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-35","exam":"g","unit":"g-u6","keyword":"情報検索","type":"choice","syllabus_ref":"6.2","stem":"情報検索は、利用者が示した検索の要求（クエリ）に対して、大量の文書の中から関連する文書を探し出して提示するタスクである。その基本的な仕組みの説明として、正しいものはどれか。","choices":["文書をあらかじめ単語の出現などの特徴で表しておき、クエリとの関連度（適合度）を計算して、関連度の高い順に文書を並べて提示する","文書の要点を保ちながら短く圧縮し、圧縮された文を利用者に提示する","書き手の感情や評価の極性を判定し、肯定的な文書だけを選んで提示する","文書を別の言語に自動的に変換してから利用者に提示する"],"answer":0,"explanation":"情報検索の中心は、利用者のクエリに対して関連する文書を探し出し、関連度の高い順に提示することである。文書とクエリの関連度を計算するために、文書は単語の出現などをもとに特徴で表され、単語の重み付けには TF-IDF（バッチ18の g6-28 で扱った）が古典的に使われてきた。ただし TF-IDF は文書を特徴で表すための手段であり、検索タスクそのものは「要求に合う文書を探し出して関連度順に提示する」点に中心がある。文書の圧縮は文書要約、感情や評価の極性の判定は感情分析、言語の変換は機械翻訳の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-36","exam":"g","unit":"g-u6","keyword":"文書要約","type":"choice","syllabus_ref":"6.2","stem":"文書要約には、元の文書から重要な文をそのまま抜き出してつなげる方式と、文書の内容を踏まえたうえで、元の文書に無い表現も使って新しい文を作る方式がある。この2つの方式の呼び方と説明の組み合わせとして、正しいものはどれか。","choices":["元の文を抜き出す方式を生成型、内容を踏まえて新しい文を作る方式を抽出型と呼ぶ","元の文をそのまま抜き出す方式を抽出型、内容を踏まえて新しい文を作る方式を生成型（抽象型）と呼び、生成型は自然な文の要約が得られる一方で、元の文書に無い内容を作り出してしまうことがある","抽出型も生成型も元の文を抜き出す方式であり、両者の違いは要約の長さだけである","抽出型は文書を別の言語に翻訳してから要約する方式で、生成型は音声から要約を作る方式である"],"answer":1,"explanation":"文書要約の方式は大きく2つに分けられる。抽出型は、元の文書の中から重要と判断した文をそのまま抜き出してつなげる方式で、元の文を使うため内容の正確さは保ちやすいが、文のつながりが不自然になることがある。生成型（抽象型とも呼ばれる）は、文書の内容を踏まえて新しい文を生成する方式で、人間の要約に近い自然な文が得られる一方、元の文書に書かれていない内容を生成してしまう危険がある。バッチ18の g6-23 では文書要約は誤答の定義文として現れただけであり、本問は要約というタスク内部の方式の区別そのものを主題とする点で中心命題が異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-37","exam":"g","unit":"g-u6","keyword":"GLUE","type":"choice","syllabus_ref":"6.2","stem":"自然言語理解のベンチマーク GLUE の説明として、正しいものはどれか。","choices":["単語の分散表現を学習するための手法の名前である","文書を単語の出現回数で表す特徴表現の名前である","Google が開発した大規模言語モデルの名前である","文どうしの意味の類似度の判定や、文の含意関係の認識、感情分析など、自然言語理解に関する複数のタスクを集めたベンチマークで、モデルの言語理解能力を共通の物差しで評価するために用いられる"],"answer":3,"explanation":"GLUE（General Language Understanding Evaluation）は、自然言語理解に関する複数のタスクを1つにまとめたベンチマーク集である。文の類似度判定、含意関係の認識、感情分析など性格の異なるタスクを共通の枠組みで評価することで、特定のタスクだけに特化していない、モデルの汎用的な言語理解能力を測る物差しとして使われてきた。後に、より難しいタスクで構成された後継の SuperGLUE も提案されている。単語の分散表現の学習手法は word2vec など、出現回数による特徴表現は BoW、大規模言語モデルの例は PaLM であり、いずれもベンチマークではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-38","exam":"g","unit":"g-u6","keyword":"CEC","type":"choice","syllabus_ref":"6.2","stem":"LSTM のメモリセル内部にある CEC（定誤差カルーセル、Constant Error Carousel）の説明として、正しいものはどれか。","choices":["セル状態を時刻ごとにゼロに初期化し直すことで、誤差の蓄積を防ぐ仕組みである","誤差を時刻ごとに増幅させて伝えることで、学習を速くする仕組みである","メモリセルの自己結合の重みを1に保つことで、誤差が時間方向に減衰も爆発もせず一定のまま流れ続けるようにした経路であり、勾配消失への対処として LSTM に組み込まれた仕組みである","入力データをセルに書き込むかどうかを制御するゲートそのものの名前である"],"answer":2,"explanation":"CEC（定誤差カルーセル）は、LSTM のメモリセルの内部で、セル状態が自分自身へ戻る自己結合の重みを1に保つ仕組みである。この経路では、学習の誤差が時間方向に伝わる際に減衰も爆発もせず一定のまま流れ続けるため、長い系列の先の情報と誤差が結びつき、単純な RNN で深刻だった勾配消失問題への対処になった。バッチ13の g5-70 はセル状態と3つのゲートという LSTM の全体像を扱ったが、本問はセル内部の誤差の流れの経路そのものを問う点で角度が異なる。なお現在の LSTM では、忘却ゲートがこの自己結合の効き具合を時刻ごとに調整する形に発展している。データを書き込むかどうかを制御するのは入力ゲートであり、CEC そのものではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-39","exam":"g","unit":"g-u6","keyword":"自然言語処理","type":"choice","syllabus_ref":"6.2","stem":"ある企業が、自然言語処理を使って業務を支援したいと考えている。（1）社員が社内の大量のマニュアルや報告書の中から、知りたい内容に関連する文書をすぐに見つけられるようにしたい。（2）顧客から寄せられる質問に、製品マニュアルの内容に基づいて自動で答えられるようにしたい。（3）自社製品のレビューを集めて、利用者の評価が肯定的か否定的かの傾向を継続的に把握したい。（1）〜（3）に適したタスクの組み合わせとして、正しいものはどれか。","choices":["（1）感情分析、（2）情報検索、（3）質問応答","（1）情報検索、（2）質問応答、（3）感情分析","（1）文書要約、（2）感情分析、（3）機械翻訳","（1）機械翻訳、（2）文書要約、（3）情報検索"],"answer":1,"explanation":"（1）大量の文書の中から内容に関連する文書を探し出すのは情報検索の役割である。（2）質問に対して知識源の内容に基づいて答えるのは質問応答の役割であり、製品マニュアルを知識源とする形は、顧客対応の自動化として実世界で広く使われている。（3）レビューに表れた評価が肯定的か否定的かの傾向を把握するのは感情分析の役割である。このように、自然言語処理のタスクは、扱いたい業務の目的に応じて選び分けるものであり、場面ごとに適切なタスクが異なる。本問はバッチ18の g6-23（定義からのタスクの同定）とは異なり、具体的な活用場面からタスクを選択する判断そのものを主題としている。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目27「自然言語処理」"},{"id":"g6-40","exam":"g","unit":"g-u6","keyword":"音声認識","type":"choice","syllabus_ref":"6.3","stem":"音声処理のタスクである音声認識の説明として、正しいものはどれか。","choices":["音声を入力として受け取り、その内容をテキスト（文字列）に変換するタスクである","テキストを入力として受け取り、読み上げ音声を生成するタスクである","音声から、誰が話しているかを特定するタスクである","音声から、話し手の感情を推定するタスクである"],"answer":0,"explanation":"音声認識は、人が話した音声をテキストに変換するタスクで、音声アシスタントへの話しかけや、会議の議事録の自動作成などに使われている。テキストから読み上げ音声を生成するのは音声合成、誰が話しているかを特定するのは話者識別、話し手の感情を推定するのは感情分析であり、いずれも音声処理の別のタスクである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-41","exam":"g","unit":"g-u6","keyword":"音声合成・WaveNet","type":"choice","syllabus_ref":"6.3","stem":"音声合成と、その代表的なモデルである WaveNet の説明として、正しいものはどれか。","choices":["音声合成は音声をテキストに変換するタスクで、WaveNet はその変換に使うモデルである","WaveNet は、音声の特徴量から話者を識別するためのモデルである","音声合成はテキストから音声を作り出すタスクで、WaveNet は、音声波形のサンプル値を過去のサンプルから1つずつ予測する自己回帰型の生成により、生の波形そのものを生成するモデルである","WaveNet は、周波数スペクトルのパラメータだけを出力し、波形そのものは生成しないモデルである"],"answer":2,"explanation":"音声合成は、テキストを読み上げ音声に変換するタスクで、カーナビの案内音声やスマートスピーカーの応答などに使われている。WaveNet は、波形の次のサンプル値を、それまでのサンプルから予測する自己回帰型の生成モデルで、生の音声波形そのものを生成することで、従来のパラメータから波形を組み立てる方式より自然な合成音声を実現した。音声をテキストに変換するのは音声認識の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-42","exam":"g","unit":"g-u6","keyword":"話者識別","type":"choice","syllabus_ref":"6.3","stem":"音声処理のタスクである話者識別の説明として、正しいものはどれか。","choices":["音声の内容をテキストに変換するタスクである","音声の特徴から、誰が話しているかを特定するタスクである","音声から、話し手の感情を推定するタスクである","テキストを読み上げ音声に変換するタスクである"],"answer":1,"explanation":"話者識別は、音声に含まれる声の特徴から、話している人物を特定するタスクである。声を本人確認に使う声紋認証はその応用である。何を話したかをテキスト化するのは音声認識、感情を推定するのは感情分析、テキストを読み上げるのは音声合成であり、音声認識が「何を言ったか」を扱うのに対して、話者識別は「誰が言ったか」を扱う点が異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-43","exam":"g","unit":"g-u6","keyword":"感情分析","type":"choice","syllabus_ref":"6.3","stem":"音声処理における感情分析の説明として、正しいものはどれか。","choices":["テキストに表れた書き手の感情や評価の極性を判定するタスクである","音声から、誰が話しているかを特定するタスクである","音声の内容をテキストに変換するタスクである","声の高さ（ピッチ）の変化や抑揚、声の大きさ、話す速さといった音声の特徴から、話し手の感情の状態を推定するタスクである"],"answer":3,"explanation":"音声処理における感情分析は、声の高さの変化や抑揚、大きさ、話す速さといった、声そのものに表れる特徴から、話し手が怒っているか喜んでいるかなどの感情の状態を推定するタスクで、コールセンターの応対分析などに応用される。テキストの書き手の感情や評価を判定するのも感情分析と呼ばれるが、そちらは自然言語処理におけるタスクであり、本問の音声からの推定とは対象が異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-44","exam":"g","unit":"g-u6","keyword":"音素・音韻","type":"choice","syllabus_ref":"6.3","stem":"言語の音の単位である音素と音韻の説明として、正しいものはどれか。","choices":["音素は、1つの音節を構成する音の塊のことである","音素は、その言語の音の体系（音韻）の中で、意味を区別する働きを持つ最小の音の単位である","音素は、文字を構成する最小の単位である","音韻は、声の高さの変化のパターンのことである"],"answer":1,"explanation":"音素は、言語の音の体系である音韻の中で、意味を区別する最小の単位である。例えば日本語では「か」と「が」は音素が異なるために意味が区別される。音声認識では、音声を音素の並びとして捉えることが音響モデルの基礎になってきた。音節は音素が集まった単位であり、音素そのものではない。文字の最小単位でもない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-45","exam":"g","unit":"g-u6","keyword":"A-D 変換・パルス符号変調器 (PCM)","type":"choice","syllabus_ref":"6.3","stem":"A-D 変換と、その代表的な方式であるパルス符号変調器 (PCM) の説明として、正しいものはどれか。","choices":["A-D 変換は、デジタルデータをアナログの音声に戻す変換である","PCM では、まず波形の振幅を量子化し、その後で一定間隔の標本化を行う","PCM は、音声データを圧縮して記録容量を減らすための方式である","A-D 変換は、アナログの音声信号をデジタルのデータに変換する処理で、PCM はその代表的な方式であり、一定間隔で波形の値を取り出す標本化、値を段階的な数値に丸める量子化、数値を符号に直す符号化の順に行う"],"answer":3,"explanation":"A-D 変換は、アナログ信号をデジタルデータに変換する処理で、逆向きの変換は D-A 変換である。PCM（パルス符号変調）は、CD などでも使われる A-D 変換の代表的な方式で、標本化（サンプリング）、量子化、符号化の3つの段階からなる。標本化の間隔を決めるサンプリング周波数と、量子化の細かさを決める量子化ビット数が、デジタル音声の品質を左右する。PCM 自体は圧縮を行わない方式である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-46","exam":"g","unit":"g-u6","keyword":"A-D 変換","type":"choice","syllabus_ref":"6.3","stem":"サンプリング周波数 44.1kHz、量子化ビット数 16 ビット、ステレオ（2チャンネル）で、60秒間の音声を PCM で記録したときのデータ量（バイト）として、正しいものはどれか。ただし、圧縮は行わず、ヘッダなどの付加情報は考えないものとする。","choices":["5,292,000","84,672,000","10,584,000","21,168,000"],"answer":2,"explanation":"1秒あたりのデータ量は、44,100 × 16 × 2 ＝ 1,411,200 ビットである。60秒分では 1,411,200 × 60 ＝ 84,672,000 ビットとなり、バイトに直すと 84,672,000 ÷ 8 ＝ 10,584,000 バイトである。84,672,000 はビットのままの値、5,292,000 は片チャンネル（モノラル）で計算した値、21,168,000 は2倍に数えた値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-47","exam":"g","unit":"g-u6","keyword":"高速フーリエ変換 (FFT)","type":"choice","syllabus_ref":"6.3","stem":"高速フーリエ変換 (FFT) の説明として、正しいものはどれか。","choices":["時間とともに変化する信号（波形）を、周波数ごとの成分（スペクトル）に分解するフーリエ変換を、高速に計算するためのアルゴリズムである","アナログの音声をデジタルデータに変換する処理そのものである","音声データの容量を圧縮するための符号化方式である","音声波形を自己回帰的に生成するモデルである"],"answer":0,"explanation":"高速フーリエ変換 (FFT) は、離散フーリエ変換を効率よく計算するアルゴリズムで、時間領域の波形を周波数領域のスペクトルに変換する。音声処理では、音声を短い区間に区切って FFT を適用し、周波数成分の分布を取り出すことが、特徴量抽出の出発点になる。アナログからデジタルへの変換は A-D 変換、波形を生成するモデルは WaveNet などである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-48","exam":"g","unit":"g-u6","keyword":"スペクトル包絡・フォルマント・フォルマント周波数","type":"choice","syllabus_ref":"6.3","stem":"音声のスペクトル包絡とフォルマントの説明として、正しいものはどれか。","choices":["スペクトル包絡は、時間の経過に伴う音の大きさの変化を表す曲線である","スペクトル包絡は、周波数スペクトルのなだらかな概形（輪郭）で、声道の共鳴の特性を表し、そのピークをフォルマントといい、フォルマントの現れる周波数（フォルマント周波数、とくに第1・第2フォルマント）の組み合わせによって母音が区別される","フォルマントは、声の高さを決める基本周波数のことである","フォルマント周波数は、音声のサンプリング周波数のことである"],"answer":1,"explanation":"音声のスペクトルは細かい凹凸を持つが、そのなだらかな輪郭をたどったものがスペクトル包絡であり、声道（口や喉の空間）の共鳴の特性を反映する。包絡のピークがフォルマントで、その周波数がフォルマント周波数である。母音の違いは、主に第1フォルマント周波数と第2フォルマント周波数の組み合わせで区別される。声の高さを決めるのは基本周波数であり、フォルマントとは別の概念である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-49","exam":"g","unit":"g-u6","keyword":"メル尺度・メル周波数ケプストラム係数 (MFCC)","type":"choice","syllabus_ref":"6.3","stem":"メル尺度と、それを用いた特徴量であるメル周波数ケプストラム係数 (MFCC) の説明として、正しいものはどれか。","choices":["メル尺度は、物理的な周波数をそのまま等間隔に区切った尺度である","MFCC は、生の音声波形をそのまま入力として使う特徴量である","MFCC は、音声合成のために声のパラメータを記録する方式である","メル尺度は、人間の聴覚の感じ方に合わせた周波数の尺度（低い周波数では細かく、高い周波数では粗く感じる）で、MFCC は、スペクトルをメル尺度で捉え直し、対数を取って離散コサイン変換することで得られる特徴量であり、音声認識の代表的な特徴量として使われてきた"],"answer":3,"explanation":"メル尺度は、人間が感じる音の高さの間隔に合わせた尺度で、物理的な周波数が2倍になっても、感じる高さが等間隔に増えるとは限らないという聴覚の性質を反映している。MFCC は、音声のスペクトルをメル尺度に基づくフィルタバンクで要約し、対数スペクトルに離散コサイン変換を適用して得る特徴量で、声道の特性（スペクトル包絡）をコンパクトに表すため、音声認識の標準的な特徴量として広く使われてきた。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-50","exam":"g","unit":"g-u6","keyword":"隠れマルコフモデル","type":"choice","syllabus_ref":"6.3","stem":"音声認識で用いられてきた隠れマルコフモデル (HMM) の説明として、正しいものはどれか。","choices":["音素などの状態の遷移確率と、各状態から音響特徴が観測される確率によって音声をモデル化するもので、状態の系列そのものは直接観測できないため「隠れ」と呼ばれる","音声波形のサンプルを自己回帰的に生成するモデルである","画像の中から物体の位置を検出するモデルである","報酬を最大化する行動を学習する強化学習の手法である"],"answer":0,"explanation":"隠れマルコフモデルは、観測されるデータの背後に、直接は見えない状態の遷移があると考える確率モデルである。音声認識では、音素などを状態として、状態どうしの遷移確率と、各状態でどのような音響特徴（MFCC など）が現れるかの確率を学習し、観測された特徴の並びから最もらしい状態の並び、すなわち音素や単語の並びを推定する、古典的な音響モデルの中核であった。波形を生成するのは WaveNet である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-51","exam":"g","unit":"g-u6","keyword":"CTC","type":"choice","syllabus_ref":"6.3","stem":"音声認識における CTC (Connectionist Temporal Classification) の説明として、正しいものはどれか。","choices":["音声データを圧縮して転送するための符号化の規格である","アナログ音声を標本化する間隔を決める方式である","入力の音響フレームの並びと出力の文字の並びで長さが異なり、どのフレームがどの文字に対応するか（対応付け）が分からなくても、空白記号の挿入や同じ文字の連続を許したあらゆる対応付けを考えて学習できる枠組みで、エンドツーエンドの音声認識に使われる","音声から話者を識別するための手法である"],"answer":2,"explanation":"音声のフレーム数は文字数よりはるかに多く、しかも学習データには「どの区間がどの文字か」の区切りが通常は与えられない。CTC は、出力に空白記号を加え、同じ文字の連続を1つにまとめる規則のもとで、考えられるすべての対応付け（アライメント）の確率を合計することで、対応付けなしに系列どうしを学習できるようにした損失の枠組みである。これにより、特徴抽出から文字の出力までを1つのニューラルネットワークで学習するエンドツーエンド音声認識が実用化した。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-52","exam":"g","unit":"g-u6","keyword":"音声処理","type":"choice","syllabus_ref":"6.3","stem":"ある企業のコールセンターでは、音声処理の技術を使って応対業務を改善したいと考えている。（1）オペレーターと顧客の通話内容を自動でテキストに変換して記録として残し、後から内容を検索できるようにしたい。（2）電話をかけてきた顧客について、声の特徴から本人であることを確認したい。（3）顧客の声の大きさや抑揚、話す速さの変化から、不満や怒りの兆候を検知して応対の改善につなげたい。（1）〜（3）に適したタスクの組み合わせとして、正しいものはどれか。","choices":["（1）話者識別、（2）音声認識、（3）感情分析","（1）音声認識、（2）話者識別、（3）感情分析","（1）音声認識、（2）感情分析、（3）話者識別","（1）音声合成、（2）音声認識、（3）感情分析"],"answer":1,"explanation":"（1）話した内容をテキストに変換するのは音声認識の役割であり、通話記録の自動作成と検索はその代表的な活用である。（2）声の特徴から「誰が話しているか」を特定するのは話者識別の役割で、声による本人確認（声紋認証）はその応用である。（3）声の大きさや抑揚、話す速さといった声そのものの特徴から話し手の感情の状態を推定するのは、音声処理における感情分析の役割である。テキストから読み上げ音声を生成する音声合成は、通話内容の記録には使われない。このように、音声処理のタスクは、活用場面で解決したい課題に応じて選び分けるものである。バッチ19の g6-40（音声認識）・g6-42（話者識別）・g6-43（感情分析）は各タスクの定義そのものを主題としたが、本問は具体的な活用場面からタスクを選択する判断そのものを主題とする点で中心命題が異なる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目28「音声処理」"},{"id":"g6-53","exam":"g","unit":"g-u6","keyword":"DQN","type":"choice","syllabus_ref":"6.4","stem":"深層強化学習の代表的な手法である DQN の説明として、正しいものはどれか。","choices":["状態における各行動の価値（Q値）を深層ニューラルネットワークで近似する手法で、ゲーム画面のような高次元の入力から、行動の価値を直接学習できるようにした","方策そのものを深層ニューラルネットワークで表し、得られた報酬の大きさに応じて方策のパラメータを勾配で更新する手法である","人間の熟練者のプレイデータを教師データとして、その行動を模倣するよう学習する手法である","環境の振る舞いを再現するシミュレータを学習し、その中で計画を立てて行動を決める手法である"],"answer":0,"explanation":"DQN は、強化学習の Q 学習で用いる行動価値（Q値）を深層ニューラルネットワークで近似した手法で、2015年に Atari のビデオゲームで、画面のピクセルだけを入力として人間並み以上のスコアを達成したことで知られる。過去の経験を蓄えて再利用する経験再生（リプレイバッファ）と、学習目標の計算に使うターゲットネットワークを分ける工夫によって、高次元の入力でも学習を安定させた。方策を直接更新するのは方策勾配法の説明、熟練者の模倣は模倣学習の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-54","exam":"g","unit":"g-u6","keyword":"ダブル DQN","type":"choice","syllabus_ref":"6.4","stem":"ダブル DQN が、通常の DQN に対して加えた改良の説明として、正しいものはどれか。","choices":["2つのネットワークを並行して学習させ、その Q 値の平均を行動の価値として使う","Q値の過大評価を抑えるため、次状態で取る行動を選ぶ役割と、選ばれた行動の価値を評価する役割とを、学習中のネットワークとターゲットネットワークに分担させる","状態の価値と各行動の優位性を別々に推定し、組み合わせて Q 値を構成する","方策を表すネットワークと、状態価値を表すネットワークを同時に学習させる"],"answer":1,"explanation":"通常の DQN では、次状態の Q 値の最大値をそのまま学習目標に使うため、推定のばらつきによって Q 値が実際より大きく見積もられる過大評価が起きやすい。ダブル DQN は、次状態でどの行動を取るかの選択を学習中のネットワークに、その行動の価値の評価をターゲットネットワークに分担させることで、この偏りを抑える。状態価値と優位性に分けるのはデュエリングネットワーク、方策と価値を同時に学ぶのはアクター・クリティック型の手法の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-55","exam":"g","unit":"g-u6","keyword":"デュエリングネットワーク・ノイジーネットワーク","type":"choice","syllabus_ref":"6.4","stem":"DQN の改良であるデュエリングネットワークとノイジーネットワークの説明の組み合わせとして、正しいものはどれか。","choices":["デュエリングネットワークは、次状態の行動の選択と評価を別々のネットワークに分担させる手法であり、ノイジーネットワークは、報酬にランダムなノイズを加えて探索を促す手法である","デュエリングネットワークは、2つの Q ネットワークの出力の平均を取る手法であり、ノイジーネットワークは、入力画像にノイズを加えてデータの多様性を増やす手法である","デュエリングネットワークは、状態そのものの価値と、各行動を取ることの優位性（アドバンテージ）を別々の流れで推定し、組み合わせて Q 値を構成するアーキテクチャであり、ノイジーネットワークは、ネットワークの重みにノイズを加えることで、ε-greedy に代わる探索を行う手法である","デュエリングネットワークは、経験を2倍の頻度で再生する手法であり、ノイジーネットワークは、ターゲットネットワークの更新を速める手法である"],"answer":2,"explanation":"デュエリングネットワークは、行動によらない状態の価値と、その状態で各行動を取る優位性を分けて推定する構造で、行動の選択が結果にあまり影響しない状態でも価値の学習が進みやすい。ノイジーネットワークは、ネットワークの重み（パラメータ）に学習可能なノイズを加え、行動の探索を ε-greedy のような外部からのランダムな行動選択ではなく、ネットワーク自身の出力の揺らぎによって行う手法である。行動の選択と評価の分担はダブル DQN の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-56","exam":"g","unit":"g-u6","keyword":"Rainbow","type":"choice","syllabus_ref":"6.4","stem":"深層強化学習の手法である Rainbow の説明として、正しいものはどれか。","choices":["複数のエージェントが同じ環境で協調しながら学習する、マルチエージェント強化学習の枠組みである","人間のフィードバックから報酬モデルを学習し、それを使って方策を最適化する手法である","シミュレーションで学習した方策を、現実のロボットで動作させるための転移の手法である","ダブル DQN、デュエリングネットワーク、優先順位付き経験再生、ノイジーネットワークなど、DQN に対する複数の改良を1つのエージェントに統合し、Atari のゲームで高い性能を示した手法である"],"answer":3,"explanation":"Rainbow は、DQN の改良として個別に提案されてきた複数の手法（ダブル DQN、優先順位付き経験再生、デュエリングネットワーク、複数ステップの学習、分布型の価値表現、ノイジーネットワーク）をすべて組み合わせたエージェントで、個々の改良の寄与を検証しながら、Atari のゲーム群で従来を上回る性能を示した。複数のエージェントの協調はマルチエージェント強化学習、人間のフィードバックの利用は RLHF の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-57","exam":"g","unit":"g-u6","keyword":"APE-X・Agent57","type":"choice","syllabus_ref":"6.4","stem":"深層強化学習の大規模化に関わる APE-X と Agent57 の説明として、正しいものはどれか。","choices":["APE-X は、多数のアクターが並行して環境で行動し経験を集め、中央の学習器が優先順位付きの経験再生によって学習する分散型のアーキテクチャであり、Agent57 はその系譜の分散学習を土台に、探索と活用のバランスの取り方自体を適応的に調整することで、Atari の全57種のゲームで人間のスコアを超えたエージェントである","APE-X は、人間のプレイヤーのフィードバックを集めて報酬を設計する仕組みであり、Agent57 は、囲碁で人間のプロ棋士に勝利したエージェントである","APE-X は、単一のコンピュータ上で学習を高速化する GPU の使い方の工夫であり、Agent57 は、57台のロボットを同時に制御するシステムである","APE-X は、シミュレーションと現実のずれを埋めるための手法であり、Agent57 は、自動運転車の走行データから学習したエージェントである"],"answer":0,"explanation":"APE-X は、経験を集める多数のアクターと、集まった経験から学習する中央の学習器を分離した分散アーキテクチャで、大量の経験を効率よく学習に使うことで Atari のゲームで高い性能を示した。Agent57 は、この分散学習の流れを汲むエージェントで、探索を重視する方策から活用を重視する方策までを用意し、状況に応じてその配分を適応的に切り替えることで、評価対象の Atari 全57種すべてのゲームで人間の基準スコアを超えた初めてのエージェントとなった。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-58","exam":"g","unit":"g-u6","keyword":"A3C・PPO","type":"choice","syllabus_ref":"6.4","stem":"方策勾配法の系統に属する A3C と PPO の説明の組み合わせとして、正しいものはどれか。","choices":["A3C は、Q値を深層ニューラルネットワークで近似する手法であり、PPO は、過去の経験をバッファに蓄えて再利用する手法である","A3C は、複数のワーカーがそれぞれ環境とやり取りしながら非同期・並列に学習し、方策（アクター）と状態価値（クリティック）を同時に更新する手法であり、PPO は、方策の更新の幅が大きくなりすぎないよう目的関数に制限（クリッピング）を加え、学習の安定を図る手法である","A3C は、環境と対話せず固定のデータだけから学習する手法であり、PPO は、人間のフィードバックから報酬モデルを学習する手法である","A3C は、複数のエージェントが協調する専用の手法であり、PPO は、Q値の過大評価を抑えるための手法である"],"answer":1,"explanation":"A3C は、アクター・クリティック型の手法を、複数のワーカーによる非同期の並列実行で学習させる方法で、経験再生を使わずに学習を安定・高速化した。PPO は、方策勾配法の学習で方策が一度に大きく変わりすぎて性能が崩れることを防ぐため、新しい方策と古い方策の変化の比率に制限（クリッピング）を加えた目的関数を用いる手法で、ロボットの制御から大規模言語モデルの調整まで幅広く使われている。固定データだけから学ぶのはオフライン強化学習、Q値の過大評価の抑制はダブル DQN の説明である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-59","exam":"g","unit":"g-u6","keyword":"報酬成形・RLHF","type":"choice","syllabus_ref":"6.4","stem":"報酬の設計や獲得に関わる、報酬成形と RLHF の説明の組み合わせとして、正しいものはどれか。","choices":["報酬成形は、人間の出力への評価から報酬モデルを学習することであり、RLHF は、本来の報酬に補助的な報酬を設計して加えることである","報酬成形は、報酬を一切与えずに学習させることであり、RLHF は、報酬をランダムに与えることで探索を促すことである","報酬成形は、本来の報酬だけでは学習が進みにくい場合に、目標に近づく行動へ手がかりとなる補助的な報酬を設計して加え、学習を進みやすくすることであり、RLHF は、人間がモデルの出力を比較・評価したフィードバックから報酬モデルを学習し、それを報酬として強化学習でモデルを最適化する手法である","報酬成形は、経験再生で使う経験の優先順位を決めることであり、RLHF は、シミュレーション環境を自動で生成する手法である"],"answer":2,"explanation":"報酬成形は、ゴールしたときだけ報酬が得られるような疎な報酬の環境で、途中の望ましい振る舞いに補助的な報酬を与えるなど、学習の手がかりを設計する工夫である。RLHF（人間のフィードバックによる強化学習）は、大規模言語モデルの調整などで使われ、人間が複数の出力の良し悪しを比較したデータから「人間が好む出力」を予測する報酬モデルを作り、その報酬を最大化するよう強化学習（PPO など）でモデルを最適化する。両者は「報酬をどう用意するか」という点で対比される。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-60","exam":"g","unit":"g-u6","keyword":"オフライン強化学習","type":"choice","syllabus_ref":"6.4","stem":"オフライン強化学習の説明として、正しいものはどれか。","choices":["学習の際にネットワーク（インターネット）へ接続しないで行う強化学習のことである","シミュレーション環境の中だけで完結し、現実の環境では使わない強化学習のことである","報酬を一切使わずに、行動の記録だけから方策を学習する枠組みである","環境と新たに対話して経験を集めることはせず、過去に収集された固定のデータセットだけを使って方策を学習する枠組みである"],"answer":3,"explanation":"オフライン強化学習は、学習の過程で環境を動かして新しい経験を集めることをせず、既存の運用記録や人間の操作記録など、あらかじめ集められた固定のデータだけから方策を学習する枠組みである。医療や産業機器のように、試行錯誤そのものにコストや危険が伴う領域で注目される。一方で、データに含まれない行動の価値を過大に見積もってしまう問題への対処が課題となる。ネットワーク接続の有無とは関係しない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-61","exam":"g","unit":"g-u6","keyword":"残差強化学習・連続値制御","type":"choice","syllabus_ref":"6.4","stem":"残差強化学習と、その主な適用先である連続値制御の説明として、正しいものはどれか。","choices":["残差強化学習は、Q値の推定誤差（残差）だけを学習する手法であり、連続値制御は、あらかじめ決められた離散的な行動の中から1つを選ぶ制御である","残差強化学習は、あらかじめ用意した基本となる制御器の出力に、強化学習で学んだ補正分（残差）を加えて最終的な指令を作る方法であり、ロボットの関節のトルクのように連続した値で指令を出す連続値制御などに用いられる","残差強化学習は、学習を最初からやり直さずに済むよう、過去の方策をそのまま保存しておく方法であり、連続値制御は、報酬を連続した値で与える制御である","残差強化学習は、複数のエージェントの出力の差分を取る方法であり、連続値制御は、環境の状態を連続値で表すことである"],"answer":1,"explanation":"残差強化学習は、従来の制御手法などで用意した基本の制御器を土台にし、その出力への補正分だけを強化学習で学習する方法である。ゼロから方策全体を学ぶより安全で効率がよいため、実機のロボット制御で用いられる。ロボットの関節トルクやモーターへの指令は連続した値であり、このような連続値制御では、離散的な行動を前提とする Q 学習系の手法をそのまま適用しにくく、方策勾配法系の手法や、この残差強化学習のような工夫が使われる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-62","exam":"g","unit":"g-u6","keyword":"sim2real・ドメインランダマイゼーション","type":"choice","syllabus_ref":"6.4","stem":"sim2real とドメインランダマイゼーションの説明として、正しいものはどれか。","choices":["sim2real は、現実の環境で集めたデータをシミュレーション用のデータに変換することであり、ドメインランダマイゼーションは、現実の環境の条件をランダムに入れ替えることである","sim2real は、シミュレーションで学習した方策を現実の環境でも追加学習なしにそのまま動かすことだけを指し、ドメインランダマイゼーションは、学習データにノイズを加えて水増しするデータ拡張のことである","sim2real は、シミュレーション環境で学習した方策を、現実のロボットなど実環境で動作させることを指し、ドメインランダマイゼーションは、シミュレーション側の見た目や重さ・摩擦などの物理パラメータをランダムに変動させて学習することで、シミュレーションと現実のずれに左右されにくい方策を得る手法である","sim2real は、現実そっくりのシミュレータを作ること自体を指し、ドメインランダマイゼーションは、複数のシミュレータを多数用意することである"],"answer":2,"explanation":"ロボットの強化学習では、実機での試行錯誤は時間もコストもかかり危険も伴うため、シミュレーションで学習して実環境へ移す sim2real が重要になる。ただしシミュレーションと現実にはずれ（リアリティギャップ）があり、そのままではうまく動かないことが多い。ドメインランダマイゼーションは、テクスチャや照明、摩擦などの条件をシミュレーション側で意図的に大きくばらつかせて学習することで、現実の条件がそのばらつきの範囲内に収まるようにし、移行の成功率を上げる手法である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-63","exam":"g","unit":"g-u6","keyword":"状態表現学習","type":"choice","syllabus_ref":"6.4","stem":"深層強化学習における状態表現学習の説明として、正しいものはどれか。","choices":["環境の状態遷移の規則を、人間が表の形で設計することである","報酬関数の形を、学習によって自動で獲得することである","環境のルールを文章で記述し、エージェントに与えることである","画像のような高次元の観測をそのまま使うのではなく、強化学習の学習に適した扱いやすい状態の表現を、観測データから学習によって獲得することである"],"answer":3,"explanation":"カメラ画像のような高次元の観測には、学習に不要な情報も多く含まれ、そのままでは強化学習の学習が難しい。状態表現学習は、観測データから、物体の位置など学習に必要な情報を保った低次元で扱いやすい状態表現を獲得する取り組みで、表現の良し悪しがその後の方策学習の効率や性能を左右する。報酬関数を学ぶのは報酬モデルの学習であり、状態表現の学習とは対象が異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-64","exam":"g","unit":"g-u6","keyword":"マルチエージェント強化学習 (MARL)・OpenAI Five・アルファスター (AlphaStar)","type":"choice","syllabus_ref":"6.4","stem":"マルチエージェント強化学習 (MARL) と、その代表的な成果である OpenAI Five とアルファスター (AlphaStar) の組み合わせとして、正しいものはどれか。","choices":["MARL は複数のエージェントが同じ環境の中で協調や競合をしながら学習する枠組みであり、OpenAI Five はチーム対戦ゲーム Dota 2 で5体のエージェントが協調して世界王者チームに勝利し、アルファスター (AlphaStar) はリアルタイムストラテジーゲーム StarCraft II で、自己対戦を重ねるリーグ方式の学習などによってプロ選手に勝利した","MARL は1体のエージェントを複数回実行して結果を平均する枠組みであり、OpenAI Five は将棋で、アルファスター (AlphaStar) は囲碁で人間に勝利した","MARL は人間のプレイヤー同士の対戦データを集める枠組みであり、OpenAI Five は自動運転の公道試験を行い、アルファスター (AlphaStar) は倉庫ロボットの制御に使われた","MARL は複数のシミュレーション環境を並列に動かす計算の工夫であり、OpenAI Five とアルファスター (AlphaStar) は、どちらも人間の模倣学習だけで人間を超えた"],"answer":0,"explanation":"マルチエージェント強化学習は、複数のエージェントが互いに影響し合う環境で学習する枠組みで、他のエージェントも学習して変わっていくため、環境が静止していない点が単一エージェントの場合との大きな違いである。OpenAI Five は Dota 2 で、5体のエージェントの協調と大規模な自己対戦による学習で世界王者チームを破った。アルファスター (AlphaStar) は StarCraft II で、人間のリプレイによる事前学習ののち、多様な戦略を持つエージェント同士を戦わせるリーグ方式の自己対戦で強化され、プロ選手に勝利した。どちらも、強化学習が複雑な実タスクへ広がったことを示す代表例として知られる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目29「深層強化学習」"},{"id":"g6-65","exam":"g","unit":"g-u6","keyword":"敵対的生成ネットワーク (GAN)","type":"choice","syllabus_ref":"6.5","stem":"敵対的生成ネットワーク (GAN) の説明として、正しいものはどれか。","choices":["本物らしいデータを生み出す生成器と、与えられたデータが本物か生成器の作った偽物かを見分ける識別器という、2つのネットワークを競わせながら学習し、生成器が本物と見分けのつかないデータを生成できるようにするモデルである","データを低次元の潜在変数に圧縮し、そこから元のデータを復元するよう学習することで、新しいデータを生成するモデルである","データに段階的にノイズを加える過程の逆向きを学習し、ノイズから少しずつノイズを取り除いてデータを生成するモデルである","入力データをあらかじめ決められたクラスに分類するよう学習し、分類の確信度が最も高いクラスを出力するモデルである"],"answer":0,"explanation":"GAN は、生成器と識別器という2つのネットワークの競合によって学習する生成モデルである。識別器は本物と偽物の判別が上達し、生成器は識別器を欺けるほど本物らしいデータを出せるようになることで、互いに性能を高め合う。潜在変数への圧縮と復元で生成するのは変分オートエンコーダ (VAE)、ノイズの除去を学習するのは Diffusion Model の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-66","exam":"g","unit":"g-u6","keyword":"DCGAN","type":"choice","syllabus_ref":"6.5","stem":"DCGAN の説明として、正しいものはどれか。","choices":["入力画像と目標画像のペアを使って、画像から画像への変換を学習する条件付き GAN である","GAN に畳み込みニューラルネットワークを本格的に取り入れたモデルで、生成器はランダムなノイズから転置畳み込みなどで少しずつ拡大して画像を作り、識別器は畳み込みで画像の特徴を捉えて本物かどうかを判定することで、画像生成の学習を安定させた","テキストの説明文を入力として、それに合った画像を生成するモデルである","3次元の座標と見る方向から色と密度を予測し、自由な視点の画像を生成するモデルである"],"answer":1,"explanation":"DCGAN は、GAN の生成器と識別器に畳み込み層を本格的に採用したモデルで、プーリングの代わりにストライド付きの畳み込みを使うなどの設計の指針を示し、それまで不安定だった画像生成の学習を安定させ、GAN による画像生成の基礎となった。ペア画像の変換は Pix2Pix、3次元の場面の表現は NeRF の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-67","exam":"g","unit":"g-u6","keyword":"Pix2Pix","type":"choice","syllabus_ref":"6.5","stem":"Pix2Pix の説明として、正しいものはどれか。","choices":["対応するペアの画像が無くても、2つの画像群の間の変換を学習できる GAN である","ノイズだけを入力として、特定の条件を与えずに画像を生成する GAN である","変換前の画像と変換後の画像のペアを教師データとして学習する条件付き GAN で、白黒写真のカラー化や、線画から写真風の画像への変換など、入力と出力の対応が明確な画像変換に使われる","画像に少しずつノイズを加え、その逆向きの除去を学習して画像を生成するモデルである"],"answer":2,"explanation":"Pix2Pix は、条件付き GAN の枠組みで画像から画像への変換を学習するモデルで、学習には変換前と変換後のペアの画像が必要になる。生成器は入力画像を条件として変換結果を作り、識別器は入力画像と対にして本物かどうかを判定する。ペアが無くても変換できるのは CycleGAN の特徴である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-68","exam":"g","unit":"g-u6","keyword":"CycleGAN","type":"choice","syllabus_ref":"6.5","stem":"CycleGAN の説明として、正しいものはどれか。","choices":["変換前と変換後のペアの画像を大量に用意し、その対応を教師として学習する GAN である","画像の特徴を低次元の潜在変数に圧縮し、潜在変数を操作して画像を生成するモデルである","文章の意味を捉えて、それに合う画像を生成するモデルである","対応するペアの画像が用意できない場合でも画像の変換を学習できる GAN で、ある画像を別の種類の画像に変換し、さらに元の種類に戻すと元の画像に復元されるという循環一貫性の条件を課すことで、馬の写真をシマウマの写真に変えるような変換を実現した"],"answer":3,"explanation":"CycleGAN は、ペアの画像が無い2つの画像の集まりの間で変換を学習するモデルである。変換して戻すと元に戻るという循環一貫性損失が、変換が内容を保ったまま見た目だけを変えるよう学習を導く。写真と絵画の画風の変換など、ペアを作れない変換に使われる。ペアの画像を教師とするのは Pix2Pix である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-69","exam":"g","unit":"g-u6","keyword":"Diffusion Model","type":"choice","syllabus_ref":"6.5","stem":"Diffusion Model（拡散モデル）の説明として、正しいものはどれか。","choices":["生成器と識別器を競わせ、識別器を欺けるデータを生成するよう学習するモデルである","データに少しずつノイズを加えていき最終的にノイズだけになる過程を考え、その逆向きとして、ノイズの状態から少しずつノイズを取り除いていく過程をニューラルネットワークに学習させることで、ノイズから新しいデータを生成するモデルである","データを潜在変数に圧縮するエンコーダと、潜在変数からデータを復元するデコーダを学習するモデルである","環境からの報酬を手がかりに、報酬が最大になる行動を学習するモデルである"],"answer":1,"explanation":"Diffusion Model は、拡散過程でデータがノイズに変わっていく逆向きの過程、すなわちノイズを取り除く操作を学習する生成モデルである。生成の際はランダムなノイズから出発し、学習した除去を何段階も繰り返してデータを形作る。画像生成で高い品質と多様性を示し、現在の画像生成の主流の1つになっている。生成器と識別器の競合は GAN、圧縮と復元はオートエンコーダ系の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-70","exam":"g","unit":"g-u6","keyword":"敵対的生成ネットワーク (GAN)・Diffusion Model","type":"choice","syllabus_ref":"6.5","stem":"GAN と Diffusion Model の、生成の仕方と学習の特徴の違いとして、正しいものはどれか。","choices":["GAN は多数のステップでノイズを除去して生成するため生成が遅く、Diffusion Model は一度の変換で生成するため生成が速い","GAN も Diffusion Model も、生成器と識別器の競合によって学習する点は共通している","GAN は学習が安定して多様な生成が得られやすく、Diffusion Model は学習が不安定で生成が偏りやすい","GAN は、学習した生成器がノイズから一度の変換でデータを生成するため生成は速いが、生成器と識別器の競合のため学習が不安定になったり生成が偏ったりしやすい。一方 Diffusion Model は、多数のステップをかけてノイズを段階的に除去して生成するため生成に時間はかかるが、学習は比較的安定し、多様で高品質な生成が得られやすい"],"answer":3,"explanation":"両者は現在の生成モデルの代表的な枠組みだが、生成と学習の性質が対照的である。GAN は一度の変換で生成するため高速だが、2つのネットワークの競合のバランスが崩れると学習が進まなかったり、似たデータばかりを生成する偏り（モード崩壊）が起きたりしやすい。Diffusion Model は生成に多数のステップを要する代わりに、ノイズ除去という明確な学習目標のもとで学習が安定しやすい。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-71","exam":"g","unit":"g-u6","keyword":"NeRF","type":"choice","syllabus_ref":"6.5","stem":"NeRF の説明として、正しいものはどれか。","choices":["3次元空間の中の位置（座標）と見る方向を入力すると、その位置の色と密度を返すニューラルネットワークで3次元の場面そのものを表現する技術で、様々な角度から撮影した写真で学習することで、撮影していない角度からの見た目を生成できる","2次元の画像同士の変換を、ペアの画像なしで学習する GAN である","単語の並びから次の単語を予測して文章を生成する言語モデルである","音声の波形を1サンプルずつ予測して音声を生成するモデルである"],"answer":0,"explanation":"NeRF は、場面を画像の集まりではなく、位置と方向から色と密度を返す関数の形でニューラルネットワークに覚えさせる技術である。学習した場面については、任意の視点から見た画像を描き出せる（自由視点画像の生成）。明示的な3Dモデルの構築とは異なり、表現そのものがニューラルネットワークである点が特徴である。ペアなしの画像変換は CycleGAN、波形の逐次予測は WaveNet の説明である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-72","exam":"g","unit":"g-u6","keyword":"画像生成・音声生成・文章生成","type":"choice","syllabus_ref":"6.5","stem":"データ生成タスクである画像生成・音声生成・文章生成の説明の組み合わせとして、正しいものはどれか。","choices":["画像生成は画像をクラスに分類するタスク、音声生成は音声をテキストに変換するタスク、文章生成は文章を要約するタスクである","画像生成は新しい画像を生成するタスク、音声生成は音声をテキストに変換するタスク、文章生成は文章を別の言語に翻訳するタスクである","画像生成は実在しない人物の顔のような新しい画像を生成するタスク、音声生成は読み上げ音声や音楽のような新しい音声を生成するタスク、文章生成は物語や対話文のような新しい文章を生成するタスクである","画像生成は新しい画像を生成するタスク、音声生成は新しい音声を生成するタスク、文章生成は文章から書き手の感情を判定するタスクである"],"answer":2,"explanation":"データ生成タスクは、学習データの分布を学んだモデルが、これまでに無い新しいデータを生み出すタスクの総称で、対象のデータの種類によって画像生成・音声生成・文章生成などに分かれる。画像の分類、音声のテキスト化、文章の要約や翻訳、感情の判定は、いずれも既存のデータを変換したり判定したりするタスクで、新しいデータを生み出す生成タスクとは区別される。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-73","exam":"g","unit":"g-u6","keyword":"画像生成","type":"choice","syllabus_ref":"6.5","stem":"画像生成タスクの説明として、正しいものはどれか。","choices":["画像に写っている物体が何であるかを判定するタスクである","画像の中で物体がどこにあるかを検出するタスクである","画像を小さいデータ量に圧縮し、保存や転送を効率化するタスクである","大量の画像の分布を学習した生成モデルが、学習データには含まれていない新しい画像を生み出すタスクで、GAN や Diffusion Model が代表的なモデルであり、デザイン案の作成や、画像認識の学習データの補充などに活用される"],"answer":3,"explanation":"画像生成は、画像データの分布そのものを学習し、そこから新しい画像をサンプルとして生み出すタスクである。物体が何かを判定するのは物体識別、位置を検出するのは物体検出であり、いずれも既存の画像を解析するタスクで、生成タスクとは方向が逆である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-74","exam":"g","unit":"g-u6","keyword":"文章生成","type":"choice","syllabus_ref":"6.5","stem":"文章生成の説明として、正しいものはどれか。","choices":["言語モデルが、それまでの単語の並びから次の単語を予測する処理を繰り返し、単語を1つずつつなげて新しい文章を生み出すタスクで、既存の文章を短くする要約や、別の言語に置き換える翻訳と異なり、もとになる文章が無くても新しい内容の文章を作り出せる","長い文章の中から重要な文を抜き出したり書き換えたりして、短い要約を作るタスクである","文章に表れた書き手の感情や評価の極性を判定するタスクである","文章を単語の頻度などの特徴量に変換し、数値で表すタスクである"],"answer":0,"explanation":"文章生成は、言語モデルが次の単語を予測し続けることで文章を生み出すタスクで、物語の創作や対話文の生成などに使われる。要約や翻訳は既存の文章を入力として変換するタスクであり、感情分析は判定のタスクである点で、もとの文章なしに新しい文章を生み出す文章生成とは異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-75","exam":"g","unit":"g-u6","keyword":"NeRF","type":"choice","syllabus_ref":"6.5","stem":"NeRF で3次元の場面を学習する際に必要な入力と、学習後に得られるものの組み合わせとして、正しいものはどれか。","choices":["入力は1枚の写真のみで、学習後はその写真の解像度を上げた画像が得られる","入力は、対象を様々な角度から撮影した複数の写真と、それぞれを撮影したカメラの位置や方向の情報であり、学習後は、撮影していない新しい視点から見た場面の画像を生成できる","入力は、対象の形を計測した3次元スキャンのデータであり、学習後はそのデータを圧縮したものが得られる","入力は、場面の様子を文章で説明したテキストであり、学習後はその文章に合う1枚の画像が得られる"],"answer":1,"explanation":"NeRF の学習には、複数の視点から撮った写真と、各写真のカメラの位置・方向が要る。写真に写った色が、視線の先の各位置の色と密度の予測と整合するよう学習することで場面が表現され、学習後はカメラを置いていない視点からでも、その視点で見えるはずの画像を描き出せる。1枚の写真だけでは奥行きの情報が足りず、場面全体は学習できない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-76","exam":"g","unit":"g-u6","keyword":"データ生成","type":"choice","syllabus_ref":"6.5","stem":"データ生成モデルの活用場面と、使うモデルの組み合わせとして、正しいものはどれか。場面（1）ペアになる画像を用意できない、実写の写真を絵画風の画像に変換したい。（2）商品を様々な角度から眺められるよう、複数枚の写真から自由な視点の画像を作りたい。（3）実在しない人物の顔写真を大量に作り、画像認識の学習データを補いたい。","choices":["（1）Pix2Pix、（2）Diffusion Model、（3）NeRF","（1）NeRF、（2）CycleGAN、（3）Pix2Pix","（1）CycleGAN、（2）NeRF、（3）GAN や Diffusion Model による画像生成","（1）CycleGAN、（2）Pix2Pix、（3）NeRF"],"answer":2,"explanation":"（1）はペアの画像が用意できない変換であり、循環一貫性でペアなしの変換を学ぶ CycleGAN が適する。Pix2Pix はペアの画像が必須である。（2）は3次元の場面を表現して新しい視点の画像を生み出す NeRF の活用である。（3）は生成モデルによる画像生成そのもので、GAN や Diffusion Model で実在しない顔写真を作り、学習データの補充に使う。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目30「データ生成」"},{"id":"g6-77","exam":"g","unit":"g-u6","keyword":"転移学習","type":"choice","syllabus_ref":"6.6","stem":"転移学習の説明として、正しいものはどれか。","choices":["あるタスクの学習で得た知識や重みを、別のタスクの学習に流用する手法で、対象のタスクのデータが少なくても、関連するタスクで学んだ特徴の捉え方を活かして効率よく学習できるようにするものである","学習データに回転や反転などの加工を加えて、データの量を人為的に増やす手法である","複数のモデルを学習させ、その予測を多数決や平均でまとめて最終的な予測とする手法である","環境からの報酬を手がかりに、試行錯誤を通じて報酬が最大になる行動を学習する手法である"],"answer":0,"explanation":"転移学習は、元のタスクで学習して得た知識（主に学習済みの重み）を対象タスクに持ち込み、流用する考え方である。画像の縁や形といった汎用的な特徴の捉え方はタスクをまたいで役立つため、対象タスクのデータが少量でも学習が進めやすくなる。データに加工を加えて増やすのはデータ拡張、複数のモデルの予測をまとめるのはアンサンブル学習、報酬から行動を学ぶのは強化学習の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-78","exam":"g","unit":"g-u6","keyword":"ファインチューニング","type":"choice","syllabus_ref":"6.6","stem":"ファインチューニングの説明として、正しいものはどれか。","choices":["事前学習済みモデルの重みを一切更新せず、入力データの特徴を取り出す仕組みとしてだけ使う方法である","事前学習済みモデルの重みを初期値として、対象タスクのデータでモデル全体または一部の層を再学習し、タスクに合わせて調整する方法である","学習率やバッチサイズなどのハイパーパラメータの組み合わせを探索し、最も性能の良いものを探す方法である","精度への影響が小さい重みを取り除き、モデルを小さく軽くする方法である"],"answer":1,"explanation":"ファインチューニングは、事前学習で得た重みを出発点にして、対象タスクのデータでさらに学習を行う方法である。全体を再学習する場合も、後ろの層だけを再学習し前の層は固定する場合もある。重みを更新せず特徴抽出にだけ使うのは転移学習のもう1つの使い方であり、ファインチューニングとは区別される。ハイパーパラメータの探索は学習の進め方の調整、重みの除去はプルーニングの説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-79","exam":"g","unit":"g-u6","keyword":"事前学習","type":"choice","syllabus_ref":"6.6","stem":"転移学習における事前学習の説明として、正しいものはどれか。","choices":["対象タスクのテストデータを使って、あらかじめモデルの性能を測っておくことである","対象タスクのラベル付きデータだけで、モデルをゼロから学習させることである","大規模なデータセットでモデルを先に学習させ、データ全般に通じる汎用的な特徴の捉え方を身につけさせる段階で、ここで得た重みが、後段のファインチューニングの出発点になる","学習の前に、データの欠損や異常値を取り除いて整える前処理のことである"],"answer":2,"explanation":"事前学習は、転移学習の前段として、大規模なデータでモデルの基礎となる表現を獲得させる段階である。例えば大量の画像で学んだモデルは、縁や模様、形といった汎用的な特徴の捉え方を身につけており、それが様々な下流のタスクへ転用できる土台になる。テストデータによる事前の性能測定や、データの前処理とは別の概念である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-80","exam":"g","unit":"g-u6","keyword":"事前学習済みモデル","type":"choice","syllabus_ref":"6.6","stem":"事前学習済みモデルを使う利点として、正しいものはどれか。","choices":["事前学習済みモデルは、事前学習に使ったデータと同じタスクでしか利用できない","事前学習済みモデルを使えば、対象タスクの学習データを用意する必要がなくなる","事前学習済みモデルの重みは固定されており、ファインチューニングで更新することはできない","大規模なデータで学習済みの重みを出発点にできるため、対象タスクのデータが少なくても比較的高い精度が得られやすく、自前で大規模な学習を行う計算コストも省ける"],"answer":3,"explanation":"事前学習済みモデルは、大規模データによる学習を済ませた重みが公開・配布されているもので、利用者はそれを土台に対象タスクへ適用できる。汎用的な特徴の捉え方は既に身についているため、少量のタスクデータでも実用的な精度に届きやすく、学習にかかる時間と計算資源も大幅に抑えられる。タスクの学習データ自体が不要になるわけではなく、重みはファインチューニングで更新できる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-81","exam":"g","unit":"g-u6","keyword":"自己教師あり学習","type":"choice","syllabus_ref":"6.6","stem":"自己教師あり学習の説明として、正しいものはどれか。","choices":["人手で付けたラベルを使わず、データそのものから学習の答えを作り出して学習する手法で、文章の一部を隠して元の単語を予測させる、画像の一部を隠して復元させるといった課題が使われ、ラベル付けが要らないため大規模なデータで事前学習を行う方法として広く使われている","少量のラベル付きデータと大量のラベルなしデータを組み合わせて学習する手法である","ラベルを一切使わず、データどうしの似ている・似ていないによってグループ分けを行う手法である","専門家が付けた正解ラベルを大量に用意し、それを教師として学習する手法である"],"answer":0,"explanation":"自己教師あり学習は、データ自体の一部を隠したり加工したりして、そこから元の内容を予測させることで、ラベルなしデータから学習用の課題と答えを自動で作り出す手法である。人手のラベル付けが不要なため、Web上の文章や画像のような大規模データで事前学習でき、言語モデルや画像モデルの事前学習の土台になっている。ラベル付きとラベルなしを組み合わせるのは半教師あり学習、グループ分けはクラスタリング、正解ラベルで学ぶのは教師あり学習の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-82","exam":"g","unit":"g-u6","keyword":"半教師あり学習","type":"choice","syllabus_ref":"6.6","stem":"半教師あり学習の説明として、正しいものはどれか。","choices":["学習に使う全てのデータにラベルが付いていることを前提とする手法である","ラベル付けのコストが高い場面で、少量のラベル付きデータと大量のラベルなしデータを組み合わせて学習する手法で、ラベルなしデータからデータ全体の分布や構造を学ぶことで、少量のラベルでも性能を高めることを狙う","データそのものから学習の答えを作り出し、人手のラベルを一切使わずに学習する手法である","環境との試行錯誤を通じて、得られる報酬が最大になる行動を学習する手法である"],"answer":1,"explanation":"半教師あり学習は、ラベル付きデータとラベルなしデータを併用する学習の枠組みである。医療画像のようにラベル付けに専門知識と手間がかかる分野では、ラベル付きデータを大量に用意できないことが多く、ラベルなしデータが持つ分布や構造の情報を併せて使うことで、少量のラベルでも実用的な性能を目指す。全てラベル付きなのは教師あり学習、データから答えを作るのは自己教師あり学習、報酬で学ぶのは強化学習の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-83","exam":"g","unit":"g-u6","keyword":"Few-shot・One-shot","type":"choice","syllabus_ref":"6.6","stem":"Few-shot 学習と One-shot 学習の説明として、正しいものはどれか。","choices":["Few-shot はクラスごとに1例だけ、One-shot はクラスごとに数例の学習データで学習することである","Few-shot は学習データを一切使わずに新しいタスクを解くこと、One-shot は1つのデータセット全体を使って学習することである","Few-shot は、クラスごとに数例程度のごく少量の学習例から新しいタスクを学習することであり、One-shot はそのうち学習例がクラスごとに1例だけの場合を指す","Few-shot は学習の繰り返し（エポック）を数回に抑えること、One-shot は学習を1回だけ行うことである"],"answer":2,"explanation":"Few-shot 学習は、新しいタスクに対して、クラスごとに数例程度というごく少量の学習例だけから学習・適応する枠組みである。One-shot 学習はその特殊な場合で、学習例がクラスごとに1例だけのものを指す。事前学習で汎用的な表現を身につけたモデルほど、少ない学習例でも新しいタスクへ適応しやすい。エポックの回数を数える言い方ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-84","exam":"g","unit":"g-u6","keyword":"破滅的忘却","type":"choice","syllabus_ref":"6.6","stem":"破滅的忘却の説明として、正しいものはどれか。","choices":["学習データに過剰に適合し、未知のデータに対する性能が下がってしまう現象である","深いネットワークで勾配が小さくなりすぎて、学習が進まなくなる現象である","学習率を大きくしすぎて、損失が発散してしまう現象である","学習済みのモデルが新しいタスクを続けて学習する際に、以前のタスクで身につけた知識が急激に失われ、以前のタスクの性能が大きく下がってしまう現象で、タスクを順に学習していく場面の課題として知られる"],"answer":3,"explanation":"破滅的忘却は、モデルが新しいタスクに適応する過程で重みが書き換えられ、以前のタスクの知識が失われてしまう現象である。1つのモデルにタスクを次々と学習させる継続学習では中心的な課題であり、以前のデータの一部を混ぜて学習するなどの対策が研究されている。学習データへの過剰適合は過学習、勾配が小さくなるのは勾配消失問題の説明である。なお本用語はシラバス第1.4版で「破壊的忘却」から「破滅的忘却」に表記が変更された。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-85","exam":"g","unit":"g-u6","keyword":"転移学習・ファインチューニング","type":"choice","syllabus_ref":"6.6","stem":"転移学習・ファインチューニングが特に効果を発揮する場面として、最も適切なものはどれか。","choices":["対象タスクのラベル付きデータが大量にあり、ゼロから学習しても十分な精度が得られる場面である","対象タスクのラベル付きデータが少なく、ゼロから学習すると精度が不足するが、関連する大規模なデータで学習したモデルの知識を流用できる場面である","対象タスクと元のタスクが全く関係なく、元のタスクで学んだ特徴が対象タスクに全く役立たない場面である","対象タスクのデータの形式が元のタスクと大きく異なり、学習済みの重みをそのまま受け取れない場面である"],"answer":1,"explanation":"転移学習とファインチューニングの価値が最も出るのは、対象タスクのデータが不足している場面である。関連タスクの大規模データで学んだ汎用的な特徴を土台にすることで、少量のデータでも実用的な精度が得られる。逆に、元のタスクと対象タスクの関連が薄い場合は流用できる知識が少なく、効果は限定的になる。データが潤沢な場面では、転移を使わなくても十分な精度が得られることが多い。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-86","exam":"g","unit":"g-u6","keyword":"ファインチューニング","type":"choice","syllabus_ref":"6.6","stem":"事前学習済みモデルの特徴抽出部分（512個の特徴を出力する）の重みは固定（凍結）し、最後に付け替えた分類層だけを学習する。分類層は、入力が512次元、出力が10クラス（10個のユニット）の全結合層で、各ユニットにバイアスがある。このとき、学習によって更新されるパラメータの総数として、正しいものはどれか。","choices":["512","5,120","5,130","51,200"],"answer":2,"explanation":"全結合層のパラメータは、重みが入力次元×出力ユニットの数で 512×10＝5,120 個、バイアスが出力ユニットごとに1つずつで10個、合計 5,120＋10＝5,130 個である。凍結した特徴抽出部分のパラメータは学習で更新されないため数に入らない。5,120 はバイアスを数え忘れた値、512 は入力次元そのもの、51,200 は桁を取り違えた値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-87","exam":"g","unit":"g-u6","keyword":"事前学習済みモデル","type":"choice","syllabus_ref":"6.6","stem":"転移学習・ファインチューニングによって、様々なタスクで大幅な精度向上を果たした代表的なモデルに共通する特徴として、正しいものはどれか。","choices":["タスクごとに全く異なる構造のモデルを設計し、それぞれをゼロから学習させた点である","学習データを一切使わず、ルールベースの処理で精度を高めた点である","1つのタスク専用に学習し、他のタスクへは一切転用できない点である","大規模なデータで事前学習した1つのモデルを土台にし、質問応答や文書分類、画像分類といった様々なタスクごとにファインチューニングして使い分けることで、各タスクで高い精度を達成した点である"],"answer":3,"explanation":"BERT のように大規模テキストで事前学習した言語モデルをタスクごとにファインチューニングする枠組みや、ImageNet のような大規模画像データで事前学習した画像モデルを個別の画像タスクへ転用する枠組みは、転移学習によって多くのタスクで従来の精度を大きく上回った代表例である。共通する特徴は、土台となる事前学習済みモデルを共有し、タスク側は少量のデータで適応させる点にある。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-88","exam":"g","unit":"g-u6","keyword":"転移学習・ファインチューニング","type":"choice","syllabus_ref":"6.6","stem":"ある病院で、症例数が少なく、ラベル付きの医療画像が200枚しかない疾患について、画像分類モデルを作りたい。最も適切な進め方はどれか。","choices":["大規模な一般画像のデータで事前学習された画像認識モデルを用意し、その重みを初期値として、200枚の医療画像でファインチューニングする","200枚の画像だけで、深いネットワークをゼロから学習する","ラベル付きデータを増やすため、性能評価用に確保した画像まで学習に使い回す","学習データが少ない分を補うため、モデルの層をできるだけ深くして表現力を上げる"],"answer":0,"explanation":"ラベル付きデータが200枚では、深いネットワークをゼロから学習しても汎用的な特徴すら捉えきれず、精度は不足しがちである。大規模データで事前学習されたモデルの重みを土台にファインチューニングすれば、縁や形といった汎用的な特徴の捉え方を流用でき、少量のデータでも実用的な精度が狙える。評価用の画像を学習に使い回すと性能を正しく測れなくなり、層を深くすることはデータ不足の解決にはならない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目31「転移学習・ファインチューニング」"},{"id":"g6-89","exam":"g","unit":"g-u6","keyword":"マルチモーダル","type":"choice","syllabus_ref":"6.7","stem":"マルチモーダルなAIの説明として、正しいものはどれか。","choices":["画像、テキスト、音声といった異なる種類のデータ（モダリティ）を組み合わせて入力・処理し、それぞれを単独で扱う場合には得られない理解や出力を得る仕組みである","画像データだけを大量に集め、画像認識の精度を極限まで高める仕組みである","音声データだけを扱い、音声認識と音声合成を1つのモデルにまとめた仕組みである","同じ種類のデータを、学習用と評価用に分けて管理する仕組みである"],"answer":0,"explanation":"モダリティとは、画像・テキスト・音声のように、データの種類や様式のことを指す。マルチモーダルなAIは、複数のモダリティを組み合わせて扱うことで、例えば画像を見ながら文章の質問に答えるといった、単一のモダリティでは成立しない処理を可能にする。画像だけ、音声だけを扱うのはシングルモーダルな処理であり、データの分割管理はモダリティの概念とは関係がない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-90","exam":"g","unit":"g-u6","keyword":"Image Captioning","type":"choice","syllabus_ref":"6.7","stem":"Image Captioning（画像キャプション生成）の説明として、正しいものはどれか。","choices":["画像の中に写っている物体の位置を、矩形（ボックス）で示すタスクである","画像を入力として、その画像の内容を説明する文章（キャプション）を自動で生成するタスクである","画像と、それに対する質問文を入力として、答えを出力するタスクである","文章を入力として、その内容に沿った画像を生成するタスクである"],"answer":1,"explanation":"Image Captioning は、画像の内容を言葉で説明する文章を生成するタスクで、画像という視覚情報からテキストという言語情報への変換を行う、マルチモーダルタスクの代表例である。物体の位置を示すのは物体検出、画像と質問から答えを出すのは Visual Question Answering、文章から画像を作るのは Text-To-Image であり、いずれも別のタスクである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-91","exam":"g","unit":"g-u6","keyword":"Visual Question Answering","type":"choice","syllabus_ref":"6.7","stem":"Visual Question Answering（VQA）の説明として、正しいものはどれか。","choices":["画像の内容を説明する文章を自動で生成するタスクである","文章で書かれた質問文だけを入力として、知識から答えを生成するタスクである","画像と、その画像に対する質問文の両方を入力として、画像の内容に基づいて質問への答えを出力するタスクである","画像を、あらかじめ決められたカテゴリのいずれかに分類するタスクである"],"answer":2,"explanation":"Visual Question Answering は、画像と言語の両方を入力とするタスクで、質問の意味を理解し、画像の中の該当する部分を見て答える必要があるため、視覚情報と言語情報の統合が要るマルチモーダルタスクの代表例である。画像の説明文を作るのは Image Captioning、質問文だけから答えるのは言語だけの質問応答、カテゴリへの振り分けは画像分類であり、いずれも VQA とは異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-92","exam":"g","unit":"g-u6","keyword":"Text-To-Image","type":"choice","syllabus_ref":"6.7","stem":"Text-To-Image の説明として、正しいものはどれか。","choices":["画像を入力として、その内容を説明する文章を生成することである","長い文章を入力として、その要約文を生成することである","画像を入力として、写っている物体のカテゴリを判定することである","テキスト（文章による指示）を入力として、その内容に沿った画像を生成することで、言葉による指示と視覚的な内容を結びつける必要があるタスクである"],"answer":3,"explanation":"Text-To-Image は、文章で与えられた指示に沿った画像を生成するタスクである。生成される画像が指示の意味に合っている必要があるため、言語の理解と画像の生成を結びつけるマルチモーダルな処理になる。画像から文章を作るのは Image Captioning の向きであり、文章の要約は言語だけのタスク、画像のカテゴリ判定は画像分類である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-93","exam":"g","unit":"g-u6","keyword":"CLIP","type":"choice","syllabus_ref":"6.7","stem":"CLIP の説明として、正しいものはどれか。","choices":["Web上の大量の画像と、それに対応するテキストのペアを使って対照学習を行い、画像とテキストを共通の埋め込み空間に対応付けることで、画像と言語の意味的な結びつきを学習したモデルである","テキストを入力として、それに沿った画像を生成するモデルである","大規模なテキストデータだけで学習し、文章の生成や質問応答を行う言語モデルである","画像の中の物体の位置とカテゴリを同時に検出するモデルである"],"answer":0,"explanation":"CLIP は、画像とテキストのペアを大量に集め、正しいペアの埋め込みが近づき、無関係なペアが離れるように学習（対照学習）することで、画像と言語を同じ空間で比べられるようにしたモデルである。これにより、カテゴリ名を文章として埋め込むことで、学習していないカテゴリの画像分類（ゼロショット分類）にも使える。テキストから画像を作るのは DALL-E などの生成モデル、テキストだけの学習は言語モデル、物体の位置検出は物体検出モデルの説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-94","exam":"g","unit":"g-u6","keyword":"CLIP・Zero-shot","type":"choice","syllabus_ref":"6.7","stem":"CLIP を用いたゼロショット（Zero-shot）画像分類の仕組みとして、正しいものはどれか。","choices":["分類したいカテゴリごとに大量の画像を集め、そのカテゴリ専用の分類器を学習してから分類する","分類したいカテゴリの名前を文章として埋め込み、入力画像の埋め込みとの類似度が最も高いカテゴリを答えとするため、そのカテゴリの画像を学習に使っていなくても分類ができる","画像の埋め込みだけを使い、似た画像どうしをグループに分けることで分類する","カテゴリ名の文章を画像化し、入力画像と画素単位で重なりを比べて分類する"],"answer":1,"explanation":"CLIP は画像とテキストを共通の埋め込み空間に置けるため、カテゴリ名を文章として埋め込めば、画像との類似度を測って最も近いカテゴリを選ぶ分類ができる。分類対象のカテゴリの画像で学習し直す必要がないため、学習例がゼロのカテゴリにも対応できることが「ゼロショット」と呼ばれる理由である。カテゴリ専用の分類器を学習するのは通常の教師あり学習、画像どうしのグループ分けはクラスタリングの発想であり、文章を画像化して画素で比べる方式ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-95","exam":"g","unit":"g-u6","keyword":"DALL-E","type":"choice","syllabus_ref":"6.7","stem":"DALL-E の説明として、正しいものはどれか。","choices":["画像を入力として、その内容を説明する文章を生成するモデルである","画像とテキストの埋め込みの類似度を計算し、画像の検索や分類に使うモデルである","テキストによる説明を入力として、その内容に沿った画像を生成するモデルで、言葉と画像の対応関係の理解を画像生成に活かした、Text-To-Image の代表的なモデルである","音声を入力として、話し手の感情を推定するモデルである"],"answer":2,"explanation":"DALL-E は、文章で与えられた指示に沿って画像を生成する Text-To-Image の代表的なモデルである。生成される画像が指示の意味に合う必要があるため、言語と画像の対応を理解するマルチモーダルな仕組みの上に成り立っている。画像から説明文を作るのは Image Captioning、埋め込みの類似度で検索や分類を行うのは CLIP の使い方、感情の推定は音声処理のタスクである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-96","exam":"g","unit":"g-u6","keyword":"Flamingo","type":"choice","syllabus_ref":"6.7","stem":"Flamingo の説明として、正しいものはどれか。","choices":["テキストを入力として、それに沿った画像を生成するモデルである","画像とテキストのペアで対照学習を行い、両者を共通の埋め込み空間に対応付けるモデルである","音声波形を自己回帰的に生成し、自然な読み上げ音声を作るモデルである","画像や動画とテキストを入力としてテキストを出力する視覚言語モデルで、画像と文章が交互に現れる入力も扱え、少数の例を示すだけ（Few-shot）で新しいタスクに対応できる"],"answer":3,"explanation":"Flamingo は、視覚情報（画像・動画）と言語を組み合わせて扱う視覚言語モデルで、学習済みの画像エンコーダと言語モデルを結びつけ、画像について文章で答える処理を行う。入力の中に少数の「画像と答え」の例を並べて示すことで、その場で新しいタスクの形式に適応できる Few-shot の能力を持つ点が特徴である。テキストから画像を作るのは DALL-E、対照学習で埋め込みを対応付けるのは CLIP、音声波形の生成は音声合成モデルの説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-97","exam":"g","unit":"g-u6","keyword":"Unified-IO","type":"choice","syllabus_ref":"6.7","stem":"Unified-IO の説明として、正しいものはどれか。","choices":["画像、テキストなど多様な入出力を、テキストや画像などの共通の表現（トークン）に統一して表し、物体検出から画像生成、質問応答まで多様なタスクを1つのモデルで処理するモデルである","タスクごとに専用のモデルを用意し、結果だけを後段で集計する方式である","画像データ専用の圧縮形式で、保存容量を減らすための仕組みである","複数のデータベースのテーブルを1つの形式に統合する、データ管理の仕組みである"],"answer":0,"explanation":"Unified-IO は、種類の異なる入出力（画像・テキストなど）を、トークンという共通の表現に変換して扱うことで、入出力の形式が異なる多様なタスクを単一のモデルでこなすことを目指したモデルである。モダリティとタスクの両方を統一する点が、マルチモーダルモデルの中でも際立った特徴である。タスク専用モデルの集計方式や、データの保存・管理の仕組みの説明ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-98","exam":"g","unit":"g-u6","keyword":"基盤モデル","type":"choice","syllabus_ref":"6.7","stem":"基盤モデルの説明として、正しいものはどれか。","choices":["1つの特定のタスク専用に、小規模なデータで学習されたモデルである","大規模で多様なデータで学習され、その後の適応によって様々な下流のタスクに使い回せる汎用性の高いモデルで、複数のモダリティを扱えるものはマルチモーダルな基盤モデルと呼ばれる","学習を一切行わず、人が書いたルールだけで処理を行うモデルである","特定の企業の社内データだけで学習され、外部のタスクには一切使えないモデルである"],"answer":1,"explanation":"基盤モデルは、大規模で多様なデータを用いて学習された、汎用性の高いモデルを指す。1つのモデルを土台として、ファインチューニングなどの適応を加えることで、多くの異なるタスクに利用できる点が特徴である。テキストだけでなく画像や音声など複数のモダリティを扱える基盤モデルも登場しており、CLIP のような画像と言語を結ぶモデルはその系譜に位置づけられる。タスク専用の小規模モデルや、ルールベースの処理の説明ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-99","exam":"g","unit":"g-u6","keyword":"マルチタスク学習","type":"choice","syllabus_ref":"6.7","stem":"マルチタスク学習の説明として、正しいものはどれか。","choices":["学習済みのモデルの知識を、新しいタスクへ順に流用していく学習方法である","複数のモデルを別々に学習させ、その予測を多数決や平均でまとめる学習方法である","複数の関連するタスクを1つのモデルで同時に学習し、タスクどうしで表現（特徴の捉え方）を共有させることで、各タスクの性能の向上を狙う学習方法である","学習データに加工を加えて量を増やし、1つのタスクの性能を上げる学習方法である"],"answer":2,"explanation":"マルチタスク学習は、関連する複数のタスクを1つのモデルが同時に学習する枠組みである。タスクどうしで共有される表現が互いの学習を助け合うため、タスク単独で学習するより性能が上がることがある。モデルの知識を新しいタスクへ順に流用するのは転移学習（同時ではなく逐次である点が異なる）、複数のモデルの予測をまとめるのはアンサンブル学習、データを加工して増やすのはデータ拡張の説明である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-100","exam":"g","unit":"g-u6","keyword":"マルチモーダル","type":"choice","syllabus_ref":"6.7","stem":"工場の設備点検を支援するシステムで、次の3つの機能を実現したい。（1）点検員が設備の写真を撮り、文章で質問すると、その写真の内容に基づいた答えが返る。（2）報告書に載せる説明用の画像を、文章の指示から作り出す。（3）学習データにない新しい種類の異常についても、異常の名前を文章で用意するだけで、写真をその異常かどうか振り分けられる。各機能に使う技術の組み合わせとして、正しいものはどれか。","choices":["（1）Image Captioning（2）音声認識（3）カテゴリ専用の分類器を学習する教師あり学習","（1）Text-To-Image（2）Visual Question Answering（3）CLIP の埋め込みによるゼロショット分類","（1）物体検出（2）Image Captioning（3）画像どうしのクラスタリング","（1）Visual Question Answering（2）Text-To-Image（3）CLIP の埋め込みによるゼロショット分類"],"answer":3,"explanation":"（1）は画像と質問文の両方を入力として答えを返す Visual Question Answering の仕事である。（2）は文章の指示から画像を作る Text-To-Image である。（3）は、学習していないカテゴリでも、カテゴリ名を文章として埋め込み、画像の埋め込みとの類似度で振り分ける CLIP のゼロショット分類で実現できる。写真の説明文を作る Image Captioning では質問への回答はできず、音声認識は音声の機能であり、新しい異常に専用分類器の学習は学習データがない条件と矛盾する。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目32「マルチモーダル」"},{"id":"g6-101","exam":"g","unit":"g-u6","keyword":"モデルの解釈性","type":"choice","syllabus_ref":"6.8","stem":"深層学習モデルの「解釈性」が求められる背景として、正しいものはどれか。","choices":["深層学習モデルは高い精度を出せる一方で、内部の処理が複雑で、なぜその判断に至ったかという根拠を人間がそのままでは読み取れない（ブラックボックス化する）ため、判断の検証や信頼の確保には、根拠を理解できる形で示す解釈性が要る","深層学習モデルは計算量が大きく推論に時間がかかるため、処理を高速化する技術として解釈性が要る","深層学習モデルは学習データの量が不足しがちなため、データを自動で増やす技術として解釈性が要る","深層学習モデルは精度が低く誤りが多いため、精度そのものを引き上げる学習手法として解釈性が要る"],"answer":0,"explanation":"解釈性とは、モデルの判断の根拠を人間が理解できることを指す。深層学習モデルは多数のパラメータを持つ複雑な構造のため、入力の何が判断を決めたのかを人が読み取ることが難しく、ブラックボックスと呼ばれる。このため、誤った判断の原因の検証、利用者への説明、モデルへの信頼の確保といった場面で、判断根拠を示す解釈性が求められる。処理の高速化やデータの増量、精度向上のための学習手法とは別の論点である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-102","exam":"g","unit":"g-u6","keyword":"説明可能 AI (XAI)","type":"choice","syllabus_ref":"6.8","stem":"説明可能 AI（XAI）の説明として、正しいものはどれか。","choices":["AIが人間の指示なしに自律的に判断し、説明を求められても根拠を示さないことを目指す技術である","AIの判断や予測について、その根拠や理由を人間が理解できる形で説明できるようにするための技術や考え方の総称である","AIが生成した文章を使って、製品やサービスの説明文を自動で作る技術である","AIモデルの内部構造を図として自動で描き、パラメータの数を数えるための技術である"],"answer":1,"explanation":"説明可能 AI（XAI: Explainable AI）は、AIの出力に対して「なぜそう判断したのか」を人間が理解できる形で示せるようにする技術・研究の総称である。判断根拠の説明を通じて、誤りの検証や利用者の信頼、説明責任への対応を可能にする点が目的であり、自律性の追求や文章の自動生成、内部構造の図示そのものとは異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-103","exam":"g","unit":"g-u6","keyword":"CAM","type":"choice","syllabus_ref":"6.8","stem":"CAM（Class Activation Mapping）の説明として、正しいものはどれか。","choices":["テキストの中で、予測に最も影響した単語を抜き出して示す手法である","画像の中の物体の位置を、矩形（ボックス）で検出して示す手法である","画像分類を行うCNNについて、最終の畳み込み層の特徴マップにクラスごとの重みを掛けて重ね合わせ、画像のどの領域がそのクラスの判断に寄与したかをヒートマップとして可視化する手法である","特徴量の値をランダムに入れ替え、精度の低下から重要度を測る手法である"],"answer":2,"explanation":"CAM は、画像分類モデルの判断根拠を画像上に示す手法で、畳み込み層の特徴マップと、分類クラスに対する重みを使って、判断に寄与した領域を色の濃淡（ヒートマップ）で表す。これにより、モデルが画像のどこを見て判断したかを確認できる。物体の位置を矩形で示すのは物体検出、特徴量の入れ替えで重要度を測るのは Permutation Importance の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-104","exam":"g","unit":"g-u6","keyword":"Grad-CAM","type":"choice","syllabus_ref":"6.8","stem":"Grad-CAM の説明として、正しいものはどれか。","choices":["CAM を使うために、モデルの構造を変更して再学習し直す必要がある手法である","テキストだけを扱う文章生成のタスクに使われる、言語専用の可視化手法である","特徴マップを使わず、入力画像の画素を1つずつ変えて判断の変化を調べる手法である","対象クラスのスコアを畳み込み層の特徴マップで微分した勾配を用いて特徴マップの重みを求めることで、CAM と同様に判断に寄与した領域を可視化する手法で、勾配を使うためモデルの構造変更や再学習なしに様々なCNNへ適用できる"],"answer":3,"explanation":"Grad-CAM は CAM の考え方を一般化した手法である。CAM は、最終層の前に大域平均プーリングを置くなど特定の構造を前提として、その重みを使うのに対し、Grad-CAM は対象クラスの出力の勾配から特徴マップごとの重要度を求めるため、構造の変更や再学習をせずに幅広い CNN に適用できる。画素を1つずつ変えて調べるのは摂動による方法であり、Grad-CAM の仕組みではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-105","exam":"g","unit":"g-u6","keyword":"LIME","type":"choice","syllabus_ref":"6.8","stem":"LIME の説明として、正しいものはどれか。","choices":["説明したい個別の予測の周辺で、入力を少しずつ変えた（摂動させた）データを多数作り、その周辺だけを単純で解釈しやすいモデルで近似することで、その予測にどの特徴が効いたかを示す、モデルに依存しない局所的な説明手法である","モデル全体を1つの決定木に置き換え直し、全体の判断ルールをそのまま読み取れるようにする手法である","対象クラスのスコアの勾配を使って、画像のどの領域が判断に寄与したかをヒートマップで示す手法である","協力ゲーム理論の配分に基づいて、各特徴量が予測をどれだけ押し上げたかを計算する手法である"],"answer":0,"explanation":"LIME は、個々の予測（局所）に対する説明手法である。対象の入力の近くで摂動したデータを生成し、元のモデルの出力を、線形モデルのような解釈しやすい単純なモデルで近似することで、その予測に効いた特徴を読み取る。元のモデルの種類を問わない（モデル非依存である）点も特徴である。勾配で画像の領域を示すのは Grad-CAM、ゲーム理論の配分に基づくのは SHAP であり、モデル全体を置き換える手法でもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-106","exam":"g","unit":"g-u6","keyword":"SHAP","type":"choice","syllabus_ref":"6.8","stem":"SHAP の説明として、正しいものはどれか。","choices":["特徴量の値をランダムにシャッフルし、予測精度がどれだけ下がるかで重要度を測る手法である","協力ゲーム理論のシャープレイ値に基づいて、各特徴量がその予測を、平均的な予測（基準）からどれだけ押し上げ、または押し下げたかという寄与を配分し、特徴量ごとに定量化する手法である","個別の予測の周辺で単純なモデルによる近似を行い、その傾きから効いた特徴を読み取る手法である","畳み込み層の特徴マップを重ね合わせ、判断に寄与した画像の領域を可視化する手法である"],"answer":1,"explanation":"SHAP は、協力ゲーム理論で用いられるシャープレイ値の考え方を予測の説明に応用した手法で、各特徴量の寄与を、予測値と基準値との差を分け合う形で定量化する。個々の予測について、どの特徴が予測を上げる方向・下げる方向にどれだけ働いたかを示せる。特徴量のシャッフルによる性能低下で測るのは Permutation Importance、周辺の近似は LIME、画像の領域の可視化は CAM や Grad-CAM の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-107","exam":"g","unit":"g-u6","keyword":"Permutation Importance","type":"choice","syllabus_ref":"6.8","stem":"Permutation Importance の説明として、正しいものはどれか。","choices":["各特徴量について、予測への寄与をシャープレイ値で配分して求める手法である","対象クラスのスコアの勾配から、特徴マップの重みを求めて可視化する手法である","学習済みモデルについて、ある特徴量の値をランダムに入れ替えて（シャッフルして）その対応関係を壊したときに予測性能がどれだけ低下するかで、その特徴量の重要度を測る手法である","説明したい予測の周辺だけを、解釈しやすい単純なモデルで近似する手法である"],"answer":2,"explanation":"Permutation Importance は、特徴量と予測対象との対応を壊すことで、その特徴量がモデルの性能にどれだけ寄与しているかを測る手法で、重要な特徴量ほど、入れ替えたときの性能低下が大きい。モデル全体に対する特徴量の重要度（大域的な重要度）を得る手法である。シャープレイ値による配分は SHAP、勾配による可視化は Grad-CAM、周辺の近似は LIME の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-108","exam":"g","unit":"g-u6","keyword":"SHAP","type":"choice","syllabus_ref":"6.8","stem":"SHAP では、個々の予測値は「基準値（データ全体の平均的な予測値）＋各特徴量の SHAP 値の合計」で表される。ある予測について、基準値が 0.20、3つの特徴量の SHAP 値がそれぞれ +0.30、+0.15、−0.10 であったとき、この予測値として、正しいものはどれか。","choices":["0.20","0.35","0.75","0.55"],"answer":3,"explanation":"SHAP 値には加法性があり、予測値 = 基準値 + 各特徴量の SHAP 値の合計となる。計算すると 0.20 + 0.30 + 0.15 − 0.10 = 0.55 である。0.35 は基準値を加えていない値（SHAP 値の合計だけ）、0.75 は負の SHAP 値の符号を取り違えた値、0.20 は基準値そのものである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-109","exam":"g","unit":"g-u6","keyword":"LIME・SHAP","type":"choice","syllabus_ref":"6.8","stem":"モデルの説明手法について、次の2つの説明の組み合わせとして、正しいものはどれか。（A）説明したい予測の周辺で摂動したデータを作り、解釈しやすい単純なモデルで局所的に近似して説明する。（B）シャープレイ値に基づいて、各特徴量が予測を基準からどれだけ動かしたかを配分して説明する。","choices":["（A）LIME（B）SHAP","（A）SHAP（B）LIME","（A）LIME（B）Permutation Importance","（A）Grad-CAM（B）SHAP"],"answer":0,"explanation":"（A）は、個別の予測の周辺を解釈しやすい単純なモデルで近似する LIME の説明である。（B）は、協力ゲーム理論のシャープレイ値に基づく SHAP の説明である。Permutation Importance は特徴量の値を入れ替えたときの性能低下で重要度を測る手法、Grad-CAM は画像の寄与領域を勾配で可視化する手法であり、いずれも（A）には当たらない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-110","exam":"g","unit":"g-u6","keyword":"モデルの解釈性","type":"choice","syllabus_ref":"6.8","stem":"モデルの解釈性における、局所的な説明と大域的な説明の区別として、正しいものはどれか。","choices":["局所的な説明はモデル全体の特徴量の重要度を示し、大域的な説明は個々の予測の根拠を示す","局所的な説明は個々の予測1件について「なぜこの判断になったか」を示すもので、大域的な説明はモデル全体を通して「どの特徴量が効いているか」といった傾向を示すものである","局所的な説明は画像にだけ使え、大域的な説明はテキストにだけ使える","局所的な説明は学習の前に行い、大域的な説明は学習の後に行うものと決まっている"],"answer":1,"explanation":"説明の範囲には2つの水準がある。個別の予測の根拠を示すのが局所的な説明で、LIME や SHAP による個々の予測への寄与の提示がこれに当たる。モデル全体での特徴量の重要度のように全体の傾向を示すのが大域的な説明で、Permutation Importance がこれに当たる。モダリティの種類や学習の前後で決まる区別ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-111","exam":"g","unit":"g-u6","keyword":"モデルの解釈性","type":"choice","syllabus_ref":"6.8","stem":"モデルの解釈性が特に求められるユースケースとして、最も適切なものはどれか。","choices":["大量の商品画像を、あらかじめ決めたカテゴリに自動で振り分ける社内作業で、結果だけが集計に使われる","天気の予測の補助として、翌日の気温の予測値を社内の画面に表示する","融資の審査で、申請を否認する場合に、その判断の理由を申請者へ説明することが求められる場面","工場のラインで、製品の外観の良否を判定し、不良品を自動で取り除く場面"],"answer":2,"explanation":"解釈性が強く求められるのは、判断が人の権利や生活に影響し、判断の理由を当事者や第三者へ説明する責任が生じる場面である。融資審査で否認の理由を申請者へ示す場面はその典型である。結果の集計だけに使う振り分け、予測値の表示、不良品の自動除去のように、判断の理由を人へ説明することが主たる要件でない場面では、解釈性の優先度は相対的に下がる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-112","exam":"g","unit":"g-u6","keyword":"モデルの解釈性","type":"choice","syllabus_ref":"6.8","stem":"医療画像の診断支援と融資審査にAIを導入するにあたり、説明のために次の3つのことがしたい。（1）診断支援モデルが、画像のどの部分を見て判断したかを医師に示す。（2）個別の融資判断について、どの項目が判断をどの方向にどれだけ動かしたかを審査担当者に示す。（3）融資モデル全体として、どの項目が判断に効いているかの傾向を把握する。各目的に使う手法の組み合わせとして、正しいものはどれか。","choices":["（1）Permutation Importance（2）Grad-CAM（3）SHAP","（1）Grad-CAM（2）Permutation Importance（3）SHAP","（1）LIME（2）Grad-CAM（3）Permutation Importance","（1）Grad-CAM（2）SHAP（3）Permutation Importance"],"answer":3,"explanation":"（1）は画像の寄与領域の可視化であり、勾配を用いる Grad-CAM の仕事である。（2）は個別の判断について、項目ごとの寄与の大きさと向きを示すもので、シャープレイ値に基づく SHAP が当たる。（3）はモデル全体としての項目の重要度の傾向であり、特徴量の値を入れ替えたときの性能低下で測る Permutation Importance が当たる。Permutation Importance は個別の判断の内訳を示すものではなく、Grad-CAM は畳み込み層を持つ画像モデルを対象とする手法である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目33「モデルの解釈性」"},{"id":"g6-113","exam":"g","unit":"g-u6","keyword":"モデルの軽量化","type":"choice","syllabus_ref":"6.9","stem":"深層学習モデルの「軽量化」が必要とされる背景として、正しいものはどれか。","choices":["深層学習モデルは大規模化によりパラメータ数や計算量が大きくなり、メモリや処理能力に制約のあるスマートフォンや組み込み機器ではそのままでは動かせない、あるいは推論の遅延や消費電力が問題になるため、精度をできるだけ保ちながらモデルを小さく・軽くする軽量化が要る","深層学習モデルは学習データが不足しがちなため、データを自動で増やす技術として軽量化が要る","深層学習モデルは判断の根拠を人間が読み取れないため、判断根拠を説明する技術として軽量化が要る","深層学習モデルは精度が頭打ちになっているため、精度そのものを引き上げる学習手法として軽量化が要る"],"answer":0,"explanation":"軽量化とは、大きなモデルを、メモリや計算資源の限られた環境でも動かせるように、サイズや計算量を減らす取り組みの総称である。背景にはモデルの大規模化と、クラウドだけでなく端末側で推論を動かしたいという需要がある。学習データを増やすのはデータ拡張、判断根拠を示すのは解釈性の論点であり、軽量化は精度そのものを上げる手法ではなく、精度をできるだけ保ちながら小さくする点が要点である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-114","exam":"g","unit":"g-u6","keyword":"モデル圧縮","type":"choice","syllabus_ref":"6.9","stem":"モデル圧縮の説明として、正しいものはどれか。","choices":["学習データを圧縮して、保存に必要な容量を減らす技術である","学習済みモデルのパラメータ数やデータ量を減らし、モデルのサイズや推論に必要な計算量を小さくすることで、保存や配布、推論の実行をしやすくする技術の総称である","入力される画像や文章を圧縮してからモデルに入力する、前処理の技術である","複数のモデルの予測を平均し、予測のばらつきを減らす技術である"],"answer":1,"explanation":"モデル圧縮は、学習済みモデルそのものを小さくする技術の総称で、量子化やプルーニング、蒸留などがその代表的な手法である。対象は学習済みモデルであり、学習データや入力データの圧縮ではない。複数のモデルの予測を平均するのはアンサンブルの考え方で、モデルを小さくする技術ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-115","exam":"g","unit":"g-u6","keyword":"量子化","type":"choice","syllabus_ref":"6.9","stem":"モデルの軽量化手法である量子化の説明として、正しいものはどれか。","choices":["寄与の小さい重みを取り除き、接続を疎にしてモデルを小さくする手法である","大きなモデルの知識を、小さなモデルへ移し替える手法である","モデルの重みや活性化の値を、32ビット浮動小数点数のような細かい表現から、8ビット整数のような粗い表現に置き換えることで、モデルサイズやメモリ使用量を減らし、推論を高速化する手法である","音声信号をデジタル化する際に、波形の振幅を段階的な数値に丸める処理である"],"answer":2,"explanation":"モデルの軽量化における量子化は、重みや活性化の値を少ないビット数で表し直すことで、データ量と計算量を減らす手法である。重みを取り除くのはプルーニング、知識を移し替えるのは蒸留である。音声の A-D 変換における量子化（振幅を段階的な値に丸める処理）も同じ「量子化」という語を使うが、対象が音声信号であり、モデルの値を低ビット化する本問の量子化とは別の文脈の概念である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-116","exam":"g","unit":"g-u6","keyword":"量子化","type":"choice","syllabus_ref":"6.9","stem":"パラメータ数が2,500万個のモデルの重みを、各パラメータ8ビット（1バイト）で表すように量子化したとき、重みのデータ量として、正しいものはどれか。ただし、パラメータ数は量子化の前後で変わらず、量子化に伴う付加情報は考えないものとする。","choices":["1億バイト","5,000万バイト","1,250万バイト","2,500万バイト"],"answer":3,"explanation":"データ量は、パラメータ数 × 1パラメータあたりのバイト数で決まる。2,500万 × 1バイト ＝ 2,500万バイトである。1億バイトは32ビット（4バイト）のまま計算した値、5,000万バイトは16ビット（2バイト）、1,250万バイトは4ビット（0.5バイト）で計算した値である。量子化ではパラメータの個数は減らず、1個あたりのビット数が減る点が要点であり、個数を減らすのはプルーニングである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-117","exam":"g","unit":"g-u6","keyword":"プルーニング","type":"choice","syllabus_ref":"6.9","stem":"モデルの軽量化手法であるプルーニング（枝刈り）の説明として、正しいものはどれか。","choices":["学習済みモデルについて、寄与が小さいと判断された重みや接続（あるいはニューロンやチャネルなどの単位）を取り除くことでパラメータ数を減らす手法で、取り除いた後に再学習（ファインチューニング）を行って精度の回復を図ることが多い","重みを低ビットの数値で表し直すことで、モデルサイズを減らす手法である","大きな教師モデルの出力に合わせて小さな生徒モデルを学習させ、知識を移す手法である","学習データに変換を加えたデータを追加し、学習データの量を増やす手法である"],"answer":0,"explanation":"プルーニングは、不要と判断した要素を取り除くことで、パラメータ数そのものを減らす手法である。取り除く単位は個々の重みや接続の場合もあれば、ニューロンやチャネルといった構造の単位の場合もある。重みを低ビットで表すのは量子化、教師から生徒へ知識を移すのは蒸留、学習データを増やすのはデータ拡張であり、いずれもプルーニングではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-118","exam":"g","unit":"g-u6","keyword":"蒸留","type":"choice","syllabus_ref":"6.9","stem":"モデルの軽量化手法である蒸留（知識蒸留）の説明として、正しいものはどれか。","choices":["寄与の小さい重みを取り除いて、既存のモデルをそのまま小さくする手法である","大規模で高精度な教師モデルの出力（各クラスへの確率など）を手がかりに、それを真似るように小規模な生徒モデルを学習させることで、教師の知識を小さいモデルへ移し、サイズを抑えながら精度を保とうとする手法である","重みを8ビット整数などで表し直し、メモリ使用量を減らす手法である","複数のモデルの予測を平均して、1つの予測として使う手法である"],"answer":1,"explanation":"蒸留は、既存のモデルを削って小さくするのではなく、教師モデルの振る舞いを手がかりに、新しい小さいモデル（生徒モデル）を学習させて作る点が特徴である。重みの取り除きはプルーニング、重みの低ビット化は量子化、複数の予測の平均はアンサンブルであり、いずれも蒸留ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-119","exam":"g","unit":"g-u6","keyword":"宝くじ仮説","type":"choice","syllabus_ref":"6.9","stem":"宝くじ仮説（Lottery Ticket Hypothesis）の説明として、正しいものはどれか。","choices":["大きなモデルを学習した後、精度への影響が小さい部分を切り取れば、再学習なしにそのまま小さいモデルとして使えるという仮説である","小さいモデルを多数ランダムに作って学習させれば、そのうちの1つが必ず大きなモデルを超えるという仮説である","ランダムに初期化された大きなネットワークの中には「当たりくじ」と呼ばれる疎な部分ネットワークが含まれており、それだけを取り出して元の初期値から学習させると、元の大きなモデルに匹敵する精度に達し得るという仮説である","モデルのパラメータをランダムに間引くことで、偶然に精度が上がることがあるという仮説である"],"answer":2,"explanation":"宝くじ仮説の要点は2つある。1つは、当たりくじと呼ばれる部分ネットワークが、ランダムな初期化の時点ですでに大きなネットワークの中に含まれていること。もう1つは、その部分ネットワークを取り出し、元の初期値から学習し直すと、大きなモデルに匹敵する精度に達し得ることである。学習済みのモデルを切り取ってそのまま使う話でも、小さいモデルを多数作る話でも、ランダムに間引いて偶然を待つ話でもない。プルーニングの理論的な背景としても知られる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-120","exam":"g","unit":"g-u6","keyword":"エッジ AI","type":"choice","syllabus_ref":"6.9","stem":"エッジ AI の説明として、正しいものはどれか。","choices":["AIの学習と推論のすべてを、大規模なクラウドのサーバ上で行う方式である","データを必ずクラウドへ送信し、結果が返ってくるのを待ってから機器を動作させる方式である","画像の輪郭（エッジ）を検出することに特化した AI の総称である","スマートフォンやカメラ、工場の機器といった端末（エッジ）側で AI の推論を実行する方式で、通信を介さないため応答が速く、データを外部へ送らないためプライバシーを守りやすく、通信できない環境でも動作する"],"answer":3,"explanation":"エッジ AI は、推論をクラウドではなく端末側で実行する方式である。端末のメモリや処理能力には制約があるため、エッジ AI ではモデルの軽量化が重要になる。学習や推論をすべてクラウドで行う方式とは対照的であり、画像の輪郭検出を指す「エッジ」とは無関係である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-121","exam":"g","unit":"g-u6","keyword":"エッジ AI","type":"choice","syllabus_ref":"6.9","stem":"エッジ AI の導入にあたって、モデルの軽量化が特に重要になるユースケースとして、最も適切なものはどれか。","choices":["通信が使えない現場で、メモリや処理能力に制約のある組み込み機器にモデルを搭載し、その場でリアルタイムに画像を判定する必要がある場面","潤沢な GPU を持つデータセンターで、夜間に大量のデータをまとめて処理する場面","クラウド上の大規模な計算資源を使って、モデルの学習そのものを行う場面","高性能なワークステーション上で、時間をかけて分析結果を検証する場面"],"answer":0,"explanation":"軽量化の要否は、モデルを動かす環境の制約と、応答の即時性によって決まる。制約のある端末に搭載し、通信なしでリアルタイムに動かす場面は、モデルのサイズや計算量を減らすことが導入の前提になる典型的なユースケースである。計算資源が潤沢なデータセンターやワークステーションで動かす場面では、大きなモデルのままでも実行できるため、軽量化の優先度は相対的に下がる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-122","exam":"g","unit":"g-u6","keyword":"量子化・プルーニング","type":"choice","syllabus_ref":"6.9","stem":"モデルの軽量化手法について、次の2つの説明の組み合わせとして、正しいものはどれか。（A）重みや活性化の値を、少ないビット数で表し直すことでモデルサイズを減らす。（B）寄与の小さい重みや接続を取り除くことで、パラメータ数を減らす。","choices":["（A）プルーニング（B）量子化","（A）量子化（B）プルーニング","（A）量子化（B）蒸留","（A）蒸留（B）プルーニング"],"answer":1,"explanation":"（A）は、値の表現のビット数を減らす量子化の説明である。（B）は、要素を取り除いてパラメータ数そのものを減らすプルーニングの説明である。蒸留は、教師モデルの知識を生徒モデルへ移す手法であり、（A）にも（B）にも当たらない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-123","exam":"g","unit":"g-u6","keyword":"蒸留","type":"choice","syllabus_ref":"6.9","stem":"蒸留で、教師モデルの出力として、正解ラベルそのもの（ハードラベル）ではなく、各クラスへの確率の分布（ソフトラベル）を使う理由として、正しいものはどれか。","choices":["確率の分布を使うと、生徒モデルのパラメータ数を自動で減らすことができるから","確率の分布を使うと、教師モデルの学習をやり直す必要がなくなるから","確率の分布には、正解クラス以外のクラスどうしの似通い具合など、正解ラベルだけでは分からない教師の知識が含まれており、それを手がかりに学ぶことで、生徒モデルが教師の判断の仕方をよりよく真似できるから","確率の分布を使うと、生徒モデルに学習データを与える必要がなくなるから"],"answer":2,"explanation":"ソフトラベル（教師の出力する確率の分布）には、「正解はこのクラスだが、次に似ているのはあのクラスだ」といった、クラスどうしの関係の情報が含まれている。この情報は暗知識とも呼ばれ、蒸留の効果の源泉とされる。生徒モデルのパラメータ数はモデルの設計で決まるものであり、蒸留でも生徒の学習には学習データが要る。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g6-124","exam":"g","unit":"g-u6","keyword":"モデルの軽量化","type":"choice","syllabus_ref":"6.9","stem":"ある画像認識モデルを実製品に組み込むにあたり、次の3つのことがしたい。（1）重みのデータ量を減らし、限られたメモリに収めたい。（2）大規模なモデルで得た判断の知識を保ちながら、より小さいモデルを新たに用意したい。（3）学習済みモデルの中から、判断への寄与が小さい接続を取り除いてパラメータ数を減らしたい。各目的に使う手法の組み合わせとして、正しいものはどれか。","choices":["（1）プルーニング（2）量子化（3）蒸留","（1）量子化（2）プルーニング（3）蒸留","（1）プルーニング（2）蒸留（3）量子化","（1）量子化（2）蒸留（3）プルーニング"],"answer":3,"explanation":"（1）は、重みを少ないビット数で表してデータ量を減らす量子化の仕事である。（2）は、教師モデルの知識を小さい生徒モデルへ移す蒸留の仕事である。（3）は、寄与の小さい要素を取り除くプルーニングの仕事である。各誤答は、少なくとも1つの目的について対応が崩れている。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目6「ディープラーニングの応用例」中項目34「モデルの軽量化」"},{"id":"g7-01","exam":"g","unit":"g-u7","keyword":"AI プロジェクトの進め方","type":"choice","syllabus_ref":"7.1","stem":"AI プロジェクトの進め方について、正しいものはどれか。","choices":["AI プロジェクトは、解くべき課題の設定、データの収集・準備、モデルの開発、実業務への導入、運用・改善といったフェーズを経て進められ、データや精度の状況に応じて前のフェーズに戻って見直すこともあり、各フェーズで関係者の合意を取りながら進める","AI プロジェクトは、まずモデルの開発から着手し、解くべき課題の設定はモデルが完成してから行う","AI プロジェクトでは、一度決めた要件や計画は変更せず、最後まで一方向に進めることが成功の条件である","AI プロジェクトでは、学習データを集めることさえできれば、課題の設定や運用の検討は不要である"],"answer":0,"explanation":"AI プロジェクトは、課題の設定から始めて、データの準備、モデルの開発、導入、運用・改善へと進む流れが基本であり、期待した精度が出るかどうかは実際に試すまで分からない不確実さがあるため、フェーズを行き来しながら進めることが多い。モデルの開発から着手する進め方では、解くべき課題とずれたものができあがるおそれがある。要件を固定して一方向に進める進め方は、変化への対応が難しい。データの収集は手段であり、課題の設定や運用の検討を置き換えるものではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-02","exam":"g","unit":"g-u7","keyword":"PoC","type":"choice","syllabus_ref":"7.1","stem":"PoC（概念実証）の説明として、正しいものはどれか。","choices":["完成した AI システムを本番環境へ移行する作業のことである","本格的な開発や導入に進む前に、小規模な範囲で実際に試作・検証を行い、技術的な実現可能性や期待できる効果、課題を確認する取り組みである","AI システムの運用開始後に、モデルの精度を継続的に監視する取り組みである","プロジェクトの企画書を作成し、社内の承認を得る手続きのことである"],"answer":1,"explanation":"PoC は、本格開発に大きな投資をする前に、小さく試して「作れるか」「効果があるか」を見極めるための検証である。AI は精度が出るかどうかが事前に読めないため、PoC で見通しを付けてから本格開発に進むかどうかを判断する進め方が取られる。本番環境への移行は導入・展開の局面の作業、運用開始後の精度の監視は運用・モニタリングの論点であり、いずれも PoC ではない。企画書の承認手続きとも異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-03","exam":"g","unit":"g-u7","keyword":"CRISP-DM","type":"choice","syllabus_ref":"7.1","stem":"CRISP-DM の説明として、正しいものはどれか。","choices":["機械学習モデルの精度を自動で評価するための指標である","プログラムの実行環境をパッケージ化する技術である","データ分析プロジェクトの進め方を標準化したプロセスモデルで、ビジネス理解、データ理解、データ準備、モデリング、評価、展開の6つのフェーズからなり、フェーズ間を行き来しながら反復的に進める","AI システムの開発を外部の事業者に委託する際の契約形態である"],"answer":2,"explanation":"CRISP-DM は、データマイニング・データ分析のプロジェクトを進めるための標準的なプロセスモデルであり、出発点が「ビジネス理解」であることと、フェーズ間を行き来する反復的な進め方であることが特徴である。モデルの精度を測る指標でも、実行環境をパッケージ化する技術（Docker など）でも、開発委託の契約形態でもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-04","exam":"g","unit":"g-u7","keyword":"CRISP-ML","type":"choice","syllabus_ref":"7.1","stem":"CRISP-ML の説明として、正しいものはどれか。","choices":["CRISP-DM とは無関係に作られた、プログラミング言語の一種である","データの前処理だけを対象とし、モデルの運用は扱わないプロセスモデルである","CRISP-DM のフェーズを減らし、評価と展開を省略した簡易版のプロセスモデルである","CRISP-DM を機械学習システムの開発・運用に合わせて拡張したプロセスモデルで、モデルの品質保証や、運用段階でのモニタリング・保守といった観点を取り入れている"],"answer":3,"explanation":"CRISP-ML は、CRISP-DM の考え方を土台に、機械学習システム特有の事情（学習によって振る舞いが変わるモデルを、運用しながら品質を保つ必要があること）に合わせて拡張されたプロセスモデルである。品質保証の考え方や、運用フェーズでのモニタリング・保守が重視される点が、CRISP-DM との違いである。プログラミング言語ではなく、前処理だけを対象とするものでも、フェーズを省略した簡易版でもない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-05","exam":"g","unit":"g-u7","keyword":"ウォーターフォール・アジャイル","type":"choice","syllabus_ref":"7.1","stem":"開発手法について、次の2つの説明の組み合わせとして、正しいものはどれか。（A）要件定義、設計、開発、テスト、運用といった工程を順番に進め、原則として前の工程に戻らない進め方。（B）短い期間の単位で開発と評価を繰り返し、要求の変化に対応しながら少しずつ完成に近づける進め方。","choices":["（A）ウォーターフォール（B）アジャイル","（A）アジャイル（B）ウォーターフォール","（A）ウォーターフォール（B）PoC","（A）CRISP-DM（B）アジャイル"],"answer":0,"explanation":"（A）は、工程を上流から下流へ順に進めるウォーターフォールの説明である。（B）は、短い反復を繰り返して変化に対応するアジャイルの説明である。PoC は本格開発の前に実現可能性を検証する取り組みであり、開発手法の型ではない。CRISP-DM はデータ分析プロジェクトのプロセスモデルであり、（A）の工程順の進め方そのものを指す語ではない。AI プロジェクトでは、精度の見通しが立てにくいことから、アジャイル的な反復を取り入れることが多いとされる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-06","exam":"g","unit":"g-u7","keyword":"MLOps","type":"choice","syllabus_ref":"7.1","stem":"MLOps の説明として、正しいものはどれか。","choices":["機械学習のプログラムを書くための専用言語である","機械学習モデルの開発と運用を一体として進める考え方・仕組みで、モデルの学習やデプロイの自動化に加え、運用中のモデルの状態を監視（ヘルスモニタリング）し、データの変化による精度低下を検知して再学習につなげるなど、モデルのライフサイクル全体を管理する","モデルの開発だけを対象とし、運用開始後の管理は含まない考え方である","学習データを保管するためのデータベースの規格である"],"answer":1,"explanation":"MLOps は、機械学習（Machine Learning）と運用（Operations）を組み合わせた語で、モデルは作って終わりではなく、運用中にデータの傾向が変われば精度が下がるため、監視と再学習を含めたライフサイクル全体を仕組みとして管理する考え方である。シラバスの目標にある「モデルのヘルスモニタリングやライフサイクル管理」は、この MLOps の中核である。プログラミング言語でもデータベースの規格でもなく、開発だけを対象とする考え方でもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-07","exam":"g","unit":"g-u7","keyword":"Python・Jupyter Notebook","type":"choice","syllabus_ref":"7.1","stem":"AI 開発で使われるツールについて、次の2つの説明の組み合わせとして、正しいものはどれか。（A）機械学習のライブラリが豊富で、AI の開発に広く使われているプログラミング言語。（B）プログラムのコードとその実行結果、説明文を1つの文書に記録しながら、対話的にコードを実行できるツール。","choices":["（A）Jupyter Notebook（B）Python","（A）Python（B）Docker","（A）Python（B）Jupyter Notebook","（A）Docker（B）Jupyter Notebook"],"answer":2,"explanation":"（A）はプログラミング言語 Python の説明である。機械学習のライブラリが充実していることが、AI 開発で広く使われる理由である。（B）は Jupyter Notebook の説明で、コードを少しずつ実行して結果を確認しながら進められるため、データの探索や試行錯誤の多い AI 開発でよく使われる。Docker は実行環境をパッケージ化する技術であり、言語でも対話的な実行ツールでもない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-08","exam":"g","unit":"g-u7","keyword":"Docker","type":"choice","syllabus_ref":"7.1","stem":"Docker の説明として、正しいものはどれか。","choices":["大量のデータを複数のコンピュータに分散して処理するための計算手法である","AI モデルを軽量化して、端末に搭載するための技術である","プログラムのソースコードを自動で生成するツールである","アプリケーションとその実行に必要な環境（ライブラリや設定など）をコンテナと呼ばれる単位にまとめてパッケージ化する技術で、開発環境と本番環境で同じ環境を再現しやすくし、環境の違いによる動作の不一致を防ぐ"],"answer":3,"explanation":"Docker は、アプリケーション本体だけでなく、動かすために必要なライブラリや設定までをコンテナとしてひとまとめにし、どの環境でも同じように動かせるようにする技術である。「開発環境では動いたのに本番環境では動かない」という、環境の違いに起因する問題を防ぐことが、AI システムをサービスとして世に出す局面で重要になる。データの分散処理の手法でも、モデルの軽量化の技術でも、コード生成ツールでもない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-09","exam":"g","unit":"g-u7","keyword":"Web API・クラウド","type":"choice","syllabus_ref":"7.1","stem":"AI システムの提供形態について、次の2つの説明の組み合わせとして、正しいものはどれか。（A）学習済みモデルの推論機能などを、ネットワーク経由で他のプログラムから呼び出せる形で提供する仕組み。（B）自前でサーバを用意せず、インターネット経由で計算資源やストレージなどを利用する形態。","choices":["（A）Web API（B）クラウド","（A）クラウド（B）Web API","（A）Web API（B）Docker","（A）MLOps（B）クラウド"],"answer":0,"explanation":"（A）は Web API の説明である。AI の機能を Web API として公開すれば、さまざまなアプリケーションやサービスから推論機能を呼び出して利用できる。（B）はクラウドの説明で、計算資源を自前で持たずに、必要に応じて借りて使う形態である。Docker は実行環境をパッケージ化する技術であり、計算資源の利用形態そのものではない。MLOps はモデルの開発と運用の仕組みであり、機能を提供する仕組みそのものではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-10","exam":"g","unit":"g-u7","keyword":"AI のビジネス活用・BPR","type":"choice","syllabus_ref":"7.1","stem":"AI のビジネス活用について、次の2つの説明の組み合わせとして、正しいものはどれか。（A）AI を業務プロセスに組み込み、業務の効率化や新たな価値の創出を目指す取り組み全般。（B）既存の業務プロセスを前提とせず、根本から見直して再設計することで、業務の進め方そのものを変革すること。","choices":["（A）BPR（B）AI のビジネス活用","（A）AI のビジネス活用（B）BPR","（A）AI のビジネス活用（B）MLOps","（A）PoC（B）BPR"],"answer":1,"explanation":"（A）は AI のビジネス活用の説明である。（B）は BPR（Business Process Re-engineering）の説明で、AI の導入にあたっては、既存の業務の進め方をそのまま自動化するのではなく、業務プロセス自体を見直すことが効果につながるという文脈で論じられる。MLOps はモデルの開発と運用の仕組みであり、業務プロセスの再設計ではない。PoC は本格開発の前の検証であり、取り組み全般を指す語ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-11","exam":"g","unit":"g-u7","keyword":"ステークホルダーのニーズ・データサイエンティスト","type":"choice","syllabus_ref":"7.1","stem":"AI プロジェクトの関係者と人材について、次の2つの説明の組み合わせとして、正しいものはどれか。（A）事業部門や現場の担当者、利用者といったプロジェクトの関係者が、AI システムに何を求めているかという要求や期待。（B）データ分析や機械学習モデルの構築に関する専門知識を持ち、プロジェクトでデータの分析やモデルの開発を担う人材。","choices":["（A）データサイエンティスト（B）ステークホルダーのニーズ","（A）ステークホルダーのニーズ（B）PoC","（A）ステークホルダーのニーズ（B）データサイエンティスト","（A）AI のビジネス活用（B）データサイエンティスト"],"answer":2,"explanation":"（A）はステークホルダーのニーズの説明である。AI プロジェクトでは、課題の設定の段階で関係者のニーズを正しく把握しておかないと、技術的には作れても現場で使われないものになりかねない。（B）はデータサイエンティストの説明で、データの分析やモデルの構築を担う専門人材を指す。PoC は検証の取り組みであり、人材ではない。AI のビジネス活用は取り組み全般を指す語であり、関係者の要求や期待そのものではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-12","exam":"g","unit":"g-u7","keyword":"オープン・イノベーション・産学連携・他企業や他業種との連携","type":"choice","syllabus_ref":"7.1","stem":"ある企業が AI の開発・活用を進めるにあたり、次の3つの進め方を検討している。（1）自社の技術や知識だけでなく、社外の技術やアイデアも取り入れて、新しい価値を生み出そうとする考え方に基づく。（2）大学などの研究機関と共同で、研究開発を行う。（3）自社とは異なる業種の企業と協力し、互いのデータや強みを組み合わせる。各進め方に当たる概念の組み合わせとして、正しいものはどれか。","choices":["（1）産学連携（2）オープン・イノベーション（3）他企業や他業種との連携","（1）オープン・イノベーション（2）他企業や他業種との連携（3）産学連携","（1）他企業や他業種との連携（2）産学連携（3）オープン・イノベーション","（1）オープン・イノベーション（2）産学連携（3）他企業や他業種との連携"],"answer":3,"explanation":"（1）は、社内外の知識や技術を組み合わせて革新を生むという考え方であるオープン・イノベーションである。（2）は、企業と大学などの研究機関が連携する産学連携である。（3）は、他企業や他業種との連携である。オープン・イノベーションは連携全般の背景にある考え方、産学連携は相手が研究機関である連携、他企業や他業種との連携は相手が企業である連携という点で区別される。各誤答は、少なくとも1つの進め方について対応が崩れている。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目35「AI プロジェクトの進め方」"},{"id":"g7-13","exam":"g","unit":"g-u7","keyword":"アノテーション","type":"choice","syllabus_ref":"7.2","stem":"アノテーションの説明として、正しいものはどれか。","choices":["機械学習の学習データとして使う個々のデータに対して、正解となるラベルやタグ、対象の位置や範囲といった情報を付与する作業である","データの容量を減らすために、不要なデータを間引いて圧縮する処理である","モデルのパラメータを自動で調整し、精度を高めるための学習の仕組みである","第三者にデータを見られないよう、データを暗号化して保存する処理である"],"answer":0,"explanation":"アノテーションは、画像・テキスト・音声などのデータに対して、分類のラベル、物体の位置を示す範囲、文章の意味タグといった「正解」の情報を人が付与する作業であり、教師あり学習の学習データを作る土台になる。データの圧縮、パラメータの自動調整、暗号化はいずれも別の処理であり、アノテーションではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-14","exam":"g","unit":"g-u7","keyword":"アノテーション","type":"choice","syllabus_ref":"7.2","stem":"アノテーションの品質を保つための取り組みとして、適切なものはどれか。","choices":["作業の速さを優先し、付与の基準は各作業者の経験と判断に委ねる","付与の基準や、判断が割れやすい事例の扱いをガイドラインに定めて作業者間で共有し、作業者によるばらつきを抑える","付与したラベルに誤りが見つかっても、学習への影響は小さいためそのままにしておく","判断に迷うデータについては、基準を決めずに作業者がその場の感覚でラベルを決める"],"answer":1,"explanation":"アノテーションは人の判断で行うため、基準が曖昧だと作業者ごとに付与の仕方がばらつき、そのばらつきがそのまま学習データの質の低下になる。基準と迷いやすい事例の扱いをガイドラインとして明文化し、作業者間で共有することが品質を保つ基本である。基準を各作業者に委ねたり、誤りを放置したり、感覚で決めたりする進め方では、ばらつきや誤りが残ったままになる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-15","exam":"g","unit":"g-u7","keyword":"コーパス","type":"choice","syllabus_ref":"7.2","stem":"コーパスの説明として、正しいものはどれか。","choices":["画像データを大量に集めて整備した、画像認識専用のデータの集合である","プログラムのソースコードを集めて、動作を検証するためのデータの集合である","自然言語処理の研究や学習に使うために、テキスト（文章）データを大規模に収集・整備したデータの集合（言語資源）である","学習済みモデルのパラメータ（重み）を集めて保存したものである"],"answer":2,"explanation":"コーパスは、新聞記事やWebページ、書籍などのテキストを大規模に集めて整備した言語資源であり、単語の出現の仕方を数えたり、言語モデルを学習させたりする土台になる。バッチ18では機械翻訳の文脈で「対訳コーパス」（二言語の文の対応を付けたコーパス）が解説に現れたが、コーパスそのものの定義は本問のとおりテキストデータの集合である。画像の集合、ソースコードの集合、パラメータの保存はいずれもコーパスではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-16","exam":"g","unit":"g-u7","keyword":"コーパス","type":"choice","syllabus_ref":"7.2","stem":"コーパスを構築・利用する際の注意点として、適切なものはどれか。","choices":["データ量さえ多ければ、収集したテキストの内容に偏りがあっても問題にならない","一度インターネット上で公開されたテキストは、出典や利用条件を確認せずに自由に再配布できる","出典が不明なテキストであっても、学習に使うだけなら問題はない","収集するテキストの出典や利用条件を確認するとともに、特定の分野・媒体・時代に偏ったテキストばかりにならないよう、収集範囲の偏りに配慮する"],"answer":3,"explanation":"コーパスに集めたテキストの偏りは、そのまま学習したモデルの偏りにつながるため、量だけでなく収集範囲のバランスに配慮する必要がある。また、テキストには著作権などの権利や利用条件が伴うため、出典と条件の確認も欠かせない。量が多ければ偏りが消えるわけではなく、公開されていることや学習用途であることは、条件確認を不要にする理由にはならない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-17","exam":"g","unit":"g-u7","keyword":"オープンデータセット","type":"choice","syllabus_ref":"7.2","stem":"オープンデータセットの説明として、正しいものはどれか。","choices":["研究や開発に使えるよう公開されているデータセットであり、定められた利用条件（ライセンス）に従うことで、誰もが利用できるものである","特定の企業内部の関係者だけが利用できる、非公開のデータセットである","公開はされているが、いかなる目的でも利用が禁止されているデータセットである","AI が自動生成した架空のデータだけを集めたデータセットである"],"answer":0,"explanation":"オープンデータセットは、行政機関や研究機関、企業などが公開しているデータセットで、ライセンスなどの利用条件に従えば誰でも研究や開発に利用できる。画像・音声・テキストなど実データを含むものが多く、AI の学習や評価の土台として広く使われている。内部限定の非公開データ、利用禁止のデータ、自動生成データだけの集合はいずれもオープンデータセットの説明には当たらない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-18","exam":"g","unit":"g-u7","keyword":"オープンデータセット","type":"choice","syllabus_ref":"7.2","stem":"オープンデータセットを自社の開発に利用する際の進め方として、適切なものはどれか。","choices":["公開されているデータセットであれば、利用条件を確認しなくても商用利用できる","ライセンスの条件（商用利用の可否、再配布の可否、出典表示の要否など）を確認し、あわせてデータの内容や収集方法が自社の目的に合っているかも確かめる","著名なデータセットであれば、データの内容を確認しなくてもそのまま学習に使える","データセットをダウンロードした時点で、そのデータの権利は自社に移転する"],"answer":1,"explanation":"オープンデータセットは「公開されている」ことと「自由に使える」ことは同じではなく、ライセンスによって商用利用や再配布の可否、出典表示の要否が異なるため、利用前に条件の確認が要る。また、収集方法や対象の偏りが自社の目的とずれていると、そのまま使うことが品質の問題にもなる。条件を確認せずに使う進め方や、内容を見ずに使う進め方、権利が移転するという理解はいずれも誤りである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-19","exam":"g","unit":"g-u7","keyword":"データリーケージ","type":"choice","syllabus_ref":"7.2","stem":"データリーケージ（リーケージ）の説明として、正しいものはどれか。","choices":["学習データが、外部の第三者に流出してしまうことである","学習に使えるデータの量が不足し、精度が上がらないことである","本来は学習時に使えないはずの情報（予測の時点では得られない情報や、テストデータ側の情報）が学習データや特徴量に混入し、評価では高い精度が出るのに実運用では再現しない結果を招く問題である","データの形式や単位がそろっておらず、そのままでは学習に使えないことである"],"answer":2,"explanation":"データリーケージは、予測したい時点ではまだ存在しない情報や、評価用のテストデータ側の情報が学習に紛れ込むことで、評価の精度が実際より高く出てしまう問題である。情報が外部に流出する「情報漏洩」とは別の概念であり、データ量の不足や形式の不統一とも異なる。評価と実運用の精度のずれに気づくことが、リーケージを疑う入口になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-20","exam":"g","unit":"g-u7","keyword":"データリーケージ","type":"choice","syllabus_ref":"7.2","stem":"次のうち、データリーケージが起きていると考えられるものはどれか。","choices":["訓練データとテストデータを、重なりがないようにランダムに分割した","特徴量の標準化に使う平均と標準偏差を、訓練データだけから計算してテストデータに適用した","時系列の売上データで、学習には過去の期間、評価には未来の期間のデータを使った","設備の故障を予測するモデルで、故障が発生した後に記録される修理完了の情報を特徴量に含めて学習していた"],"answer":3,"explanation":"修理完了の情報は故障が起きた後に初めて記録されるもので、故障を予測したい時点では得られない。このような「未来の情報」を特徴量に含めると、評価では故障をよく当てられるように見えても、実際に予測する場面ではその情報が存在しないため精度は再現しない。訓練とテストの分割、訓練データだけでの標準化の計算、時系列での期間の分割はいずれもリーケージを避けるための正しい進め方である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-21","exam":"g","unit":"g-u7","keyword":"データリーケージ","type":"choice","syllabus_ref":"7.2","stem":"データリーケージを防ぐための進め方として、適切なものはどれか。","choices":["先に訓練データとテストデータを分割し、標準化の平均・標準偏差のような前処理のパラメータは訓練データだけで計算してテストデータに適用する。時系列データでは、未来のデータが学習側に入らないよう期間で分割する","前処理は、訓練データとテストデータを合わせた全データで一度に行う方が、値が安定してよい","テストデータでの精度が低かったら、そのテストデータを訓練データに加えて再学習し、精度を上げ直す","特徴量は、予測対象との相関が高いものを、予測の時点で得られるかどうかを確認せずに全て採用する"],"answer":0,"explanation":"リーケージを防ぐ基本は、テストデータを学習のあらゆる工程から切り離すことである。前処理のパラメータを全データから計算すると、テストデータの分布の情報が学習側に漏れる。全データでの前処理、テストデータの訓練への流用、時点を確かめない特徴量の採用はいずれもリーケージを招く進め方である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-22","exam":"g","unit":"g-u7","keyword":"データの収集・加工・分析・学習","type":"choice","syllabus_ref":"7.2","stem":"AI の学習に使うデータを外部から取得・利用する際の注意点として、適切なものはどれか。","choices":["インターネット上で公開されているデータは、利用規約を確認しなくても学習に使ってよい","取得先の利用規約やライセンスで、AI の学習への利用が認められているかを確認し、個人情報が含まれるデータについては、利用目的の範囲内かどうかなど取扱いに配慮する","個人情報が含まれるデータでも、学習に使ってしまえば元の個人が分からなくなるため、特別な配慮は要らない","一度取得したデータは、取得元の条件が後から変更されても、従来どおり使い続けることができる"],"answer":1,"explanation":"外部のデータを取得・利用するときは、利用規約やライセンスが学習への利用を認めているかの確認が前提になる。個人情報を含むデータは、学習に使った後も取扱いの責任が残るため、利用目的の範囲や管理の方法に配慮が要る。公開されていることをもって無条件に使えるわけではなく、学習すれば個人が分からなくなるわけでも、条件変更の影響を受けないわけでもない。なお個人情報保護法そのものの制度は中項目38（パイロット）で扱っており、本問はデータ取得の実務上の注意を問うものである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-23","exam":"g","unit":"g-u7","keyword":"データの収集・加工・分析・学習","type":"choice","syllabus_ref":"7.2","stem":"集めたデータを加工・分析・学習に使う際の注意点として、適切なものはどれか。","choices":["データの量が十分に多ければ、収集した対象の偏りは自動的に解消される","学習データの収集条件や対象に偏りがあるとモデルもその偏りを反映するため、実運用で対象となるデータの分布とずれていないかを確認する","データの偏りはモデルの評価指標には一切現れないため、確認する必要はない","学習データは、入手しやすいデータだけに絞って集める方が、モデルが安定する"],"answer":2,"explanation":"モデルは学習データの傾向を学ぶため、収集したデータに偏り（特定の地域・年代・条件への偏りなど）があると、その偏りを持ったモデルになり、実運用の対象と分布がずれる場面で精度が落ちる。量を増やしても偏り自体は消えず、評価の場面でも偏ったデータで測れば問題が見えにくくなるため、収集の段階から対象の代表性を確認することが注意点になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g7-24","exam":"g","unit":"g-u7","keyword":"データの収集・加工・分析・学習","type":"choice","syllabus_ref":"7.2","stem":"複数の企業がデータを共有しながら AI を共同開発する場面で、進め方として適切なものはどれか。","choices":["開発の速度を優先し、データの取扱いの取り決めは後回しにして、まず全データを共有する","共有を受けたデータは、各社が共同開発以外の目的にも自由に使ってよい","個人情報を含むデータは、加工せずにそのまま共有する方が、精度の検証に役立つ","共有するデータの範囲や利用目的、個人情報や機密情報の取扱い、成果物の権利の帰属などを事前に取り決め、匿名化などの加工が必要な場合はその方法も合意しておく"],"answer":3,"explanation":"データを共有する共同開発では、データそのものに個人情報や機密情報、権利が伴うため、共有の範囲・目的・取扱いと、成果物の権利の帰属を事前に取り決めることが欠かせない。取り決めなしの共有、目的外の利用、無加工での個人情報の共有はいずれも、漏洩や権利をめぐるトラブルの原因になる。匿名化などの加工を行う場合は、その方法と精度への影響も含めて合意しておく進め方が適切である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目7「AI の社会実装に向けて」中項目36「データの収集・加工・分析・学習」"},{"id":"g9-13","exam":"g","unit":"g-u9","keyword":"著作権","type":"choice","syllabus_ref":"9.2","stem":"著作権の説明として、正しいものはどれか。","choices":["著作物を創作した時点で、登録などの手続を経なくても著作者に発生する権利である","特許庁などの機関に出願し、登録を受けて初めて発生する権利である","著作物を公表した時点で発生し、未公表の創作には発生しない権利である","法人だけが持つことができる権利であり、個人の創作には発生しない権利である"],"answer":0,"explanation":"著作権は、著作物を創作した時点で手続なしに著作者に発生する（無方式主義）。登録は権利の発生の要件ではなく、公表の有無も発生には関係しない。著作者は個人・法人を問わず著作物を創作した者であり、著作権は複製や公衆送信などについて許諾・禁止できる権利の総称である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-14","exam":"g","unit":"g-u9","keyword":"著作物","type":"choice","syllabus_ref":"9.2","stem":"著作権法における「著作物」の定義として、正しいものはどれか。","choices":["技術的に新規で、高度な工夫が施された創作物のことである","思想又は感情を創作的に表現したものであって、文芸、学術、美術又は音楽の範囲に属するものをいう","感情を含まず、事実だけを正確に記録した情報のことである","国に登録され、公報に掲載された創作物のことである"],"answer":1,"explanation":"著作権法第2条第1項第1号は、著作物を「思想又は感情を創作的に表現したものであって、文芸、学術、美術又は音楽の範囲に属するもの」と定義している。技術的な新規性は特許の領域の考え方であり、登録も要件ではない。事実だけの記録は、創作的な表現とは言い難い。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-15","exam":"g","unit":"g-u9","keyword":"著作物","type":"choice","syllabus_ref":"9.2","stem":"プログラム（コンピュータプログラム）と著作権法の関係についての説明として、正しいものはどれか。","choices":["プログラムは著作権法の保護対象ではなく、特許権でのみ保護される","プログラムの著作物が保護されれば、そのプログラムを作成するために用いるプログラム言語や解法（アルゴリズム）も含めて保護される","プログラムは著作権法で著作物の例として挙げられており（プログラムの著作物）、著作物として保護され得る。ただし、その保護はプログラム言語、規約及び解法には及ばない","プログラムについては、その機能や処理の仕組み（アイデア）が保護の対象であり、コードとしての表現は保護されない"],"answer":2,"explanation":"著作権法第10条第1項第9号は「プログラムの著作物」を著作物の例として挙げており、プログラムは著作物として保護され得る。一方、同条第3項により、その保護はプログラムを作成するために用いるプログラム言語、規約及び解法（アルゴリズム）には及ばない。保護されるのはコードとしての具体的な表現であり、機能や仕組みというアイデア自体ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-16","exam":"g","unit":"g-u9","keyword":"創作性","type":"choice","syllabus_ref":"9.2","stem":"次のうち、創作性が認められず、著作物に当たらないと考えられるものはどれか。","choices":["独自の比喩や言い回しを工夫して書かれた、製品紹介の短い文章","撮影場所や構図、シャッターのタイミングを選んで撮影された風景写真","筆者の見解や評価を交えて論じた、新聞のコラム記事","気温や降水量などの観測データを、誰が作っても同じになる形で、そのまま並べただけの表"],"answer":3,"explanation":"著作物であるためには、思想又は感情の「創作的な」表現であることが必要である。観測データのような事実そのものには創作性がなく、それを誰が作っても同じになる形で並べただけでは、表現の選択に個性が表れないため著作物には当たらない。著作権法第10条第2項も、事実の伝達にすぎない雑報及び時事の報道は言語の著作物に該当しないとしている。短い文章や写真、コラムでも、表現の工夫や選択があれば創作性が認められ得る。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-17","exam":"g","unit":"g-u9","keyword":"著作権","type":"choice","syllabus_ref":"9.2","stem":"著作権による保護の対象についての説明として、正しいものはどれか。","choices":["保護されるのは著作物の具体的な「表現」であり、その背後にあるアイデアや作風、事実そのものは保護の対象にならない。表現が異なれば、同じアイデアに基づく別の創作は、原則として著作権侵害にならない","著作権はアイデアも表現と一体のものとして保護するため、同じアイデアを用いて別の表現を作っても著作権侵害になる","ある作品の作風に似せて作れば、具体的な表現が異なっていても著作権侵害になる","事実を最初に発見・報道した者には、その事実を独占的に利用できる権利が発生する"],"answer":0,"explanation":"著作権が保護するのは、思想又は感情の創作的な「表現」であり、アイデアや作風、事実そのものは保護の対象ではない（アイデアと表現の区別）。そのため、表現が異なれば、同じアイデアや似た作風に基づく創作であっても、原則として著作権侵害にはならない。AI 生成物の侵害判断でも、作風が似ているだけでは侵害にならず、具体的な表現の類似性が問われるのはこのためである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-18","exam":"g","unit":"g-u9","keyword":"AI 生成物","type":"choice","syllabus_ref":"9.2","stem":"AI 生成物の著作物性について、現在確立されている考え方として、適切なものはどれか。","choices":["AI 生成物については、入力したプロンプトの内容にかかわらず、常にその入力者が著作者になる","AI が自律的に生成したものは、人の思想又は感情を創作的に表現したものとは言い難く、通常は著作物に当たらない。一方、人が AI を道具として使い、指示や修正の仕方などに創作的な寄与が認められる場合は、その寄与が及ぶ範囲で著作物となり得る","AI 生成物に著作権が発生する場合は、その権利は常に AI の開発者に帰属する","AI 生成物は、人の手が一切加わっていないため、いかなる場合も著作物になることはないと法律で定められている"],"answer":1,"explanation":"文化庁の著作権分科会法制度小委員会「AIと著作権に関する考え方について」（2024年3月）が整理しているとおり、AI が自律的に生成したものは、通常、著作物には当たらないと考えられる。一方、人が AI を道具として使い、具体的な指示や修正の繰り返しなどに創作的な寄与が認められる場合は、その範囲で著作物となり得る。ただし、指示がアイデアにとどまる場合や、生成を繰り返したこと、候補から選んだことだけでは、創作的な寄与とは言えないとされている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-19","exam":"g","unit":"g-u9","keyword":"AI 生成物","type":"choice","syllabus_ref":"9.2","stem":"生成 AI の利用と著作権侵害に関する事例の判断として、適切なものはどれか。","choices":["既存のイラストの作風に似せて生成したというだけで、具体的な表現が似ていなくても著作権侵害になる","AI が生成したものである以上、生成物が既存の著作物と実質的に同一であっても、著作権侵害にはならない","生成物が、既存の著作物の創作的な表現と実質的に同じ内容を含み、その著作物に依拠して生成されたと認められる場合（学習データにその著作物が含まれていた場合など）は、AI による生成であっても著作権侵害となり得る","利用者が既存の著作物の存在を知らなかった場合は、著作権侵害は成立せず、生成物の利用を差し止められることもない"],"answer":2,"explanation":"生成物が著作権侵害になるかは、AI を使わずに作った場合と同じく、既存の著作物との「類似性」（創作的な表現が実質的に同じか）と「依拠性」（既存の著作物に基づいて作られたか）の両方で判断される。元の著作物が学習データに含まれていて、それに似た生成物が出た場合は、通常、依拠性があったと推認される。作風が似ているだけでは侵害にならない一方、利用者に故意や過失がなくても、権利者は生成物の利用の差止めを求めることができる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-20","exam":"g","unit":"g-u9","keyword":"著作権侵害","type":"choice","syllabus_ref":"9.2","stem":"AI 開発におけるコードやデータの利用方法のうち、著作権侵害となり得るものはどれか。","choices":["オープンソースのプログラムを、そのライセンスの条件に従って AI 開発に利用する","情報解析（学習）を目的として、著作権法第30条の4に基づき、必要と認められる限度で著作物を複製して学習データに用いる","自社で正規に購入した書籍の文章を、情報解析のために電子化して学習に用いる","権利者に無断で著作物をアップロードしている海賊版サイトであることを知りながら、データを収集し、学習データとして利用する"],"answer":3,"explanation":"著作権法第30条の4は、享受を目的としない情報解析のための利用を許容するが、著作権者の利益を不当に害することとなる場合は適用されない。海賊版であることを知りながらデータを収集して学習に利用することについては、文化庁の小委員会の「AIと著作権に関する考え方について」が、厳に慎むべきものとし、開発事業者が侵害の責任主体とされ得るという整理を示しており、第30条の4ただし書の「不当に害する場合」に当たり得るとの解釈もある（なお「考え方」自体は、海賊版の利用が直ちに著作権法違反に当たるとは明言していない）。ライセンス条件に従った利用や、正規に入手した著作物の情報解析目的の複製は、侵害には当たらない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-21","exam":"g","unit":"g-u9","keyword":"著作権法","type":"choice","syllabus_ref":"9.2","stem":"著作権法第30条の4についての説明として、正しいものはどれか。","choices":["著作物に表現された思想又は感情を享受することを目的としない利用（情報解析など）については、著作権者の利益を不当に害する場合を除き、権利者の許諾なく、必要と認められる限度で著作物を利用できるという制度であり、AI の学習のための複製も、これにより許容される場合がある","AI の学習を目的とする場合に限り、いかなる著作物でも無制限に利用できるようにする制度である","学習に利用した著作物については、その後、第三者への再配布も含めて自由に利用できるようにする制度である","営利を目的とする AI 開発には一切適用されず、研究目的の利用だけを認める制度である"],"answer":0,"explanation":"著作権法第30条の4は、著作物に表現された思想又は感情を自ら享受し又は他人に享受させることを目的としない場合に、必要と認められる限度で、権利者の許諾なく著作物を利用できるとする規定である。情報解析（第2号）はその代表例で、AI の学習のための複製はこの規定により許容される場合がある。ただし、著作権者の利益を不当に害することとなる場合は適用されず、営利目的かどうかで線引きされるものでもない。また、許容されるのは解析のための利用であり、集めた著作物そのものの再配布まで認めるものではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-22","exam":"g","unit":"g-u9","keyword":"著作権侵害","type":"choice","syllabus_ref":"9.2","stem":"次のうち、著作権法第30条の4が適用されず、著作権侵害となり得るものはどれか。","choices":["大量の文章データを情報解析し、単語の出現傾向といった情報を抽出して利用する","情報解析のために販売されているデータベースの著作物を、無断で複製して学習に用い、その販売事業者の市場と競合する形で利用する","適法に入手した著作物を、学習のために自社のサーバに複製する","情報解析によって得られた統計情報や傾向を、論文として公表する"],"answer":1,"explanation":"第30条の4には「当該著作物の種類及び用途並びに当該利用の態様に照らし著作権者の利益を不当に害することとなる場合は、この限りでない」というただし書がある。情報解析用に販売されているデータベースを無断で複製し、販売元の市場と競合する形で利用することは、この「不当に害する場合」に当たり得る。大量の情報からの要素の抽出・解析そのもの、適法に入手した著作物の学習用の複製、解析結果である統計情報の公表は、享受を目的としない利用として許容される範囲である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-23","exam":"g","unit":"g-u9","keyword":"利用規約","type":"choice","syllabus_ref":"9.2","stem":"生成 AI サービスの利用規約についての説明として、適切なものはどれか。","choices":["利用規約は法律そのものであるため、規約に違反すると直ちに著作権侵害が成立する","生成物の権利が誰に帰属するかは著作権法だけで決まるため、利用規約の内容は関係しない","生成物の権利の帰属や商用利用の可否などが、サービスの利用規約で定められている場合があるため、業務で利用する際は規約の確認が必要である。また、規約への違反は契約上の問題であり、著作権侵害とは区別して考える必要がある","生成 AI サービスの生成物については、法律により、常にサービス提供者に著作権が帰属すると定められている"],"answer":2,"explanation":"生成 AI サービスでは、生成物の権利の帰属や、商用利用の可否、利用できる範囲などが利用規約で定められていることが多く、同じ生成物でもサービスごとに扱いが異なるため、利用前の規約確認が欠かせない。利用規約は利用者と提供者の間の契約であり、規約に違反することは契約上の問題であって、それ自体が直ちに著作権侵害になるわけではない。生成物の著作物性や権利の帰属が、法律で一律に提供者と決められているわけでもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-24","exam":"g","unit":"g-u9","keyword":"利用規約","type":"choice","syllabus_ref":"9.2","stem":"AI 開発でオープンソースソフトウェア（OSS）などライセンスの対象となるものを利用する際の留意点として、適切なものはどれか。","choices":["無料で公開されているソフトウェアは、条件なく自由に改変・再配布できる","ライセンスの条件は慣習上の表示にすぎず、従わなくても法的な問題にはならない","ライセンスの条件に違反した場合は、利用の停止を求められることはあっても、著作権侵害として扱われることはない","ライセンスは、条件を守ることを前提に利用を許諾する契約であり、著作権表示の保持や、改変したものの扱いなどの条件を守ることが利用の前提になる。条件に違反すれば、許諾のない利用として著作権侵害となり得る"],"answer":3,"explanation":"OSS などのライセンスは、著作権者が条件付きで利用を許諾する契約であり、無料で公開されていることは「条件なく自由に使える」ことを意味しない。著作権表示の保持、改変した場合の扱い、派生物への同じライセンスの適用など、ライセンスごとに定められた条件を守ることが利用の前提であり、条件に違反すれば、許諾の範囲を超えた利用として著作権侵害となり得る。AI 開発で他者のコードやデータを組み込む際は、ライセンスの必要性と内容の理解が欠かせない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目39「著作権法」"},{"id":"g9-25","exam":"g","unit":"g-u9","keyword":"知的財産権","type":"choice","syllabus_ref":"9.3","stem":"知的財産権の説明として、正しいものはどれか。","choices":["発明や著作物など、人の知的創作活動によって生み出されたものなどに関する権利の総称で、特許権や著作権、商標権などが含まれる","特許庁に登録された技術だけに認められる権利の総称で、著作物に関する権利は含まれない","企業だけが持つことができる権利であり、個人の創作には認められない","有体物（物そのもの）に対する所有権と同じ性質の権利であり、無形の情報には認められない"],"answer":0,"explanation":"知的財産権は、発明、著作物、商標、営業秘密など、知的創作活動の成果や営業上の標識などに関する権利の総称である。特許権・実用新案権・意匠権・商標権の産業財産権と、著作権などが含まれる。対象は無形の成果であり、有体物を対象とする所有権とは性質が異なる。権利者は個人・法人を問わない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-26","exam":"g","unit":"g-u9","keyword":"特許権","type":"choice","syllabus_ref":"9.3","stem":"特許権の発生と性質についての説明として、正しいものはどれか。","choices":["発明を完成させた時点で、著作権と同じく手続なしに自動的に発生する権利である","特許庁に出願し、審査を経て設定登録を受けることで発生する権利であり、権利者は業として特許発明を実施する権利を専有する","出願をすれば審査を受けなくても発生し、誰でもその発明を自由に実施できる権利である","登録を受けても、他者が独自に同じ発明を完成させた場合は、その実施を止めることはできない権利である"],"answer":1,"explanation":"特許権は、特許庁への出願と審査を経て、設定の登録を受けることで発生する（特許法第66条）。創作した時点で手続なしに発生する著作権とは対照的である。特許権者は、業として特許発明を実施する権利を専有する（同法第68条）。この独占は、他者が独自に同じ発明に至った場合の無断実施にも及び得る点で、相対的な保護にとどまる著作権の侵害判断（依拠性が必要）とは異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-27","exam":"g","unit":"g-u9","keyword":"特許権","type":"choice","syllabus_ref":"9.3","stem":"特許権の存続期間と、出願公開の制度についての説明として、正しいものはどれか。","choices":["存続期間は設定登録の日から20年であり、出願の内容は登録されるまで一切公開されない","存続期間は出願の日から10年であり、期間満了後は更新手続により何度でも延長できる","存続期間は特許出願の日から20年をもって終了する。また、出願の内容は原則として出願から1年6か月を経過すると公開され（出願公開）、公開の代償として独占が認められる制度になっている","存続期間に法律上の定めはなく、特許料を納付し続ける限り半永久的に存続する"],"answer":2,"explanation":"特許法第67条第1項は、特許権の存続期間を特許出願の日から20年と定めている。起算点は登録日ではなく出願日である。また、同法第64条の出願公開により、出願の内容は原則として出願から1年6か月後に公開される。特許制度は、発明を公開する代償として一定期間の独占を認める仕組みであり、商標権のような更新制度はない（医薬品等について延長の登録が認められる例外はある）。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-28","exam":"g","unit":"g-u9","keyword":"発明","type":"choice","syllabus_ref":"9.3","stem":"特許法における「発明」の定義として、正しいものはどれか。","choices":["自然法則そのものを新たに発見したこと","計算の手順やゲームのルールなど、人為的に定めた取り決めのこと","思想又は感情を創作的に表現したもののこと","自然法則を利用した技術的思想の創作のうち高度のものをいう"],"answer":3,"explanation":"特許法第2条第1項は、発明を「自然法則を利用した技術的思想の創作のうち高度のもの」と定義している。自然法則そのものの発見や、計算方法・ゲームのルールのような人為的な取り決め自体は、自然法則を利用した技術的思想とは言えず、発明には当たらない。「思想又は感情を創作的に表現したもの」は著作権法における著作物の定義であり、特許法の発明とは保護の対象が異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-29","exam":"g","unit":"g-u9","keyword":"発明","type":"choice","syllabus_ref":"9.3","stem":"AI 関連の技術と、特許法上の「発明」への該当性についての説明として、適切なものはどれか。","choices":["プログラムや学習済みモデルであっても、ソフトウェアによる情報処理がハードウェア資源を用いて具体的に実現されている場合などには「発明」に該当し得ると、特許庁の審査基準や事例で整理されている","プログラムは無形の情報であるため、いかなる場合も特許法の「発明」に当たることはない","学習済みモデルはパラメータの集まりであるため、常に「発明」に該当し、当然に特許を受けられる","AI が生成した技術は、人が関与していないため、常に「発明」に該当しないと法律で明示されている"],"answer":0,"explanation":"特許庁の特許・実用新案審査基準では、ソフトウェア関連発明について、ソフトウェアによる情報処理がハードウェア資源を用いて具体的に実現されている場合に発明該当性が認められるとされ、学習済みモデルがプログラムとして扱われる場合に発明に該当し得る事例も示されている。これは審査基準・運用上の整理であり、発明に該当しても、新規性・進歩性などの他の要件を満たさなければ特許は受けられない。また、情報の単なる提示や、自然法則を利用しないものは発明に当たらない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-30","exam":"g","unit":"g-u9","keyword":"新規性","type":"choice","syllabus_ref":"9.3","stem":"特許法における新規性についての説明として、正しいものはどれか。","choices":["新規性は、出願の時点で発明者自身が主観的に新しいと思っていたかどうかで判断される","出願前に国内外で公然知られた発明、公然実施された発明、刊行物に記載された発明や電気通信回線を通じて公衆に利用可能となった発明は、新規性を欠き、特許を受けられない","論文や学会で発表した後でも、発表したのが発明者本人であれば、新規性は一切失われない","新規性の判断の対象は日本国内で知られた発明に限られ、外国の公知技術は関係しない"],"answer":1,"explanation":"特許法第29条第1項は、出願前に公然知られた発明（第1号）、公然実施された発明（第2号）、頒布された刊行物に記載された発明や電気通信回線を通じて公衆に利用可能となった発明（第3号）は特許を受けられないと定めており、新規性の喪失は国内外を問わない。発明者自身による発表でも、原則として新規性は失われる（例外は第30条の制度で、次問の範囲）。主観的な新しさではなく、出願時点での公知の状態が基準になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-31","exam":"g","unit":"g-u9","keyword":"進歩性","type":"choice","syllabus_ref":"9.3","stem":"特許法における進歩性についての説明として、正しいものはどれか。","choices":["新規性が認められれば、進歩性も自動的に認められる","進歩性は、発明の技術が社会にどれだけ普及したかによって判断される","進歩性は、出願人が発明の完成にどれだけの費用と時間をかけたかによって判断される","出願前に、その発明の属する技術の分野における通常の知識を有する者（当業者）が、公知の発明に基づいて容易に発明をすることができたときは、新規性があっても特許を受けられない"],"answer":3,"explanation":"特許法第29条第2項は、公知の発明に基づいて当業者が容易に発明をすることができたときは、特許を受けることができないと定めている。新規性（公知技術と同一ではないこと）と進歩性（公知技術から容易に思いつかないこと）は別の要件である。公知技術の単純な組み合わせや置き換え、設計変更の範囲にとどまるものは、進歩性を欠くと判断されやすい。開発にかけた費用や時間の多寡は、判断の基準ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-32","exam":"g","unit":"g-u9","keyword":"新規性","type":"choice","syllabus_ref":"9.3","stem":"研究者が自らの発明を学会で発表した後、その発明について特許出願を考えている。この場合の新規性の扱いについての説明として、適切なものはどれか。","choices":["自分で発表したものであれば、発表から何年経過しても新規性は失われない","学会で発表した時点で新規性は完全に失われ、いかなる手続によっても特許を受けることはできない","原則として発表により新規性は失われるが、特許を受ける権利を有する者の行為に起因して公知となった場合は、公知となった日から1年以内に出願し、所定の手続を行えば、新規性を失わなかったものとして扱われ得る","発表の前に特許庁へ発表の届け出をしておけば、その後の出願では常に例外が認められる"],"answer":2,"explanation":"特許法第30条は「発明の新規性の喪失の例外」を定めている。特許を受ける権利を有する者の行為に起因して公知となった発明は、公知となった日から1年以内にその者が出願し、例外の適用を受けようとする旨の書面を出願と同時に提出するなどの所定の手続を行えば、第29条の適用について公知にならなかったものとみなされる。例外は自動的には認められず、また国によっては同様の制度がないため、実務上は出願前の公開を避けることが原則とされる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-33","exam":"g","unit":"g-u9","keyword":"発明者","type":"choice","syllabus_ref":"9.3","stem":"AI と発明者についての説明として、適切なものはどれか。","choices":["AI が自律的に生成した発明について AI 自身を発明者とする出願が争われた裁判例（いわゆるダバス事件）では、東京地方裁判所が、特許法の「発明者」は自然人に限られると判断した","日本では、AI を発明者として記載した特許出願が既に認められており、AI 自身が特許権者になることができる","発明者は、発明の完成に資金を提供した者や、発明者の上司が自動的に決まる","発明者が誰であるかは特許の効力に無関係であるため、出願書類に発明者を記載する必要はない"],"answer":0,"explanation":"発明者は、発明の完成に創作的に寄与した自然人をいう。AI システム「ダバス」を発明者として記載した出願をめぐる訴訟では、東京地方裁判所が2024年の判決で、特許法の「発明者」は自然人に限られ、AI は含まれないと判断した（条文に「自然人」と明記されているわけではなく、裁判所の解釈として示された判断である）。AI を道具として使い、人が創作的に寄与して発明を完成させた場合は、その人が発明者となり得る。願書には発明者の氏名の記載が必要である（特許法第36条）。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-34","exam":"g","unit":"g-u9","keyword":"職務発明","type":"choice","syllabus_ref":"9.3","stem":"職務発明についての説明として、正しいものはどれか。","choices":["従業者が職務と無関係に個人的に行った発明も、すべて職務発明に当たる","従業者等がした発明で、その性質上使用者等の業務範囲に属し、かつ、発明をするに至った行為が従業者等の現在又は過去の職務に属するものをいい、使用者等は、職務発明について特許が受けられたときは、その特許権について通常実施権を有する","職務発明については、特許を受ける権利は常に自動的に使用者等に帰属する","職務発明の制度は大企業だけに適用され、中小企業には適用されない"],"answer":1,"explanation":"特許法第35条第1項は、職務発明を、従業者等がした発明であって、その性質上使用者等の業務範囲に属し、かつ、発明をするに至った行為がその従業者等の現在又は過去の職務に属するものと定め、使用者等はその特許権について通常実施権を有するとしている。特許を受ける権利は原則として発明者である従業者等に生じ、あらかじめ契約・勤務規則等で定めた場合に限り、発生した時から使用者等に帰属させることができる（同条第3項）。職務発明でない発明について、あらかじめ使用者等に権利を取得させる等の定めは無効である（同条第2項）。企業規模による区別はない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-35","exam":"g","unit":"g-u9","keyword":"職務発明","type":"choice","syllabus_ref":"9.3","stem":"職務発明における従業者等の「相当の利益」についての説明として、正しいものはどれか。","choices":["従業者等が使用者等に特許を受ける権利を取得させた場合でも、法律上、対価を受け取ることはできない","相当の利益の金額は法律で一律に定められており、契約や勤務規則で定めることはできない","相当の利益は金銭でなければならないと法律で定められており、それ以外の形で与えることはできない","従業者等は、契約・勤務規則等の定めにより使用者等に特許を受ける権利を取得させる等をした場合、相当の金銭その他の経済上の利益を受ける権利を有する。その利益の内容を定めるに当たっては、基準の策定に関する協議の状況等に照らして不合理であってはならない"],"answer":3,"explanation":"特許法第35条第4項は、従業者等が、定めにより使用者等に特許を受ける権利を取得させる等をした場合、相当の金銭その他の経済上の利益（相当の利益）を受ける権利を有すると定めている。2015年の改正で「相当の対価」から「相当の利益」に改められ、金銭以外の経済上の利益も含まれる。同条第5項は、利益の内容を定める場合、基準の策定に際した協議の状況、基準の開示の状況、意見の聴取の状況等を考慮して、その定めが不合理であってはならないとしている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-36","exam":"g","unit":"g-u9","keyword":"特許権","type":"choice","syllabus_ref":"9.3","stem":"AI 開発企業が、開発した学習済みモデルに関する技術を保護する方法を検討している。特許権と営業秘密による保護の違いを踏まえた判断として、適切なものはどれか。","choices":["特許出願をすれば、発明の内容を公開せずに独占的な保護を受けられるため、秘密にしたい技術ほど特許による保護が適している","営業秘密として管理しておけば、他者が独自に同じ技術を開発して実施した場合でも、その実施を差し止めることができる","特許は、出願により発明が公開される代わりに、他者の独自開発に対しても及ぶ独占的な権利が一定期間得られる。一方、営業秘密は公開されず期間の制限もないが、秘密として管理されていることが必要であり、他者の独自開発や適法なリバースエンジニアリングによる取得までは防げない。このため、製品を解析すれば技術が分かりやすいものは特許、外部から推測されにくい学習手法やデータは営業秘密、という使い分けが考えられる","同じ技術について、特許出願をして独占権を得ながら、同時にその内容を営業秘密として保護し続けることが常に可能である"],"answer":2,"explanation":"特許権は、出願により発明が公開される代償として、出願日から20年の独占的な権利が得られ、その効力は他者の独自開発にも及ぶ。営業秘密は、不正競争防止法上保護される情報であり、公開されないため期間の制限はないが、秘密として管理されていること等が前提で、他者が独自に開発した場合や、適法なリバースエンジニアリングで取得した場合には対抗できない。特許出願をすれば内容は公開されるため、同じ技術を同時に秘密のまま保つことはできない。AI の分野では、解析されやすい技術は特許、学習データやパラメータのように外から分かりにくい情報は営業秘密、という使い分けが実務上議論される。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目40「特許法」"},{"id":"g9-37","exam":"g","unit":"g-u9","keyword":"営業秘密","type":"choice","syllabus_ref":"9.4","stem":"不正競争防止法における「営業秘密」の定義として、正しいものはどれか。","choices":["秘密として管理されている生産方法、販売方法その他の事業活動に有用な技術上又は営業上の情報であって、公然と知られていないものをいう","経済産業省に届け出て、登録を受けた技術上又は営業上の情報をいう","企業が秘密であると宣言した情報であれば、実際にどのように管理されていても営業秘密に当たる","特許出願中の発明に関する情報だけをいい、営業上の情報は含まれない"],"answer":0,"explanation":"不正競争防止法第2条第6項は、営業秘密を「秘密として管理されている生産方法、販売方法その他の事業活動に有用な技術上又は営業上の情報であって、公然と知られていないもの」と定義している。登録や届出の制度はなく、保護を受けるには、秘密として管理されていること（秘密管理性）、事業活動に有用であること（有用性）、公然と知られていないこと（非公知性）の三要件を満たす必要がある。技術上の情報だけでなく、顧客名簿のような営業上の情報も対象になる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-38","exam":"g","unit":"g-u9","keyword":"営業秘密","type":"choice","syllabus_ref":"9.4","stem":"営業秘密の三要件の一つである「秘密管理性」についての説明として、適切なものはどれか。","choices":["情報そのものが客観的に高度な内容であれば、管理の方法にかかわらず秘密管理性が認められる","事業者が情報を秘密として管理しようとする意思が、アクセス制限や秘密である旨の表示などの具体的な措置によって、その情報に触れる者に認識できる状態になっていることが必要である","秘密管理性が認められるためには、情報を暗号化し、金庫や施錠された部屋に保管することが法律上必須である","社内の会議で一度「これは秘密だ」と口頭で述べたことがあれば、その後の管理の実態にかかわらず秘密管理性が認められる"],"answer":1,"explanation":"秘密管理性は、情報を秘密として管理しようとする事業者の意思が、具体的な措置によって、情報に触れる従業員等に認識可能な状態になっていることをいう。アクセスできる者の制限、秘密である旨の表示、パスワードによる管理などがその例であり、経済産業省の「営業秘密管理指針」でもこの考え方が示されている。情報の内容の高度さや、特定の保管方法の有無だけで決まるものではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-39","exam":"g","unit":"g-u9","keyword":"営業秘密","type":"choice","syllabus_ref":"9.4","stem":"営業秘密の三要件のうち「有用性」と「非公知性」についての説明として、適切なものはどれか。","choices":["有用性が認められるのは、現在実際に事業に使用されている情報に限られ、失敗した実験のデータのような情報は有用とは言えない","非公知性が認められるためには、保有者以外の誰一人としてその情報を知らない状態でなければならない","有用性は、生産方法の改善や経費の節約など事業活動にとって役立つ性質をいい、失敗した実験のデータのように、同じ失敗を避けるために役立つ情報も含まれ得る。非公知性は、保有者の管理下以外では一般に入手できない状態をいい、守秘義務を負う特定の者に開示されていても失われない","有用性と非公知性は、いずれもその情報が特許を受けられるかどうかによって判断される"],"answer":2,"explanation":"有用性は、事業活動に有用な性質をいい、現に使用されている情報に限られない。失敗した実験データのような、いわゆるネガティブ・インフォメーションも、研究開発の重複を避けるなどの点で有用となり得る。非公知性は「公然と知られていない」ことをいい、守秘義務を負う取引先など特定の者に示されている場合でも、その情報が一般に入手できない状態であれば失われない。特許を受けられるかどうかとは別の判断である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-40","exam":"g","unit":"g-u9","keyword":"営業秘密","type":"choice","syllabus_ref":"9.4","stem":"次の情報の管理の事例のうち、営業秘密の三要件を満たさず、営業秘密に当たらないと考えられるものはどれか。","choices":["顧客リストについて、アクセスできる従業員を担当部署に限定し、ファイルに秘密である旨を表示して管理している","学習済みモデルの調整手法について、関係者以外は閲覧できないサーバに保管し、閲覧履歴を記録している","製造工程の条件表について、守秘義務を課したうえで、共同研究先の担当者にだけ開示している","学習データの収集・加工方法をまとめた文書について、社内の誰でも制限なくアクセスできる共有フォルダに置き、秘密である旨の表示もしていない"],"answer":3,"explanation":"営業秘密として保護されるには、秘密管理性・有用性・非公知性の三要件を全て満たす必要がある。誰でも制限なくアクセスできる状態で、秘密である旨の表示もなければ、情報を秘密として管理しようとする意思が認識できる状態とは言えず、秘密管理性を欠く。アクセス制限や表示、守秘義務を課したうえでの限定的な開示は、秘密管理性を保つ管理の例である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-41","exam":"g","unit":"g-u9","keyword":"営業秘密","type":"choice","syllabus_ref":"9.4","stem":"営業秘密の取得・使用と不正競争防止法の関係についての説明として、適切なものはどれか。","choices":["他者の営業秘密と結果的に同じ内容の情報であれば、どのように取得したかにかかわらず、その使用は全て不正競争に当たる","窃取、詐欺、強迫その他の不正の手段により営業秘密を取得する行為や、そのようにして取得した営業秘密を使用し、又は開示する行為は不正競争に当たる。一方、自ら独自に開発して得た情報や、市販の製品を適法に分析するリバースエンジニアリングによって得た情報は、不正の手段による取得には当たらない","営業秘密を偶然知ってしまった場合は、その後どのような使い方をしても不正競争には当たらない","営業秘密の侵害が問題になるのは、情報を盗み取った本人だけで、その情報を譲り受けた者の行為は対象にならない"],"answer":1,"explanation":"不正競争防止法第2条第1項第4号は、窃取、詐欺、強迫その他の不正の手段により営業秘密を取得する行為（営業秘密不正取得行為）と、それにより取得した営業秘密の使用・開示を不正競争としている。規制されるのは取得や使用の「不正さ」であり、独自開発や適法なリバースエンジニアリングで同じ情報にたどり着くこと自体は妨げられない。不正取得が介在したことを知って取得した者などの行為も、別の号で不正競争とされている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-42","exam":"g","unit":"g-u9","keyword":"営業秘密","type":"choice","syllabus_ref":"9.4","stem":"AI 開発企業の従業者 A は、業務の中で自社の営業秘密である学習データの前処理手法を示されていた。競合企業への転職に際し、A がこの手法を転職先で使う目的で持ち出し、開示した。この行為についての説明として、適切なものはどれか。","choices":["在職中に示された営業秘密であれば、退職や転職に伴って自由に使えるようになる","転職先で使う目的があっても、実際に転職先の製品に使われなければ、不正競争には当たり得ない","営業秘密を保有者から示された者が、不正の利益を得る目的で、又は保有者に損害を加える目的で、その営業秘密を使用し、又は開示する行為は、不正競争に当たる","従業者が営業秘密を持ち出す行為は、労働法の問題にはなっても、不正競争防止法の対象にはならない"],"answer":2,"explanation":"不正競争防止法第2条第1項第7号は、営業秘密を保有者から示された場合において、不正の利益を得る目的で、又は保有者に損害を加える目的で、その営業秘密を使用し、又は開示する行為を不正競争としている。在職中に正当に示された秘密であっても、この目的をもって持ち出し・開示すれば対象になり、差止請求や損害賠償、場合によっては刑事罰の対象にもなり得る。なお、従業者が身に付けた一般的な知識やスキル自体は営業秘密ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-43","exam":"g","unit":"g-u9","keyword":"営業秘密","type":"choice","syllabus_ref":"9.4","stem":"営業秘密の転得者（他人から営業秘密を取得した者）の行為についての説明として、適切なものはどれか。","choices":["その営業秘密について不正取得行為が介在したことを知って、又は重大な過失により知らないで営業秘密を取得し、又はその取得した営業秘密を使用し、若しくは開示する行為も、不正競争に当たる","転得者は、取得の経緯を一切問われることはなく、どのような場合でも自由に使用できる","不正取得行為が介在したことを知っていた場合でも、対価を支払って取得していれば不正競争には当たらない","転得者の行為が不正競争になるのは、刑事事件として立件された場合に限られる"],"answer":0,"explanation":"不正競争防止法第2条第1項第5号は、不正取得行為が介在したことを知って、又は重大な過失により知らないで営業秘密を取得し、使用・開示する行為を不正競争としている。不正開示行為が介在した場合についても同様の定めがある（同項第8号）。対価の支払いの有無で結論は変わらない。一方、介在したことを知らず、知らないことに重大な過失もない者が、取引によって取得した権原の範囲内で使用・開示する行為は、適用除外として保護されている（同法第19条第1項第7号）。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-44","exam":"g","unit":"g-u9","keyword":"限定提供データ","type":"choice","syllabus_ref":"9.4","stem":"不正競争防止法における「限定提供データ」の定義として、正しいものはどれか。","choices":["秘密として管理されている技術上又は営業上の情報のうち、特に重要なものをいう","企業が保有する個人に関する情報のうち、提供先を限定して提供するものをいう","無償で広く一般に公開されているオープンデータのうち、利用条件が定められているものをいう","業として特定の者に提供する情報として電磁的方法により相当量蓄積され、及び管理されている技術上又は営業上の情報であって、営業秘密を除くものをいう"],"answer":3,"explanation":"不正競争防止法第2条第7項は、限定提供データを「業として特定の者に提供する情報として電磁的方法により相当量蓄積され、及び管理されている技術上又は営業上の情報（営業秘密を除く。）」と定義している。要件として整理されるのは、特定の者に提供されるものであること（限定提供性）、相当量が蓄積されていること（相当蓄積性）、ID・パスワードなどの電磁的な方法で管理されていること（電磁的管理性）であり、営業秘密のように秘密として管理されていることは要件にならない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-45","exam":"g","unit":"g-u9","keyword":"限定提供データ","type":"choice","syllabus_ref":"9.4","stem":"限定提供データの制度が設けられた趣旨についての説明として、適切なものはどれか。","choices":["企業間でデータを提供し合う場面では、秘密として管理されていないために営業秘密としては保護できないデータも多い。そのようなデータについても不正な取得・使用等を規制することで、安心してデータを提供・共有できるようにし、データの利活用を促すために、2019年に施行された改正で導入された","データの流通そのものを抑えるため、企業間でのデータ提供を原則として禁止する制度として導入された","営業秘密の三要件が厳しすぎたため、三要件を廃止して限定提供データの制度に置き換えたものである","データに登録番号を付け、国が一元的に管理する制度として導入された"],"answer":0,"explanation":"限定提供データの制度は、平成30年（2018年）の不正競争防止法改正で設けられ、令和元年（2019年）7月1日に施行された。取引先など特定の者に提供するデータは、提供する以上「秘密として管理されている」とは言いにくく、営業秘密の枠組みでは保護しにくい。そこで、秘密管理性を要件としない代わりに、限定提供性・相当蓄積性・電磁的管理性を備えたデータについて不正取得・使用等を不正競争とし、差止請求などを認めることで、データ提供への不安を減らし、利活用を促すことが制度の趣旨である。経済産業省は「限定提供データに関する指針」を公表して要件の考え方を示している。営業秘密の制度は廃止されておらず、両制度は併存している。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-46","exam":"g","unit":"g-u9","keyword":"限定提供データ","type":"choice","syllabus_ref":"9.4","stem":"限定提供データに対する規制と、営業秘密に対する規制との違いについての説明として、適切なものはどれか。","choices":["限定提供データの不正取得等については、営業秘密と同じく刑事罰が定められており、法人にはより重い罰金が科される","限定提供データについては、不正取得行為が介在したことを知らずに取得した者は、知らないことに重大な過失がある場合でも、取得の行為自体は不正競争とされていない。また、限定提供データの侵害には刑事罰の定めはなく、保護は差止請求や損害賠償請求といった民事上の請求による","限定提供データについては、差止請求をすることが認められておらず、損害賠償請求だけが認められている","限定提供データを保有者から示された者が図利加害の目的で使用する行為は、その使用が管理に係る任務に違反するかどうかを問わず、全て不正競争に当たる"],"answer":1,"explanation":"限定提供データの転得者については、不正競争防止法第2条第1項第12号が「介在したことを知って」取得等する行為を対象としており、営業秘密の場合（同項第5号）と異なり、重大な過失により知らなかった場合は取得自体は対象に含まれない。また、営業秘密侵害には刑事罰（第21条）があるが、限定提供データについては刑事罰の定めはなく、差止請求（第3条）や損害賠償請求（第4条）による民事上の保護にとどまる。保有者から示された者の使用が不正競争になるのは、そのデータの管理に係る任務に違反して行うものに限られる（同項第14号）。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-47","exam":"g","unit":"g-u9","keyword":"不正競争防止法","type":"choice","syllabus_ref":"9.4","stem":"不正競争防止法による営業秘密の保護と、特許権による保護との違いについての説明として、適切なものはどれか。","choices":["営業秘密の保護を受けるためには、特許と同じく出願と登録が必要であり、保護の期間も出願日から20年である","不正競争防止法の保護は、技術の内容を公開することが条件であり、公開の代償として独占が認められる","不正競争防止法による保護は、出願・登録や公開を必要とせず、不正な手段による取得や、不正の目的による使用・開示といった行為を規制するものであって、独占的な権利を付与するものではない。そのため保護期間の定めはないが、他者が独自に開発した技術に対しては対抗できない","営業秘密として保護される情報については、その内容が特許法の発明の定義に当てはまることが必要である"],"answer":2,"explanation":"特許権は、出願により発明を公開する代償として、設定登録により独占的な権利が発生し、存続期間は出願日から20年と定められている。これに対して不正競争防止法による営業秘密の保護は、登録の制度を持たず、不正競争に当たる行為を規制する行為規制型の保護である。秘密として管理されるなどの要件を満たす限り期間の定めなく保護が及び得る一方、独占権ではないため、他者の独自開発や適法なリバースエンジニアリングには対抗できない。保護の対象は技術上の情報に限られず、営業上の情報も含まれる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-48","exam":"g","unit":"g-u9","keyword":"不正競争防止法","type":"choice","syllabus_ref":"9.4","stem":"AI 開発企業 X 社の情報管理についての判断として、適切なものはどれか。X 社は、(1) 学習済みモデルの性能を左右する調整手法を、アクセス制限と秘密である旨の表示を付けて社内で管理している。(2) 取引先の限られた企業に対して、ID・パスワードで管理されたサーバを介して、学習用データセットを有償で提供しているが、提供先では秘密として管理する義務までは課していない。","choices":["(1) は社内で管理しているだけであり、外部に提供していないため、営業秘密としては保護され得ない","(2) は提供先に秘密管理の義務を課していないため、不正競争防止法上、いかなる保護も受けられない","(1) も (2) も、保護を受けるためには特許出願をして登録を受けることが必要である","(1) は、秘密として管理され、事業活動に有用で、公然と知られていなければ、営業秘密として保護され得る。(2) は、秘密として管理されていなくても、特定の者に提供する情報として電磁的方法により相当量蓄積・管理されていれば、限定提供データとして、その不正取得・使用等が規制され得る"],"answer":3,"explanation":"(1) は営業秘密の三要件（秘密管理性・有用性・非公知性）を満たせば保護され得るもので、外部へ提供しているかどうかは要件ではない。(2) のように、特定の相手に提供し、秘密として管理されているとは言いにくいデータであっても、限定提供データの要件（限定提供性・相当蓄積性・電磁的管理性）を満たせば、不正取得・使用・開示等が不正競争として規制され、差止請求などが認められ得る。両制度は対象となる情報の状態が異なり、使い分けられる。特許出願は両制度の保護の条件ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目41「不正競争防止法」"},{"id":"g9-49","exam":"g","unit":"g-u9","keyword":"独占禁止法","type":"choice","syllabus_ref":"9.5","stem":"独占禁止法（私的独占の禁止及び公正取引の確保に関する法律）の目的として、正しいものはどれか。","choices":["私的独占、不当な取引制限及び不公正な取引方法を禁止し、事業支配力の過度の集中を防止することなどにより、公正かつ自由な競争を促進し、一般消費者の利益を確保するとともに、国民経済の民主的で健全な発達を促進すること","国内の事業者を外国の事業者との競争から保護し、国内産業の国際競争力を強化すること","商品やサービスの価格を国が適正な水準に管理し、物価の安定を図ること","大企業による事業活動そのものを禁止し、中小企業だけが事業を行えるようにすること"],"answer":0,"explanation":"独占禁止法第1条は、私的独占、不当な取引制限及び不公正な取引方法を禁止し、事業支配力の過度の集中を防止することなどにより、公正かつ自由な競争を促進し、事業者の創意を発揮させ、事業活動を盛んにすることなどを通じて、一般消費者の利益を確保するとともに、国民経済の民主的で健全な発達を促進することを目的としている。価格を国が管理する法律でも、特定の産業を保護する法律でもなく、市場における競争の仕組みを守るための法律である。規模の大きい事業者の存在そのものが禁止されるわけでもない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-50","exam":"g","unit":"g-u9","keyword":"独占禁止法","type":"choice","syllabus_ref":"9.5","stem":"独占禁止法が禁止する行為の類型として、正しい組み合わせはどれか。","choices":["私的独占、不当な取引制限、不正競争","私的独占、不当な取引制限、不公正な取引方法","私的独占、カルテル、営業秘密の侵害","不当な取引制限、不公正な取引方法、著作権侵害"],"answer":1,"explanation":"独占禁止法の中心となる禁止行為は、私的独占と不当な取引制限（第3条）、そして不公正な取引方法（第19条）の三つである。このほか、事業者団体の禁止行為や、競争を実質的に制限することとなる企業結合の禁止なども定められている。「不正競争」や営業秘密の侵害は不正競争防止法、著作権侵害は著作権法の領域であり、独占禁止法の禁止類型ではない。カルテルは不当な取引制限の代表例を指す通称であり、独立した類型ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-51","exam":"g","unit":"g-u9","keyword":"競争制限","type":"choice","syllabus_ref":"9.5","stem":"独占禁止法における「私的独占」の説明として、適切なものはどれか。","choices":["事業者が、他の事業者と共同して、商品の対価を引き上げる行為をいう","市場におけるシェアが一定の割合を超えた事業者の地位そのものをいう","事業者が、単独に、又は他の事業者と結合し、若しくは通謀し、その他いかなる方法によるかを問わず、他の事業者の事業活動を排除し、又は支配することにより、公共の利益に反して、一定の取引分野における競争を実質的に制限することをいう","事業者が、自社の商品をその供給に要する費用を著しく下回る対価で継続して供給する行為だけをいう"],"answer":2,"explanation":"私的独占は独占禁止法第2条第5項で定義され、第3条で禁止されている。ポイントは、他の事業者の事業活動を「排除」し、又は「支配」するという手段を用いて、一定の取引分野における競争を実質的に制限する「行為」であることであり、シェアの大きさという地位そのものは禁止されていない。他の事業者と共同して対価を引き上げる行為は不当な取引制限（カルテル）であり、費用を著しく下回る対価での継続的な供給は不公正な取引方法の一類型（不当廉売）である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-52","exam":"g","unit":"g-u9","keyword":"競争制限","type":"choice","syllabus_ref":"9.5","stem":"独占禁止法における「不当な取引制限」（カルテル）の説明として、適切なものはどれか。","choices":["事業者が単独で、取引の相手方に対して不当に不利益を与える行為をいう","商品を不当に安く供給し、他の事業者の事業活動を困難にさせるおそれがある行為をいう","事業者が、取引の相手方を一方的に変更する行為をいう","事業者が、契約、協定その他何らの名義によるかを問わず、他の事業者と共同して対価を決定し、維持し、若しくは引き上げ、又は数量、技術、製品、設備若しくは取引の相手方を制限する等、相互にその事業活動を拘束し、又は遂行することにより、公共の利益に反して、一定の取引分野における競争を実質的に制限することをいう"],"answer":3,"explanation":"不当な取引制限は独占禁止法第2条第6項で定義され、第3条で禁止されている。競争関係にある事業者同士が「共同して」事業活動を相互に拘束し、競争を実質的に制限する点が中心であり、価格カルテルや入札談合が典型例である。単独で取引の相手方に不利益を与える行為は、態様により不公正な取引方法（優越的地位の濫用など）の問題であり、不当に安く供給する行為は不公正な取引方法の一類型（不当廉売）である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-53","exam":"g","unit":"g-u9","keyword":"競争制限","type":"choice","syllabus_ref":"9.5","stem":"AI・アルゴリズムと独占禁止法の論点として、価格設定アルゴリズムを利用した協調的行為についての説明として、適切なものはどれか。","choices":["アルゴリズムが自動的に価格を決める場合には人の手を介さないため、不当な取引制限が問題になることは一切ない","複数の競争事業者が、価格が同調するようなアルゴリズムを利用していることを互いに認識し、それを認容したうえで利用しているような場合には、事業者間に直接の情報交換がなくても「意思の連絡」があると評価され、不当な取引制限が成立し得る。また、同一のプラットフォームやアルゴリズム提供者を介して価格が同調する協調（ハブ・アンド・スポーク型）も論点とされている","価格設定アルゴリズムの利用は業務の効率化につながるため、結果として価格が同調しても、独占禁止法上の問題は生じない","アルゴリズムによる協調が問題になるのは、事業者が書面でカルテルの合意を交わした場合に限られる"],"answer":1,"explanation":"公正取引委員会の研究会報告書「アルゴリズム／AIと競争政策」（2021年）は、アルゴリズムによる協調的行為を、監視型、並行利用（同一のアルゴリズムの利用）、シグナリング、自己学習アルゴリズムによる協調の4類型に分けて検討している。不当な取引制限の要件である「意思の連絡」については、価格が同調することを認識・認容してアルゴリズムを用いている場合には、直接の情報交換がなくても認められ得ると整理されている。アルゴリズムを用いたからといって規制の対象外になるわけではなく、書面の合意も要件ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-54","exam":"g","unit":"g-u9","keyword":"競争制限","type":"choice","syllabus_ref":"9.5","stem":"AI の競争力を支える要因としてのデータと、独占禁止法・競争政策上の論点についての説明として、適切なものはどれか。","choices":["大量のデータを収集・蓄積し、AI の精度向上に活かせる事業者は競争上有利になり得る。データの集中やネットワーク効果によって新規参入が難しくなれば、競争が制限されるおそれがあるため、データへのアクセスの拒否や、データを持つ事業者の買収などが論点とされている","データは複製が容易で、どの事業者も同じものを保有できるため、データの保有量が競争力の差になることはない","データを大量に保有すること自体が独占禁止法で禁止されており、一定量を超えるデータの収集は違法である","データの集中が問題になるのは個人情報を含むデータに限られ、産業データについては論点にならない"],"answer":0,"explanation":"公正取引委員会の研究会報告書「アルゴリズム／AIと競争政策」（2021年）は、アルゴリズム／AI の競争力を支える要因を、データと AI 技術階層の観点から整理している。利用者が増えるほどデータが集まり、サービスの精度が上がってさらに利用者が増えるという循環（ネットワーク効果を含む）が働くと、先行する事業者との差が開き、新規参入が難しくなり得る。問題になるのはデータの保有そのものではなく、競争者の事業活動を排除するような行為や競争を制限する効果であり、個人情報に限らず産業データも論点に含まれる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-55","exam":"g","unit":"g-u9","keyword":"公正競争阻害性","type":"choice","syllabus_ref":"9.5","stem":"独占禁止法における「不公正な取引方法」の説明として、適切なものはどれか。","choices":["私的独占と同じく、一定の取引分野における競争を実質的に制限する行為だけをいう","消費者の利益を害する行為であれば、競争への影響が一切なくても、全てこれに当たる","取引に関する行為のうち、刑事罰の対象になるものだけをいう","公正な競争を阻害するおそれがある行為をいい、私的独占や不当な取引制限のように競争の実質的な制限までは要件とされていない。不当廉売、差別対価、取引妨害、優越的地位の濫用などが、その類型として法律に定められている"],"answer":3,"explanation":"不公正な取引方法は独占禁止法第2条第9項で定義され、第19条で禁止されている。要件は「公正な競争を阻害するおそれがあること」（公正競争阻害性）であり、競争の実質的制限という結果までは必要ないため、競争を制限するに至らない段階の行為も捉えることができる。類型は法律の各号に定められており、共同の取引拒絶、差別対価、不当廉売、再販売価格の拘束、優越的地位の濫用などが含まれる。刑事罰の対象になるかどうかで範囲が決まるものではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-56","exam":"g","unit":"g-u9","keyword":"独占禁止法","type":"choice","syllabus_ref":"9.5","stem":"独占禁止法違反に対する公正取引委員会の措置についての説明として、適切なものはどれか。","choices":["公正取引委員会は、違反行為を発見しても、事業者に対する指導ができるだけで、命令を出す権限は持たない","課徴金は、不公正な取引方法の全ての類型に対して課される","公正取引委員会は、違反行為を排除するために必要な措置を命ずる排除措置命令を行うことができる。また、私的独占や不当な取引制限などについては、違反行為に係る売上額等を基礎に算定される課徴金の納付を命ずることができる","独占禁止法違反への対応は刑事罰のみであり、行政上の措置は定められていない"],"answer":2,"explanation":"公正取引委員会は、独占禁止法の執行機関であり、私的独占・不当な取引制限については排除措置命令（第7条）と課徴金納付命令（第7条の2）を行うことができる。課徴金の対象は、私的独占や不当な取引制限のほか、不公正な取引方法の一部の類型（優越的地位の濫用など）に限られており、全ての類型に課されるわけではない。このほか、悪質な違反については刑事告発の制度もあるが、対応は刑事罰のみではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-57","exam":"g","unit":"g-u9","keyword":"公正競争阻害性","type":"choice","syllabus_ref":"9.5","stem":"AI・アルゴリズムと独占禁止法の論点として、プラットフォーム事業者によるランキング操作についての説明として、適切なものはどれか。","choices":["検索や商品表示のランキングが重要な販路を提供している場合、その順位付けのアルゴリズムを操作して自社の商品・サービスを優遇したり、競争者の表示順位を引き下げたりする行為は、競争上の問題となり得るものとして論点とされている","ランキングの順位付けは事業者の自由な判断に全て委ねられており、どのような操作をしても独占禁止法上の問題になることはない","ランキング操作が問題になるのは、利用者に金銭的な損害が発生した場合に限られる","ランキングのアルゴリズムは企業秘密であるため、競争政策の観点から検討の対象になることはない"],"answer":0,"explanation":"公正取引委員会の研究会報告書「アルゴリズム／AIと競争政策」（2021年）は、単独行為の論点の一つとしてランキング操作を取り上げている。ランキングを用いるサービスが競争事業者にとって重要な販路である場合、順位付けの操作による自社優遇や競争者の排除は、態様によって私的独占や不公正な取引方法（取引妨害など）に当たり得る。利用者の金銭的損害の発生が要件ではなく、アルゴリズムの詳細が公表されていないこと自体も、問題の検討を妨げるものではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-58","exam":"g","unit":"g-u9","keyword":"公正競争阻害性","type":"choice","syllabus_ref":"9.5","stem":"AI を用いたパーソナライズド・プライシング（利用者の属性や行動データに基づいて価格を個別に変える手法）と独占禁止法の関係についての説明として、適切なものはどれか。","choices":["価格を個別に変えること自体が、直ちに独占禁止法違反になる","パーソナライズド・プライシングは、利用者に気付かれない形で行われるため、独占禁止法の規制の対象にはならない","価格の個別化そのものが直ちに違法となるわけではないが、例えば競争事業者の顧客にだけ低い価格を提示して競争者の事業活動を困難にさせるような場合には、不公正な取引方法（差別対価など）に当たり得る。また、どのようなデータに基づいて価格が決まるのかが利用者に分からないという不透明さも論点とされている","パーソナライズド・プライシングは、効率的な価格付けとして競争を促進するものとされており、独占禁止法上の論点にはなっていない"],"answer":2,"explanation":"公正取引委員会の研究会報告書「アルゴリズム／AIと競争政策」（2021年）は、パーソナライズド・プライシングを単独行為の論点として検討している。相手方により差別的な対価で供給し、他の事業者の事業活動を困難にさせるおそれがある行為は、不公正な取引方法の一類型である差別対価（第2条第9項第2号）に当たり得る。もっとも、価格の個別化の全てが問題になるわけではなく、行為の態様と競争への影響によって判断される。価格決定の根拠となるデータや仕組みの不透明さも、あわせて論点とされている。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-59","exam":"g","unit":"g-u9","keyword":"公正競争阻害性","type":"choice","syllabus_ref":"9.5","stem":"デジタル・プラットフォーム事業者と消費者との関係における、独占禁止法上の論点についての説明として、適切なものはどれか。","choices":["優越的地位の濫用が問題になるのは事業者同士の取引に限られ、消費者との関係では問題にならない","消費者がサービスの対価として個人情報等を提供している場合、その消費者は独占禁止法上の「取引の相手方」に当たり得る。プラットフォーム事業者が優越した地位を利用し、利用目的を十分に知らせることなく個人情報等を取得するなど、消費者に不当に不利益を与える行為は、優越的地位の濫用として問題になり得る","個人情報の取得方法の問題は個人情報保護法だけの問題であり、独占禁止法が関わることは一切ない","無料で提供されるサービスについては、金銭の支払いがないため、独占禁止法の適用対象にはならない"],"answer":1,"explanation":"公正取引委員会は「デジタル・プラットフォーム事業者と個人情報等を提供する消費者との取引における優越的地位の濫用に関する独占禁止法上の考え方」（2019年）を公表し、個人情報等を対価として提供する消費者も「取引の相手方」に含まれると整理している。優越した地位を利用して、正常な商慣習に照らして不当に消費者に不利益を与える行為は、消費者の自由かつ自主的な判断による取引を阻害し、事業者に競争上有利な地位をもたらすおそれがあるため、優越的地位の濫用（不公正な取引方法の一類型）として規制される。個人情報保護法とは別に、競争法の観点からも問題になり得る。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-60","exam":"g","unit":"g-u9","keyword":"独占禁止法","type":"choice","syllabus_ref":"9.5","stem":"AI を活用したオンラインモール運営企業 P 社の次の行為のうち、独占禁止法との関係で問題となり得るものの組み合わせとして、最も適切なものはどれか。（ア）検索結果の表示アルゴリズムを変更し、合理的な理由なく自社の直販商品だけを常に最上位に表示し、競争事業者の商品の表示順位を引き下げた。（イ）競合するモール運営事業者と、互いの出店手数料の料率を引き上げる時期と幅を申し合わせた。（ウ）収集した購買データを分析し、商品の需要予測の精度を高めて品揃えを改善した。","choices":["（ア）のみ","（イ）のみ","（ア）と（ウ）","（ア）と（イ）"],"answer":3,"explanation":"（ア）は、ランキングの操作による自社優遇であり、プラットフォームが重要な販路を提供している場合には、競争者の事業活動の排除につながる行為として、私的独占や不公正な取引方法に当たり得る論点である。（イ）は、競争関係にある事業者同士が共同して対価（手数料）を引き上げる申し合わせであり、不当な取引制限（カルテル）に当たり得る。（ウ）は、データを活用した通常の事業活動の改善であり、それ自体は独占禁止法上の問題にはならない。したがって、問題となり得るのは（ア）と（イ）の組み合わせである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目42「独占禁止法」"},{"id":"g9-61","exam":"g","unit":"g-u9","keyword":"AI・データの利用に関する契約ガイドライン","type":"choice","syllabus_ref":"9.6","stem":"「AI・データの利用に関する契約ガイドライン」（経済産業省）についての説明として、適切なものはどれか。","choices":["データの利用に関する契約を扱う「データ編」と、AI技術を利用するソフトウェアの開発・利用に関する契約を扱う「AI編」から構成され、契約で定めておくべき事項や主な論点、契約条項例、条項作成時の考慮要素を示した手引きである。契約の内容そのものを法的に義務付けるものではなく、当事者が協議して契約内容を定める際の参考として用いられる","AI開発の契約について国が定めた標準的な契約条件をまとめたもので、当事者は原則としてこのガイドラインの内容どおりの契約を締結しなければならない","AI開発契約に関する紛争が生じた場合に、裁判所が判断の基準として用いるために公表された資料である","データやAIに関する契約のひな形だけを集めた資料であり、論点や考慮要素についての説明は含まれていない"],"answer":0,"explanation":"このガイドラインは経済産業省が公表した手引きであり、データ編とAI編から構成される。契約で定めておくべき事項や主な論点、契約条項例、条項作成時の考慮要素を示すもので、契約の自由を制約したり、特定の契約内容を法的に義務付けたりするものではない。裁判所が紛争の判断基準として公表した資料でも、ひな形だけの寄せ集めでもない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-62","exam":"g","unit":"g-u9","keyword":"AI・データの利用に関する契約ガイドライン","type":"choice","syllabus_ref":"9.6","stem":"契約ガイドライン（AI編）が提唱する「探索的段階型」の開発方式における段階の順序と内容として、適切なものはどれか。","choices":["要件定義、基本設計、詳細設計、開発・テストという順に進み、各段階の成果物を検収して次へ進む方式であり、契約は開発全体を1本にまとめる","アセスメント、開発、PoC、追加学習の順に進み、PoCは開発が終わった後の最終確認として行う","アセスメント（一定量のデータを用いて、学習済みモデルを生成できる可能性を検証する）、PoC（学習用データセットを用いて、ユーザが希望する精度の学習済みモデルが生成できるかを検証する）、開発（学習済みモデルを開発する）、追加学習（納品された学習済みモデルについて追加の学習を行う）の順に、開発プロセスを独立した複数の段階に分けて、段階ごとに契約を結ぶ方式である","最初の契約で完成までの全工程を一括して定め、段階ごとの契約は結ばない方式である"],"answer":2,"explanation":"AI編は、学習済みモデルの性質や効果が契約締結の時点では不明瞭であり、学習用データセットに左右されるというAI技術の特性を踏まえ、開発プロセスをアセスメント、PoC、開発、追加学習の段階に分け、段階ごとに契約を結ぶ「探索的段階型」の開発方式を提唱している。全工程を1本の契約で一括して定める方式や、従来型のウォーターフォール開発の工程区分とは異なる考え方である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-63","exam":"g","unit":"g-u9","keyword":"準委任契約","type":"choice","syllabus_ref":"9.6","stem":"準委任契約についての説明として、適切なものはどれか。","choices":["受託者が仕事の完成を約束し、完成した仕事の結果に対して報酬が支払われる契約である","法律行為でない事務の処理を委託する契約であり、民法の委任の規定が準用される。受託者は、委任の本旨に従い、善良な管理者の注意をもって事務を処理する義務（善管注意義務）を負うが、仕事の完成そのものを約束するものではない","受託者は結果について無過失責任を負い、注意を尽くしても成果が得られなければ報酬を請求できない契約である","労働者を雇用する契約の一種であり、受託者は発注者の指揮命令の下で労働する義務を負う"],"answer":1,"explanation":"準委任は民法第656条により、法律行為でない事務の委託について委任の規定が準用される契約類型である。受託者の義務は善管注意義務（同法第644条）であり、事務を適切に処理することにあって、結果や仕事の完成を保証するものではない。仕事の完成を約束し、その結果に対して報酬が支払われるのは請負（同法第632条）である。また、指揮命令の下で労働する雇用契約とも異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-64","exam":"g","unit":"g-u9","keyword":"請負契約","type":"choice","syllabus_ref":"9.6","stem":"請負契約についての説明として、適切なものはどれか。","choices":["受託者は事務処理の過程に注意を払いさえすればよく、仕事が完成しなくても当然に全額の報酬を請求できる契約である","完成した仕事の目的物が契約の内容に適合しない場合でも、受託者が責任を負うことは一切ない","報酬は、作業に要した時間に応じて支払われることが法律で定められている","当事者の一方がある仕事を完成することを約し、相手方がその仕事の結果に対して報酬を支払うことを約することによって効力を生ずる契約である（民法第632条）。完成した仕事の目的物が種類、品質又は数量に関して契約の内容に適合しない場合、注文者は、履行の追完、報酬の減額、損害賠償、契約の解除などを求めることができる（契約不適合責任）"],"answer":3,"explanation":"請負は民法第632条の契約類型であり、仕事の「完成」と、その結果に対する報酬が中核である。報酬は原則として仕事の結果に対して支払われるもので、完成していない仕事について当然に全額を請求できるわけではない。目的物に契約不適合がある場合の注文者の権利（追完請求、報酬減額請求、損害賠償請求、解除）は同法第634条以下に定められており、受託者が一切責任を負わないということはない。報酬を作業時間に応じて支払う形は、準委任における履行割合型などに見られるもので、請負の法定の要件ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-65","exam":"g","unit":"g-u9","keyword":"準委任契約","type":"choice","syllabus_ref":"9.6","stem":"AI開発において、学習済みモデルの生成に関する契約に準委任型が親和的であるとされる理由として、適切なものはどれか。","choices":["学習済みモデルの性質や効果（精度など）は学習用データセットの内容に大きく左右され、契約を締結する時点では、どの程度のものが生成できるかが不明瞭なことが多い。このため、仕事の完成を約束させる請負型よりも、段階を分けながら事務の処理自体を委託する準委任型が適しているとされる","準委任型では受託者に善管注意義務が課されないため、ベンダ側のリスクが小さいからである","準委任型の契約を結べば、生成された学習済みモデルの精度が法律上保証されるからである","AI開発では、データを提供するユーザ側には一切の役割がなく、全てのリスクをベンダが負うべきであるとされているからである"],"answer":0,"explanation":"契約ガイドライン（AI編）は、学習済みモデルの性質・効果が学習用データセットに左右され、契約締結時には不明瞭な場合が多いというAI技術の特性を挙げ、学習済みモデルの生成については、どの段階においても準委任型の契約が親和的であると整理している。準委任型でも受託者は善管注意義務を負い、精度が法律で保証されるわけでもない。また、学習用データの提供や利用条件の設定など、ユーザ側にも果たすべき役割がある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-66","exam":"g","unit":"g-u9","keyword":"請負契約","type":"choice","syllabus_ref":"9.6","stem":"AI開発の契約における請負型の位置づけについての説明として、適切なものはどれか。","choices":["AI開発では、どの部分についても請負型の契約を締結することが法的に禁止されている","学習済みモデルの生成についても、ベンダは常に請負型で完成と精度を約束しなければならない","学習済みモデルの生成そのものについては、結果を事前に確定できないため準委任型が中心になるが、成果物の内容や検収の条件を明確に定めることができる部分（例えば、仕様が確定した既存システムとの連携部分の開発など）については、請負型の契約が選択されることもある。どちらの型を選ぶかは、対象となる作業の性質に応じて検討される","請負型を選んだ場合、受託者は注意義務を一切負わなくなる"],"answer":2,"explanation":"請負型がAI開発で一律に禁止されているわけではない。学習済みモデルの生成のように結果を事前に確定しにくい作業には準委任型が親和的であるが、成果物と検収条件を明確に定義できる作業については、請負型も選択肢になる。請負型を選んでも受託者が注意義務を全く負わなくなるわけではなく、契約不適合責任をはじめとする責任を負う。なお、どちらの型が適するかは作業の性質や契約内容の定め方による実務上の判断であり、個別の案件によって異なり得る。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-67","exam":"g","unit":"g-u9","keyword":"PoC","type":"choice","syllabus_ref":"9.6","stem":"AI開発委託における PoC（概念実証）の段階と、その契約についての説明として、適切なものはどれか。","choices":["PoCは本開発の後に行う最終検査の段階であり、納品された学習済みモデルの検収だけを行う","PoCの契約では、ベンダが希望精度の達成を保証する請負型が標準とされている","PoCでは、ユーザのデータは一切使わず、公開されているデータだけで検証を行うことが前提である","PoCは、学習用データセットを用いて、ユーザが希望する精度の学習済みモデルが生成できるかどうかを検証する段階である。契約ガイドライン（AI編）は、この段階のモデル契約として「導入検証契約書」を用意しており、その性質は準委任型とされ、検証の結果をまとめたレポート等が成果物となる"],"answer":3,"explanation":"PoCは本開発に先立つ検証の段階であり、ユーザの学習用データセットを用いて、希望する精度の学習済みモデルが生成できるかを確かめる。検証の成果は事前に予測しにくいため、モデル契約である導入検証契約書は準委任型を想定しており、ベンダが精度の達成を保証する請負型ではない。成果物は検証結果をまとめたレポート等である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-68","exam":"g","unit":"g-u9","keyword":"NDA","type":"choice","syllabus_ref":"9.6","stem":"秘密保持契約（NDA）に関する基本的事項として、適切なものはどれか。","choices":["NDAを締結すれば、相手方に開示した情報は全て自動的に不正競争防止法上の営業秘密として保護される","情報を開示する場面に先立って締結し、秘密情報の範囲（定義）、開示の目的、目的外利用や第三者への開示の禁止、契約終了時の情報の返還・消去、秘密保持義務が存続する期間などを取り決めるのが基本である","NDAは口頭で合意すれば十分であり、書面で取り決める必要はないとされている","NDAを締結した後は、開示した情報を相手方が自由に利用できるようになる"],"answer":1,"explanation":"NDAは、秘密情報の定義や開示目的の限定、目的外利用・第三者への開示の禁止、情報の返還・消去、義務の存続期間などを定める契約であり、情報の開示に先立って締結される。NDAを締結しただけで、開示した情報が当然に不正競争防止法上の営業秘密の要件（秘密管理性、有用性、非公知性）を満たすわけではなく、実際の秘密管理の態様も関係する。また、NDAの締結によって相手方の利用が自由になるものでもない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-69","exam":"g","unit":"g-u9","keyword":"NDA","type":"choice","syllabus_ref":"9.6","stem":"AI開発のアセスメント段階における秘密保持契約（NDA）の位置づけとして、適切なものはどれか。","choices":["アセスメント段階では、まだデータの受け渡しが行われないため、NDAは不要である","アセスメント段階のNDAでは、ベンダの技術情報だけが保護の対象となり、ユーザから提供されるデータは対象にならない","アセスメント段階では、学習済みモデルを生成できる可能性があるかを検証するために、ユーザから一定量のデータがベンダに提供される。そのため契約ガイドライン（AI編）は、この段階に対応するモデル契約として秘密保持契約書を用意しており、データの提供に先立って秘密保持の取り決めを結ぶことが想定されている","NDAを結んだ場合、ユーザは保有する全てのデータをベンダに提供する義務を負う"],"answer":2,"explanation":"アセスメント段階は、ユーザから提供される一定量のデータを用いて、学習済みモデルの生成可能性を事前に検証する段階であり、データの受け渡し自体がこの段階の中核である。ガイドラインはこの段階のモデル契約として秘密保持契約書を示している。提供されるデータの範囲は契約で定めるものであり、全てのデータの提供義務が生じるわけではない。保護の対象は、ユーザのデータを含む当事者双方の秘密情報である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-70","exam":"g","unit":"g-u9","keyword":"精度保証","type":"choice","syllabus_ref":"9.6","stem":"AI開発委託契約における「精度保証」の扱いについての説明として、適切なものはどれか。","choices":["学習済みモデルの精度は、学習用データセットの質や量など、ベンダだけでは制御できない要素に大きく左右されるため、ベンダが一定の精度を保証することは一般に困難である。そのため契約では、精度を保証するかどうか自体を含め、精度の評価方法や評価に用いるデータ、目標に届かなかった場合の扱い（追加学習の実施や契約の終了条件など）をあらかじめ定めておくことが重要とされる","ベンダは、納品する学習済みモデルについて、ユーザが希望する精度を保証しなければならないと法律で定められている","精度は契約で保証するのが通常であり、保証された精度に届かなければ、学習用データの内容にかかわらず常にベンダの契約不適合責任となる","精度に関する取り決めは、運用が始まってから問題が生じた時点で定めればよく、契約の締結時に定めておく必要はない"],"answer":0,"explanation":"AIの精度は学習用データセットに依存する度合いが大きく、ベンダが結果を確定的に保証することには限界がある。精度保証の有無が法律で一律に定められているわけではなく、契約でどう取り決めるかの問題である。評価方法や評価用データ、目標未達の場合の扱いを契約の締結時に定めておくことが、後のトラブルの防止につながる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-71","exam":"g","unit":"g-u9","keyword":"保守契約","type":"choice","syllabus_ref":"9.6","stem":"AI開発委託における運用・追加学習の段階と保守契約についての説明として、適切なものはどれか。","choices":["学習済みモデルは一度納品されれば精度が変わることはないため、運用段階での保守や追加学習の取り決めは不要である","運用が始まった後は、入力されるデータの傾向の変化などによってモデルの精度が低下していくことがあるため、精度の監視や、追加の学習用データセットを用いた追加学習などを継続的に行う必要が生じる。契約ガイドライン（AI編）は追加学習の段階について専用のモデル契約を用意しておらず、保守運用に関する契約や学習支援の契約、別途の開発契約などで対応することが想定されている","追加学習は当初の開発契約に当然に含まれるため、保守に関する契約を別途結ぶことはできない","保守契約では、ベンダが将来にわたってモデルの精度を保証することが標準とされている"],"answer":1,"explanation":"AIのモデルは、運用環境や入力データの傾向の変化により精度が低下していくことがあるため、精度の監視と追加学習を含む継続的な保守が重要になる。ガイドラインがモデル契約を用意しているのはアセスメント、PoC、開発の3段階であり、追加学習の段階は保守運用契約や学習支援契約、別途の開発契約などで対応する整理である。保守契約で精度の保証が標準とされているわけでもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-72","exam":"g","unit":"g-u9","keyword":"AI開発委託契約","type":"choice","syllabus_ref":"9.6","stem":"製造業の X 社が、ベンダの Y 社に対し、X 社の生産データを用いた不良検知用の学習済みモデルの開発を委託する。この開発で生成される学習済みモデルとその利用をめぐる契約上の取り決めとして、契約ガイドライン（AI編）の考え方に沿ったものはどれか。","choices":["学習済みモデルの権利は、対価を支払った X 社に当然に全て帰属するので、契約で取り決める必要はない","Y 社は、X 社の生産データから生成した学習済みモデルを、X 社に断りなく他の顧客の案件に自由に転用できるのが原則である","権利の帰属さえ決めておけば、利用の範囲や転用の可否などの利用条件を別に定める必要はない","学習済みモデルについて著作権などの権利が成立するか自体が問題となり得るため、権利の帰属だけでなく、X 社がどの範囲でモデルを利用できるか、Y 社がモデルや開発で得たノウハウを他の案件に再利用してよいかなど、利用条件を具体的に取り決めておくことが重要である"],"answer":3,"explanation":"学習済みモデル（学習によって得られたパラメータ等）については、著作権の成立自体を含め、権利関係が明確でない部分がある。契約ガイドライン（AI編）は、権利の帰属を決めるだけでなく、利用の範囲や再利用の可否といった利用条件をきめ細かく設定することで、ユーザとベンダの利益を調整する考え方を示している。対価の支払いだけで権利関係が自動的に確定するわけではなく、他案件への転用の可否も契約の取り決めによる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目43「AI開発委託契約」"},{"id":"g9-73","exam":"g","unit":"g-u9","keyword":"SaaS","type":"choice","syllabus_ref":"9.7","stem":"AIサービスの提供形態としての「SaaS」についての説明として、適切なものはどれか。","choices":["学習済みモデルそのものを買い取り、自社のサーバに設置して運用する提供形態である","ソフトウェアを自社に導入・納品してもらうのではなく、提供者がクラウド上で運用するソフトウェアの機能を、利用者がインターネット経由で利用する提供形態であり、利用者はソフトウェア自体を所有しない","ソフトウェアのソースコードが公開され、誰でも無償で改変や再配布ができる提供形態である","AIの開発を外部の事業者に委託し、成果物の納品を受ける契約形態である"],"answer":1,"explanation":"SaaS（Software as a Service）は、提供者がクラウド上で運用するソフトウェアの機能を、利用者がインターネット経由で利用する提供形態である。利用者はソフトウェアや学習済みモデルを買い取って自社で運用するのではなく、サービスとして機能を利用する。ソースコードが公開される形態はオープンソースソフトウェアの話であり、開発を委託して納品を受けるのは開発委託契約の話である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-74","exam":"g","unit":"g-u9","keyword":"SaaS","type":"choice","syllabus_ref":"9.7","stem":"SaaS型のAIサービスに共通する特徴として、適切なものはどれか。","choices":["利用者ごとに専用の学習済みモデルが個別に開発され、納品される","利用者は学習済みモデルの内部構造を自由に改変して使うことができる","多数の利用者が同一のサービス基盤を共用することが一般的であり、機能やモデルは提供者が一括して管理・更新するため、利用者ごとに個別の仕様へ作り替えることは難しい","サービスは一度提供が始まれば内容が固定され、提供者が機能やモデルを更新することはない"],"answer":2,"explanation":"SaaS型では、多数の利用者が同一のサービス基盤を共用し（マルチテナント）、機能や学習済みモデルは提供者が一括して管理・更新する。そのため、利用者ごとに個別の仕様へ作り替えることは難しく、サービスの内容も提供者の更新によって変わり得る。専用モデルを開発して納品する形態や、利用者がモデル内部を改変できる形態は、SaaS型の一般的な姿ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-75","exam":"g","unit":"g-u9","keyword":"SaaS","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスにおける提供者と利用者の役割分担として、適切なものはどれか。","choices":["システムの運用・保守や学習済みモデルの管理は提供者が担い、利用者は、入力するデータに適法な利用権限があることや、出力結果を業務に利用する際の確認・判断について責任を負うのが一般的である","サーバの運用やモデルの保守は全て利用者が担い、提供者はサービスの提供開始後は何もしない","出力結果の正確性は全て提供者が保証するため、利用者は内容を確認せずにそのまま業務に利用できる","利用者が入力したデータに第三者の権利を侵害する内容があっても、その責任は全て提供者が負う"],"answer":0,"explanation":"SaaS型では、サービス基盤の運用・保守やモデルの管理は提供者が担う一方、利用者は、入力するデータを提供する正当な権限があることや、出力結果を業務に使う際の確認・判断について責任を負うのが一般的である。出力結果の正確性が無条件に保証されるわけではなく、入力データの適法性まで提供者が引き受けるわけでもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-76","exam":"g","unit":"g-u9","keyword":"利用規約","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスの契約が利用規約への同意によって成立することについての説明として、適切なものはどれか。","choices":["利用規約は提供者の社内規則にすぎないため、利用者との契約の内容にはならない","利用者は利用規約の各条項について個別に交渉し、合意した条項だけが契約の内容になる","利用規約に同意しても、法律上の契約は別途書面の契約書を交わさない限り成立しない","多数の利用者と画一的な内容で取引するため、契約条件は提供者があらかじめ定めた利用規約に同意する形で定まるのが一般的であり、民法の定型約款の規定では、あらかじめ規約を契約の内容とする旨が表示されていた場合などには、個別の条項についても合意をしたものとみなされる"],"answer":3,"explanation":"SaaS型のサービスは不特定多数の利用者と画一的な内容で取引するため、個別交渉ではなく、提供者が定めた利用規約（定型約款）への同意によって契約が成立するのが一般的である。民法第548条の2は、定型取引の合意をした者は、定型約款を契約の内容とする旨の合意をした場合や、準備者があらかじめその旨を表示していた場合には、個別の条項についても合意をしたものとみなすと定めている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-77","exam":"g","unit":"g-u9","keyword":"利用規約","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスの利用規約の変更や条項の効力についての説明として、適切なものはどれか。","choices":["提供者はいつでも自由に利用規約を変更でき、利用者に知らせる必要もない","利用規約の変更には常に全利用者の個別の合意が必要であり、周知だけでは一切変更できない","提供者が規約を変更する場合、民法の定型約款の規定では、変更が相手方の一般の利益に適合するとき、または変更に係る事情に照らして合理的なものであるときなどに、変更内容と効力発生時期を周知することで、個別の合意をしなくても契約の内容を変更できるとされる。一方、信義則に反して利用者の利益を一方的に害すると認められる条項は、合意をしなかったものとみなされる","利用規約に書かれた条項は、内容がどれほど利用者に不利なものであっても、全て有効である"],"answer":2,"explanation":"民法第548条の4は、定型約款の変更が相手方の一般の利益に適合するとき、または変更の必要性や変更後の内容の相当性などに照らして合理的なものであるときには、変更内容と効力発生時期を周知することで、個別の合意なく契約内容を変更できると定める。一方で第548条の2第2項は、信義則に反して相手方の利益を一方的に害する条項は合意をしなかったものとみなすとしており、提供者が無制約に変更できるわけでも、どんな条項でも有効になるわけでもない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-78","exam":"g","unit":"g-u9","keyword":"データ利用権","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスにおける「データ利用権」の取り決めについての説明として、適切なものはどれか。","choices":["利用者が入力・提供したデータを、提供者がサービスの提供のほか、モデルの追加学習やサービス改善などに利用できるかどうかは、利用規約や契約で定められる事項であり、利用者は自社のデータがどの範囲で利用されるのかを事前に確認する必要がある","入力したデータの利用権は、法律によって全て利用者に帰属すると定められているため、利用規約で確認する必要はない","入力したデータは、提供者が自由に第三者へ提供したり販売したりできるのが原則である","データは民法上の所有権の対象であるため、所有権の移転として処理すれば利用範囲の取り決めは不要である"],"answer":0,"explanation":"データは無体物であり、民法上の所有権の対象にはならないため、データの扱いは「誰のものか」ではなく「誰がどの範囲で利用できるか」という利用権限の取り決めで定めることになる。SaaS型サービスでは、利用者が入力したデータを提供者が追加学習やサービス改善に利用できるかどうかが利用規約や契約で定められるため、利用者は事前にその範囲を確認する必要がある。経済産業省の契約ガイドライン（AI編）第5（AI技術の利用契約）でも、入力データの取扱いや利用条件について、サービス利用契約で取り決めることが望ましいとされている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-79","exam":"g","unit":"g-u9","keyword":"データ利用権","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスに利用者が提供したデータの管理や、契約終了時の扱いについての説明として、適切なものはどれか。","choices":["提供したデータは利用者の手元にも残るのが当然であるため、契約終了時の扱いを定める必要はない","提供者は、契約が終了した後も、利用者のデータを無期限に保管し続けなければならない","提供したデータの管理責任は全て利用者にあり、提供者はデータの保管や管理に一切関与しない","利用者が提供したデータは提供者のサーバに保存・蓄積されるため、第三者への開示の制限といった管理の方法や、契約終了時に削除されるのか返却されるのかといった扱いを、利用規約や契約で定めておくことが重要であり、データのバックアップなどの保全は利用者自身の責任で行うべき場合もある"],"answer":3,"explanation":"SaaS型では、利用者が提供したデータは提供者のサーバに保存・蓄積されるため、契約終了時にそのデータがどうなるかは利用者の業務に直結する。経済産業省の契約ガイドライン（AI編）のモデル契約（導入検証契約書）第13条（対象データの管理）でも、対象データの保存・管理、書面による承諾のない第三者への開示の制限、契約終了時の破棄・返還・削除といった扱いが条項として示されており、利用規約や契約で事前に定めておくことが重要である。なお、データのバックアップなどの保全は、利用者自身の責任で行うべき場合もある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-80","exam":"g","unit":"g-u9","keyword":"精度保証","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスにおける「精度保証」の扱いについての説明として、適切なものはどれか。","choices":["SaaSでは提供者がモデルを管理しているため、サービスの精度は常に提供者によって保証される","サービスの精度は、利用者が入力するデータや利用環境によっても変動し、提供者が一定の精度を保証することは一般に難しいため、利用規約では精度を保証しない旨が定められることが多い。利用者は、精度が自社の業務要件を満たすかどうかを、利用開始前に自ら確認することが求められる","精度が目標に届かなかった場合、利用者は常に利用料の全額の返金を受けられる","精度保証の内容は法律で統一的に定められているため、サービスごとに規約の内容が異なることはない"],"answer":1,"explanation":"AIサービスの精度は、利用者が入力するデータや利用環境によっても左右されるため、提供者が一定の精度を保証することは一般に難しく、SaaS型サービスの利用規約では精度を保証しない旨が定められることが多い。開発委託の場面で評価方法や目標未達時の扱いを個別に取り決めるのとは異なり、SaaS型では画一的な規約の下で提供されるため、利用者側が利用開始前に自社の要件を満たすかを確認する姿勢が求められる。精度保証の内容が法律で統一されているわけでも、全額返金が常に認められるわけでもない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-81","exam":"g","unit":"g-u9","keyword":"精度保証","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスでは、提供者によるモデルの更新や、利用されるデータの傾向の変化によって、利用開始後の精度が変動することがある。このような提供開始後の精度の変動への備えとして、利用規約や契約で定めておくことが望ましい事項はどれか。","choices":["モデルの更新や仕様の変更を行う場合の利用者への通知の方法、精度の監視や改善の取り組みの内容、精度の低下が続く場合の対応など、提供開始後の運用に関する取り決め","利用開始時点の精度を将来にわたって固定し、提供者が以後モデルを一切更新しないことの保証","精度が変動した場合に生じる損害の全てを、提供者が無条件に補償することの約束","利用者が学習済みモデルの内部パラメータを直接調整できる権利の設定"],"answer":0,"explanation":"SaaS型ではモデルの管理・更新が提供者側で行われるため、利用開始後の精度は、提供者の更新やデータの傾向の変化によって変動し得る。精度そのものを固定したり損害の全補償を約束したりすることは現実的ではなく、更新や仕様変更の通知、精度の監視・改善の取り組み、精度低下時の対応といった、提供開始後の運用に関する取り決めをあらかじめ定めておくことが望ましい。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-82","exam":"g","unit":"g-u9","keyword":"AIサービス提供契約","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスの契約における保守に関する条項の基本事項として、適切なものはどれか。","choices":["保守は利用者が自ら行うものであり、提供者は障害が発生しても対応しない","障害発生時の対応や復旧の手順、計画的なメンテナンスに伴うサービス停止の予告、問い合わせへのサポート体制など、サービスを継続的に提供するための運用・保守の内容が、利用規約やサービス水準に関する取り決めで定められる","SaaS型では保守という概念自体が不要であり、障害や不具合への対応は取り決めの対象にならない","保守の内容は利用者ごとに個別交渉で決めることが原則であり、共通の取り決めが置かれることはない"],"answer":1,"explanation":"SaaS型ではサービス基盤の運用・保守は提供者が担うため、障害時の対応・復旧の手順、メンテナンスに伴う停止の予告、サポート体制といった保守の内容が、利用規約やサービス水準に関する取り決めで定められる。多数の利用者が同一基盤を使うSaaS型では、これらが利用者ごとの個別交渉ではなく共通の取り決めとして置かれる点が、開発委託における保守契約との違いである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-83","exam":"g","unit":"g-u9","keyword":"AIサービス提供契約","type":"choice","syllabus_ref":"9.7","stem":"SaaS型AIサービスの契約における知的財産に関する条項の基本事項として、適切なものはどれか。","choices":["利用料を支払えば、学習済みモデルに関する知的財産権は利用者に移転する","利用者は、サービスを改変したり、第三者に再提供したりすることが自由に認められる","知的財産に関する条項はSaaSの契約には含まれず、問題が生じた場合にのみ協議して決める","サービスや学習済みモデルに関する権利は提供者に帰属し、利用者には契約の範囲内でサービスを利用する権利（利用許諾）が与えられるのが一般的であり、利用者が入力したデータや生成物の扱いも含め、権利関係と利用条件を利用規約で確認する必要がある"],"answer":3,"explanation":"SaaS型では、サービスや学習済みモデルは提供者の資産であり、利用者は利用料の支払いによって権利の移転を受けるのではなく、契約の範囲内でサービスを利用する許諾を受けるのが一般的である。自社の開発成果物の帰属や利用条件を取り決める開発委託とは異なり、提供型では、入力データや生成物の扱いを含めた権利関係と利用条件が利用規約でどう定められているかを確認することが基本になる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g9-84","exam":"g","unit":"g-u9","keyword":"AIサービス提供契約","type":"choice","syllabus_ref":"9.7","stem":"ある企業が、顧客対応の自動化のためにSaaS型のAIチャットサービスを導入しようとしている。この導入にあたって、契約・利用規約の観点から確認すべき事項として、最も適切なものはどれか。","choices":["SaaSは個別交渉によって契約内容を自由に決められるため、利用規約の内容を確認する必要はない","利用料を支払えば、入力したデータや生成物に関する権利は全て自社に移るため、権利関係の確認は不要である","自社の顧客データを入力することになるため、そのデータをサービス側が追加学習やサービス改善に利用できる範囲、精度が保証されるのかどうか、障害時の対応や利用規約変更の扱いなど、利用規約の内容を事前に確認する","精度や障害対応の内容は法律で統一的に定められているため、サービスごとに確認する必要はない"],"answer":2,"explanation":"SaaS型のAIサービスは、提供者が定めた利用規約への同意で契約が成立し、個別交渉で内容を決めることは通常できない。そのため導入時には、入力する顧客データをサービス側が追加学習やサービス改善に利用できる範囲（データ利用権）、精度が保証されるのかどうか、障害時の対応、規約変更の扱いといった、業務に影響する条項を利用規約で事前に確認することが重要である。権利が利用料の支払いで自動的に全て移ることも、精度や障害対応が法律で統一されていることもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目44「AIサービス提供契約」"},{"id":"g10-01","exam":"g","unit":"g-u10","keyword":"AI倫理","type":"choice","syllabus_ref":"10.1","stem":"「AI倫理」についての説明として、適切なものはどれか。","choices":["AIの開発・提供・利用が、人権や人間の尊厳、公平性、安全性といった倫理的な価値に反しないよう、どのような配慮や原則が必要かを検討する考え方であり、国内外のガイドラインで共通の基盤となっている","AIの処理速度や精度といった技術的な性能を最大化するための設計手法のことである","AIの開発に必要なプログラミング言語や数学の知識体系のことである","AIに関する法律に違反した場合の罰則を定めた法制度のことである"],"answer":0,"explanation":"AI倫理は、AIが社会に及ぼす影響について、人権・人間の尊厳の尊重、公平性、プライバシー、安全性、透明性といった倫理的な観点から望ましい在り方を検討するものである。技術的な性能の追求そのものや、法制度そのものとは区別され、法律（ハードロー）だけではカバーしきれない価値判断の基盤として、ガイドライン等の形で具体化されてきた。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-02","exam":"g","unit":"g-u10","keyword":"国内外のガイドライン","type":"choice","syllabus_ref":"10.1","stem":"日本の「人間中心のAI社会原則」についての説明として、適切なものはどれか。","choices":["AIの開発者に課される技術基準を定めた法律であり、違反した場合には罰則が適用される","2019年に日本政府の統合イノベーション戦略推進会議が決定した原則であり、「人間中心の原則」をはじめ、教育・リテラシー、プライバシー確保、セキュリティ確保、公正競争確保、公平性・説明責任及び透明性、イノベーションの7つの社会原則を掲げている","EUが制定したAIに関する包括的な法律であり、日本にも直接適用される","民間企業が共同で策定した業界の自主基準であり、政府は関与していない"],"answer":1,"explanation":"人間中心のAI社会原則は、2019年3月に統合イノベーション戦略推進会議が決定した日本の基本原則であり、「人間の尊厳が尊重される社会」などの基本理念の下、7つのAI社会原則を示している。法律ではなく、法的拘束力を持つものではない。EUのAI法とは別の文書であり、政府が決定した点も押さえておきたい。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-03","exam":"g","unit":"g-u10","keyword":"国内外のガイドライン","type":"choice","syllabus_ref":"10.1","stem":"OECDのAI原則についての説明として、適切なものはどれか。","choices":["EU加盟国だけを対象とする法律であり、域内で直接の効力を持つ","AI製品の安全規格を定めた国際標準であり、認証を取得しなければAIを販売できない","2019年に採択された、AIに関する初の政府間標準とされるもので、包摂的な成長、人間中心の価値と公平性、透明性と説明可能性、頑健性・セキュリティ・安全性、説明責任といった、価値に基づく5つの原則を示している。理事会勧告であり、法的拘束力はない","日本のAI事業者ガイドラインを英訳したものである"],"answer":2,"explanation":"OECDのAI原則は、2019年5月にOECD理事会勧告として採択され、AIに関する初の政府間標準と位置づけられる。信頼できるAIのための価値に基づく5つの原則と、各国政府への5つの勧告から成り、G20のAI原則の基礎にもなった。勧告であるため法的拘束力はない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-04","exam":"g","unit":"g-u10","keyword":"国内外のガイドライン","type":"choice","syllabus_ref":"10.1","stem":"日本の「AI事業者ガイドライン」についての説明として、適切なものはどれか。","choices":["AIの開発を国に届け出る手続を定めた法律であり、2024年に施行された","AIに関する唯一の国際条約であり、日本も批准している","個人情報の取扱いだけを対象とする、個人情報保護委員会のガイドラインである","2024年に総務省と経済産業省が公表した指針であり、それまでのAI開発・利活用・ガバナンスに関する3つのガイドラインを統合したものである。AI開発者・AI提供者・AI利用者を対象とし、人間中心や公平性、透明性などの共通の指針を示す、法的拘束力のないソフトローである"],"answer":3,"explanation":"AI事業者ガイドラインは、2024年4月に第1.0版が公表され、「国際的な議論のためのAI開発ガイドライン案」「AI利活用ガイドライン」「AI原則実践のためのガバナンス・ガイドライン」を統合・見直ししたものである。AI開発者・AI提供者・AI利用者の3つの主体を対象に共通の指針を示し、ガイドライン自らが非拘束的なソフトローと位置づけている。法律でも条約でもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-05","exam":"g","unit":"g-u10","keyword":"価値原則","type":"choice","syllabus_ref":"10.1","stem":"国内外のAIに関するガイドラインを通じて共通に議論されている事項として、適切なものはどれか。","choices":["人間中心（人権・人間の尊厳の尊重）を基盤に、公平性、プライバシー保護、安全性・セキュリティの確保、透明性・説明可能性、説明責任（アカウンタビリティ）といった価値が、国や組織を問わず共通して重視されている","AIの計算速度や省電力性能といった技術的性能の目標値が、国際的に統一されている","AIの開発言語やフレームワークを国際的に統一することが求められている","各国のガイドラインは内容が互いに無関係であり、共通する価値や原則は存在しない"],"answer":0,"explanation":"人間中心のAI社会原則、OECDのAI原則、AI事業者ガイドラインなどでは、人間中心を基盤として、公平性、プライバシー保護、安全性・セキュリティの確保、透明性・説明可能性、説明責任といった価値原則が共通して掲げられている。AI事業者ガイドラインの「共通の指針」10項目（人間中心、安全性、公平性、プライバシー保護、セキュリティ確保、透明性、アカウンタビリティ、教育・リテラシー、公正競争確保、イノベーション）にも、この共通性が表れている。技術仕様の統一を目的とするものではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-06","exam":"g","unit":"g-u10","keyword":"ハードロー","type":"choice","syllabus_ref":"10.1","stem":"「ハードロー」についての説明として、適切なものはどれか。","choices":["法的拘束力のない指針やガイドラインの総称であり、関係者の自主的な取組に委ねられる規範である","法律のように法的拘束力のある規範を指し、違反した場合には罰則や行政処分などの制裁があり得る。AIの分野では、EUのAI法が、AIを包括的に規制する世界初の法律として代表例に挙げられる","業界団体が定める自主的な行動規範のことである","国際機関が採択する勧告や原則のことである"],"answer":1,"explanation":"ハードローは、法律など法的拘束力を持つ規範であり、義務違反には制裁が伴い得る。EUのAI法（2024年発効）はAIを包括的に扱う世界初の法律であり、ハードローの代表例である。ガイドラインや勧告のように法的拘束力のない規範はソフトローと呼ばれ、他の選択肢はいずれもソフトロー側の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-07","exam":"g","unit":"g-u10","keyword":"ソフトロー","type":"choice","syllabus_ref":"10.1","stem":"「ソフトロー」についての説明として、適切なものはどれか。","choices":["法律と同等の拘束力を持ち、違反には刑事罰が科される規範である","裁判所の判例だけを指す言葉であり、行政機関が示す指針は含まれない","法的な拘束力はないものの、ガイドラインや原則の形で関係者の行動の指針となる規範を指す。AIの分野では、日本のAI事業者ガイドラインやOECDのAI原則、人間中心のAI社会原則などがこれに当たり、関係者の自主的な取組を通じて目的の達成を図る","民間企業同士の契約のことであり、公的な文書は含まれない"],"answer":2,"explanation":"ソフトローは、法的拘束力はないが、事実上、関係者の行動を方向づける規範である。AI分野の主要なガイドライン・原則の多くはソフトローであり、技術の進展が速い分野で、法律によらず柔軟に対応する手段として用いられてきた。違反への刑事罰を伴うものではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-08","exam":"g","unit":"g-u10","keyword":"ソフトロー","type":"choice","syllabus_ref":"10.1","stem":"AIのガバナンスにおけるソフトローとハードローの比較として、適切なものはどれか。","choices":["ソフトローは、技術の変化への対応が遅い代わりに、違反への制裁によって実効性が確実に担保される点が長所である","ハードローは、制定後も内容を即座に変更できるため、技術の急速な進展に最も柔軟に対応できる","ソフトローとハードローに実質的な違いはなく、どちらを用いても効果は同じである","ソフトローは、ガイドラインの改訂等によって技術や社会の変化に柔軟・迅速に対応でき、多様な関係者の合意を形成しやすい反面、法的拘束力がないため実効性は関係者の自主的な取組に依存する。ハードローは、義務と制裁によって実効性を担保できる反面、制定や改正に時間を要し、技術の変化に対して硬直的になりやすい"],"answer":3,"explanation":"ソフトローの長所は柔軟性と迅速性、合意形成のしやすさにあり、短所は拘束力のなさに由来する実効性の限界である。ハードローはその逆で、実効性や予見可能性が長所、硬直性や制定・改正の遅さが短所とされる。両者は対立するものではなく、分野やリスクに応じて組み合わせて用いられる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-09","exam":"g","unit":"g-u10","keyword":"リスクベースアプローチ","type":"choice","syllabus_ref":"10.1","stem":"AIの規制やガバナンスにおける「リスクベースアプローチ」についての説明として、適切なものはどれか。","choices":["AIの利用がもたらすリスクの大きさや性質に応じて、規制や対策の強さを変える考え方であり、リスクの高い用途には厳格な要件を課し、リスクの低い用途には過度な負担を課さないことで、安全の確保とイノベーションの促進の両立を図る","全てのAIに一律に最も厳しい規制を適用し、リスクの大小による区別をしない考え方である","AIのリスクは予測できないため、規制や対策は一切行わないという考え方である","リスクの評価を民間の自主性に全面的に委ね、公的なルールを設けない考え方である"],"answer":0,"explanation":"リスクベースアプローチは、リスクの程度に応じた比例的な対応を取る考え方である。全てのAIに一律の規制をかけるのではなく、高リスクの用途に規制や対策を集中させることで、安全性の確保と、過剰な規制によるイノベーションの阻害の防止を両立させる。EUのAI法は、この考え方を法律の枠組みで採用した代表例である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-10","exam":"g","unit":"g-u10","keyword":"リスクベースアプローチ","type":"choice","syllabus_ref":"10.1","stem":"EUのAI法における、リスクに応じたAIシステムの分類の説明として、適切なものはどれか。","choices":["全てのAIシステムに同一の要件が課され、用途による区別はない","AIシステムはリスクの程度に応じて分類され、人の安全や基本権に受容できないリスクをもたらす用途は禁止され、雇用や教育などの分野で使われる高リスクのAIには厳格な要件が課され、チャットボットのような限定的なリスクのAIには透明性の義務が課され、最小リスクのAIは原則として自由に利用できる","リスクの高いAIほど規制が緩くなり、イノベーションが優先される","分類は事業者の自己申告だけで決まり、用途は考慮されない"],"answer":1,"explanation":"EUのAI法はリスクベースアプローチを採用し、AIシステムを「受容できないリスク」「高リスク」「限定的リスク」「最小リスク」に分類する。受容できないリスクの用途（例：公的機関による社会的スコアリング）は禁止され、高リスクのAIにはリスク管理や人間の監督などの厳格な要件が、限定的なリスクのAIにはAIとやり取りしていることの通知などの透明性義務が課され、最小リスクのAIには特段の義務は課されない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-11","exam":"g","unit":"g-u10","keyword":"リスクベースアプローチ","type":"choice","syllabus_ref":"10.1","stem":"リスクベースアプローチのメリットと留意点についての説明として、適切なものはどれか。","choices":["リスクの程度を問わず一律の対応になるため、評価の手間がかからない点が最大のメリットである","リスク評価さえ行えば、その後の運用でリスクを見直す必要は一切ない","リスクの高い用途に規制や対策を集中させることで、過剰な規制によるイノベーションの阻害を避けられるメリットがある一方、どの用途をどのリスク水準に位置づけるかの評価や線引き自体が難しく、技術や利用の変化に応じて評価を見直し続ける必要があるという留意点がある","リスクベースアプローチを採用すると、法律による規制は一切不要になる"],"answer":2,"explanation":"リスクベースアプローチは、比例的な対応によって安全性とイノベーションの両立を図る考え方だが、その前提となるリスク評価・分類の妥当性が成否を左右する。AIの能力や利用形態は変化するため、一度分類して終わりではなく、継続的な見直しが必要とされる。また、リスクベースであることはハードローの不存在を意味せず、EUのAI法のように法律の枠組みの中で採用されることもある。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-12","exam":"g","unit":"g-u10","keyword":"AIガバナンス","type":"choice","syllabus_ref":"10.1","stem":"ある企業が、AIを用いたサービスを開発し、顧客に提供しようとしている。国内外のガイドラインに沿ったAIガバナンスの取組として、最も適切なものはどれか。","choices":["ガイドラインには法的拘束力がないため、ガイドラインの内容は一切考慮せず、自社の判断だけで開発・提供を進める","リスクの大小にかかわらず、全てのAIに法律で定められた同一の手続を適用する","一度社内ルールを定めたら、技術や社会の変化があっても見直す必要はない","AI事業者ガイドラインなどの指針を参照し、人間中心、公平性、プライバシー保護、透明性、説明責任といった共通の指針に沿って、自社のAIがもたらすリスクを受容可能な水準で管理しつつ便益を最大化できるよう、組織としての仕組みを設計し、運用していく"],"answer":3,"explanation":"AIガバナンスは、AI事業者ガイドラインにおいて「AIの利活用によって生じるリスクをステークホルダーにとって受容可能な水準で管理しつつ、そこからもたらされる正のインパクト（便益）を最大化することを目的とする、ステークホルダーによる技術的、組織的、及び社会的システムの設計並びに運用」と定義されている。ガイドラインに法的拘束力がないことは考慮しなくてよいことを意味せず、事業者の自主的な取組を促すソフトローとして位置づけられている。リスクに応じた対応や継続的な見直しも、その実践に含まれる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目45「国内外のガイドライン」"},{"id":"g10-13","exam":"g","unit":"g-u10","keyword":"プライバシー","type":"choice","syllabus_ref":"10.2","stem":"AIの利活用におけるプライバシー上の問題の所在として、適切なものはどれか。","choices":["AIは大量のデータを収集・解析することで、個人の行動や属性を詳細に把握したり推定したりできるため、本人が意図しない形で個人に関する情報が集められたり、知られたりしてしまうおそれがある点に問題がある","AIの計算処理が大量の電力を消費し、環境負荷が大きくなる点に問題がある","AIの判断根拠が人間には説明できない点に問題がある","AIが人間の仕事を代替し、雇用が失われる点に問題がある"],"answer":0,"explanation":"AIにおけるプライバシー上の問題は、データの収集・解析を通じて、個人に関する情報が本人の意図しない形で集められ、把握・推定されてしまうところに生じる。電力消費は環境保護、判断根拠の説明は透明性、雇用の代替は労働政策の問題であり、いずれも隣接する別の論点である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-14","exam":"g","unit":"g-u10","keyword":"プライバシー","type":"choice","syllabus_ref":"10.2","stem":"2019年に問題となった、就職活動生の内定辞退予測に関する事例の説明として、適切なものはどれか。","choices":["小売店が防犯カメラの顔認識で来店客を万引き犯と誤認し、通報した事例である","就職情報サイトの運営事業者が、サイトの利用履歴などから就活生の内定辞退の可能性を予測して採用企業に提供していたところ、本人の同意が適切に得られていない学生の分が含まれていたことが判明し、個人情報保護委員会から勧告・指導を受けた事例である","官報に掲載された破産者の情報を地図上に表示するサイトが公開された事例である","小売企業が購買履歴の分析から顧客の妊娠を推測し、関連商品のクーポンを送付した事例である"],"answer":1,"explanation":"就活生の内定辞退予測問題は、リクルートキャリアが運営する就職情報サイトのデータを用い、内定辞退の可能性をスコア化して企業に提供していたサービスが問題となった事例である。本人の同意が得られていない学生のデータが企業に提供されていたことが判明し、個人情報保護委員会が勧告・指導を行った。AIによる予測結果の提供において、本人の同意や目的の伝達が不十分だった点が問題の核心である。他の選択肢は、それぞれ別の事例（顔認識の誤認、破産者マップ、妊娠の推測）の説明である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-15","exam":"g","unit":"g-u10","keyword":"プライバシー","type":"choice","syllabus_ref":"10.2","stem":"「破産者マップ」がプライバシー上の問題として批判された理由として、適切なものはどれか。","choices":["破産者の情報は個人情報には当たらず、法律上まったく問題がなかったためである","官報への破産情報の掲載自体が、このサイトをきっかけに法律で禁止されたためである","もともと官報で公開されていた破産者の氏名・住所などの情報であっても、地図上に集約され検索・閲覧しやすい形で可視化されることで、本人が知られたくない情報が広く知られ得る状態になり、プライバシーを侵害するとして問題となったためである","サイトに掲載された破産者の情報は、AIが生成した誤った情報だったためである"],"answer":2,"explanation":"破産者マップは、官報に掲載された破産者の情報を地図上に表示するウェブサイトが2019年に公開され、批判を受けて閉鎖された事例である。個々の情報が公開情報であっても、それらを集約し、検索や閲覧が容易な形で結びつけて示すことで、本人が知られたくない事実が広く知られ得る状態になり、プライバシーの侵害となり得ることを示した点に意義がある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-16","exam":"g","unit":"g-u10","keyword":"プライバシー","type":"choice","syllabus_ref":"10.2","stem":"AIにおけるプライバシー上の問題を「データ収集段階」と「推論段階」に分けて考えることについての説明として、適切なものはどれか。","choices":["収集段階の問題とは推論結果の誤りのことであり、推論段階の問題とはデータの漏えいのことである","収集段階と推論段階で生じる問題は実質的に同一であり、区別することに意味はない","推論段階では問題は生じず、プライバシー上の問題はデータの収集段階に限られる","収集段階では、本人が知らないうちにデータが集められたり、収集の目的が本人に十分伝わらないまま利用されたりすることが問題となり、推論段階では、本人が提供していない機微な情報まで、集めたデータの解析によって推定されてしまうことが問題となるため、段階ごとに問題の性質と求められる対策が異なる"],"answer":3,"explanation":"AIのプライバシー問題は、データを集める段階と、集めたデータから推論する段階とで性質が異なる。収集段階の問題は、本人の認識や同意を欠いた収集、目的の不透明さにあり、推論段階の問題は、本人がそもそも提供していない機微な情報が推定されてしまうことにある。段階を区別することで、それぞれに応じた対策（収集の最小化や目的の明示、機微な推論の制限など）を検討できる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-17","exam":"g","unit":"g-u10","keyword":"プライバシー","type":"choice","syllabus_ref":"10.2","stem":"米国の小売企業が、顧客の購買履歴の分析から妊娠を推測し、関連商品のクーポンを送付したところ、家族にも知らせていなかった妊娠が知られる結果になったとされる事例がある。この事例が示す、推論段階におけるプライバシー上の問題として、適切なものはどれか。","choices":["本人が提供していない健康に関する機微な情報が、一見すると機微とは言えない日常的な購買データの解析によって推定されてしまう点に問題がある","購買データが外部の第三者に漏えいしてしまった点に問題がある","データの収集の際に、利用目的を明示しなかった点に問題がある","推論の精度が低く、妊娠していない顧客にまでクーポンが送られた点に問題がある"],"answer":0,"explanation":"この事例の核心は、推論が当たってしまったことにある。健康状態のような機微な情報は本人が提供していないにもかかわらず、購買履歴のような一見機微でないデータの組み合わせから推定され得る。これが推論段階特有のプライバシー問題であり、データの漏えい（管理の問題）や、収集時の目的明示（収集段階の問題）とは区別される。推論が不正確な場合の不利益も別の問題としてあるが、この事例で問われているのは機微な情報が推定されてしまうこと自体である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-18","exam":"g","unit":"g-u10","keyword":"プライバシー・バイ・デザイン","type":"choice","syllabus_ref":"10.2","stem":"「プライバシー・バイ・デザイン」についての説明として、適切なものはどれか。","choices":["プライバシー侵害が発生した後に、被害者の救済手続を迅速に行うための考え方である","システムやサービスを設計する段階からプライバシー保護を組み込んでおくという考え方であり、カナダのオンタリオ州で情報・プライバシーコミッショナーを務めたアン・カヴォキアンが提唱し、2010年にデータ保護・プライバシーコミッショナーの国際会議で国際標準として採択された","個人データを暗号化して保存するための技術規格の名称である","個人情報を第三者に提供する際に、本人の同意を取得するための手続のことである"],"answer":1,"explanation":"プライバシー・バイ・デザイン（Privacy by Design）は、プライバシー保護を事後の対応や後付けの機能に頼るのではなく、企画・設計の段階からシステムや業務の在り方に組み込む考え方である。アン・カヴォキアンが提唱した7つの基本原則から成り、2010年に国際標準として採択された。暗号化のような個別の技術ではなく、設計思想・原則の枠組みである点がポイントである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-19","exam":"g","unit":"g-u10","keyword":"プライバシー・バイ・デザイン","type":"choice","syllabus_ref":"10.2","stem":"プライバシー・バイ・デザインの基本原則の一つである「初期設定としてのプライバシー（プライバシー・バイ・デフォルト）」の説明として、適切なものはどれか。","choices":["プライバシー侵害が起きた場合に備え、初期対応の手順をあらかじめ定めておくことである","利用者が設定を変更すれば、プライバシー保護の水準を自由に下げられるようにしておくことである","利用者が何も設定しなくても、初期設定の段階でプライバシーが最大限に保護される状態にしておき、本人の積極的な操作なしに個人情報が余分に集められたり使われたりしないようにすることである","プライバシー保護の機能は、サービスの運用が始まってから後付けで追加することである"],"answer":2,"explanation":"「初期設定としてのプライバシー」は、プライバシー・バイ・デザインの7原則の一つで、デフォルト設定の時点で最もプライバシーが保護される状態にしておくことを求める。本人が設定を探して変更しなければ保護されない設計ではなく、本人が何もしなくても保護されることが要点である。他の選択肢は、事後対応の備えや後付けの追加など、いずれも原則の趣旨と異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-20","exam":"g","unit":"g-u10","keyword":"プライバシー・バイ・デザイン","type":"choice","syllabus_ref":"10.2","stem":"ある事業者が、新しいAIサービスを開発するにあたり、プライバシー・バイ・デザインに沿った取組を行おうとしている。最も適切なものはどれか。","choices":["サービスを開始し、利用者から苦情が寄せられてからプライバシー対策を検討する","プライバシー保護を優先するため、データを使う機能そのものを設けないことにする","プライバシー保護については利用規約に記載すれば十分であり、システムの設計に組み込む必要はない","企画・設計の段階からプライバシーへの影響を評価し、収集するデータを必要最小限に抑え、初期設定で最も保護水準の高い状態にし、データの取得から廃棄までのライフサイクル全体を通じて保護する仕組みを組み込む"],"answer":3,"explanation":"プライバシー・バイ・デザインは、事後的ではなく事前的に（予防的に）対応すること、プライバシーを設計に組み込むこと、初期設定で保護すること、取得から廃棄までの全ライフサイクルで保護すること、プライバシーと機能を二者択一にせず両立させること（ゼロサムではなくポジティブサム）などを原則とする。苦情後の対応は事後的であり、機能を設けない判断は両立の考え方に反し、規約への記載だけでは設計への組み込みにならない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-21","exam":"g","unit":"g-u10","keyword":"カメラ画像利活用ガイドブック","type":"choice","syllabus_ref":"10.2","stem":"「カメラ画像利活用ガイドブック」についての説明として、適切なものはどれか。","choices":["カメラ画像を利活用する事業者向けに、経済産業省・総務省・IoT推進コンソーシアムが策定した指針であり、個人情報保護法などの関係法令の遵守を前提に、カメラに写る生活者のプライバシーへの配慮事項を整理したものである。法的拘束力を持つものではない","店舗への防犯カメラの設置を義務づける法律であり、違反した場合には罰則が適用される","個人情報保護委員会が定めた規則であり、カメラ画像の取扱いに関する法令解釈を示したものである","顔認証技術の認識精度に関する国家規格であり、認証を取得しなければカメラ画像を利用できない"],"answer":0,"explanation":"カメラ画像利活用ガイドブックは、2017年にver1.0が策定され、その後改訂が重ねられてきた（ver3.0は2022年公表）事業者向けの指針である。カメラ画像の利活用にあたり、関係法令の遵守を前提としつつ、生活者と事業者の相互理解や信頼の構築のために配慮すべき事項を、企画・設計・事前告知・取得・取扱い・管理などの場面ごとに整理している。法律や規則ではなく、法的拘束力はない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-22","exam":"g","unit":"g-u10","keyword":"カメラ画像利活用ガイドブック","type":"choice","syllabus_ref":"10.2","stem":"カメラ画像利活用ガイドブックが示す、カメラ画像を利用する際の配慮事項として、適切なものはどれか。","choices":["利用者が警戒しないよう、カメラで撮影していることは知らせない方がよい","カメラで撮影していることや、取得した画像の利用目的を、掲示などにより事前に生活者へ知らせ、生活者と事業者の相互理解や信頼の構築に努めること","取得した画像は、分析の精度を高めるため、期間を定めず保存し続けることが望ましい","顔が写った画像は個人情報には当たらないため、自由に第三者へ提供できる"],"answer":1,"explanation":"ガイドブックは、法令遵守を前提に、生活者との相互理解・信頼関係の構築を重視し、事前告知（撮影していることや利用目的の掲示等）をはじめ、企画・設計の段階からの配慮を求めている。撮影を秘匿すること、無期限の保存、顔画像の自由な第三者提供は、いずれもガイドブックの趣旨に反する。顔が識別できる画像は個人情報に当たり得る点にも注意が必要である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-23","exam":"g","unit":"g-u10","keyword":"カメラ画像利活用ガイドブック","type":"choice","syllabus_ref":"10.2","stem":"ある小売事業者が、店内カメラの画像を分析して来店客の動向を把握し、売場づくりに活かしたいと考えている。カメラ画像利活用ガイドブックに照らした対応として、最も適切なものはどれか。","choices":["防犯目的で設置したカメラの画像を、目的を変えてそのままマーケティング分析に利用する","来店客の顔画像を購買履歴と紐付けて個人ごとに蓄積し、告知は行わない","利用目的を明確にして店頭掲示などにより事前に告知し、個人を識別する必要のない分析では、画像から人数や動線などの特徴量を抽出した後は速やかに元の画像を削除するなど、取得から取扱い・管理までの各過程で、情報の個人情報への該当性と必要な配慮を検討する","取得した画像データを外部の分析事業者にそのまま渡し、その後の管理は全て任せる"],"answer":2,"explanation":"ガイドブックは、カメラ画像の取扱いを過程ごとに整理し、利用目的の明確化と事前告知、必要のない個人識別を避ける加工（特徴量への変換後の元画像の削除等）、保存や管理の在り方の検討を求めている。防犯目的で取得した画像の目的外の流用、告知なき個人の特定・蓄積、管理を伴わない外部への丸渡しは、いずれもガイドブックの趣旨に反する。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-24","exam":"g","unit":"g-u10","keyword":"プライバシー","type":"choice","syllabus_ref":"10.2","stem":"AIを活用する事業者が、プライバシー上の問題に対応するための方策として、最も適切なものはどれか。","choices":["将来の分析に備え、利用目的が定まっていなくても、取得できるデータは可能な限り多く集めておく","推論によって得られた個人に関する評価は、本人に知らせる必要は一切ない","プライバシー上の問題は、表面化してから対応すれば十分である","収集段階では取得するデータの範囲を必要最小限にし、利用目的を明示して本人の同意や関与の機会を確保すること、推論段階では機微な属性の推論やその利用に制限を設けることなど、段階ごとにリスクを洗い出して対策を講じるとともに、設計の段階からプライバシー保護を組み込む"],"answer":3,"explanation":"プライバシー上の問題への対応は、段階ごとに異なるリスクに応じた方策を組み合わせることが求められる。収集段階ではデータの最小化・目的の明示・本人の関与の確保、推論段階では機微な情報の推論・利用の制限が論点となり、これらを事後対応ではなく設計段階から組み込む考え方がプライバシー・バイ・デザインである。目的のない大量収集、本人の関与の否定、表面化後の対応は、いずれも方策として不適切である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目46「プライバシー」"},{"id":"g10-25","exam":"g","unit":"g-u10","keyword":"公平性","type":"choice","syllabus_ref":"10.3","stem":"AIにおける公平性の問題として、適切なものはどれか。","choices":["AIによる判断が、性別や人種などの属性によって特定のグループに系統的に不利に働き、採用や融資、量刑判断などの場面で不平等な取扱いを生じさせてしまう問題である","AIの判断根拠が人間には分かりにくく、説明が難しいという問題である","AIが大量の個人データを収集し、本人の意図しない形で利用してしまう問題である","AIの誤作動や攻撃によって、人命や財産に危害が及ぶおそれがあるという問題である"],"answer":0,"explanation":"AIにおける公平性の問題は、AIの出力が属性グループによって系統的に偏り、不利な取扱いの差を生んでしまう点にある。判断根拠の説明の難しさは透明性、個人データの意図しない利用はプライバシー、誤作動や攻撃による危害は安全性の問題であり、いずれも隣接する別の論点である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-26","exam":"g","unit":"g-u10","keyword":"アルゴリズムバイアス","type":"choice","syllabus_ref":"10.3","stem":"「アルゴリズムバイアス」についての説明として、適切なものはどれか。","choices":["計算の丸め誤差によって、AIの出力がわずかにずれる現象のことである","学習データや設計・評価の過程に潜む偏りがAIに取り込まれ、特定の属性グループに対して系統的に不公平な判断や精度の差を生じさせることである","利用者がAIの出力を過信し、検証せずに受け入れてしまう心理的傾向のことである","AIが学習を繰り返すうちに、性能が徐々に低下していく現象のことである"],"answer":1,"explanation":"アルゴリズムバイアスとは、データの偏りや設計・評価の過程の偏りを通じて、特定のグループに不利な出力が系統的に生じることである。プログラムの計算誤差とは異なり、データが正しく処理されていても、学習の素材や評価の仕方に偏りがあれば生じ得る点が特徴である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-27","exam":"g","unit":"g-u10","keyword":"公平性","type":"choice","syllabus_ref":"10.3","stem":"AIの公平性に関する代表的な事例として報じられた、米国の大手IT企業における採用支援ツールの問題について、適切なものはどれか。","choices":["応募者の顔画像を分析して性格を推定する機能が、科学的根拠を欠くとして批判された事例である","採用ツールが特定の大学の出身者を優遇するよう、開発者が意図的にプログラムを書き換えた事例である","過去約10年分の応募履歴書を学習させたところ、技術職の応募者の多くが男性だった経緯から、女性であることをうかがわせる経歴を含む履歴書を低く評価するようになり、開発が中止されたと報じられた事例である","採用ツールが応募者の個人情報を外部に漏えいさせた事例である"],"answer":2,"explanation":"2018年にロイターが報じた事例である。学習データに刻まれた過去の偏り（男性中心の応募実績）をAIが再現した典型例とされ、「女性」という語句を含む経歴などが低く評価される手がかりになったと報じられた。意図的なプログラムの改変ではなく、データの偏りが原因とされる点が重要である。なお、同社はこのツールを採用評価に実際に用いたことはないと説明したとされる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-28","exam":"g","unit":"g-u10","keyword":"公平性","type":"choice","syllabus_ref":"10.3","stem":"米国の裁判所で用いられた再犯リスク予測ソフトウェアをめぐる論争について、適切なものはどれか。","choices":["予測の全体の正解率が低かったことだけが問題となり、属性による差は確認されなかった","開発企業が人種を入力変数として明示的に使っていたことが発覚し、直ちに使用が禁止された","報道機関の分析では属性による誤りの偏りは見られず、論争は生じなかった","報道機関の分析では、再犯しなかった人を高リスクと誤る割合に人種間で大きな差があると指摘された一方、開発側は、同じスコアの人では実際の再犯率が人種間でほぼ等しい（較正されている）と反論し、公平性の定義の違いが論争の核心となった"],"answer":3,"explanation":"2016年の報道機関ProPublicaの分析では、再犯しなかった黒人被告の約45%が高リスクとされたのに対し、白人被告では約24%にとどまるなど、誤りの偏りが指摘された。これに対し開発側は、同じスコアにおける実際の再犯率は人種間でほぼ等しい（較正されている）として反論した。その後の研究で、集団間で再犯率そのもの（ベースレート）が異なる場合、誤り率の均等と較正などを同時に満たすことは一般にできないことが示されており、「どの定義を公平とするか」という問題の典型例となった。なお、このソフトウェアは人種自体を入力には含んでいなかったとされ、他の変数を通じた間接的な影響（代理変数）が論点の一つである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-29","exam":"g","unit":"g-u10","keyword":"データの偏り","type":"choice","syllabus_ref":"10.3","stem":"AIの公平性の問題が生じる原因としての「データの偏り」について、適切なものはどれか。","choices":["過去の人間の判断や社会の不平等が学習データのラベルや分布に刻まれていると、AIはその偏りを再現し、場合によっては増幅してしまう","学習データの量が多ければ多いほど、偏りは必ず大きくなる","データの偏りは、収集時の測定機器の故障によってのみ生じる","データに偏りがあっても、計算能力の高いAIを使えば偏りは自動的に解消される"],"answer":0,"explanation":"偏りの代表的な経路は、過去の採用・貸出・取締りといった人間の判断の記録が、そのまま「正解」のラベルとして学習されることである。偏りはデータの量や計算能力では解消されず、むしろ大規模に再現され得る。また、予測に基づいて取締りを強化した地域で新たな逮捕データが生まれ、それが再び予測を強めるというフィードバックループも、偏りを増幅させる経路として指摘されている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-30","exam":"g","unit":"g-u10","keyword":"サンプリングバイアス","type":"choice","syllabus_ref":"10.3","stem":"商用の性別分類システムを調べた研究で、学習や評価に使われる顔画像データに明るい肌の被写体が偏って多く含まれていたため、肌の色が濃い女性では誤分類率が最大で3割を超えた一方、肌の色が明るい男性では1%未満だったと報告された。この問題の性質として、最も適切なものはどれか。","choices":["利用者がシステムを誤って操作したことによる問題である","学習データが、実際に判定の対象となる人々全体を代表していないために生じるサンプリングバイアス（標本の偏り）の問題である","顔画像が外部に漏えいしたことによるプライバシーの問題である","攻撃者が細工した画像を入力したことによるセキュリティの問題である"],"answer":1,"explanation":"2018年に公表されたBuolamwiniとGebruの研究（Gender Shades）の報告である。既存のベンチマーク用データでは明るい肌の被写体が約8割を占めるなど偏りがあり、データの代表性の欠如が、グループ間の大きな精度差として現れた。サンプリングバイアスとは、収集された標本が母集団を代表していないことから生じる偏りをいう。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-31","exam":"g","unit":"g-u10","keyword":"代理変数","type":"choice","syllabus_ref":"10.3","stem":"「代理変数（プロキシ変数）」とAIの公平性について、適切なものはどれか。","choices":["センシティブ属性を学習データから除外すれば、代理変数による影響も自動的になくなる","代理変数とは、欠損値を補うために用いる代替データのことであり、公平性とは無関係である","居住地の郵便番号のように、センシティブ属性と強く相関する変数が学習に使われると、その変数が属性の代理として働き、属性自体を使わなくても間接的に差別的な判断が生じ得る","代理変数を使うことは、常に公平性を高める手法として推奨されている"],"answer":2,"explanation":"センシティブ属性そのものを除外するだけでは不十分であり、属性と強く相関する他の変数を通じて、属性の情報が実質的に復元されてしまうことがある。これが代理変数の問題であり、属性を使わないことで公平性が確保されるという考え方の限界を示す。どの変数が代理になり得るかの検討が、公平性への対処で必要になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-32","exam":"g","unit":"g-u10","keyword":"公平性の定義","type":"choice","syllabus_ref":"10.3","stem":"「公平性の定義」についての説明として、適切なものはどれか。","choices":["公平性の定義は国際的に一つに定まっており、どの場面でも同じ基準を用いるべきである","公平性は、AI全体の正解率が高ければ自動的に確保される","公平性の基準は、グループ間の取扱いの差を一切認めないものだけである","肯定的な判断を受ける割合をグループ間で等しくする基準、実際に望ましい結果を得た人のうち肯定的に判断される割合（真陽性率）を等しくする基準など、複数の基準が提案されており、グループ間で基礎となる比率（ベースレート）が異なる場合には、これらを全て同時に満たすことは一般にできない"],"answer":3,"explanation":"公平性の定義には、肯定的判断の割合の均等（統計的パリティ）、真陽性率の均等（機会均等）、真陽性率と偽陽性率の双方の均等（等化オッズ）など複数の基準がある。ベースレートがグループ間で異なる場合、これらを同時に満たすことは一般に不可能であることが知られており、再犯予測をめぐる論争の核心もここにあった。どの定義を採用するかは、場面ごとの検討事項になる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-33","exam":"g","unit":"g-u10","keyword":"公平性の定義","type":"choice","syllabus_ref":"10.3","stem":"ある融資審査AIについて、実際に返済した人のうち承認された人の割合（真陽性率）を、属性グループ別に調べた。前提として、真陽性率は「実際に返済した人の数に対する、その中で承認された人の数の割合」とする。グループAでは実際に返済した100人のうち80人が承認され、グループBでは実際に返済した100人のうち60人が承認された。「真陽性率をグループ間で等しくする」という公平性の基準（機会均等）に照らした評価として、適切なものはどれか。","choices":["真陽性率はグループAが0.8、グループBが0.6であり、等しくないため、この基準は満たされていない","両グループとも過半数が承認されているため、この基準は満たされている","真陽性率はグループAが0.2、グループBが0.4であり、等しくないため、この基準は満たされていない","この基準は申込者全体の承認率の一致を見るものであり、真陽性率は関係しない"],"answer":0,"explanation":"真陽性率は、グループAが80/100＝0.8、グループBが60/100＝0.6である。機会均等は真陽性率のグループ間の均等を求める基準であり、過半数が承認されているかどうかでは判断しない。なお、0.2と0.4は承認されなかった割合（偽陰性率）であり、申込者全体の承認率の均等は、統計的パリティという別の基準である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-34","exam":"g","unit":"g-u10","keyword":"センシティブ属性","type":"choice","syllabus_ref":"10.3","stem":"「センシティブ属性」についての説明として、適切なものはどれか。","choices":["測定の際に誤差が生じやすい、扱いに注意が必要な数値データのことである","性別・人種・年齢・信条など、それを根拠に不利な取扱いをすることが差別につながり得るため、AIの判断における扱いに特に注意を要する属性のことである","暗号化して保存しなければならない個人情報のことである","AIの予測精度に最も大きく寄与する変数のことである"],"answer":1,"explanation":"センシティブ属性とは、性別・人種・年齢など、差別の根拠になり得る属性の総称である。公平性の評価ではグループ分けの軸として結果を比較する一方で、判断への直接の利用や、代理変数を通じた間接的な利用には注意が必要とされる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-35","exam":"g","unit":"g-u10","keyword":"公平性","type":"choice","syllabus_ref":"10.3","stem":"AIの公平性に対処するにあたり検討すべき事項として、適切なものはどれか。","choices":["公平性の基準は技術的に一意に決まるため、利用場面の文脈を考慮する必要はない","全体の予測精度さえ高ければ、属性グループごとの結果の差は検討しなくてよい","どの公平性の定義を採用するかは、利用場面や影響を受ける人々（ステークホルダー）、法的な要請によって変わり得るため、関係者で検討して決める必要があり、精度とのトレードオフや、運用開始後に偏りが生じていないかの継続的な確認も検討事項になる","公平性への対処は、開発が完了した後でのみ行うものであり、企画や設計の段階で検討する必要はない"],"answer":2,"explanation":"公平性の定義は複数あり、同時に満たせない場合があるため、どの基準を採用するか自体が検討事項になる。その判断は利用場面やステークホルダー、法的要請に依存する。あわせて、グループ別の結果の評価、全体の精度とのトレードオフ、運用開始後のモニタリングまで含めて検討することが求められる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-36","exam":"g","unit":"g-u10","keyword":"公平性","type":"choice","syllabus_ref":"10.3","stem":"ある金融機関が、与信審査AIで特定の属性グループの承認率が他のグループより系統的に低いことに気づいた。公平性に対処する技術的・実務的な取組として、最も適切なものはどれか。","choices":["全体の正解率を上げるため、より大規模なモデルに置き換える","問題が表面化しないよう、グループ別の承認率の集計をやめる","センシティブ属性のデータを全て削除し、それ以外の変更は行わない","学習データの偏りを点検して不足するグループのデータを補ったり重み付けを調整したりし（前処理）、学習の際に公平性に関わる制約を組み込むことや、判定の閾値を調整すること（後処理）も含め、グループ別の性能を評価しながら対処する"],"answer":3,"explanation":"公平性に対処する技術は、データ段階の前処理（不足するデータの補充、リサンプリング、リウェイティングなど）、学習段階の処理（公平性に関する制約の導入など）、出力段階の後処理（判定の閾値の調整など）に大別され、グループ別の性能評価と組み合わせて用いられる。センシティブ属性の削除だけでは代理変数の影響が残り、グループ別の集計をやめることは問題を見えなくするだけである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目47「公平性」"},{"id":"g10-37","exam":"g","unit":"g-u10","keyword":"安全性とセキュリティ","type":"choice","syllabus_ref":"10.4","stem":"AIにおける安全性とセキュリティに関する論点の所在として、適切なものはどれか。","choices":["AIが自動運転や医療、インフラ制御など物理世界や重要な判断に組み込まれるにつれ、AIの誤判断・誤作動が人命や財産への危害につながるという安全性の問題と、攻撃者がAI自体を攻撃して誤動作させたり情報を盗んだりするというセキュリティの問題の、双方が論点になる","AIによる判断が、性別や人種などの属性によって特定のグループに系統的に不利に働いてしまう問題である","AIの判断根拠が人間には分かりにくく、説明が難しいという問題である","AIが大量の個人データを収集し、本人の意図しない形で利用してしまう問題である"],"answer":0,"explanation":"安全性は、AIの誤判断や誤作動が現実世界に危害を及ぼす側面であり、セキュリティは、外部からの攻撃によってAIが狙われる側面である。属性による不利な取扱いは公平性、判断根拠の説明の難しさは透明性、個人データの意図しない利用はプライバシーの問題であり、いずれも隣接する別の論点である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-38","exam":"g","unit":"g-u10","keyword":"安全性とセキュリティ","type":"choice","syllabus_ref":"10.4","stem":"2018年に米国で起きた、自動運転の実験車両が歩行者をはねて死亡させた事故について、米国の国家運輸安全委員会（NTSB）の調査で指摘された内容として、適切なものはどれか。","choices":["攻撃者が車両のシステムに侵入し、制御を奪ったことが原因とされた","システムは衝突の約6秒前に歩行者を検知していたものの、横断歩道の外を横断する歩行者を想定した設計になっておらず対象の分類が安定しなかったことや、コンピュータ制御中は自動の緊急ブレーキが無効化されていたことなどが重なり、衝突を回避できなかった","学習データに悪意のあるデータが混入していたことが、事故の原因であると断定された","監視役の安全運転手は常に前方を注視しており、人為的な要因は一切なかったとされた"],"answer":1,"explanation":"2018年3月にアリゾナ州テンピで起きた事故で、自動運転の実験車両による歩行者死亡事故として知られる。NTSBの調査では、検知自体は衝突の約6秒前にできていた一方、横断歩道外の歩行者を想定していない設計のために分類が車両・自転車・不明な物体の間で揺れ続けたこと、車両側の自動緊急ブレーキがコンピュータ制御中は無効化されていたこと、監視役の運転手が前方を注視していなかったことなどが指摘された。攻撃やデータの混入による事故ではない。AIの安全性は、認識の性能だけでなく、想定外の状況への備えやフェイルセーフ、人間の監視の在り方を含む設計全体の問題であることが示された事例である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-39","exam":"g","unit":"g-u10","keyword":"Adversarial Attack (Adversarial Examples)","type":"choice","syllabus_ref":"10.4","stem":"「Adversarial Examples（敵対的サンプル）」についての説明として、適切なものはどれか。","choices":["学習データに紛れ込ませることで、モデルの学習結果を歪める悪意のあるデータのことである","公開されたモデルへの問い合わせ結果を集めて、モデルを複製するために使われる入力のことである","人間にはほとんど気づかないようなわずかな改変（摂動）を入力に加えることで、AIに意図的な誤分類や誤判断を引き起こさせるよう細工された入力のことである","モデルの出力から、学習に使われたデータを復元するために生成される入力のことである"],"answer":2,"explanation":"敵対的サンプルは、推論段階の入力に対する攻撃であり、人間には元の入力とほぼ同じに見えても、AIには別のクラスに高確信度で誤分類されるよう、勾配情報などを使って意図的に作られる。学習データへの混入はデータ汚染、問い合わせによる複製はモデル窃取、学習データの復元はデータ窃取の側の攻撃であり、攻撃の段階と対象が異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-40","exam":"g","unit":"g-u10","keyword":"Adversarial Attack (Adversarial Examples)","type":"choice","syllabus_ref":"10.4","stem":"敵対的サンプルの物理世界での実証として報告された、道路標識を対象とした研究について、適切なものはどれか。","choices":["標識そのものを偽物の標識に交換することで、AIを誤認させた","攻撃者が車両のカメラに細工した画像データを直接送り込むことで、AIを誤認させた","人間のドライバーも同じ標識を同じように誤認することが確認された","一時停止の標識に、落書きのように見える白黒のステッカーを貼ったところ、画像認識AIがそれを制限速度の標識と誤認することが、実験室の条件では全ての画像で、走行中の車両から撮影した映像でも高い割合で確認された"],"answer":3,"explanation":"2018年に査読付きの国際会議（CVPR）で発表された研究である。人間が見れば落書きのある一時停止標識にしか見えないものでも、AIには制限速度45の標識として認識された。敵対的サンプルは画面の中のデータだけの話ではなく、物理世界の対象物への細工によっても実現し得ること、そして自動運転のような安全性に関わる用途では現実の脅威になり得ることを示した。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-41","exam":"g","unit":"g-u10","keyword":"データ汚染","type":"choice","syllabus_ref":"10.4","stem":"「データ汚染（データポイズニング）」についての説明として、適切なものはどれか。","choices":["学習データに悪意のあるデータを紛れ込ませ、学習後のモデルに意図した誤った振る舞いをさせる攻撃であり、画像生成AIについては、見た目には通常の画像と区別がつかないよう細工された少数の画像が、特定の概念についての学習を歪めることが実証されている","運用中のAIへの入力にわずかな改変を加えて、その場の判断を誤らせる攻撃である","学習済みモデルのパラメータを直接書き換えて、振る舞いを変える攻撃である","モデルへの問い合わせを繰り返し、学習に使われたデータを復元する攻撃である"],"answer":0,"explanation":"データ汚染は学習段階への攻撃で、正解ラベルを付け替えたデータや、特定の入力で誤動作するよう仕組まれたデータを混入させる。画像生成AIについては、シカゴ大学の研究チームが2024年の査読付きのセキュリティ会議で、見た目では判別できないよう細工した100枚未満の画像で、特定の語への生成結果を支配できることを示した（Nightshade）。Webから大規模にデータを収集する現在の学習方法では、収集経路そのものが攻撃の入口になり得る。入力への改変は敵対的サンプル、パラメータの書き換えはモデル汚染、データの復元はデータ窃取である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-42","exam":"g","unit":"g-u10","keyword":"モデル汚染","type":"choice","syllabus_ref":"10.4","stem":"「モデル汚染」についての説明として、適切なものはどれか。","choices":["学習データに悪意のあるデータを混入させ、学習の結果を歪めることである","学習済みモデル自体が改ざん・細工された状態で配布・流通し、それを入手して利用した側のシステムで、特定の入力に対して意図しない振る舞いを引き起こす問題であり、通常の入力では正常に振る舞うため発見が難しい場合がある","公開された予測APIへの問い合わせを繰り返し、元のモデルと同等の複製を作ることである","利用が長期間に及ぶうちに、社会の変化に合わなくなりモデルの精度が自然に低下することである"],"answer":1,"explanation":"モデル汚染は、データではなくモデル自体が汚染の対象になる問題である。特定の合図（トリガー）となる入力でのみ誤動作するバックドアが仕込まれたモデルは、通常の評価では正常に見えるため、そのまま組み込まれやすい。学習済みモデルを共有サイトなどから入手して使うことが一般的になったことで、モデルの出所の確認や検証が供給網（サプライチェーン）全体の課題になっている。セキュリティ企業の実証では、改ざんしたモデルを共有サイトに公開し、入手され得る状態に置けることも示されている。学習データへの混入はデータ汚染、APIによる複製はモデル窃取、精度の自然な低下は汚染ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-43","exam":"g","unit":"g-u10","keyword":"データ窃取","type":"choice","syllabus_ref":"10.4","stem":"AIにおける「データ窃取」に関する攻撃の一つ、モデル反転（モデルインバージョン）攻撃についての説明として、適切なものはどれか。","choices":["サーバに不正に侵入し、学習データが保存されたデータベースのファイルを直接盗み出す攻撃のことである","学習データに悪意のあるデータを混入させ、モデルの振る舞いを歪める攻撃のことである","モデルが出力する確信度などの情報を手がかりに問い合わせを繰り返すことで、学習に使われたデータの内容を復元・推定してしまう攻撃であり、モデルの内部に直接アクセスできなくても、学習データに含まれる個人の顔画像などを復元できることが示されている","収集した入出力の組を学習材料にして、元のモデルと同等のモデルを複製する攻撃のことである"],"answer":2,"explanation":"モデル反転攻撃は、2015年の研究で、顔認識モデルの出力する確信度を手がかりに、名前を与えるだけでその人物の顔画像を復元できることが示された。学習データそのものは公開していなくても、モデルの出力が学習データの情報を漏らし得るという点が本質であり、データ窃取はサーバへの侵入のような従来型の経路だけでなく、モデルへの正規の問い合わせを通じても起こり得る。対策としては、出力する確信度の丸めや、出力情報そのものの制限が検討される。入出力の組による複製はモデル窃取、学習データへの混入はデータ汚染である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-44","exam":"g","unit":"g-u10","keyword":"モデル窃取","type":"choice","syllabus_ref":"10.4","stem":"「モデル窃取（モデル抽出）」についての説明として、適切なものはどれか。","choices":["モデルのパラメータが保存されたファイルを、物理的に盗み出すことである","モデルへの問い合わせの結果から、学習に使われた個々のデータを復元することである","入力にわずかな改変を加えて、モデルの判断を誤らせることである","公開された予測APIに対して大量の入力と出力の組を収集し、それを学習材料とすることで、元のモデルとほぼ同等の振る舞いをする複製モデルを作り出す攻撃であり、モデルのパラメータや学習データを直接知らなくても行えることが実証されている"],"answer":3,"explanation":"モデル窃取は、2016年の査読付きのセキュリティ会議で、商用の機械学習サービスの予測APIから、元とほぼ完全に一致する複製モデルを抽出できることが実証された。学習済みモデルは開発コストがかかった知的財産であり、無断で複製されれば事業上の損害になるうえ、複製が手元にあることで敵対的サンプルの作成など他の攻撃の足がかりにもなる。対策としては、APIの利用回数の制限や異常な問い合わせの検知、出力する確信度の制限などが挙げられる。データの復元はデータ窃取、入力への改変は敵対的サンプルである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-45","exam":"g","unit":"g-u10","keyword":"セキュリティ・バイ・デザイン","type":"choice","syllabus_ref":"10.4","stem":"「セキュリティ・バイ・デザイン」についての説明として、適切なものはどれか。","choices":["情報セキュリティを、製品やサービスの企画・設計の段階から確保する考え方であり、開発の後段や運用開始後に脆弱性が見つかってから対策を後付けするのではなく、上流の工程で脅威分析やセキュリティ要件の定義を行い、対策をあらかじめ組み込んでおくことである","運用を開始した後に、セキュリティの専門チームが24時間体制で監視することである","セキュリティ機能を基本機能から切り離し、利用者が必要に応じて後から追加できるようにする設計のことである","利用者に複雑なパスワードの設定と定期的な変更を義務づけることである"],"answer":0,"explanation":"セキュリティ・バイ・デザインは、情報処理推進機構（IPA）の導入指南書などでも示される考え方で、後工程で見つかった脆弱性への対処はコストが大きくなるため、企画・設計の段階から脅威を分析し、セキュリティ要件を定めて対策を組み込むことを指す。AIについても、学習データやモデル、推論の仕組みが攻撃対象になることを設計段階から想定しておくことが求められる。運用時の監視や利用者側のパスワード管理は、それ自体は対策の一部でも、この考え方の中心ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-46","exam":"g","unit":"g-u10","keyword":"データ汚染","type":"choice","syllabus_ref":"10.4","stem":"ある企業が、Webから収集した大規模な画像データで画像生成AIを追加学習したところ、特定の語で指示した際に無関係な画像が生成されるようになった。学習データに細工された画像が混入したことによるデータ汚染が疑われる。対処として、最も適切なものはどれか。","choices":["生成結果におかしな画像が混ざらないよう、出力側のフィルタリングだけを追加する","学習データとして使う範囲を出所・来歴を確認できるものに絞り、収集したデータについて異常なサンプルの検出・除去などの検証を行ったうえで再学習し、今後のデータ収集でも出所の確認と検証を継続する","より大規模なモデルに置き換えて、同じデータで再学習する","混入した画像を特定することは困難であるため、生成結果の傾向を注視しながらそのまま運用を続ける"],"answer":1,"explanation":"データ汚染は学習の素材そのものが汚染されている問題であり、出力側のフィルタは症状を隠すだけで、学習された歪みは残る。モデルの規模を変えても、同じ汚染データで学習すれば結果は変わらない。根本的な対処は、データの出所・来歴の確認、混入が疑われるサンプルの検出・除去と検証、そのうえでの再学習であり、収集の経路自体を継続的に管理することが求められる。Webからの大規模収集は、誰でもデータを置ける経路である以上、汚染の入口になるという前提で扱う必要がある。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-47","exam":"g","unit":"g-u10","keyword":"Adversarial Attack (Adversarial Examples)","type":"choice","syllabus_ref":"10.4","stem":"敵対的サンプルの生成手法の一つであるFGSMでは、入力 x に対して「x ＋ ε ×（損失関数の勾配の符号）」という式で敵対的サンプルを作る。前提として、ある入力の値が 0.50、ε が 0.10、その入力についての勾配の符号が +1 であるとき、生成される敵対的サンプルのその入力の値はどれか。","choices":["0.40","0.55","0.60","0.50"],"answer":2,"explanation":"式に当てはめると、0.50 ＋ 0.10 × (+1) ＝ 0.60 である。0.40 は符号を逆向きに加えた場合、0.55 は ε の半分だけを加えた場合、0.50 は改変を加えなかった場合の値である。FGSMは、損失が大きくなる方向へ、ε の大きさだけ入力を一度にずらす手法であり、このような小さな変更の積み重ねが、人間には気づかれにくいままモデルに誤判断を引き起こさせる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-48","exam":"g","unit":"g-u10","keyword":"安全性とセキュリティ","type":"choice","syllabus_ref":"10.4","stem":"AIへの攻撃に対する対応手段の考え方として、最も適切なものはどれか。","choices":["敵対的サンプルへの対策は、入力画像を圧縮・縮小する処理を入れるだけで十分であり、それ以上の備えは不要である","モデル窃取への対策は、モデルのパラメータを暗号化して保存することで完了し、予測APIを通じた複製は考慮しなくてよい","データ汚染への対策は、学習が終わった後にモデルの出力だけを検査すれば十分であり、学習データ自体を確かめる必要はない","敵対的サンプルには敵対的訓練（敵対的サンプルを学習に含めて頑健性を高める）、モデル窃取には予測APIの利用回数の制限や出力する確信度の丸め、データ汚染には学習データの出所の確認と検証というように、攻撃の段階と経路に応じた対策を組み合わせる必要がある"],"answer":3,"explanation":"AIへの攻撃は、学習データ、学習済みモデル、推論時の入力、公開されたAPIなど、段階と経路ごとに形が異なるため、対策もそれに応じて組み合わせる必要がある。敵対的訓練は敵対的サンプルへの代表的な対策として研究されてきた手法である。入力の圧縮だけでは敵対的サンプルを防ぎきれず、パラメータの暗号化はAPI経由の複製には効かず、出力の検査だけでは学習データの汚染は取り除けない。加えて、どの攻撃を想定し、どこに対策を組み込むかは、企画・設計の段階から検討するセキュリティ・バイ・デザインの考え方につながる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目48「安全性とセキュリティ」"},{"id":"g10-49","exam":"g","unit":"g-u10","keyword":"ディープフェイク","type":"choice","syllabus_ref":"10.5","stem":"「ディープフェイク」についての説明として、適切なものはどれか。","choices":["深層学習などのAI技術を使って、実在の人物の顔や声を別の映像や音声に合成したりすることで、本人が実際には言っていない発言や、行っていない行動をしているように見せる映像・音声、およびその作成技術のことである","映像や音声の圧縮率を高めて、データ量を大幅に小さくする技術のことである","過去の映像資料をAIで修復し、高画質化する技術のことである","俳優の演技をデジタルデータとして記録し、CGキャラクターの動きに反映させる技術のことである"],"answer":0,"explanation":"ディープフェイクは「ディープラーニング」と「フェイク（偽物）」を組み合わせた言葉で、顔の差し替えや声の複製などにより、本物らしく見える偽の映像・音声を作る技術と、その成果物を指す。娯楽や創作などの正当な用途もあり得るが、なりすましによる詐欺や、偽の発言映像の拡散などに悪用されることが問題になっている。映像の圧縮や修復、モーションキャプチャは別の技術である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-50","exam":"g","unit":"g-u10","keyword":"ディープフェイク","type":"choice","syllabus_ref":"10.5","stem":"AIによる音声の複製が詐欺に使われた初期の事例として報じられた、2019年に英国のエネルギー企業で起きた事件について、適切なものはどれか。","choices":["攻撃者が企業のサーバに侵入し、経営者のメールアカウントを乗っ取って送金指示のメールを送った","詐欺グループが、親会社の経営者の声をAIで複製したとみられる電話で子会社の経営者に送金を指示し、約22万ユーロがだまし取られたと報じられた。声には本人の訛りや話し方の特徴が再現されていたとされる","経営者本人が、AIで複製された音声であることを知りながら送金を承認した","被害は未遂に終わり、送金は実行されなかった"],"answer":1,"explanation":"2019年に報じられた事例で、英国のエネルギー企業の経営者が、ドイツの親会社の経営者を名乗る電話を受け、声の特徴まで似ていたために指示を信じて送金したとされる。AIによる音声複製が使われた初期の事例として広く引用される。なお、AIが使われたという点は、関係する保険会社の見立てとして報じられたものである。声だけを手がかりにした本人確認は、音声を複製できる技術の前では成り立たなくなっていることを示した事例である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-51","exam":"g","unit":"g-u10","keyword":"ディープフェイク","type":"choice","syllabus_ref":"10.5","stem":"2024年に香港で公表された、多国籍企業を狙ったディープフェイク詐欺の事件について、適切なものはどれか。","choices":["企業の広報担当者が、宣伝用の動画にディープフェイクを使ったことが問題になった事件である","偽の請求書がメールで送られ、担当者が気づかずに支払ったという、AIを使わない従来型の詐欺であった","本社の財務責任者を名乗る連絡をきっかけに開かれたビデオ会議で、画面に映った参加者が全員ディープフェイクで作られた偽物であり、指示を信じた社員が合計約2億香港ドルを送金してしまった","会議の参加者は実在の社員であり、発言の記録だけが後から改ざんされた"],"answer":2,"explanation":"香港警察が2024年に公表した事件である。公開されている映像などから経営層の顔と声が再現され、ビデオ会議の自分以外の参加者は全員偽物だったとされる。見慣れた顔と声が複数そろっていたことで疑いが働かず、大口の送金が複数回に分けて実行された。「映像で顔を見て、声を聞いたから本人だ」という確認の前提そのものが崩れた事例であり、送金の確認を別の経路で行うなどの手順面の対策が重要になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-52","exam":"g","unit":"g-u10","keyword":"ディープフェイク","type":"choice","syllabus_ref":"10.5","stem":"選挙へのディープフェイクの悪用として、2024年に米国で起きた事例について、適切なものはどれか。","choices":["候補者本人が、自分の声をAIで複製して有権者への電話に使うことを公表し、議論になった","選挙管理委員会が、投票所の案内にAIの音声を使うことを決定した","偽の投票所の情報が印刷物で配布されたが、AIは使われていなかった","大統領選挙の予備選の直前に、大統領の声をAIで模した自動音声電話が多数の有権者にかけられ、予備選では投票しないよう促す内容が流された。当局は投票を妨げる試みだとして捜査し、通信規制当局はAIで生成した音声にも既存の規制が及ぶことを示した"],"answer":3,"explanation":"2024年1月、ニューハンプシャー州の予備選の2日前に起きた事例である。声の複製は安価に作られ、発信者番号も偽装されていた。選挙のような短い期間に判断が求められる場面では、偽物であることが判明する前に投票行動へ影響し得る点が、悪用としての深刻さである。作った人物には通信規制当局から多額の制裁金が科された。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-53","exam":"g","unit":"g-u10","keyword":"フェイクニュース","type":"choice","syllabus_ref":"10.5","stem":"「フェイクニュース」と生成AIの関係についての説明として、適切なものはどれか。","choices":["フェイクニュースは、事実でない内容を事実らしく見せて広める偽情報のことであり、生成AIによって、もっともらしい文章や画像、音声、映像を大量かつ低コストに作れるようになったことで、作成と拡散の規模が拡大しやすくなった","フェイクニュースは生成AIの登場によって初めて生まれた現象であり、それ以前には存在しなかった","生成AIが作った文章や画像は、必ずフェイクニュースに分類される","フェイクニュースと誤情報は同じ意味であり、広める側にだます意図があるかどうかは区別されない"],"answer":0,"explanation":"偽情報の拡散自体は生成AI以前からあったが、生成AIは作成の手間とコストを大きく下げ、受け手に合わせた文面の量産も容易にした。生成AIの出力が全て偽情報なのではなく、正当な用途も多い。また、だます意図を持って作られる偽情報と、意図せず広まる誤情報は、対策の立て方が異なるため区別して論じられることが多い。影響の大きさは、作る側の変化だけでなく、SNSなどの拡散の経路と結びついて生じる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-54","exam":"g","unit":"g-u10","keyword":"フェイクニュース","type":"choice","syllabus_ref":"10.5","stem":"フェイクニュースの影響が大きくなりやすい理由として、適切なものはどれか。","choices":["偽情報は公的機関によって即座に削除される仕組みが整っているため、影響は限定的である","SNSなどでは感情を強く揺さぶる内容ほど広がりやすく、偽情報が訂正情報よりも先に広く拡散してしまうことがある。また、同じ情報に繰り返し触れることで、根拠がなくても本当らしく感じてしまう効果も指摘されている","偽情報は文章だけで作られるため、画像や映像を伴う情報は常に信頼できる","拡散の速さは情報の真偽とは無関係であり、偽情報と訂正情報は同じ速さで広がる"],"answer":1,"explanation":"偽情報は、新奇さや感情への訴えかけによって拡散しやすく、一度広がった後は、訂正が全ての受け手に届くとは限らない。生成AIによって画像や音声まで伴う偽情報が作れるようになり、「映像があるから本当だ」という判断も成り立たなくなっている。受け手の側の確認習慣と、拡散を抑えるプラットフォーム側の対応の双方が課題になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-55","exam":"g","unit":"g-u10","keyword":"フェイクニュース","type":"choice","syllabus_ref":"10.5","stem":"フェイクニュースへの対応策として、適切なものはどれか。","choices":["拡散を防ぐには、疑わしい情報を見た人が、そのまま共有して注意を喚起するのが最も効果的である","AIで生成された文章かどうかは検出ツールで完全に見分けられるため、検出結果だけで真偽を判断できる","情報の出所や一次情報を確認する、複数の信頼できる報道と照らし合わせるといった受け手の確認に加え、ファクトチェック機関による検証と結果の公表、プラットフォームによる拡散の抑制や表示の工夫など、複数の層の対応を組み合わせることが求められる","偽情報への対応は政府だけが行うべきであり、個人やメディアが関与する余地はない"],"answer":2,"explanation":"単独で決定的な対策はなく、受け手のリテラシー、検証を行う機関、拡散の場であるプラットフォーム、制度面の対応を組み合わせることが基本になる。AIの検出ツールには誤判定があり、それだけで真偽を断定することはできない。また、疑わしい情報を注意喚起のつもりで共有すること自体が、拡散を助けてしまう場合がある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-56","exam":"g","unit":"g-u10","keyword":"悪用","type":"choice","syllabus_ref":"10.5","stem":"AI技術の「悪用」に関する論点の所在として、適切なものはどれか。","choices":["AIが人間の指示に反して、自律的に悪意ある行動を取ることだけが悪用の論点である","AIの学習データに偏りがあることで、意図せず差別的な結果が生じる問題である","AIシステムが外部からの攻撃を受けて誤動作させられる問題である","生成AIなどの技術そのものは中立的な道具であっても、利用する人間が、詐欺や偽情報の拡散、なりすましといった目的に意図的に使うことで社会的な被害が生じる、という側面が悪用の論点である"],"answer":3,"explanation":"悪用は、技術を使う側の意図的な行為に焦点を当てる論点である。学習データの偏りによる意図しない差別は公平性、外部からの攻撃による誤動作は安全性とセキュリティの問題であり、AIが狙われる側か、使う側が悪意を持つ側かで論点が分かれる。生成AIの普及で、偽の映像・音声・文章を作る能力が広く行き渡ったことが、悪用の規模と深刻さを変えている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-57","exam":"g","unit":"g-u10","keyword":"悪用","type":"choice","syllabus_ref":"10.5","stem":"生成AIがサイバー犯罪や詐欺に悪用される形として、指摘されているものはどれか。","choices":["大規模言語モデルを使って、文法の誤りの少ない自然なフィッシングメールの文面を、対象の言語や属性に合わせて大量に作成したり、不正なプログラムの作成を補助させたりする形が指摘されている","生成AIが単独で銀行のシステムへ侵入し、口座から自動的に送金する形だけが確認されている","生成AIの悪用は文章の生成に限られ、音声や画像が詐欺に使われることはない","サイバー犯罪への悪用は理論上の可能性にとどまり、実際の報告は存在しない"],"answer":0,"explanation":"従来、フィッシング文面の不自然な言い回しは、受け手が気づく手がかりの一つだったが、生成AIによってその手がかりが失われつつある。AIサービスの提供事業者も、自社サービスが詐欺や不正なプログラムの作成に使われた事例を公表し、アカウントの停止などの対応を取っている。音声や画像の悪用（なりすまし詐欺）も実際に起きており、文章に限られない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-58","exam":"g","unit":"g-u10","keyword":"悪用","type":"choice","syllabus_ref":"10.5","stem":"ある企業の財務担当者が、上司を名乗る電話で「至急、指定口座へ送金してほしい」と指示を受けた。声は上司によく似ていたが、普段と違う経路での指示だった。この場面での対応として、最も適切なものはどれか。","choices":["声が本人によく似ているため、本人の指示と判断して直ちに送金する","声や映像はAIで複製され得ることを前提に、いったん電話を切り、社内名簿に登録された番号へのかけ直しや、別の担当者への確認など、あらかじめ定めた別の経路で指示の真正性を確認してから手続きを進める","指示の内容を録音しておけば後から確認できるため、そのまま送金してよい","不審に思った場合は、相手にAIではないかと尋ね、否定されれば送金してよい"],"answer":1,"explanation":"音声や映像の複製技術の前では、「声が似ている」「顔が見えた」は本人確認の根拠にならない。ディープフェイク詐欺への実務上の対策は、検出技術だけに頼るのではなく、送金のような重要な手続きでは別経路での確認（かけ直し）や複数人での承認を手順として組み込むことである。録音は事後の証拠にはなっても被害は防げず、相手への質問は確認にならない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-59","exam":"g","unit":"g-u10","keyword":"悪用","type":"choice","syllabus_ref":"10.5","stem":"ディープフェイクなどの生成AIの悪用への技術的・制度的な対応策として、適切なものはどれか。","choices":["検出技術の精度はすでに完全であり、偽物は全て自動で見分けられる","来歴情報を付ける仕組みは、本物のコンテンツであることを絶対に保証するものではないため、対策として意味を持たない","コンテンツの作成・編集の履歴を電子署名とともに記録する来歴情報（C2PAなどの規格）や電子透かしによって、正規に作られたものを確認する手がかりを増やすことに加え、EUのAI法のように、ディープフェイクであることの開示を求める制度面の対応が進められている","悪用への対応は、生成AIの提供を全面的に禁止することでのみ可能である"],"answer":2,"explanation":"検出技術は生成技術との追いかけ合いであり、単独では決定的な対策にならない。来歴情報は「本物であることの絶対の保証」ではないが、正規の発信元から出たコンテンツを確認する手がかりにはなる。EUのAI法（第50条）は、ディープフェイクを生成・操作するAIシステムの利用者に、人工的に生成・操作されたものであることの開示を求めている。技術、制度、受け手の確認を組み合わせることが基本的な方向である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-60","exam":"g","unit":"g-u10","keyword":"ディープフェイク","type":"choice","syllabus_ref":"10.5","stem":"家族の声をAIで複製した電話による詐欺への備えとして、適切なものはどれか。","choices":["家族の声の特徴をよく覚えておけば、複製された声とは聞き分けられる","電話で金銭の要求があった場合は、声の主に直接会うまでは全て詐欺と断定するしかない","SNSに家族の音声や映像を公開しないよう徹底すれば、声を複製されることはなくなる","声は複製され得ることを前提に、家族の間であらかじめ合い言葉を決めておく、金銭の要求は一度電話を切って本人にかけ直して確認する、といった手順を平時から取り決めておくことが有効とされる"],"answer":3,"explanation":"短い音声からでも声の複製が作られ得るため、聞き分けや公開の抑制だけでは防ぎきれない。各国の当局も、家族の声をまねた電話で金銭を求める手口への注意を呼びかけている。実務上の備えは、合い言葉や、かけ直しによる確認など、「声そのもの」を本人確認の根拠にしない手順をあらかじめ決めておくことである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目49「悪用」"},{"id":"g10-61","exam":"g","unit":"g-u10","keyword":"ブラックボックス","type":"choice","syllabus_ref":"10.6","stem":"AIにおける「ブラックボックス」についての説明として、適切なものはどれか。","choices":["深層学習などのモデルでは、多数のパラメータが複雑に組み合わさって判断が行われるため、入力から出力に至る内部の処理過程や、個別の判断の根拠を、人間がそのまま理解することが難しい状態を指す","モデルの内部構造が営業秘密として公開されていない状態のことであり、公開されれば中身は容易に理解できる","入力と出力を暗号化して通信する仕組みを備えたモデルのことである","学習データが存在しないため、出力の正しさを検証できないモデルのことである"],"answer":0,"explanation":"ブラックボックスは、公開・非公開の問題ではなく、モデル内部の処理の複雑さから、人間が判断の過程や根拠を理解しにくいという性質を指す。ソースコードやパラメータが手に入っても、それだけでは個別の判断の理由は読み取れない。暗号化は通信や保管の保護の仕組みであり、学習データの有無とも別の話である。この理解しにくさが、透明性や説明可能性が求められる出発点になっている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-62","exam":"g","unit":"g-u10","keyword":"ブラックボックス","type":"choice","syllabus_ref":"10.6","stem":"ブラックボックスなAIモデルを社会で利用する際の、透明性・ガバナンスの観点からの考え方として、適切なものはどれか。","choices":["内部の根拠を示せないモデルは、どのような用途でも一切利用すべきではない","ブラックボックスであること自体が直ちに利用の可否を決めるのではなく、判断が人に与える影響の大きさに応じて、求められる説明や検証の水準を変え、解釈しやすいモデルへの置き換え、事後的な説明、人間による監督などを組み合わせて対応するのが基本とされる","精度が高ければ、判断の根拠を示せなくても問題はないため、説明のための取組は不要である","モデルのパラメータを全て公開すれば、ブラックボックスの問題は解消する"],"answer":1,"explanation":"透明性の要求は一律ではなく、リスクや影響の大きさに応じた水準が求められる（リスクベースの考え方）。影響の大きい用途では、説明や記録、人間の関与の要求が強まる。精度の高さは根拠の検証可能性とは別の性質であり、パラメータの公開だけでは個別の判断の理由は読み取れない。逆に、あらゆる用途で一律に利用を禁じる考え方も、一般的な整理ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-63","exam":"g","unit":"g-u10","keyword":"説明可能性","type":"choice","syllabus_ref":"10.6","stem":"「説明可能性」と「透明性」の関係についての説明として、適切なものはどれか。","choices":["説明可能性とは、モデルのソースコードを全て公開することであり、透明性と同じ意味である","透明性とは、モデルの予測精度を数値で公表することだけを指す","説明可能性は、AIの判断について、根拠や理由を人間が理解できる形で示せる性質を指し、透明性は、AIが使われている事実や仕組み、データ、開発・運用の過程に関する情報が、関係者に分かる形で示されているという、より広い概念である","説明可能性は開発者だけに関係する性質であり、透明性は利用者だけに関係する概念である"],"answer":2,"explanation":"説明可能性は「個別の判断の理由を示せるか」に焦点を当てるのに対し、透明性は、利用の事実の開示、仕組みやデータに関する情報提供、過程の記録などを含む広い概念として整理される。ソースコードの公開は説明可能性そのものではなく、精度の公表も透明性の一要素にすぎない。どちらも、開発者だけでなく、利用者や判断の影響を受ける人を含む関係者との関係で論じられる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-64","exam":"g","unit":"g-u10","keyword":"説明可能性","type":"choice","syllabus_ref":"10.6","stem":"日本政府の「人間中心のAI社会原則」（2019年）における、透明性・説明に関する位置づけとして、適切なものはどれか。","choices":["同原則は技術開発の促進だけを目的とし、透明性や説明には触れていない","同原則は、AIの開発者にソースコードの全面公開を義務づけている","同原則は法律であり、透明性の義務に違反した場合の罰則が定められている","同原則は7つの社会原則の一つに「公平性、説明責任及び透明性の原則」を掲げ、AIを使っている事実や、データの取得・使用の方法について、用途や状況に応じた説明が得られることなどを求めている"],"answer":3,"explanation":"人間中心のAI社会原則は、2019年に統合イノベーション戦略推進会議が決定した原則であり、法律ではなく、罰則やソースコード公開の義務を定めるものではない。「公平性、説明責任及び透明性の原則」では、不当な差別を受けないことに加え、AIの利用の事実やデータの扱いについて、用途や状況に応じた説明が得られることが求められている。説明の内容や水準は一律ではなく、場面に応じて変わるという考え方が、ここでも前提になっている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-65","exam":"g","unit":"g-u10","keyword":"説明可能性","type":"choice","syllabus_ref":"10.6","stem":"説明可能性を確保するための技術的なアプローチの代表例の概要として、適切なものはどれか。","choices":["代表的なアプローチには、線形モデルや決定木のように、モデル自体の構造が人間にとって解釈しやすいものを使う方法と、学習済みの複雑なモデルに対して、判断に効いた特徴の寄与の大きさや、画像のどの部分に注目したかなどを事後的に示す手法がある","学習データを大量に集めて精度を上げることが、説明可能性を確保する技術である","モデルを大規模化してパラメータ数を増やすことで、判断の根拠は自動的に説明できるようになる","入出力を暗号化し、第三者から処理過程を見えなくすることが、説明可能性の確保につながる"],"answer":0,"explanation":"説明可能性の確保技術は、大きく、モデル自体を解釈しやすい構造にするアプローチと、複雑なモデルの判断を事後的に説明するアプローチに分けられる。後者には、特徴量ごとの寄与の大きさを示す手法や、画像のどの部分に注目したかを可視化する手法などがあり、これら個別の手法の仕組み自体は「モデルの解釈性」の技術領域で扱われる。データ量やモデル規模は精度に関わる要素であり、暗号化は秘匿のための仕組みで、いずれも説明可能性の確保とは別の話である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-66","exam":"g","unit":"g-u10","keyword":"説明可能性","type":"choice","syllabus_ref":"10.6","stem":"AIの判断について説明を行う際に考慮すべき事項として、適切なものはどれか。","choices":["説明は、専門的な内容を省略せず、開発者向けの技術的な詳細を全ての受け手にそのまま示すのがよい","説明の受け手（専門家か、判断の影響を受ける一般の人か）に応じて、内容や表現の分かりやすさを調整する必要がある。また、もっともらしく見えても実際の判断過程を正しく反映していない説明は、誤った信頼を生むため、説明が判断の根拠を忠実に表しているかにも注意が要る","受け手が納得しさえすれば、説明の内容が実際の判断過程と異なっていても問題はない","説明は一度用意すれば、モデルの更新や利用場面の変化があっても見直す必要はない"],"answer":1,"explanation":"説明は、誰に向けたものかで求められる形が変わる。専門家には技術的な詳細が有効でも、判断の影響を受ける一般の人には、判断に効いた主な要素を平易に示す形が求められる。また、事後的な説明手法が生む説明は近似であり、実際の判断過程とずれ得る。納得感だけを目的にすると、検証の手段としての説明の意味が失われる。モデルや使い方の変化に応じて、説明の見直しも必要になる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-67","exam":"g","unit":"g-u10","keyword":"データの来歴","type":"choice","syllabus_ref":"10.6","stem":"「データの来歴」についての説明として、適切なものはどれか。","choices":["データが暗号化されて保管されてきた経路のことである","データへのアクセス権を持つ利用者の一覧のことである","データがどこから来たか（出所や収集の方法・時期）、どのような加工・変換・結合を経てきたかといった履歴を記録し、後からたどれるようにしておくことであり、データの素性を確認する手がかりになる","データの容量が時間とともにどう変化したかの記録のことである"],"answer":2,"explanation":"データの来歴（プロビナンス）は、出所と加工の履歴を指す。どのような経路で集められ、どう手を加えられたかがたどれることで、そのデータが学習などに使ってよいものか、偏りや問題が入り込む余地がなかったかを、後から検証できる。暗号化やアクセス権の管理はデータの保護の仕組みであり、容量の記録とも別の概念である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-68","exam":"g","unit":"g-u10","keyword":"データの来歴","type":"choice","syllabus_ref":"10.6","stem":"学習データの来歴を記録・確保することが、透明性や説明責任の観点で重要とされる理由として、適切なものはどれか。","choices":["来歴が記録されていれば、モデルの予測精度が自動的に向上するため","来歴の記録は、データの保管コストを削減するためのものである","来歴を公開すれば、個人情報や営業秘密を含むデータもそのまま開示できるようになるため","AIの判断に偏りや誤りなどの問題が見つかったとき、学習に使ったデータの出所や加工の履歴をたどることで、問題が入り込んだ過程を検証できる。また、データの入手が適法だったか、同意の範囲内だったかといった点も確認でき、関係者への説明の土台になる"],"answer":3,"explanation":"来歴は、問題が起きた後の検証と説明を可能にする基盤である。どのデータが、どのような経緯で学習に使われたかが分からなければ、偏りの原因の切り分けも、入手経路の適法性の確認もできない。精度の向上や保管コストとは直接の関係はなく、来歴の記録があること自体が、含まれる個人情報や秘密情報を無条件に開示してよい理由にはならない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-69","exam":"g","unit":"g-u10","keyword":"透明性","type":"choice","syllabus_ref":"10.6","stem":"AIの透明性を確保するための文書化の取組として、知られているものはどれか。","choices":["モデルに、その用途や想定する利用者、属性グループ別を含む性能評価の結果、既知の限界などを記した文書（モデルカード）を添付したり、データセットに、作成の目的や収集の過程、構成などを記した文書（データシート）を添付したりする取組がある","モデルの内部パラメータの値を全て印刷して公開することが、文書化の標準的な取組である","文書化とは、開発の会議の議事録を社内だけで保管することだけを指す","文書化の取組は、利用者への開示を目的としないため、性能や限界を文書に書く必要はない"],"answer":0,"explanation":"モデルカードは Mitchell らが2019年に提案した枠組みで、モデルの用途・性能・限界を利用者に伝えるための短い文書である。データシートは Gebru らが提案した、データセットの作成経緯や収集過程を記録する文書で、電子部品の仕様書（データシート）になぞらえた考え方である。どちらも、開発の前提と結果を文書として残し、使う側が自分の用途に適切かどうかを判断できるようにする点で、透明性を支える代表的な実践とされる。パラメータ値の羅列は文書化の目的（理解と判断の材料）に沿わず、議事録の内部保管だけでは関係者への情報提供にならない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-70","exam":"g","unit":"g-u10","keyword":"透明性","type":"choice","syllabus_ref":"10.6","stem":"AIにおける「透明性を与える対象」と、対象ごとに示される情報の関係として、適切なものはどれか。","choices":["透明性の対象はモデルの開発者だけで、利用者や判断の影響を受ける人に情報を示すことは想定されていない","対象は複数あり、判断の影響を受ける本人には、AIが判断に関与した事実や根拠の概要が、システムの利用者・導入者には、能力や限界、適切な使い方に関する情報が、監査や検証を行う者には、データやモデルの記録が、といったように、相手に応じて示す情報の内容や詳しさが変わる","全ての対象に対して、ソースコードを含む全く同じ情報を、同じ詳しさで示すことが求められる","透明性の対象は規制当局だけで、一般の利用者に情報を示すことは営業秘密の観点から認められていない"],"answer":1,"explanation":"透明性は、誰に対して何を示すかで中身が変わる。EUのAI法でも、高リスクのAIシステムについて、利用者（導入者）が出力を解釈して適切に使えるよう、用途・精度・限界などを記した利用のための情報を添えることが求められている（第13条）。判断の影響を受ける本人、導入・運用する組織、監査者など、対象ごとに必要な情報は異なり、一律の全面開示が求められるわけでも、対象が一部に限られるわけでもない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-71","exam":"g","unit":"g-u10","keyword":"透明性","type":"choice","syllabus_ref":"10.6","stem":"透明性を確保する取組を進めるうえでの考慮事項として、適切なものはどれか。","choices":["透明性のためには、営業秘密やセキュリティへの影響を考慮せず、あらゆる情報を開示すべきである","開示の範囲を調整することは、透明性の考え方に反するため、認められない","仕組みの詳細な開示は、営業秘密の漏洩につながったり、攻撃者に悪用の手がかりを与えたりするおそれがあるため、誰に・何を・どの詳しさで示すかを、目的と相手に応じて調整することが求められる。AI事業者ガイドラインの「透明性」も、ステークホルダーへの適切な情報提供を求めるもので、アルゴリズムやソースコードの開示を必ずしも想定していないとされる","透明性の取組は、開示する情報の量が多いほど常に評価が高くなる"],"answer":2,"explanation":"透明性は無条件の全面開示ではない。詳細な仕組みの開示は、知的財産の流出や、攻撃の手がかりの提供といった別のリスクを生む。そのため実務では、検証可能性を確保しつつ、相手と目的に応じた範囲と粒度で情報を出す調整が行われる。ガイドラインが求めるのも「適切な情報提供」であり、情報の量そのものが目的ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-72","exam":"g","unit":"g-u10","keyword":"説明可能性","type":"choice","syllabus_ref":"10.6","stem":"ある企業が採用選考にAIを導入している。不採用になった応募者から「AIが自分の評価にどう関わったのか、根拠を示してほしい」と求められた。透明性・説明責任の観点から、最も適切な対応はどれか。","choices":["「AIが判断したので、理由は分からない」と回答する","選考モデルのソースコードの全文を応募者に開示する","説明を求めること自体が想定されていないため、一切回答しない","AIが選考に関与した事実と、評価で重視された要素の概要を、応募者が理解できる形で説明する。その前提として、使ったデータやモデルの情報、AIの結果に対して人がどう関与したかの記録を、日頃から残しておく"],"answer":3,"explanation":"人の処遇に関わる判断では、影響を受ける本人への説明が特に求められる。説明は、技術的な全容の開示ではなく、本人が自分の評価のされ方を理解し、誤りがあれば指摘できる水準のものが想定される。それを可能にするには、判断の時点で後から説明できる記録（データ・モデルの素性、人の関与の経緯）が残っていることが前提になる。「AIだから分からない」は説明責任を果たしておらず、ソースコードの開示は本人の理解にも営業秘密の保護にもつながらない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目50「透明性」"},{"id":"g10-73","exam":"g","unit":"g-u10","keyword":"フィルターバブル","type":"choice","syllabus_ref":"10.7","stem":"「フィルターバブル」についての説明として、適切なものはどれか。","choices":["検索エンジンやSNSなどの推薦・パーソナライズの仕組みが、利用者の過去の行動や嗜好に合う情報を優先的に表示し、合わない情報を目に入りにくくすることで、利用者が自分の考えに近い情報ばかりに囲まれる状態を指す。エリ・パライザーが2011年の著書で広めた概念である","利用者が自分の意見と異なる情報源を自ら避け、同じ意見のメディアだけを選んで購読する行動のことである","偽情報だけを自動的に削除する、プラットフォームのフィルタリング機能のことである","インターネットへのアクセスが制限され、特定の国や地域の情報だけしか得られない状態のことである"],"answer":0,"explanation":"フィルターバブルの要点は、情報の偏りが利用者の選択だけでなく、プラットフォーム側のパーソナライズ（個別最適化）によって、本人が意識しないうちに生じる点にある。異なる情報源を自ら避ける行動は「選択的接触」と呼ばれる利用者側の傾向で、重なる部分はあるが同じ概念ではない。偽情報の削除機能や、国家によるアクセス制限とも別の話である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-74","exam":"g","unit":"g-u10","keyword":"フィルターバブル","type":"choice","syllabus_ref":"10.7","stem":"フィルターバブルが生じる仕組みについての説明として、適切なものはどれか。","choices":["利用者が検索のたびに表示条件を細かく設定し、自分の意見に合う結果だけを選んでいるために生じる","推薦アルゴリズムは、クリックや視聴、滞在時間などの行動履歴から利用者の嗜好を推定し、関心を持ちやすい情報（反応や滞在が得られやすい情報）を優先して表示するよう最適化される。この過程は利用者からは見えにくく、同じ検索語でも人によって異なる結果が返ることがある","プラットフォームが、政治的な立場ごとに表示する情報を意図的に分けているために生じる","偽情報の量が本物の情報より圧倒的に多いため、結果として偏った情報ばかりが表示される"],"answer":1,"explanation":"仕組みの中心は、嗜好の推定と、反応（エンゲージメント）の最大化を目的とした最適化であり、表示の調整は自動的・継続的に行われる。利用者が自分で表示条件を設定するわけではなく、プラットフォームが政治的立場で意図的に振り分けているという説明も、一般的な整理ではない。また、情報の偏りは偽情報の量だけでは説明できず、正確な情報であっても、嗜好に合うものばかりが優先されれば偏りは生じる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-75","exam":"g","unit":"g-u10","keyword":"フィルターバブル","type":"choice","syllabus_ref":"10.7","stem":"フィルターバブルが民主主義にとって問題とされる理由として、適切なものはどれか。","choices":["利用者の行動履歴が推薦アルゴリズムに利用されるため、プライバシーが侵害されるから","パーソナライズによって広告の精度が上がり、企業の宣伝効果が高くなりすぎるから","民主的な議論や選挙での判断は、有権者が一定の事実や争点を共有していることを前提とする。人によって目にする情報の世界が大きく分かれると、共通の前提のうえで意見を交換したり、相手の主張を検証したりすることが難しくなり、合意形成の基盤が弱まると指摘されているから","フィルターバブルがあると、利用者はインターネット上の情報に一切アクセスできなくなるから"],"answer":2,"explanation":"論点は、情報にアクセスできるかどうかではなく、アクセスする情報の構成が人ごとに分かれてしまうことにある。行動履歴の利用に伴うプライバシーは、推薦の仕組みに関わる別の論点であり、広告の宣伝効果は民主主義そのものの問題ではない。なお、フィルターバブルの実際の強さや、分極化への寄与の大きさについては、実証研究でも議論が続いている。ここで問うているのは、問題とされる理由の整理である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-76","exam":"g","unit":"g-u10","keyword":"エコーチェンバー","type":"choice","syllabus_ref":"10.7","stem":"「エコーチェンバー」についての説明として、適切なものはどれか。","choices":["SNSの投稿が、短時間に大量のアカウントから一斉に拡散される現象のことである","音声コンテンツを反響させて聞かせるための、配信プラットフォームの音響処理機能のことである","検索エンジンが、同じ利用者に同じ検索結果を繰り返し表示する仕様のことである","自分と似た意見を持つ人同士で主に交流する環境の中で、同じ主張が繰り返し聞かれ、あたかもそれが広く共有された意見であるかのように感じられたり、意見の偏りが強まったりする状態を指す。キャス・サンスティーンが2001年の著書で警告した概念として知られる"],"answer":3,"explanation":"エコーチェンバーは「反響室」の比喩で、交流する相手の同質性によって生じる情報環境の偏りを指す。投稿の大量拡散そのものや、音響処理、検索結果の表示仕様とは別の概念である。フィルターバブルがプラットフォームのパーソナライズを主因とするのに対し、こちらは人の交流の構造に着目する点が違いとされる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-77","exam":"g","unit":"g-u10","keyword":"エコーチェンバー","type":"choice","syllabus_ref":"10.7","stem":"エコーチェンバーと「集団分極化」の関係についての説明として、適切なものはどれか。","choices":["似た考えを持つ者同士で議論を重ねると、集団の意見が当初の傾向よりも極端な方向へ寄っていく現象が知られており（集団分極化）、エコーチェンバーは、この現象が起きやすい情報環境として論じられる。SNSのグループやフォローの構造が同質な交流を容易にすることが、その一因として指摘されている","集団分極化とは、エコーチェンバーの中で多様な意見に触れることで、集団の意見が穏健な中間へ収れんしていく現象のことである","エコーチェンバーの中にいると、外部の異なる意見が自動的に大量に届くため、意見の対立は自然に解消される","集団分極化は、面識のない大人数のランダムな集団でのみ起こり、同質な集団では起こらないとされている"],"answer":0,"explanation":"集団分極化は社会心理学で古くから知られる現象で、サンスティーンもこの知見を踏まえてエコーチェンバーの危険を論じた。意見が中間へ収れんする方向や、外部の意見が自動的に届いて対立が解消するという説明は逆であり、分極化は同質な集団でこそ起きやすいとされる点が要点である。SNSはその環境を大規模に作り出し得ることが論点になっているが、影響の実証的な評価については議論がある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-78","exam":"g","unit":"g-u10","keyword":"エコーチェンバー","type":"choice","syllabus_ref":"10.7","stem":"フィルターバブルとエコーチェンバーの違いについての説明として、適切なものはどれか。","choices":["フィルターバブルはオフラインの交流で生じ、エコーチェンバーはオンラインでのみ生じる現象である","フィルターバブルは、プラットフォームのパーソナライズ（アルゴリズムによる情報の選別）が主因とされる概念であり、エコーチェンバーは、自分と似た意見の人との交流が中心になるという、人の選択や交流の構造に着目する概念である。両者は重なって生じることも多いが、偏りを生む仕組みの説明が異なる","フィルターバブルは偽情報だけに関する概念で、エコーチェンバーは正確な情報だけに関する概念である","両者は全く同じ現象を指す別名であり、区別されることはない"],"answer":1,"explanation":"両概念はしばしば並べて論じられるが、フィルターバブルはアルゴリズム側の選別、エコーチェンバーは交流する相手の同質性という、仕組みの説明が異なる。どちらもオンライン・オフラインを問わず論じられるものであり、扱う情報の真偽を問う概念でもない。重なって現れることはあっても、同義語として扱われるわけではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-79","exam":"g","unit":"g-u10","keyword":"フェイクニュース","type":"choice","syllabus_ref":"10.7","stem":"フェイクニュース（偽情報）が選挙や民主的な過程に与える影響についての説明として、適切なものはどれか。","choices":["偽情報は、受け手が全員その真偽を見抜けるため、選挙の結果に影響することはあり得ない","偽情報の影響は、個々の有権者がだまされるかどうかだけの問題であり、組織的に拡散される場合でも性質は変わらない","選挙期間中に偽情報が大規模に拡散されると、有権者の判断材料そのものが歪められ得る。2016年の米大統領選では、ロシアの組織がSNS上に多数の偽アカウントを作り、米国の有権者を装って偽情報や対立をあおる情報を発信したとされ、米情報機関の評価報告書や、その後の起訴で組織的な介入の存在が指摘された。偽情報は、外国の勢力が他国の民主的過程に介入する手段にもなり得る","偽情報が選挙に影響したとされる事例は、まだ確認されていない"],"answer":2,"explanation":"2016年の米大統領選への介入については、米情報機関が共同で公表した評価（2017年）と、インターネット・リサーチ・エージェンシー関係者らへの起訴（2018年）という公的な記録がある。ロシア政府は関与を否定している。また、介入が選挙結果そのものを変えたかどうかは立証されておらず、ここでも「判断材料が歪められ得る」という水準に留めている。個々の有権者が真偽を見抜けるかではなく、組織的・大規模な拡散の構造そのものが論点である点も要点である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-80","exam":"g","unit":"g-u10","keyword":"フェイクニュース","type":"choice","syllabus_ref":"10.7","stem":"フェイクニュースやディープフェイクの蔓延が、民主主義にもたらす間接的な影響として指摘されているものはどれか。","choices":["有権者が政治への関心を失うことはなく、情報の真偽をめぐる議論が活発になるだけである","偽物が増えると本物の情報の価値が相対的に上がり、信頼できる報道機関への信頼は自動的に高まる","影響は偽の情報が信じられる場合に限られ、本物の情報が疑われるようになることはない","偽物が容易に作れることが広く知られるようになると、本物の映像や音声まで「偽物ではないか」と疑われるようになる。不都合な証拠を示された人物が「それはAIで作られた偽物だ」と主張して説明責任を逃れる余地が生まれることも指摘されており（「うそつきの配当」と呼ばれる）、何を事実として共有できるかという基盤そのものが弱まるとされる"],"answer":3,"explanation":"「うそつきの配当（liar’s dividend）」は、法学者のチェズニーとシトロンが2019年の論文で論じた概念で、偽物の存在が本物への疑いを可能にし、説明責任の回避に使われ得るという指摘である。影響は「偽を信じる」方向だけではなく「本物を信じられなくなる」方向にも及び、メディアや制度への信頼の低下につながると論じられる。偽物の増加によって信頼が自動的に回復するという整理はない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-81","exam":"g","unit":"g-u10","keyword":"民主主義","type":"choice","syllabus_ref":"10.7","stem":"選挙における「マイクロターゲティング」と、ケンブリッジ・アナリティカ事件についての説明として、適切なものはどれか。","choices":["マイクロターゲティングは、有権者の個人データから関心や心理的特性を推定し、小さな集団や個人ごとに内容を変えた政治広告を届ける手法である。2018年に表面化したケンブリッジ・アナリティカ事件では、性格診断アプリを通じて集められた、最大で約8,700万人分のフェイスブック利用者のデータが、本人の十分な同意なく同社に渡り、2016年の米大統領選などで有権者への働きかけに使われたとされる。個別に届く広告は公開の場で検証や反論を受けにくく、有権者ごとに異なる主張が示されることで、共通の争点の形成が妨げられると指摘されている","マイクロターゲティングとは、全ての有権者に全く同じ広告を一斉に配信する手法のことであり、ケンブリッジ・アナリティカ事件とは無関係である","ケンブリッジ・アナリティカ事件は、選挙の投票集計システムが不正アクセスを受けた事件である","同事件で問題になったデータは、全て利用者本人の明示的な同意を得て収集されたものである"],"answer":0,"explanation":"データは、性格診断アプリの利用者本人（数十万人規模）だけでなく、その友人のデータまでが当時のプラットフォームの仕組みを通じて取得され、フェイスブック自身が、最大で約8,700万人分の情報が不適切に共有された可能性があると公表した。心理的特性に基づくターゲティングの実際の効果の大きさについては議論があるが、同意なきデータの利用と、公開の検証を受けにくい個別化された広告のあり方が、民主的な過程の観点から問題視された。投票集計システムへの不正アクセスの事件ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-82","exam":"g","unit":"g-u10","keyword":"民主主義","type":"choice","syllabus_ref":"10.7","stem":"SNS上の自動アカウント（ボット）や組織的なアカウント群が、民主主義にとって問題とされる理由として、適切なものはどれか。","choices":["ボットは投稿の翻訳や情報の収集に使われるだけであり、世論に影響を与えることはない","自動化された多数のアカウントが特定の意見や情報を一斉に発信・拡散すると、実際以上にその意見が多くの人に支持されているかのような見かけを作ることができる。世論がどうなっているかという認識そのものが有権者の判断に影響するため、出所を隠した組織的な発信は、世論形成をゆがめる手段になり得ると指摘されている","ボットの投稿は全てプラットフォームによって自動的に削除されるため、利用者の目に触れることはない","ボットを使うのは各国の政府だけであり、民間や個人が使うことはできない"],"answer":1,"explanation":"論点は、個々の投稿内容の真偽だけではなく、「多くの人がそう考えている」という見かけが作られることにある。発信の量や拡散のされ方は、話題の重要度や支持の広がりの目安として受け取られるため、組織的な水増しは世論についての認識を操作する。ボット自体には正当な用途もあるが、削除が完全に行われるわけではなく、利用の主体も政府に限らない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-83","exam":"g","unit":"g-u10","keyword":"民主主義","type":"choice","syllabus_ref":"10.7","stem":"「SNSや推薦アルゴリズムが社会の分極化を招いた」という見方について、実証研究を踏まえた理解として、適切なものはどれか。","choices":["実証研究によって、SNSが分極化の主因であることは既に証明されている","実証研究によって、SNSは分極化に一切関係していないことが証明されている","影響を指摘する議論は多いが、因果関係の実証は単純ではない。米国のデータを用いた研究（ボクセルら、2017年）では、分極化の進み方が大きかったのは、インターネットやSNSをあまり使わない高齢の層であり、SNSが分極化の主因だとする単純な説明には疑問が示された。フィルターバブルやエコーチェンバーの影響は、仕組みとしては指摘されつつも、その大きさや因果については議論が続いていると理解するのが適切である","分極化は経済的な要因だけで説明でき、情報環境は全く関係しないと結論づけられている"],"answer":2,"explanation":"ボクセル、ゲンツコウ、シャピロの研究（米国科学アカデミー紀要、2017年）は、複数の分極化の指標を用い、インターネット利用の少ない層ほど分極化の進展が大きかったことを示して、「ネットが主因」という見方に留保を付けた。だからといってSNSの影響が全くないと証明されたわけでもなく、影響の大きさと因果の向きは研究上の論点であり続けている。断定のどちら側にも寄らないことが、この論点の理解として求められる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-84","exam":"g","unit":"g-u10","keyword":"民主主義","type":"choice","syllabus_ref":"10.7","stem":"ある国の選挙期間中、特定の候補者に関する根拠の不明な情報が、出所を隠した多数の自動アカウントから一斉に拡散され始めた。民主主義の観点から、プラットフォーム事業者や制度に求められる対応として、最も適切なものはどれか。","choices":["政府が情報の真偽をその場で判断し、誤りと判断した投稿を直ちに全て削除するよう命じる","拡散を止める有効な手段はないため、何も対応しない","対抗する側の陣営も、同じように自動アカウントを使って自陣営に有利な情報を大量に拡散する","政治広告については出稿者や費用の負担者を明らかにし、誰が何を見せたかを後から検証できる記録（広告のライブラリ等）を残すこと、推薦の仕組みが選挙過程に与えるリスクを事業者自身が評価して対策を取ること、公式の選挙情報やファクトチェックへの導線を用意することなど、表現の自由との緊張に配慮しながら、発信の透明性と検証可能性を確保する対応が求められる。EUのデジタルサービス法は、大規模プラットフォームに選挙過程へのリスクの評価と軽減を求める枠組みの一つである"],"answer":3,"explanation":"政府が表現内容の真偽を直接判断して一律に削除する方式は、表現の自由や、権力による言論統制の観点から、別の民主主義上の問題を生む。同じ手法での対抗は、情報環境のゆがみを拡大させるだけである。実際の制度設計（EUのデジタルサービス法など）では、事業者にリスクの評価と軽減、政治広告の透明性、推薦システムに関する説明などを求める方向が取られており、削除の強制よりも、誰が・どのように発信しているかを見えるようにすることが軸になっている。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目51「民主主義」"},{"id":"g10-85","exam":"g","unit":"g-u10","keyword":"モデル学習の電力消費","type":"choice","syllabus_ref":"10.8","stem":"大規模な言語モデルなどの学習に、大きな電力が必要になる理由として、適切なものはどれか。","choices":["膨大な量の計算を、多数のGPUやTPUなどの演算装置で長時間にわたって並列に実行するためである。開発の過程では、試行錯誤やパラメータ調整のために学習が繰り返されることも多く、学習1回分にとどまらない電力が使われる。さらに、装置の発熱を冷やす冷却などの付帯設備も電力を消費する","学習データの保存に電力の大半が使われるためである","1回の学習は数秒で終わるが、学習していない間の待機電力が非常に大きいためである","学習に必要な電力は、主に利用者のスマートフォンやパソコンなどの端末側で消費されるためである"],"answer":0,"explanation":"学習の電力消費の中心は、モデルの規模とデータ量に応じた計算そのものであり、多数の演算装置を長時間稼働させることが大きな消費につながる。データを保存するストレージの消費は相対的に小さく、学習はデータセンター側で行われるもので、利用者の端末で消費される話でもない。なお、消費される電力量そのものと、それに伴うCO2排出量は別の量であり、排出量は電力の調達先（電源構成）によって変わる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-86","exam":"g","unit":"g-u10","keyword":"モデル学習の電力消費","type":"choice","syllabus_ref":"10.8","stem":"学習の環境負荷をめぐる議論のきっかけの一つとなった、Strubellらの2019年の論文による推計についての説明として、適切なものはどれか。","choices":["ニューラルアーキテクチャ探索（NAS）を伴うTransformerの学習では、CO2排出量は約0.09tと推計された","BERTの学習では、CO2排出量は約1.9tと推計され、旅客機の米国横断フライト1人分とほぼ同じ水準とされた","ニューラルアーキテクチャ探索（NAS）を伴うTransformerの学習では、CO2排出量は約62.6万ポンド（約284t）と推計され、米国の平均的な自動車の生涯排出量（約12.6万ポンド）のおよそ5台分に当たるとされた。ただしこれは前提を置いた推計であり、後の研究では前提の置き方によって大きく異なる値が示されている","同論文は、モデルの学習によるCO2排出量は無視できる水準だと結論づけた"],"answer":2,"explanation":"Strubellらの論文（2019年）は、自然言語処理モデルの学習にかかる電力とCO2排出量を推計し、特にアーキテクチャ探索を伴う学習の負荷の大きさを問題提起したことで知られる。Transformer単体の学習は約192ポンド（約0.09t）、BERTは約1,438ポンド（約0.65t）で、後者は米国横断フライト1人分（約1,984ポンド）と同程度とされた。いずれの数値も、データセンターの効率（PUE）や電力の排出係数に平均的な値を仮定した推計であり、確定した実測値ではない点に注意が要る。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-87","exam":"g","unit":"g-u10","keyword":"モデル学習の電力消費","type":"choice","syllabus_ref":"10.8","stem":"Pattersonらの2021年の論文は、大規模言語モデルGPT-3の学習に要した電力量を約1,287MWhと推計した。この電力を、CO2排出係数0.429kg/kWhの電力系統から調達したと仮定した場合、CO2排出量はおよそ何tになるか。","choices":["約55t","約552t","約1,287t","約5,520t"],"answer":1,"explanation":"計算は、1,287MWh＝1,287,000kWhに排出係数0.429kg/kWhを掛けて、約552,000kg、すなわち約552tとなる。これは同論文が示したGPT-3の学習に伴う排出量の推計値（約552t）と一致する。ただしこの値は、電力量の推計と排出係数という前提の上に立つ推計であり、実際にどのデータセンターで、どのような電源構成の電力が使われたかによって変わり得る。電力量が同じでも、排出量は調達する電力によって大きく異なることが要点である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-88","exam":"g","unit":"g-u10","keyword":"モデル学習の電力消費","type":"choice","syllabus_ref":"10.8","stem":"同じニューラルアーキテクチャ探索（NAS）を伴う学習について、Strubellら（2019年）は約284t、Pattersonら（2021年）は約3tと、大きく異なるCO2排出量の推計を示した。この食い違いが生じた主な理由として、適切なものはどれか。","choices":["どちらか一方の研究が、単純な計算ミスをしていたためである","2つの研究が対象にしたモデルが、まったく別のものだったためである","CO2排出量の定義が、国によって異なるためである","データセンターの効率（PUE）や電力の炭素強度に、世界・米国平均の値を仮定するか、実際に使われたデータセンターの値を用いるか、また探索に要した計算量をどう見積もるかなど、前提の置き方が異なったためである。推計値は前提に強く依存し、単一の数値を確定的な事実として扱うことはできない"],"answer":3,"explanation":"Pattersonらは、実際に学習が行われたデータセンターの効率や炭素強度を用い、探索の計算量の見積もりも見直した結果、大幅に小さい値を示した。どちらの推計が「間違い」という話ではなく、消費電力量の見積もり方と、電力から排出量へ換算する際の前提が結果を大きく左右することの表れである。学習の排出量を論じる際は、数値そのものだけでなく、出典と前提（いつの、どの設備で、どの電源構成か）を併せて確認する必要がある。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-89","exam":"g","unit":"g-u10","keyword":"気候変動","type":"choice","syllabus_ref":"10.8","stem":"「AIと気候変動」の関係について議論されていることの整理として、適切なものはどれか。","choices":["AIの利用は環境とは無関係であり、気候変動との関係が議論されることはない","AIを使えば、温室効果ガスの排出は自動的にゼロになる","AIの学習や運用は、電力消費を通じて温室効果ガスの排出源になり得る一方で、気象予測の高度化やエネルギーシステムの最適化など、気候変動への対策や適応に役立つ面もある。このため、環境負荷の側面と、対策に貢献する側面の両方から議論されている","AIの環境負荷は学習のときに限られ、気候変動対策への利用は議論されていない"],"answer":2,"explanation":"この中項目で問われているのは、AIと環境保護をめぐる議論の全体像である。負荷の側では、学習だけでなく運用（推論）も含めた電力消費や、それに伴う排出が論点になる。貢献の側では、気象・気候の予測、電力需要の予測や系統の運用最適化、省エネルギーの制御などが挙げられる。どちらか一方だけを見るのではなく、負荷と貢献の両面を、規模や前提とともに評価することが議論の前提になっている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-90","exam":"g","unit":"g-u10","keyword":"気候変動","type":"choice","syllabus_ref":"10.8","stem":"国際エネルギー機関（IEA）の報告（2024年）による、世界のデータセンター等の電力消費についての説明として、適切なものはどれか。","choices":["データセンター等の電力消費は、2022年の約460TWh（世界の電力消費の約2%）から減少に転じている","データセンター、AI、暗号資産を合わせた電力消費は、2022年に約460TWh（世界の電力消費の約2%）で、2026年には620〜1,050TWhの範囲まで増え得ると見通された。AI関連の需要の伸びが、その押し上げ要因の一つとして挙げられている。見通しに幅があるのは、普及の速さや効率改善の進み方によって変わるためである","データセンター等の電力消費は、世界の電力消費の約半分を占めている","AIの電力消費だけで、2022年時点で約460TWhに達していた"],"answer":1,"explanation":"IEAの見通しは、データセンター単体ではなく、データセンター・AI・暗号資産を合わせた推計である点に注意が要る。460TWhという数値を「AIだけ」の消費と読むのは正確ではない。また、2026年の見通しは620〜1,050TWhという幅のある予測であり、効率改善の進展や需要の伸び方によって結果が変わる。社会全体の電力の中でデータセンター等が占める割合の増大と、それをまかなう電源の構成が、気候変動の観点からの論点になっている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-91","exam":"g","unit":"g-u10","keyword":"気候変動","type":"choice","syllabus_ref":"10.8","stem":"AIが気候変動への適応や対策に役立つ事例として、気象予測モデル「GraphCast」についての説明として、適切なものはどれか。","choices":["機械学習で構築された気象予測モデルで、欧州中期予報センター（ECMWF）の従来型の高精度予報システムと比較し、検証対象の約9割でそれを上回る精度を示したと報告された（Lamら、Science誌、2023年）。台風の進路予測など異常気象の予測にも役立つとされ、災害への備えを通じた気候変動への適応に貢献し得る事例として知られる","AIは気象予測には利用できず、従来の物理シミュレーションだけが使われている","GraphCastは、精度では従来手法に及ばない代わりに、計算が速いことだけが評価されたモデルである","GraphCastは、大気中のCO2を直接取り除くための装置を制御するシステムである"],"answer":0,"explanation":"GraphCastは、過去の気象データから学習したモデルで、10日先までの予報を短時間で出せることも特徴である。気象予測の高度化は、異常気象への備えや、再生可能エネルギーの発電量予測などを通じて、気候変動への適応と対策の両方に関わる。なお、この事例はAIの「貢献」の側の例であり、AIの学習・運用自体の環境負荷が無くなることを意味するものではない。両面を分けて評価する姿勢が、この分野の議論の前提である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-92","exam":"g","unit":"g-u10","keyword":"環境保護","type":"choice","syllabus_ref":"10.8","stem":"AIによる省エネルギーへの貢献の事例として、GoogleのデータセンターにおけるDeepMindの機械学習の活用についての説明として、適切なものはどれか。","choices":["機械学習の活用により、データセンターの冷却に使うエネルギーが約40%増加した","機械学習の活用により、サーバの計算そのものに使うエネルギーが約40%削減された","機械学習の活用により、データセンターの冷却をすべて廃止することができた","データセンター内の多数のセンサのデータから学習した機械学習モデルで冷却の運用を最適化し、冷却に使うエネルギーを最大で約40%削減したと、2016年にGoogleとDeepMindが公表した。データセンター全体の効率指標（PUE）の改善にもつながったとされる"],"answer":3,"explanation":"この事例は、AIがエネルギーを消費する側であると同時に、エネルギー消費を最適化する側にも回り得ることを示す代表例として知られる。削減されたのは冷却に使うエネルギーであり、計算そのものの消費が同率で減ったわけではない点に注意が要る。また、これは特定の事業者の高度に最適化された設備での公表事例であり、あらゆるデータセンターで同じ効果が得られると一般化はできない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-93","exam":"g","unit":"g-u10","keyword":"環境保護","type":"choice","syllabus_ref":"10.8","stem":"AIの電力消費を考えるとき、「学習」だけでなく「推論」にも注目すべきだとされる理由として、適切なものはどれか。","choices":["推論は1回あたりの電力消費が、学習1回分よりも大きいためである","学習は一度行えば終わるのに対し、推論はサービスが使われるたびに繰り返し実行され、利用が大規模になるほど累積の消費が大きくなるためである。Googleの分析では、同社の機械学習のエネルギー使用のうち、2019年から2021年にかけて約60%が推論、約40%が学習だったと報告されている","推論には電力が一切使われないため、学習だけを数えれば十分だからである","学習は何度も繰り返されるが、推論は各利用者につき1回しか実行されないためである"],"answer":1,"explanation":"1回の推論の消費は小さいが、利用回数が膨大になると、モデルの運用期間を通じた累積では学習を上回り得る。このため、環境負荷の評価は、学習時の一時的な消費だけでなく、運用時の消費を含めたライフサイクル全体で見る必要があると議論されている。なお、学習と推論の比率は、サービスの利用規模や運用期間によって変わるもので、ここで挙げた約60%対約40%は、特定の事業者の一定期間の分析に基づく数字である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-94","exam":"g","unit":"g-u10","keyword":"環境保護","type":"choice","syllabus_ref":"10.8","stem":"データセンターの環境負荷は、電力消費やCO2排出だけではない。水の消費に関する、Liらの2023年の研究による推計についての説明として、適切なものはどれか。","choices":["GPT-3を米国のデータセンターで学習させた場合、冷却に伴ってデータセンターの敷地内で蒸発する水の量が、約70万リットルに上ると推計された。水の消費量は、データセンターの立地や冷却方式によって大きく変わるとされる","データセンターの冷却には水は使われず、空気だけで冷やされているため、水の消費はゼロである","GPT-3の学習で消費された水は、約70リットルと推計された","データセンターの冷却に使われるのは海水のみであり、淡水の消費は問題にならない"],"answer":0,"explanation":"データセンターでは、冷却のために大量の水が蒸発によって消費されることがある。Liらの研究は、AIの環境負荷をCO2だけでなく水の観点からも捉えるべきだと問題提起したもので、約70万リットルという数値は、特定の立地と設備を前提とした推計である。発電に伴う水の消費まで含めるかどうかでも値は変わる。電力・CO2と同様に、水についても、数値は前提と併せて理解する必要がある。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-95","exam":"g","unit":"g-u10","keyword":"環境保護","type":"choice","syllabus_ref":"10.8","stem":"EUのAI法における、AIモデルのエネルギー消費に関する規定についての説明として、適切なものはどれか。","choices":["汎用AIモデルの学習に使う電力量には上限が定められ、上限を超えた学習は禁止されている","エネルギー消費量の多いモデルについては、再生可能エネルギー100%での運用が義務付けられている","汎用AIモデルの提供者は、技術文書の中に、そのモデルの「既知の、または推定されたエネルギー消費量」を含めることが求められる（第53条・附属書XI）。消費量が不明な場合は、使われた計算資源の情報から見積もることも認められている。排出量そのものの上限を課す規定ではなく、測定と文書化を通じた透明性の仕組みである","エネルギー消費は企業の自由な判断に委ねられており、AI法では一切触れられていない"],"answer":2,"explanation":"EU AI法のこの規定は、汎用AIモデルの提供者が作成する技術文書の記載事項として、エネルギー消費量（実測できない場合は推定値）を位置づけたものである。環境負荷を「測って、記録して、求められれば示せる」状態にすることが狙いで、消費や排出の上限規制とは性格が異なる。OECDのAI原則でも「包摂的な成長、持続可能な開発及び幸福」が原則の一つに掲げられており、環境への配慮と、その前提としての測定・開示は、国際的な議論に共通する方向である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-96","exam":"g","unit":"g-u10","keyword":"環境保護","type":"choice","syllabus_ref":"10.8","stem":"ある企業が、大規模なAIモデルを開発・運用するにあたり、性能を保ちながら環境負荷を抑えたいと考えている。対応として、最も適切なものはどれか。","choices":["排出量を相殺するクレジットを購入することだけに集中し、消費電力そのものの測定や削減は行わない","モデルを大きくすれば計算効率が上がるため、性能が頭打ちでも規模の拡大を続ける","環境負荷が問題になるため、AIの開発と利用をすべて中止する","学習や推論にかかる電力を測定し、効率の良いモデルや演算装置の選択、電力の炭素強度が低い地域や時間帯での学習の実施、運用時の効率化などを組み合わせ、消費量や排出量を記録して開示できる状態にする"],"answer":3,"explanation":"環境負荷への対応は、単一の手段ではなく、測定を前提に、モデルの効率、設備の効率、電力の調達先と実行のタイミング、運用の最適化を組み合わせることが基本になる。相殺（オフセット）だけに頼る姿勢は、消費そのものの把握や削減を伴わない点で不十分とされる。また、効率化が進んでも、利用の拡大によって全体の消費が増えることがある（リバウンド）ため、単位あたりの効率だけでなく総量の推移を見ることも論点になる。開発をすべて止めることは、AIが気候変動対策に貢献する側面を放棄することにもなる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目52「環境保護」"},{"id":"g10-97","exam":"g","unit":"g-u10","keyword":"労働政策","type":"choice","syllabus_ref":"10.9","stem":"AIの普及が雇用に与える影響について、現在の議論の整理として、適切なものはどれか。","choices":["AIによって一部の仕事や業務が代替される可能性がある一方で、新しい仕事が生まれたり、既存の仕事の内容が変わって人間とAIの分担が進んだりする面もあり、影響は「代替」だけでは捉えられないと議論されている","AIが普及すれば、すべての仕事が短期間のうちにAIに置き換わると結論づけられている","AIは雇用に一切影響を与えないことが、実証によって確認されている","AIの影響は製造業の肉体労働に限られ、事務や知的労働には及ばないとされている"],"answer":0,"explanation":"雇用の議論では、代替（仕事や業務の置き換え）、創出（新しい仕事の発生）、変化（仕事の内容や分担の変化）の三つの面を併せて見ることが前提になっている。影響の大きさや時期については、推計や予測によって見解が分かれており、特定の見通しを確定した結論として扱うことはできない。歴史的にも、技術革新は仕事を消すだけでなく、その形を変えてきた。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-98","exam":"g","unit":"g-u10","keyword":"労働政策","type":"choice","syllabus_ref":"10.9","stem":"フレイとオズボーンによる2013年の研究（『雇用の未来』）についての説明として、適切なものはどれか。","choices":["米国の雇用の約47%が、すでにAIによって代替されたという実績を報告した研究である","日本の労働人口を対象に、601種類の職業を分析した研究である","米国の702種類の職業を対象に、コンピュータ化によって代替される可能性が高い職業に、雇用の約47%が就いていると推計した研究である。ただし、これは技術的な代替可能性の推計であり、実際に雇用がその分失われるという予測ではない","職業ではなく個々の業務（タスク）単位で分析し、代替可能性が高い職業は約9%にとどまるとした研究である"],"answer":2,"explanation":"同研究は、米国の702の職業について、10〜20年程度のうちにコンピュータ化され得るかという技術的な可能性を職業単位で推計し、高いリスクの区分に雇用の約47%が入るとした。雇用の需給や社会の受け入れ方までは織り込んでおらず、「仕事の半分が消える」と受け取られがちである点は、後の議論でも注意されてきた。日本の労働人口の約49%という推計は、この手法を用いた野村総合研究所とオックスフォード大学の共同研究（2015年）によるものである。タスク単位で分析し直すと値が大きく下がるという研究（アーンツら、2016年）もある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-99","exam":"g","unit":"g-u10","keyword":"労働政策","type":"choice","syllabus_ref":"10.9","stem":"世界経済フォーラムの『雇用の未来レポート2025』は、2030年までに世界で約1億7,000万の仕事が新たに生まれ、約9,200万の仕事が失われる（代替される）と見通した。現在の世界の正式な雇用を約12億人とする同レポートの前提に立つと、創出と消失を合わせた雇用の変動は、現在の雇用のおよそ何%に当たるか。","choices":["約7%","約22%","約47%","約85%"],"answer":1,"explanation":"計算は、（1億7,000万＋9,200万）÷12億＝2億6,200万÷12億≒21.8%で、約22%となる。なお、創出から消失を差し引いた純増は約7,800万人で、現在の雇用の約7%に当たる。レポートは世界の企業への調査に基づく見通しであり、雇用が大きく入れ替わることを示す一方で、確定した予測ではない点に注意が要る。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-100","exam":"g","unit":"g-u10","keyword":"AIとの協働","type":"choice","syllabus_ref":"10.9","stem":"「AIとの協働」という考え方についての説明として、適切なものはどれか。","choices":["人間がAIの出力をそのまま受け入れ、判断もAIに任せる働き方のことである","AIを導入した業務では、人間は監視だけを行い、作業には一切関わらない働き方のことである","AIと人間が同じ仕事を競い合い、優れた方が仕事を担う仕組みのことである","大量の情報処理や定型的な作業などAIが得意な処理をAIが担い、判断や対人対応、創造的な仕事などを人間が担うように役割を分け、人間の能力を補い高め合う働き方のことである"],"answer":3,"explanation":"協働の要点は「置き換え」ではなく「補完・拡張」にある。AIの出力を人間が確認し、判断するという人間の関与を保ちながら分担することで、生産性や仕事の質を上げることが目指される。国際労働機関（ILO）の分析（2023年）でも、ほとんどの職業は一部のタスクだけが自動化の影響を受けるため、職業全体の代替よりも、仕事の拡張（補完）が中心になるとされている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-101","exam":"g","unit":"g-u10","keyword":"AIとの協働","type":"choice","syllabus_ref":"10.9","stem":"AIによる雇用の代替を考えるとき、「職業単位ではなくタスク（業務）単位で見るべきだ」とされる理由として、適切なものはどれか。","choices":["職業は複数のタスクの束であり、その一部が自動化されても、残りのタスクを人間が担うことで職業自体は残り、仕事の内容が変わることが多いためである。タスク単位で分析し直した研究では、大半のタスクが自動化可能な職業は約9%にとどまるという推計も示されている","タスク単位で見れば、すべての職業が完全に自動化できると分かるためである","タスクは職業とは無関係に存在し、職業への影響の分析には使えないためである","タスク単位の分析では、職業単位の分析よりもAIの影響を過大に見積もることになるためである"],"answer":0,"explanation":"アーンツ、グレゴリー、ジーラーン（2016年、OECDのワーキングペーパー）は、職業単位の推計（フレイとオズボーンの約47%）に対し、職業を構成するタスクの単位で分析し直し、大半のタスクが自動化されるリスクの高い仕事は、対象国の平均で約9%にとどまるという推計を示した。同じ「AIと雇用」の問題でも、分析の単位によって推計は大きく変わる。タスク単位の見方は、一部の業務をAIに任せて人間が残りの業務に集中するという、協働の設計にもつながる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-102","exam":"g","unit":"g-u10","keyword":"AIとの協働","type":"choice","syllabus_ref":"10.9","stem":"生成AIの支援ツールが実際の職場で生産性に与えた影響を調べた実証研究（ブリニョルフソンら、2023年）についての説明として、適切なものはどれか。","choices":["AI支援によって、経験豊富な担当者の生産性が最も大きく伸びたと報告された","AI支援による生産性の向上は、確認されなかったと報告された","顧客サポートの担当者約5,000人を対象とした調査で、AI支援により1時間あたりの対応件数が平均で約14%増え、特に経験の浅い担当者では約34%増えた。一方、経験豊富な担当者への効果は小さかったと報告された","AI支援ツールを導入した職場では、担当者の仕事がすべてAIに置き換えられたと報告された"],"answer":2,"explanation":"この研究（NBERワーキングペーパー、2023年）は、生成AIが仕事を置き換えたのではなく、担当者の作業を支援して生産性を上げた事例として知られる。熟練した担当者の対応のやり方をAIが広める形になり、経験の浅い層ほど恩恵が大きかったと分析されている。ただし、これは特定の企業・業務での実測であり、数値がすべての職場にそのまま当てはまるわけではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-103","exam":"g","unit":"g-u10","keyword":"スキルの喪失","type":"choice","syllabus_ref":"10.9","stem":"AIの利用に伴う「スキルの喪失」への懸念についての説明として、適切なものはどれか。","choices":["AIを使うと、人間の記憶そのものが物理的に失われるという医学的な現象のことである","AIに判断や作業を任せる機会が増えると、人間が自ら考えたり手を動かしたりする機会が減り、身についていた技能や判断力が衰えたり、そもそも身につかなくなったりするのではないかという懸念である","AIの導入によって、企業が保有する学習データが失われることである","スキルは一度身につければ、使う機会がなくても衰えることはないため、この懸念は不要と結論づけられている"],"answer":1,"explanation":"スキルの喪失は、自動化やAI支援が進むほど、人間が技能を使う場面が減ることへの懸念を指す。技能には使われなければ衰える面があり、ベテランから若手への技能の継承が細ることも問題になる。AIとの協働を設計する際には、人間が担い続ける部分や、技能を使う機会を意識的に残すことが論点になる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-104","exam":"g","unit":"g-u10","keyword":"スキルの喪失","type":"choice","syllabus_ref":"10.9","stem":"「自動化の皮肉」として知られる指摘についての説明として、適切なものはどれか。","choices":["自動化を進めると、かえって導入コストが増えて採算が合わなくなるという指摘である","自動化が進むほど、現場で必要になる人手が増えて効率が下がるという指摘である","自動化によって作業の負担は減るが、同時に賃金も下がっていくという指摘である","自動化によって人間が日常の作業から外れるほど、システムが想定外の事態に陥ったときに人間が引き継がなければならなくなるのに、そのための技能や状況を把握する力がかえって衰えてしまうという指摘である"],"answer":3,"explanation":"ベインブリッジが1983年に指摘した「自動化の皮肉（Ironies of Automation）」。自動化は人間の負担を減らす一方で、人間に残される役割を「監視と非常時の対応」という、より難しいものにする面がある。非常時に適切に介入するには技能の維持が必要だが、普段使わない技能ほど衰えやすいという緊張関係がある。AI支援が広がる場面でも、同様の論点として議論されている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-105","exam":"g","unit":"g-u10","keyword":"スキルの喪失","type":"choice","syllabus_ref":"10.9","stem":"ある企業が、業務にAIの支援ツールを導入するにあたり、従業員のスキルの喪失を防ぎながら活用したいと考えている。対応として、最も適切なものはどれか。","choices":["AIに任せる作業と人間が担い続ける作業を分け、AIの出力を確認・修正する過程を業務に組み込んだうえで、AIなしで作業する訓練や、必要になるスキルを学び直す（リスキリング）機会を用意する","スキルが衰えないよう、AIの利用をベテランの従業員だけに限定し、若手には一切使わせない","AIの出力は正確であるため確認の手間を省き、従業員には監視だけをさせる","スキルの喪失は避けられないため対策は取らず、AIへの全面的な移行を急ぐ"],"answer":0,"explanation":"スキルの喪失への対応は、AIを使わせないことではなく、使い方の設計である。人間が判断に関わり続ける形（出力の確認・修正）を業務に残し、技能を使う機会と学び直しの機会を確保することが、AIとの協働と技能の維持を両立させる方向として議論されている。若手に使わせない方法は、若手がAI活用のスキル自体を身につける機会を奪う面もある。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-106","exam":"g","unit":"g-u10","keyword":"労働力不足","type":"choice","syllabus_ref":"10.9","stem":"日本で労働力不足が深刻化するとされる背景についての説明として、適切なものはどれか。","choices":["日本の人口は増加を続けており、仕事の数だけが減っているためである","労働力不足は一時的な景気の変動によるもので、構造的な要因はないとされている","少子高齢化によって生産年齢人口（15〜64歳）が減少を続ける一方で、介護や物流など、高齢化が進んでも需要が減らない仕事も多く、働き手の供給が需要に追いつかなくなると見られているためである","AIの普及によって仕事が増えすぎたことが、労働力不足の主因であるとされている"],"answer":2,"explanation":"日本の労働力不足は、景気の波ではなく人口構造に根ざした構造的な問題とされる。働き手の中心である生産年齢人口は今後も減り続ける見通しで、需要の側は高齢者向けのサービスを中心に減りにくい。この需給のずれが、AIやロボットによる省力化・自動化への期待が高まる背景にもなっている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-107","exam":"g","unit":"g-u10","keyword":"労働力不足","type":"choice","syllabus_ref":"10.9","stem":"リクルートワークス研究所の試算（『未来予測2040』、2023年）についての説明として、適切なものはどれか。","choices":["2040年には、日本の労働力が約1,100万人余るという試算である","労働力不足は2030年までに解消するという試算である","不足するのはIT技術者だけで、他の職種では不足しないという試算である","2040年には、必要とされる労働力に対して供給が約1,100万人分不足するという試算である。介護や輸送、建設など生活を維持するサービスで不足が大きくなるとされ、機械化・自動化の徹底などが対応策として挙げられた"],"answer":3,"explanation":"この試算は、人口推計に基づくシミュレーションであり、将来の確定した事実ではない。不足への対応（自動化の推進、働き手の裾野の拡大、無駄の削減など）は政策や社会の選択に左右される。労働力不足の文脈では、AIの活用は「雇用を奪う」側面だけでなく、「担い手を補う」側面からも議論される。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-108","exam":"g","unit":"g-u10","keyword":"労働力不足","type":"choice","syllabus_ref":"10.9","stem":"労働力不足への対応としてAIやロボットを活用することについて、議論されている点として、適切なものはどれか。","choices":["AIやロボットを導入すれば、あらゆる職種の人手不足が直ちに解消される","記録や調整などの定型的な業務をAIやロボットが担うことで、限られた人手を、対人サービスなど人間にしかできない仕事に振り向けることができる可能性がある。一方で、導入にはコストや現場の体制づくりが必要であり、不足する分野の仕事のすべてを代替できるわけではないと議論されている","労働力不足の分野は対人サービスが中心であるため、AIは一切役に立たないと結論づけられている","人手不足は賃金の問題だけで生じるため、技術の活用とは無関係であるとされている"],"answer":1,"explanation":"不足への対応としてのAI活用は、仕事の置き換えではなく「補完」の発想で議論される。介護や接客など対人性の高い仕事は代替が難しく、記録作成や日程調整といった周辺業務をAIが担って人間の時間を生み出す形が、現実的な落とし所として挙げられる。効果は、技術そのものよりも、現場の業務をどう設計し直すかに依存する。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目53「労働政策」"},{"id":"g10-109","exam":"g","unit":"g-u10","keyword":"インクルージョン","type":"choice","syllabus_ref":"10.10","stem":"AIの倫理をめぐる議論で「インクルージョン（包摂）」が重視される理由として、適切なものはどれか。","choices":["AIの利用を専門家や技術者に限定し、一般の人が誤って使うことを防ぐためである","年齢、障害の有無、言語、経済状況などにかかわらず、誰もがAIの恩恵を受け、社会に参加できるようにすることが、社会の構成員を排除しないために重要だからである","AIの判断にすべての人を従わせ、社会の意見を一つにまとめるためである","インクルージョンとは、AIの学習データにできるだけ多くの個人情報を含めることを指すからである"],"answer":1,"explanation":"インクルージョンは「誰一人取り残さない」という考え方につながるもので、技術の恩恵が一部の人に偏らないようにする観点である。総務省の『情報通信白書』でも、年齢や地理的条件などによるデジタル格差を是正し、「誰一人取り残さない」デジタル化を実現することが課題として掲げられている。なお、公平性（中項目47）が主にAIの出力の偏りや差別を扱うのに対し、インクルージョンは「そもそも使えるか、参加できるか」というアクセスと参加の面に重心がある。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-110","exam":"g","unit":"g-u10","keyword":"インクルージョン","type":"choice","syllabus_ref":"10.10","stem":"AIの普及に伴って「格差が広がる」ことが懸念される理由として、適切なものはどれか。","choices":["AIの価格が下がれば、格差は自動的に解消すると結論づけられている","格差が生じるのは、AIの性能の差だけが原因であるとされている","端末や通信環境の有無に加え、使いこなす知識や身近な支援の有無によって、AIから得られる恩恵に差が生じる。年齢や地域、経済状況などによる既存のデジタル格差（デジタルデバイド）が、AIの場面でも拡大するおそれがあるためである","AIの利用格差は、都市部と地方の人口差だけによって生じるとされている"],"answer":2,"explanation":"総務省『情報通信白書』は、年齢や地理的条件などによってインターネットの利用率に差があることを指摘し、デジタル格差の是正を課題としてきた。AIについても、アクセスの環境（端末・通信）、使いこなすための知識（リテラシー）、身近な支援の有無が、得られる恩恵の差につながり得る。対策としては、地理的・経済的・身体的制約にかかわらず必要なときにデジタルを利用できる環境（アクセシビリティ）の確保や、支援体制の整備などが議論されている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-111","exam":"g","unit":"g-u10","keyword":"インクルージョン","type":"choice","syllabus_ref":"10.10","stem":"AI技術がインクルージョンを進める可能性と、その実現に向けた留意点についての説明として、適切なものはどれか。","choices":["音声認識や読み上げ、自動翻訳などのAI技術は、視覚や聴覚に障害のある人や高齢者、日本語を母語としない人の情報アクセスや社会参加を支え得る。一方で、想定する利用者の範囲が狭いと、かえって使えない人を生むため、設計の段階から多様な当事者の参加を得ることが重要とされる","AI技術は障害のない人の利用を前提に設計すべきであり、障害のある人への対応は別の仕組みに任せるのが適切とされる","支援技術としてのAIはすでに完成しており、当事者の意見を聞く必要はないとされる","AIによる支援は、対面による支援をすべて置き換えることを目的としている"],"answer":0,"explanation":"AIは情報アクセスの障壁を下げる技術でもある（音声と文字の相互変換、翻訳、要約など）。『情報通信白書』でも、電話リレーサービスや聴覚障害者向けの会議支援システムなど、障がい者の社会参画を後押しする機器やサービスの普及が掲げられてきた。ただし、設計の段階で当事者が関わらなければ、実際の使いにくさには気づけない。なお、開発体制そのものの多様性（ダイバーシティ）は中項目55「AIガバナンス」の論点であり、この問題では利用と参加の面に限って扱っている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-112","exam":"g","unit":"g-u10","keyword":"軍事利用","type":"choice","syllabus_ref":"10.10","stem":"「自律型致死兵器システム（LAWS）」についての説明として、適切なものはどれか。","choices":["人間が遠隔操作する無人機（ドローン）の総称である","軍事用のAIであれば、すべてLAWSに当たるとされている","サイバー攻撃に使われるAIを指す言葉である","標的の選定や攻撃の判断を、人間の関与なしに機械が自律的に行う兵器システムを指す。人間が最終的な判断に関与しない点が、倫理や法の観点から問題とされている"],"answer":3,"explanation":"LAWSは Lethal Autonomous Weapons Systems の略である。人間が遠隔操作する無人機は、人間の操作がある点で区別される。軍事利用のAIには、情報分析や意思決定の支援など、致死性を持たないものも多い。国際的には特定通常兵器使用禁止制限条約（CCW）の枠組みで議論が続いているが、現時点でLAWSの定義について国際的な合意があるわけではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-113","exam":"g","unit":"g-u10","keyword":"軍事利用","type":"choice","syllabus_ref":"10.10","stem":"特定通常兵器使用禁止制限条約（CCW）の枠組みで2019年に承認された、自律型致死兵器システム（LAWS）に関する指針（指導原則）の内容として、適切なものはどれか。","choices":["AIを搭載した兵器については、国際人道法は適用されないことが確認された","兵器の使用による結果の責任は、開発した機械自身が負うことが原則とされた","国際人道法は、LAWSを含むすべての兵器システムに完全に適用されること、兵器システムの使用に関する人間の責任は確保されなければならず、説明責任を機械に転嫁することはできないことが示された","LAWSの開発と使用は、直ちに全面的に禁止されることが決定された"],"answer":2,"explanation":"2019年のCCW締約国会合で承認された指針は、国際人道法の全面的な適用と、兵器システムのライフサイクルを通じた人間の責任の確保を柱とする。この指針は2021年の運用検討会議でも承認された。ただし、LAWSを全面的に禁止する条約が成立したわけではなく、規制の在り方については各国の立場に隔たりがあり、議論が続いている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-114","exam":"g","unit":"g-u10","keyword":"軍事利用","type":"choice","syllabus_ref":"10.10","stem":"自律型致死兵器システム（LAWS）に関する日本政府の立場についての説明として、適切なものはどれか。","choices":["日本政府は、人間の関与が及ばない完全自律型の致死性を有する兵器システムについては開発する意図がなく、国際的にも開発・使用は認められるべきではないとの立場を示している。一方、人間の関与が確保された自律性を有する兵器システムには、ヒューマンエラーの減少などの意義があるとして、国際的なルール作りに参加している","日本政府は、完全自律型の致死性兵器の開発を積極的に進める方針を示している","日本政府は、AIの軍事利用そのものを一切認めない立場を示している","日本政府は、LAWSについては立場を明らかにしておらず、国際的な議論にも参加していない"],"answer":0,"explanation":"防衛白書（令和元年版）は「人間の関与が及ばない完全自律型の致死性兵器の開発を行う意図はない」と明記した。2024年6月に外務省が公表した見解でも、人間中心の原則を維持し、国際人道法上の責任を問うことのできる人間の関与が必要だとしたうえで、完全自律型の致死性を有する兵器システムは、国際的にも開発・使用が認められるべきではないと主張している。立場の線引きの中心は「有意な人間の関与」の有無にある。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-115","exam":"g","unit":"g-u10","keyword":"死者への敬意","type":"choice","syllabus_ref":"10.10","stem":"死者に関する情報と個人情報保護法との関係についての説明として、適切なものはどれか。","choices":["死者の情報も、生者と同じく個人情報保護法の「個人情報」として全面的に保護される","死者の情報は、誰がどのように使っても一切問題にならないとされている","死者の情報が問題になるのは、著作権の侵害があった場合に限られる","個人情報保護法が対象とする「個人情報」は生存する個人に関する情報に限られるため、死者に関する情報そのものは同法の保護の対象ではない。ただし、その情報が同時に生存する遺族などに関する情報でもある場合は、遺族の個人情報として対象になり得る。なお、法律の対象外であることと、死者への敬意や遺族の感情への配慮が不要であることは、別の問題である"],"answer":3,"explanation":"個人情報保護委員会のガイドラインQ&Aでも、個人情報保護法は「個人情報」を生存する個人に関する情報に限っており、死者に関する情報は保護の対象とならないとされている（同時に遺族など生存する個人に関する情報でもある場合を除く）。一方、法の対象かどうかと、倫理的な配慮は別の層の問題である。デジタル遺品や故人のデータの利用では、死者への敬意や遺族の感情といった後者の観点からの議論が中心になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-116","exam":"g","unit":"g-u10","keyword":"死者への敬意","type":"choice","syllabus_ref":"10.10","stem":"故人の発言や声などのデータを学習し、故人との対話を再現するAI（いわゆるデッドボット／グリーフボット）をめぐる論点として、適切なものはどれか。","choices":["本人のデータだけを使うため、本人の意思の問題は生じないとされている","故人本人はすでに亡くなっており、生前に再現への同意や拒否を確認する仕組みがなければ、本人の意思に反する形で姿や発言が作られ得ること、AIが故人の言わなかったことまで生成し得ること、遺族の悲しむ過程に影響し得ることなどが論点になっている","遺族が望めば、どのような形で故人を再現しても問題はないと結論づけられている","このようなAIは技術的に実現不可能であり、議論は仮定のものにすぎない"],"answer":1,"explanation":"2020年には、特定の人物（故人を含む）の社会的データから、その人物らしく会話するチャットボットを作る技術の特許が米国で成立し、話題になった（マイクロソフトによるもの。同社は製品化の計画はないと表明したと報じられている）。ケンブリッジ大学の研究者らは2024年、こうしたサービスについて、データを提供する本人の生前の同意、再現であることの明示、利用者や遺族がいつでも利用をやめられる仕組みなどの安全策を提唱している。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-117","exam":"g","unit":"g-u10","keyword":"人間の自律性","type":"choice","syllabus_ref":"10.10","stem":"AI倫理で「人間の自律性」が守るべき価値とされる理由として、適切なものはどれか。","choices":["AIの推薦や誘導に無自覚に流されるのではなく、情報を吟味し、最終的には自分の意思で選択・決定できることが、人間が意思決定の主体であり続けるための基盤だからである","自律性とは、AIが人間から独立して自律的に動作する能力のことを指すからである","人間がAIの指示に常に従う状態を、自律性が高い状態と呼ぶからである","自律性は利便性と両立しないため、AIの利用をやめるべきだという結論が導かれるからである"],"answer":0,"explanation":"ここでの自律性は、機械の自律性ではなく、人間の意思決定の主体性のことである。AIが選択肢の提示や順位づけを担う場面が増えるほど、人間が「自分で決めた」と言える状態をどう保つかが問われる。内閣府の「人間中心のAI社会原則」（2019年）も、「人間の尊厳が尊重される社会」を基本理念の一つに掲げ、AIは人間の能力を拡張するものとして位置づけている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-118","exam":"g","unit":"g-u10","keyword":"人間の自律性","type":"choice","syllabus_ref":"10.10","stem":"人の自律性を守るための制度的な対応として、EUのAI法（AI規則）の内容に当たるものはどれか。","choices":["AIによる推薦を受けた場合は、その推薦に従うことを義務づけている","AIの利用者には、AIの判断を検証しないことが求められている","操作的なAIの利用は、利用者の同意があれば全面的に認められている","人の意識に上らない潜在意識的な手法や、意図的に操作・欺瞞する手法を用いて、十分な情報に基づく意思決定の能力を損ない、人の行動を実質的にゆがめるAIの利用を禁止している"],"answer":3,"explanation":"EU AI法第5条は、禁止されるAIの利用形態の一つとして、潜在意識的・操作的な手法によって人の行動を実質的にゆがめることを挙げている。欧州委員会のガイドラインは、この禁止の根拠を、操作や欺瞞、弱みの利用から個人の自律性とウェルビーイングを守ることに置いている。年齢や障害、社会的・経済的な状況による弱みにつけ込み、行動をゆがめる利用も、同様に禁止の対象とされている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-119","exam":"g","unit":"g-u10","keyword":"人間の自律性","type":"choice","syllabus_ref":"10.10","stem":"AIへの依存が進むことへの懸念のうち、「人間の自律性」の観点から論じられるものとして、適切なものはどれか。","choices":["AIに頼ることで、人間の技能そのものが衰えるという、技能面の懸念のことである","AIの利用が進むと、電気使用量が増えるという、環境面の懸念のことである","推薦や判断をAIに委ねる場面が増えるにつれ、自分で情報を集めて比較し、決めるという過程そのものが痩せ、気づかないうちにAIの提示する方向へ選択が寄せられていくという、意思決定の主体性に関する懸念である","AIへの依存は個人の選択に影響しないため、懸念は不要と結論づけられている"],"answer":2,"explanation":"技能が衰えることへの懸念は「スキルの喪失」（中項目53）として扱われる論点であり、自律性の懸念とは焦点が異なる。自律性の観点の中心は、決める力そのものではなく、「決めているのが自分かどうか」という主体性の側にある。対応としては、AIの推薦の根拠を示すこと（透明性）や、別の選択肢を検討する機会を残すことなどが議論されるが、あくまで人間の側の決定の在り方を守るためのものである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-120","exam":"g","unit":"g-u10","keyword":"死者への敬意","type":"choice","syllabus_ref":"10.10","stem":"ある企業が、利用者が生前に登録した音声や文章をもとに、死後、遺族がその人との対話を再現できるAIサービスの提供を検討している。「死者への敬意」の観点から、提供の設計として、最も適切なものはどれか。","choices":["遺族の求めがあれば、本人の生前の意思を確認する仕組みがなくても、登録されたデータで直ちに再現を開始する","本人が生前に、死後の再現に同意するかどうかを登録できる仕組みを設け、その意思を尊重する。再現であることを遺族に明示し、遺族側からいつでも利用の停止や削除ができるようにするなど、本人の意思と遺族の感情の双方に配慮する","本人のデータは相続財産として扱い、相続人の多数決だけで再現の可否を決める","再現の精度を上げるため、本人が生前に残さなかった発言も、故人らしい内容であれば積極的に生成して補う"],"answer":1,"explanation":"故人の再現では、本人の意思（生前に確認できる場合はその尊重）、遺族の感情、再現と現実の区別（AIが生成した発言を、故人の実際の発言と誤認させないこと）が論点になる。研究者らが提唱する安全策も、データ提供者の生前の同意、透明性、関係者が離脱できる仕組みを柱としている。本人が残さなかった発言の生成は、故人の人格をゆがめるおそれがあり、敬意の観点から特に慎重さが求められる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目54「その他の重要な価値」"},{"id":"g10-121","exam":"g","unit":"g-u10","keyword":"倫理アセスメント","type":"choice","syllabus_ref":"10.11","stem":"AI倫理アセスメントの必要性についての説明として、適切なものはどれか。","choices":["倫理アセスメントは、事故や問題が起きた後に原因を調べるための手続であり、開発・導入の前に行うものではない","AIが社会に与える影響は、広く使われるようになった後では手戻りのコストが大きいため、開発・導入の前の段階で、公平性やプライバシー、人権への影響などをあらかじめ評価し、問題の芽を早期に発見して、設計や利用方法に反映することが必要とされる","倫理アセスメントの目的はAIの精度や処理速度を測定することであり、倫理面の影響は対象に含まれない","倫理アセスメントは、すべてのAIに対して法令で一律の様式が義務づけられている手続であり、その様式に従うことだけが求められる"],"answer":1,"explanation":"倫理アセスメントは、AIが個人や社会に与える影響を事前に評価し、問題を未然に防ぐための取組である。AIシステムの影響評価は、AIマネジメントシステムの国際規格ISO/IEC 42001でも、計画段階で実施すべきものとして位置づけられている。一度社会に広がったAIの影響を取り戻すことは難しいため、「問題が起きてから直す」のではなく、早い段階で評価して設計や運用に反映する点に意味がある。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-122","exam":"g","unit":"g-u10","keyword":"倫理アセスメント","type":"choice","syllabus_ref":"10.11","stem":"AI倫理アセスメントを実施する際の進め方として、適切なものはどれか。","choices":["評価は導入前に一度行えば十分であり、運用開始後に利用条件や社会の状況が変わっても、見直す必要はない","チェックリストの項目をすべて満たしたことを確認する形式的な手続であり、項目に当てはまらない問題については実質的な判断は不要である","開発担当者だけで完結させず、法務や倫理、影響を受ける立場の知見など多様な視点を取り入れて評価し、結果を記録に残すとともに、問題が見つかれば設計の変更や利用範囲の限定などの対応につなげる","評価の結果は社外に説明するものではないため、記録に残す必要はない"],"answer":2,"explanation":"アセスメントは、チェックを付けること自体が目的ではなく、発見した問題への対応までを含めて意味を持つ。また、AIの使われ方や社会の状況は変わるため、導入前の一度きりではなく、変更や運用の節目で見直すことが求められる。開発者だけでは気づけない影響もあるため、多様な視点を取り入れることと、結果を記録して後の検証に使えるようにすることが重要である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-123","exam":"g","unit":"g-u10","keyword":"人間の関与","type":"choice","syllabus_ref":"10.11","stem":"AIガバナンスにおける「人間の関与（人間による監督）」についての説明として、適切なものはどれか。","choices":["AIの判断を人間が鵜呑みにせず、必要に応じて内容を確認し、介入・修正したり、利用を停止したりできるようにすることであり、影響の大きい判断では人間が最終的な決定を行う体制が求められる","人間の関与とは、AIのすべての出力を人間が事前に作成し、AIはそれを表示するだけにすることを指す","人間の関与とは、AIの判断結果に人間が形式的に承認の印を押すことを指し、内容の確認は伴わなくてよい","一度、人間が関与する体制を作れば、その後はAIの判断を監視し続ける必要はなくなる"],"answer":0,"explanation":"人間の関与の中心は、AIの出力を人間が主体的に確認し、誤りに気づいたときに止めたり直したりできる状態を保つことにある。EUのAI法も、高リスクのAIについて人間による監督を求め、監督する者が出力を解釈し、介入したり停止したりできることを挙げている。判断の影響が大きい場面ほど、人間が最終決定を行う体制（ヒューマン・イン・ザ・ループなど）の重要性が高まる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-124","exam":"g","unit":"g-u10","keyword":"人間の関与","type":"choice","syllabus_ref":"10.11","stem":"AIの開発・運用にステークホルダーが関与することの意味と必要性についての説明として、適切なものはどれか。","choices":["ステークホルダーの関与とは、株主に対して利益の配分を決める手続のことを指す","関与は開発の最終段階で一度だけ行えばよく、運用開始後は関係者の意見を聞く必要はない","意見を取り入れることは、寄せられた意見のすべてにそのまま従うことを意味する","利用者や、AIの判断の影響を受ける人、専門家、市民社会など、開発者以外の多様な関係者の声を取り入れることで、開発者だけでは気づけない影響や懸念を早い段階で把握し、対応に反映できる。また、関与の過程自体が、説明責任や信頼の基盤になる"],"answer":3,"explanation":"AI事業者ガイドラインは、AIガバナンスを「ステークホルダーによる技術的、組織的、及び社会的システムの設計並びに運用」と定義しており、関係者の関与をガバナンスの中心に置いている。意見を聞くことは、そのすべてに従うこととは別であり、聞いたうえで判断し、判断の理由を説明できることが求められる。影響を受ける人の声は、開発の早い段階ほど反映しやすい。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-125","exam":"g","unit":"g-u10","keyword":"AIポリシー","type":"choice","syllabus_ref":"10.11","stem":"組織が定める「AIポリシー」についての説明として、適切なものはどれか。","choices":["AIポリシーとは、AIシステムの技術仕様を定めた文書のことである","組織としてAIをどのような原則のもとで開発・利用するかの基本方針を明文化したものであり、経営層の関与のもとで定められ、個別の判断の拠り所になる。ただし、方針を定めるだけでは実効性は生まれず、体制の整備や教育、アセスメントや監査といった運用の仕組みと結びついて初めて機能する","AIポリシーは一度公表すれば、その内容は自動的に現場で守られるため、運用の仕組みを別に用意する必要はない","AIポリシーは法令そのものであり、違反した場合には罰則が伴う"],"answer":1,"explanation":"AIポリシーは、組織のAIに対する姿勢と原則を示す出発点である。AIマネジメントシステムの国際規格ISO/IEC 42001でも、トップマネジメントがAI方針を定めることが求められている。一方で、方針は宣言にすぎず、役割と責任の明確化、教育、アセスメント、監査、見直しといった運用の仕組みが伴わなければ、現場の判断は変わらない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-126","exam":"g","unit":"g-u10","keyword":"ダイバーシティ","type":"choice","syllabus_ref":"10.11","stem":"AIの開発やガバナンスに携わる人々の「ダイバーシティ（多様性）」が重視される理由として、適切なものはどれか。","choices":["ダイバーシティとは、AIの学習データを多様にすることを指す言葉であり、携わる人の構成は関係がない","多様な人材を集めれば、AIの公平性は自動的に保証される","性別や年齢、専門分野、文化的背景などが偏った体制では、学習データの偏りや、特定の人々への不利な影響に気づきにくい。多様な背景を持つ人々が関わることで、見落とされやすい問題に気づく機会が増えるためである","ダイバーシティは広報上の配慮であり、開発やガバナンスの実質とは関係がない"],"answer":2,"explanation":"偏りの問題の多くは、作る側・確かめる側の視点の偏りから見落とされる。「人間中心のAI社会原則」も、基本理念の一つに「多様な背景を持つ人々が多様な幸せを追求できる社会（Diversity & Inclusion）」を掲げている。なお、ここでのダイバーシティは、利用者側のアクセスや参加を扱ったインクルージョン（中項目54）と重なる面もあるが、主として作る側・統治する側の構成の多様性を指す。また、多様性は保証ではなく、見落としを減らす条件の一つである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-127","exam":"g","unit":"g-u10","keyword":"ダイバーシティ","type":"choice","syllabus_ref":"10.11","stem":"AI倫理を実現するための組織体制の在り方として、適切なものはどれか。","choices":["開発部門だけで判断を完結させず、法務・倫理・セキュリティなど多様な専門性を持つメンバーによる横断的な体制を置き、責任の所在を明確にしたうえで、開発の節目ごとに倫理面の確認を行う。必要に応じて、組織の外の専門家など、独立した立場からの意見を取り入れることも有効とされる","倫理面の判断は開発責任者が一人で行い、他の部門は関与しない方が迅速で望ましい","倫理委員会を設置すれば、個別の開発案件ごとに倫理面の確認を行う必要はなくなる","組織体制は形を整えることが目的であり、個別の判断に影響を与えるものではない"],"answer":0,"explanation":"倫理上の問題は、技術・法・社会の複数の観点にまたがるため、一部門・一人の判断では扱いきれない。横断的な体制、責任の所在の明確化、案件ごとの節目での確認、独立した立場からの意見が、体制の要点とされる。ISO/IEC 42001でも、役割と責任の明確化を含む内部組織に関する管理策が置かれている。委員会の設置自体が目的ではなく、実際の案件の判断に結びつくことが必要である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-128","exam":"g","unit":"g-u10","keyword":"AIに対する監査","type":"choice","syllabus_ref":"10.11","stem":"「AIに対する監査」についての説明として、適切なものはどれか。","choices":["監査とは、AIの出力の正確さを一度だけ測定する性能試験のことである","監査は開発した本人だけが行うものであり、独立性は求められない","監査の目的は、問題がないことを証明する文書を作ることにある","AIシステムやその運用が、定めた方針や基準、法令などに沿っているかを、証拠に基づいて独立した立場から確認する仕組みであり、実施する主体によって、組織内部の監査と、第三者による外部の監査がある。問題が見つかれば、是正につなげることが前提になる"],"answer":3,"explanation":"監査は、性能の測定ではなく、方針や基準への適合を、記録などの証拠に基づいて確かめる仕組みである。ISO/IEC 42001は、マネジメントシステムが機能しているかを確認する内部監査を求めており、認証の場面では外部の審査も行われる。監査で見つかった問題は、是正と改善につなげて初めて意味を持つ。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-129","exam":"g","unit":"g-u10","keyword":"モニタリング","type":"choice","syllabus_ref":"10.11","stem":"AIの運用開始後に「モニタリング（継続的な監視）」が必要とされる理由として、適切なものはどれか。","choices":["導入前の評価が完全であれば、運用開始後の監視は不要になる","AIの挙動は、扱うデータや利用環境、社会の変化によって導入時の想定からずれていくことがあり、精度の低下や新たな偏りが運用開始後に現れることもある。そのため、性能や公平性、利用の実態を継続的に確認し、変化を捉えて対応する必要があるためである","モニタリングの目的は、利用者の行動を監視して管理することだけにある","モニタリングは、法令で定められた一部のAIだけに関わる話であり、一般のAIには関係がない"],"answer":1,"explanation":"AIは、導入時点の評価だけでは、その後の振る舞いまで保証できない。再学習やデータの変化によって、導入時にはなかった偏りや性能の低下が生じることがある。EUのAI法も、高リスクのAIについて市販後モニタリングの仕組みを求めている。AI事業者ガイドラインが示す、環境・リスク分析から評価までを繰り返す継続的なガバナンス（アジャイル・ガバナンス）でも、運用段階の確認は欠かせない要素である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-130","exam":"g","unit":"g-u10","keyword":"モニタリング","type":"choice","syllabus_ref":"10.11","stem":"ある企業が、問い合わせ対応にAIチャットボットを導入して運用している。モニタリングで、特定の属性の利用者からの問い合わせに対して、誤った案内をする割合が導入当初より増えていることが分かった。AIガバナンスの観点から、企業の対応として最も適切なものはどれか。","choices":["誤案内の割合が増えていても、全体の精度が社内の基準を満たしている間は、特に対応は不要である","原因の調査は行わず、利用者向けの案内文だけを変更し、問題があったことは公表せずに対応を終える","まず記録を確認して原因の調査を始め、影響の大きさに応じて、当該機能の一時停止や利用範囲の限定も含めて判断する。調査結果と対応を記録し、関係するステークホルダーへの説明や、再発防止のための見直し（必要に応じた再アセスメント）につなげる","問題の記録は風評を招くため残さず、担当者の判断で静かに修正する"],"answer":2,"explanation":"モニタリングは、異常を検知して終わる仕組みではない。記録に基づく原因の調査、影響に応じた判断（停止や限定を含む）、関係者への説明、見直しまでが一連の対応である。問題の記録を残さないことは、原因の究明や説明責任の基盤を失わせる。特定の属性への影響の偏りは、全体の精度が基準内でも看過できない問題である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-131","exam":"g","unit":"g-u10","keyword":"再現性","type":"choice","syllabus_ref":"10.11","stem":"AIの開発・検証における「再現性」についての説明として、適切なものはどれか。","choices":["再現性とは、AIが過去の出力を記憶し、そのまま返す能力のことである","再現性は学術論文の世界だけの概念であり、実務の開発や運用には関係がない","再現性を確保すれば、AIの判断が倫理的に正しいことが保証される","使用したデータやモデルの条件、手順などを記録し、同じ条件で再び実行すれば同じ結果が得られる状態を保つことであり、結果の検証や、問題が起きた際の原因の切り分けを可能にする。再学習や更新で結果が変わるAIでは、条件の記録が特に重要になる"],"answer":3,"explanation":"再現性は、得られた結果を後から確かめ直せる状態のことであり、監査や検証の前提になる。再現性がなければ、問題が起きたときに、データの問題か、モデルの条件の問題かを切り分けることも難しい。ただし、再現できることは、結果が正しいことや倫理的であることの保証ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g10-132","exam":"g","unit":"g-u10","keyword":"トレーサビリティ","type":"choice","syllabus_ref":"10.11","stem":"AIガバナンスにおける「トレーサビリティ（追跡可能性）」についての説明として、適切なものはどれか。","choices":["どのデータやモデル、バージョン、設定を用いて、いつ、どのような判断や生成が行われたかを、記録をもとに後からたどれる状態にしておくことであり、問題発生時の原因究明や、説明責任を果たすための基盤になる。再現性が「同じ結果を再び得られること」であるのに対し、トレーサビリティは「過程を後から追えること」に重心がある","トレーサビリティとは、利用者の位置情報を追跡する技術のことである","トレーサビリティを確保すれば、AIの判断過程のすべてを人間が理解できることが保証される","トレーサビリティは、記録を外部にすべて公開することと同義である"],"answer":0,"explanation":"トレーサビリティは、記録（ログ）をもとに、判断や生成の過程を事後的にたどれる状態を指す。EUのAI法も、高リスクのAIについて、記録を自動的に生成する機能（ロギング）を求めている。なお、記録が残っていることと、その内容を人間が理解できること（説明可能性、中項目50）は別の問題であり、記録の保持と、どこまで公開するかも別の判断である。ここでは、透明性の確保技術としてではなく、ガバナンスの基盤としての記録と追跡を扱っている。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目10「AI倫理・AIガバナンス」中項目55「AIガバナンス」"},{"id":"g2-01","exam":"g","unit":"g-u2","keyword":"探索木","type":"choice","syllabus_ref":"2.1","stem":"探索・推論における「探索木」についての説明として、適切なものはどれか。","choices":["初期状態を根とし、そこからたどることのできる状態を枝で結んで広げた木構造であり、目標状態に当たるノードまでの経路が解になる","学習データを分類するための木構造で、葉に分類の結果を持たせたもののことである","ニューラルネットワークの層どうしの接続を表した図のことである","知識を概念どうしの階層的な関係として表したネットワークのことである"],"answer":0,"explanation":"探索木は、問題の状態と、その状態から移ることのできる次の状態を、根（初期状態）から枝分かれする木として表したものである。根から目標状態のノードまでの経路が、そのまま解（行動の系列）になる。学習データの分類に使う木は決定木（中項目7「教師あり学習」）、概念の関係を表すネットワークは意味ネットワーク（中項目4「知識表現とエキスパートシステム」）であり、いずれも探索木とは別のものである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-02","exam":"g","unit":"g-u2","keyword":"幅優先探索","type":"choice","syllabus_ref":"2.1","stem":"幅優先探索についての説明として、適切なものはどれか。","choices":["根から最も深いところまで一気にたどり、行き詰まったら戻って別の枝を試す方法である","根に近い浅いノードから順に、同じ深さのノードを広げていく方法であり、1手のコストが均一であれば、最小の手数で目標に到達する経路が得られる","目標に近いと見込まれる度合い（評価値）の高いノードを優先して広げる方法である","ノードをランダムに選んで広げていく方法である"],"answer":1,"explanation":"幅優先探索は、浅いノードから順に同心円状に広げていく探索であり、キュー（先入れ先出し）で管理される。浅いところから順に調べるため、コストが均一な場合は最初に見つけた目標への経路が最小手数になる。一方で、同じ深さのノードを大量に保持するため、深さが増すとメモリの消費が大きくなる。深くたどってから戻る方法は深さ優先探索、評価値で優先順位を付ける方法は最良優先探索などと呼ばれる別の手法である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-03","exam":"g","unit":"g-u2","keyword":"深さ優先探索","type":"choice","syllabus_ref":"2.1","stem":"深さ優先探索についての説明として、適切なものはどれか。","choices":["浅いノードから順に広げていくため、常に最短の経路が得られる方法である","すべてのノードを深さの順に並べ替えてから探索する方法である","一つの枝をできるだけ深くたどり、行き詰まったら直前の分岐まで戻って（バックトラック）別の枝を試す方法であり、幅優先探索に比べて必要なメモリが少ない","目標に近いと見込まれるノードだけを選んで探索する方法である"],"answer":2,"explanation":"深さ優先探索は、一つの経路を深くたどり、行き詰まれば戻って別の枝を試す方法である。保持するのは現在の経路と戻るための分岐点が中心であり、必要なメモリは深さに比例する程度で済む。ただし、最初に見つけた解が最短であるとは限らず、枝が無限に続く木では目標に到達できないまま深く入り込むおそれもある。最短の経路が保証されるのは幅優先探索（コスト均一の場合）である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-04","exam":"g","unit":"g-u2","keyword":"幅優先探索・深さ優先探索","type":"choice","syllabus_ref":"2.1","stem":"分岐数が3で深さが2の探索木がある。根から3つの子（A・B・C）が出て、A・B・Cのそれぞれから3つの子が出ている。目標状態はAの2番目の子（A2）である。左の子から順にたどり、根と目標を含めて「訪れたノードの数」を数えると、幅優先探索と深さ優先探索ではそれぞれいくつになるか。","choices":["幅優先探索では4個、深さ優先探索では6個","幅優先探索では6個、深さ優先探索では6個","幅優先探索では5個、深さ優先探索では4個","幅優先探索では6個、深さ優先探索では4個"],"answer":3,"explanation":"幅優先探索は浅い順にたどるため、根→A→B→C→A1→A2 の順になり、目標は6個目に訪れる。深さ優先探索は左の枝を深くたどるため、根→A→A1→A2 の順になり、目標は4個目に訪れる。目標が浅く左寄りにある場合は深さ優先探索が速いが、逆に目標が深い位置や右寄りの枝にある場合は、深さ優先探索が遠回りになることもある。どちらの手法が有利かは、木の形と目標の位置に依存する。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-05","exam":"g","unit":"g-u2","keyword":"ブルートフォース","type":"choice","syllabus_ref":"2.1","stem":"ブルートフォース（総当たり）についての説明として、適切なものはどれか。","choices":["考えられる候補を手がかりなしにすべて列挙して一つずつ確かめる方法であり、候補の数が小さいうちは確実だが、候補が増えると組み合わせの数が爆発的に増え、現実的な時間では終わらなくなる","有望な候補だけを評価関数で選んで確かめる方法である","候補をランダムに抽出し、確率的に確かめる方法である","過去の成功例のパターンを学習して候補を絞り込む方法である"],"answer":0,"explanation":"ブルートフォースは、手がかり（ヒューリスティクス）を使わず、候補をすべて試す力任せの方法である。候補の数が少ない問題では単純で確実だが、候補の数が増えると組み合わせが爆発的に増える（組み合わせ爆発）ため、大規模な問題には使えない。探索や推論の工夫の多くは、この総当たりを避け、候補をいかに絞るかという点に向けられてきた。ランダムに抽出して確率的に確かめる方法はモンテカルロ法である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-06","exam":"g","unit":"g-u2","keyword":"ハノイの塔","type":"choice","syllabus_ref":"2.1","stem":"ハノイの塔は、探索・推論の具体例として知られるパズルである。3本の柱と大きさの異なる3枚の円盤があり、円盤は1回に1枚だけ動かすことができ、小さい円盤の上に大きい円盤を置くことはできない。すべての円盤を別の柱へ移すのに必要な最小の移動回数は何回か。","choices":["6回","7回","8回","9回"],"answer":1,"explanation":"n枚の円盤を移す最小の移動回数は 2のn乗−1 回である。3枚では 2の3乗−1＝7回になる（上の2枚を空き柱へ移す3回、一番大きい円盤を移す1回、上の2枚を重ねる3回）。4枚では15回となり、枚数が1枚増えるごとにほぼ倍になる。伝説として語られる64枚の場合では約1,844京回に達し、手数が指数的に増える探索空間の広がりを示す例として知られる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-07","exam":"g","unit":"g-u2","keyword":"Mini-Max法","type":"choice","syllabus_ref":"2.1","stem":"二人で対戦するゲームにおける Mini-Max 法についての説明として、適切なものはどれか。","choices":["自分の手番では自分の評価値が最大になる手を想定し、相手の手番でも自分の評価値が最大になるものとして先読みする方法である","ランダムに指し手を選んで多数回試行し、勝率の高い手を選ぶ方法である","自分の手番では評価値が最大になる手を、相手の手番では評価値が最小になる手（相手は自分にとって最も不利な手を選ぶ）を想定して木をたどり、末端の評価値を根までさかのぼらせて手を決める方法である","過去の対戦データから学習し、評価値を近似する方法である"],"answer":2,"explanation":"Mini-Max 法は、将棋やチェスのような二人・ゼロ和・完全情報のゲームで使われる先読みの方法である。自分の手番（MAX）では評価値を最大化し、相手の手番（MIN）では相手が自分の評価値を最小化する手を選ぶと想定して、探索木の末端から根へ評価値を伝える。相手も最善を尽くすという前提に立つ点が要点であり、ランダムな試行で勝率を測る方法（モンテカルロ法の応用）とは異なる。実際のゲームでは木が大きすぎるため、途中の深さで打ち切り、評価関数で局面を評価する。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-08","exam":"g","unit":"g-u2","keyword":"αβ法","type":"choice","syllabus_ref":"2.1","stem":"次の探索木に Mini-Max 法とαβ法を適用する。根は自分の手番（最大化）で、その子A・Bは相手の手番（最小化）である。葉の評価値は、Aの子が左から 3・5、Bの子が左から 2・7 である。左の枝から順に評価するとき、根に返る値と、αβ法によって評価を省略できる葉の組み合わせとして、正しいものはどれか。","choices":["根の値は5で、省略できる葉はない","根の値は3で、Bの子「7」も含め、すべての葉を評価する必要がある","根の値は2で、Aの子「5」を評価しなくてよい","根の値は3で、Bの子「7」は評価しなくてよい"],"answer":3,"explanation":"まずAは相手の手番なので min(3, 5)＝3 となり、根は少なくとも3を得られることが分かる。次にBの最初の葉は2であり、Bの値は min であるため2以下になることが確定する。Bの値が3を上回ることはないため、Bの残りの葉「7」を評価しても根の値は変わらず、評価を省略できる（βカット）。根の値は max(3, 2以下)＝3 である。このように、αβ法は結論に影響しない枝の評価を打ち切る（枝刈り）ことで、Mini-Max 法と同じ結論を保ったまま探索を効率化する。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-09","exam":"g","unit":"g-u2","keyword":"モンテカルロ法","type":"choice","syllabus_ref":"2.1","stem":"モンテカルロ法についての説明として、適切なものはどれか。","choices":["ランダムな試行を多数回繰り返し、その結果の統計から面積や確率などの近似値を求める方法であり、試行の回数を増やすほど精度が上がる","候補をすべて列挙し、一つずつ確かめて厳密な答えを求める方法である","評価値の高い候補だけを残して探索を進める方法である","数式を変形して、誤差のない厳密な解を導く方法である"],"answer":0,"explanation":"モンテカルロ法は、乱数を使った試行の繰り返しによって近似値を得る方法の総称である。代表例として、一辺1の正方形の中にランダムに点を打ち、半径1の四分円の中に入った点の割合から円周率を近似する方法がある。試行回数を増やすほど精度は上がるが、得られるのは近似値であり厳密な解ではない。候補をすべて確かめる方法はブルートフォースであり、モンテカルロ法とは対照的である。ゲームAIでは、ランダムな対局を繰り返して手の良し悪しを測るモンテカルロ木探索にも応用されている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-10","exam":"g","unit":"g-u2","keyword":"STRIPS","type":"choice","syllabus_ref":"2.1","stem":"STRIPS についての説明として、適切なものはどれか。","choices":["二人対戦ゲームで用いられる探索手法で、相手の手を自分にとって最も不利なものとして扱う方法である","1970年代に開発された自動プランニング（計画立案）のシステムであり、各行動について「前提条件」と「効果（成立するようになる事実と、成立しなくなる事実）」を記述し、初期状態から目標状態に至る行動の系列を探索した。ロボット Shakey の計画立案に用いられた","ブロックの世界を対象に、自然言語の指示を理解して対話するシステムである","画像認識のためのニューラルネットワークの一種である"],"answer":1,"explanation":"STRIPS は、1971年にフィークスとニルソンによって発表された自動プランニングの枠組みであり、移動ロボット Shakey の行動計画に用いられた。各行動（オペレータ）を、前提条件と、効果としての追加リスト・削除リストで記述し、初期状態から目標状態へ至る行動の並びを探索で求める。この「行動を前提条件と効果で記述する」という考え方は、その後のプランニング研究の基礎になった。ブロックの世界で対話するシステムは SHRDLU、相手の手を不利なものとして扱うのは Mini-Max 法である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-11","exam":"g","unit":"g-u2","keyword":"SHRDLU","type":"choice","syllabus_ref":"2.1","stem":"SHRDLU についての説明として、適切なものはどれか。","choices":["円盤を別の柱へ移すパズルの解法として考案された探索アルゴリズムである","自動プランニングのために、行動の前提条件と効果を記述したシステムである","1970年前後にテリー・ウィノグラードが開発した自然言語理解システムであり、「ブロックの世界」を対象に、英語の指示や質問に応じてブロックを動かしたり、過去に行った動作について答えたりできた。言葉の理解と、行動・推論を結びつけた初期の研究として知られる","ランダムな試行の繰り返しによって近似値を求める計算手法である"],"answer":2,"explanation":"SHRDLU は、テリー・ウィノグラードが1968年から1970年頃に開発したシステムで、積み木（ブロック）の世界を舞台に、人間と英語で対話しながら指示どおりにブロックを操作した。文の解析だけでなく、世界の状態の把握、計画、過去の出来事への言及までを一つのシステムで扱った点が画期的だった。一方で、扱える世界はブロックの世界に限られており、限定された世界（マイクロワールド）の中でだけ成立する仕組みである点も、初期の人工知能研究の特徴を示している。行動の前提条件と効果を記述したのは STRIPS である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-12","exam":"g","unit":"g-u2","keyword":"深さ優先探索","type":"choice","syllabus_ref":"2.1","stem":"倉庫内を自律移動するロボットが、棚の間の通路を移動して目的の荷物を探す。ロボットのメモリは限られており、経路の短さよりも、まず荷物を見つけることが優先される。行き止まりでは来た道を戻って別の通路を試す。この状況で深さ優先探索が適している理由として、最も適切なものはどれか。","choices":["深さ優先探索は、常に最短の経路を保証するためである","深さ優先探索は、すべての通路の候補を同時に記録しておくためである","深さ優先探索は、評価関数によって最も有望な通路だけを選ぶためである","深さ優先探索は、現在の経路と戻るための分岐点だけを記録すればよく、幅優先探索のように同じ深さの候補を大量に保持する必要がないため、限られたメモリでも深い探索空間をたどることができるためである"],"answer":3,"explanation":"幅優先探索は、浅い順に広げるため同じ深さの候補（フロンティア）をすべて保持する必要があり、深さが増すとメモリの消費が爆発的に増える。深さ優先探索は、現在の経路とバックトラックのための分岐点を記録するだけでよく、メモリの消費は深さに比例する程度に抑えられる。代わりに、最短の経路が得られる保証はない。この問題のように、メモリに制約があり、最適な経路よりも解を見つけること自体が優先される場面では、深さ優先探索の性質が適合する。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目3「探索・推論」"},{"id":"g2-13","exam":"g","unit":"g-u2","keyword":"機械学習","type":"choice","syllabus_ref":"2.3","stem":"機械学習についての説明として、適切なものはどれか。","choices":["データの中にある規則性やパターンをコンピュータ自身が学習し、学んだ結果を使って予測や分類などの判断を行う仕組みである","人間が判断のためのルールをすべてプログラムとして書き下し、そのとおりに処理する仕組みである","専門家の知識を「もし〜ならば〜」というルールの形で登録しておき、それを組み合わせて推論する仕組みである","大量の計算を高速に実行すること自体を指す言葉である"],"answer":0,"explanation":"機械学習は、人間が判断の規則を直接書き下すのではなく、データから規則性やパターンをコンピュータに獲得させる考え方である。学んだ結果（モデル）を使って、未知のデータへの予測や分類を行う。人間がルールをすべて書き下す方式はルールベース、専門家の知識をルール化して推論する仕組みはエキスパートシステム（中項目4「知識表現とエキスパートシステム」）であり、いずれも機械学習とは異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-14","exam":"g","unit":"g-u2","keyword":"機械学習","type":"choice","syllabus_ref":"2.3","stem":"機械学習とルールベース手法の差異についての説明として、適切なものはどれか。","choices":["ルールベース手法はデータから自動的に判断の仕方を獲得するが、機械学習は人間が条件を書き下す必要がある","ルールベース手法は人間が条件を事前に書き下すため、想定していなかった入力への対応が難しい。一方、機械学習はデータから判断の仕方を獲得するため、人間が明示しにくい規則でも扱うことができる","両者の違いは処理速度だけであり、判断の仕方を決める方法に違いはない","機械学習はルールベース手法の一種であり、ルールの数が多いものを特に機械学習と呼ぶ"],"answer":1,"explanation":"ルールベース手法は、人間が「この条件ならこう判断する」という規則をあらかじめ書き下す方式であり、想定外の入力や、規則として言葉にしにくい判断（画像の見分けなど）への対応が難しい。機械学習は、データの例から判断の仕方を獲得するため、明示しにくい規則でも扱える反面、結果は学習に使うデータに左右される。両者は判断の仕方を「誰が・どうやって決めるか」という点で異なっている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-15","exam":"g","unit":"g-u2","keyword":"機械学習","type":"choice","syllabus_ref":"2.3","stem":"機械学習のメリットとデメリットについての説明として、適切なものはどれか。","choices":["機械学習は学習データが少量でも、常に人間の専門家を上回る精度を保証できる","機械学習は判断の根拠を人間が直接書いたルールとして示すため、根拠の確認が常に容易である","判断の規則を人が直接書かなくてよい一方で、結果は学習データの量や質に左右され、データに偏りがあればその偏りまで学んでしまう","ルールベース手法は、データが増えると自動的に判断の仕方を改善していくことができる"],"answer":2,"explanation":"機械学習のメリットは、規則を人が直接書かなくても、データから判断の仕方を獲得できることにある。一方でデメリットとして、十分な量と質の学習データが必要なこと、データに偏りがあれば偏った判断を学んでしまうこと、判断の根拠がルールの形で直接は示されず確認しにくい場合があることが挙げられる。精度が常に保証されるわけではなく、データが増えて自動的に改善するのはルールベース手法ではなく機械学習側の性質である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-16","exam":"g","unit":"g-u2","keyword":"ビッグデータ","type":"choice","syllabus_ref":"2.3","stem":"ビッグデータについての説明として、適切なものはどれか。","choices":["個人情報を集めたデータのことである","AIが自動生成したデータ全般のことである","1台のサーバに保存できる範囲内の、大きな表形式のデータのことである","量が膨大であることに加え、種類が多様で、生成や更新の速度も速く、従来の方法では扱うことが困難なデータの総称である"],"answer":3,"explanation":"ビッグデータは、単に量が多いだけでなく、多様な種類のデータが、速い速度で生まれ続けるような、従来のデータベースや処理方法では扱いきれない規模のデータを指す総称である。インターネット上の行動記録やセンサーの計測値などが発生源となり、機械学習の学習データの供給源にもなった。個人情報かどうかや、誰が生成したかは、ビッグデータかどうかを決める条件ではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-17","exam":"g","unit":"g-u2","keyword":"ビッグデータ","type":"choice","syllabus_ref":"2.3","stem":"機械学習が注目されるようになった背景についての説明として、適切なものはどれか。","choices":["インターネットやセンサーの普及によって大量のデータが集まるようになり、計算機の性能も向上したため、データから学ぶ手法が現実的に使えるようになった","ルールベース手法の研究が世界的に禁止され、代替として機械学習が選ばれた","人間の専門家が不足し、専門知識を持つ人がいなくなった","プログラムを書くための言語が不要になり、誰でも同じ結果が得られるようになった"],"answer":0,"explanation":"機械学習の考え方自体は古くからあったが、注目されるようになったのは、学習に使える大量のデータ（ビッグデータ）がインターネットや各種センサーを通じて集まるようになり、それを処理できる計算機の性能が向上したことが大きい。データと計算資源という条件がそろったことで、データから学ぶ手法が実用的な精度を出すようになった。ルールベース手法が禁止されたわけではなく、現在も用途に応じて併用されている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-18","exam":"g","unit":"g-u2","keyword":"スパムフィルタ","type":"choice","syllabus_ref":"2.3","stem":"機械学習の代表的な応用例であるスパムフィルタについての説明として、適切なものはどれか。","choices":["送信を禁止されたメールアドレスの一覧と照合し、一致したものだけを遮断する仕組みである","大量の迷惑メールと通常のメールを学習し、本文に現れる単語の傾向などの特徴から、新しく届いたメールが迷惑メールかどうかを分類する仕組みである","件名に特定の語句が含まれるメールを、一律に削除する仕組みである","受信したすべてのメールについて、送信者に確認の返信を求める仕組みである"],"answer":1,"explanation":"学習型のスパムフィルタは、迷惑メールと通常のメールの実例を大量に学習し、単語の現れ方などの特徴から新しいメールを分類する、機械学習の代表的な応用例である。アドレスの一覧との照合や、特定の語句による一律の削除は、あらかじめ決めた規則で処理するルールベースの方法であり、学習によって判断の仕方を獲得しているわけではない。迷惑メールの文面が変化しても、学習し直すことで対応を続けられる点が学習型の特徴である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-19","exam":"g","unit":"g-u2","keyword":"スパムフィルタ","type":"choice","syllabus_ref":"2.3","stem":"あるメールサービスでは、迷惑メールの文面や手口が日々変化するため、人手で判定ルールを書き足す方式では追いつかなくなっている。学習型のスパムフィルタがこの場面で効果を発揮する理由として、適切なものはどれか。","choices":["判定ルールを書く担当者が、24時間体制で新しい手口を監視できるから","迷惑メールの文面は実際には変化しないため、一度作った判定がそのまま使い続けられるから","新しい文面のメールでも、学習した単語の傾向などから判定でき、蓄積されたメールを使って学習し直すことで、手口の変化に追随できるから","迷惑メールと通常のメールを区別せず、受信をすべて拒否するから"],"answer":2,"explanation":"学習型のフィルタは、個々の文面を規則として覚えるのではなく、迷惑メールに共通する特徴の傾向を学ぶため、初めて見る文面でも判定できる。さらに、新しく集まったメールで学習し直せば、手口の変化にも追随できる。人手でルールを書き足す方式は、変化のたびに人の作業が必要で追いつきにくい。文面が変化しないという前提はこの場面の設定と反し、すべて拒否しては通常のメールが使えなくなってしまう。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-20","exam":"g","unit":"g-u2","keyword":"レコメンデーションエンジン","type":"choice","syllabus_ref":"2.3","stem":"機械学習を用いたレコメンデーションエンジンについての説明として、適切なものはどれか。","choices":["すべての利用者に、同じ売れ筋ランキングを表示する仕組みである","広告枠を出稿価格の高い順に並べて表示する仕組みである","在庫の多い商品から順に表示する仕組みである","利用者の購買履歴や閲覧履歴などのデータから好みの傾向を学習し、その人が関心を持ちそうな商品やコンテンツを提示する仕組みである"],"answer":3,"explanation":"レコメンデーションエンジンは、利用者ごとの行動データから好みの傾向を学び、人によって異なる推薦を行う仕組みであり、機械学習の代表的な応用例の一つである。全員に同じ売れ筋一覧を示す方法は、個人のデータから学習しているわけではない。価格順や在庫順の表示は、並べ替えの規則によるもので、好みの学習とは異なる。推薦の具体的な手法（協調フィルタリングなど）は中項目8「教師なし学習」の範囲である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-21","exam":"g","unit":"g-u2","keyword":"レコメンデーションエンジン","type":"choice","syllabus_ref":"2.3","stem":"機械学習が効果を発揮する場面として、最も適切なものはどれか。","choices":["商品の数が膨大で、利用者ごとに好みが異なり、過去の購買や閲覧のデータが蓄積されている場面","判断のルールが法令で一意に定められていて、例外が一切ない場面","判断に使えるデータが全く存在せず、今後も得られる見込みがない場面","すべての利用者に、完全に同じ答えを返さなければならない場面"],"answer":0,"explanation":"機械学習は、明示的な規則を書きにくく、判断の材料となるデータが蓄積されている場面で効果を発揮する。膨大な商品の中から利用者ごとに異なる推薦を行う場面は、その典型である。逆に、ルールが一意に定まっている場面ではルールベースの処理で足り、データが得られない場面では学習そのものができない。全員に同じ答えを返す用途では、個人のデータから学ぶ利点が生かせない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-22","exam":"g","unit":"g-u2","keyword":"統計的自然言語処理","type":"choice","syllabus_ref":"2.3","stem":"統計的自然言語処理についての説明として、適切なものはどれか。","choices":["文法の規則や単語の意味を、人間が辞書と規則として書き尽くすことで言語を処理するアプローチである","大量の文章データ（コーパス）を集め、単語の出現頻度や並び方といった統計的な性質を利用して、言語を処理するアプローチである","言語の処理には統計は使わず、記号の論理的な操作だけで意味を導くアプローチである","音声の波形を分析して話者を特定することだけを指す言葉である"],"answer":1,"explanation":"統計的自然言語処理は、大量の文章データを材料に、単語がどのくらいの頻度で現れるか、どの単語と一緒に現れやすいかといった統計的な性質を使って言語を処理するアプローチである。人手で文法規則や辞書を書き尽くすルールベースの言語処理と対比される。文章データが電子的に大量に集まるようになったことが、このアプローチの広がりを支えた。なお、統計的な考え方を機械翻訳に用いる統計的機械翻訳は、中項目2のキーワードとして別に扱われる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-23","exam":"g","unit":"g-u2","keyword":"次元の呪い","type":"choice","syllabus_ref":"2.3","stem":"「次元の呪い」についての説明として、適切なものはどれか。","choices":["特徴量を減らしすぎると、判断に必要な情報まで失われてしまう現象である","計算にかかる時間が、特徴量の数に比例して増えていく現象である","特徴量の数を増やすほど、学習の精度は常に上がっていく現象である","特徴量（次元）が増えると、データが存在する空間が急激に広がって学習データがまばらになり、データ同士の近さや頻度といった手がかりが効きにくくなって、学習が難しくなる現象である"],"answer":3,"explanation":"次元の呪いは、特徴量の数を増やすほど、データを置く空間の広がりが指数的に大きくなり、用意できる学習データがその中でまばらになってしまう問題を指す。データがまばらになると、似たデータ同士の近さや、事例の頻度といった学習の手がかりが頼れなくなり、精度を保つには次元に応じて膨大なデータが必要になる。特徴量を減らしすぎる問題や、計算時間の比例的な増加とは別の現象である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-24","exam":"g","unit":"g-u2","keyword":"次元の呪い","type":"choice","syllabus_ref":"2.3","stem":"データを特徴量ごとに区切って数えることを考える。各特徴量を10段階に区切ると、特徴量が1つのときは10通り、2つのときは10×10＝100通りの組み合わせができる。特徴量が5つのとき、組み合わせは何通りになるか。","choices":["50通り","1,000通り","100,000通り","10,000通り"],"answer":2,"explanation":"組み合わせの数は、特徴量が1つ増えるごとに10倍になる。特徴量が5つでは 10の5乗＝100,000通りになる。このように、次元が増えると区切られた空間（セルの数）は指数的に増えるため、すべての組み合わせを学習データでまんべんなく埋めることは現実的でなくなる。これが次元の呪いの具体的な姿であり、特徴量の選び方や次元削減（中項目8「教師なし学習」）が重要になる理由の一つである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目5「機械学習」"},{"id":"g2-25","exam":"g","unit":"g-u2","keyword":"人間の神経回路","type":"choice","syllabus_ref":"2.4","stem":"ディープラーニングの基盤であるニューラルネットワークが、人間の神経回路から着想を得ている点についての説明として、適切なものはどれか。","choices":["脳の神経細胞（ニューロン）がシナプスを介してつながり、信号の伝わりやすさ（結合の強さ）を変えながら情報を処理する仕組みを、人工的なニューロンのネットワークとしてモデル化したものである","人間の脳の神経細胞をそのまま電子回路に移植し、脳と計算機を直接つなぐ仕組みである","人間の神経回路の構造を完全に再現することを目的とし、意識や感情まで再現できたネットワークである","神経回路とは無関係に、統計学の回帰モデルだけから発展した仕組みである"],"answer":0,"explanation":"ニューラルネットワークは、ニューロンがシナプスで結合し、結合の強さ（重み）によって信号の伝わり方が変わるという脳の神経回路の仕組みを、単純化してモデル化したものである。脳そのものの完全な再現ではなく、着想の源としての位置づけであり、学習とはこの重みを調整する過程に対応する。ニューラルネットワークの仕組みの詳細は中項目17以降の範囲である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-26","exam":"g","unit":"g-u2","keyword":"ネオコグニトロン","type":"choice","syllabus_ref":"2.4","stem":"ネオコグニトロンについての説明として、適切なものはどれか。","choices":["2012年の画像認識の競技会で優勝し、ディープラーニングブームのきっかけとなったモデルである","1980年に福島邦彦が発表した多層の神経回路モデルで、人間の視覚野の階層構造を模し、文字の位置がずれても認識できる仕組みを持ち、後の畳み込みニューラルネットワークの原型とされる","囲碁で人間のプロ棋士に勝利した、強化学習を中心とするシステムである","大量の文章データから学習し、文章を生成することに特化したモデルである"],"answer":1,"explanation":"ネオコグニトロンは1980年に福島邦彦が発表した視覚の神経回路モデルである。視覚野の単純型細胞・複雑型細胞の階層的な働きを模し、入力の位置ずれに強い認識を実現したことから、畳み込みニューラルネットワーク（CNN）の原型と位置づけられる。CNNの仕組み自体は中項目26の範囲である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-27","exam":"g","unit":"g-u2","keyword":"LeNet","type":"choice","syllabus_ref":"2.4","stem":"LeNetについての説明として、適切なものはどれか。","choices":["画像の大規模データセットの名称で、約1,400万枚の画像にラベルが付けられたものである","囲碁AIの学習に使われた、自己対戦による強化学習の手法の名称である","ルカン（Yann LeCun）らが開発した初期の畳み込みニューラルネットワークで、手書き数字の認識に用いられ、郵便番号の読み取りなどに実用化された","2016年に囲碁で勝利したシステムが使った探索手法の名称である"],"answer":2,"explanation":"LeNetは1980年代末から1990年代にかけてルカンらが開発した初期の畳み込みニューラルネットワークである。手書き数字の認識で成果を上げ、郵便番号や銀行小切手の読み取りに実用化された。ディープラーニングが広く注目される以前から、畳み込み構造の有効性を示した初期の実例である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-28","exam":"g","unit":"g-u2","keyword":"ImageNet","type":"choice","syllabus_ref":"2.4","stem":"ImageNetについての説明として、適切なものはどれか。","choices":["画像を生成することに特化した、生成AIのモデルの名称である","画像認識の精度を競う競技会そのものの名称である","インターネット上の画像の著作権を自動で処理する仕組みの名称である","1,000万枚を超える大量の画像に、写っているもののラベルを付けた大規模な画像データセットで、ディープラーニングの学習に使えるデータの供給源となった"],"answer":3,"explanation":"ImageNetは2009年に公開された大規模なラベル付き画像データセットであり、分類のカテゴリはWordNetの体系に基づいている。大量の学習データがそろったことは、データから特徴を学ぶディープラーニングの発展を支えた条件の一つである。画像認識の競技会の名称はILSVRCであり、ImageNetはそこで使われたデータセットである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-29","exam":"g","unit":"g-u2","keyword":"ILSVRC","type":"choice","syllabus_ref":"2.4","stem":"ILSVRCについての説明として、適切なものはどれか。","choices":["画像認識の精度を競う競技会で、2012年に深い層を持つ畳み込みニューラルネットワーク（AlexNet）が分類の誤りを大きく減らして優勝したことが、ディープラーニングが広く注目される転機となった","囲碁の世界王者を決める公式戦で、AIが初めて人間に勝利した大会である","文章生成の性能を競う競技会で、大規模言語モデルの順位付けに使われている","ロボットの運動性能を競う競技会で、強化学習の評価に使われている"],"answer":0,"explanation":"ILSVRCはImageNetを用いた画像認識の競技会（2010〜2017年）である。2012年にトロント大学のチームによるAlexNetが、上位5位までの候補に正解を含むかで測る分類の誤り率を約15%まで下げ、2位の約26%を大きく引き離して優勝し、多層のニューラルネットワークの有効性を示した。この出来事が、ディープラーニングへの注目が一気に高まる転機とされる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-30","exam":"g","unit":"g-u2","keyword":"ディープラーニング","type":"choice","syllabus_ref":"2.4","stem":"古典的な機械学習とディープラーニングの差異についての説明として、適切なものはどれか。","choices":["ディープラーニングは学習データを必要とせず、ルールだけで判断する点が古典的な機械学習と異なる","古典的な機械学習では、判断の手がかりとなる特徴量を人間が設計することが多いのに対し、ディープラーニングでは、多層のネットワークがデータから特徴の表現そのものを学習する","古典的な機械学習はニューラルネットワークだけを使い、ディープラーニングは決定木などの古典的手法を組み合わせたものである","両者の違いは計算速度だけであり、特徴量の扱いに違いはない"],"answer":1,"explanation":"両者の大きな差異は特徴量の扱いにある。古典的な機械学習では「何を見て判断するか」という特徴量の設計が人間の仕事であり、性能はその設計に左右された。ディープラーニングでは、多層のニューラルネットワークが、生のデータから判断に役立つ特徴の表現を段階的に学習する。このため、特徴を人間が言葉や数式で設計しにくい画像・音声・言語などの分野で特に威力を発揮した。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-31","exam":"g","unit":"g-u2","keyword":"ディープラーニング","type":"choice","syllabus_ref":"2.4","stem":"ディープラーニングの性質についての説明として、適切なものはどれか。","choices":["ディープラーニングは少量のデータでも常に古典的な機械学習より高い精度が出るため、データの量を気にする必要はない","ディープラーニングのモデルは判断の根拠をルールの形で直接示せるため、古典的な機械学習より解釈が常に容易である","ディープラーニングは多層で多数のパラメータを持つモデルを学習するため、一般に大量の学習データと大きな計算資源を必要とし、データが十分に得られない場面では古典的な機械学習のほうが適する場合がある","ディープラーニングでは学習が不要で、あらかじめ用意した重みをそのまま使う"],"answer":2,"explanation":"ディープラーニングの性能は、大量のデータと計算資源（GPUなどによる並列計算）に支えられている。データが少ない場面では過学習しやすく、特徴量を人間が設計できる古典的な機械学習が有利な場合もある。手法の優劣は場面によって異なり、データの量と性質に応じた選択が要る。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-32","exam":"g","unit":"g-u2","keyword":"アルファ碁 (AlphaGo)","type":"choice","syllabus_ref":"2.4","stem":"アルファ碁（AlphaGo）についての説明として、適切なものはどれか。","choices":["文章を生成する大規模言語モデルで、対話型AIの原型となったシステムである","画像認識の競技会で優勝し、画像分類の誤り率を大きく下げたモデルである","人間の棋譜だけを学習し、自己対戦は一切行わずに強くなったシステムである","DeepMindが開発した囲碁AIで、2016年に韓国の李世ドル九段との五番勝負で4勝1敗とし、ディープラーニングの代表的な成果として知られる"],"answer":3,"explanation":"アルファ碁は2016年3月、囲碁のトップ棋士である李世ドル九段との五番勝負に4勝1敗で勝利した。場合の数が膨大で、直感的な判断が要るとされてきた囲碁での勝利は、ディープラーニングの到達点を示す出来事として広く報じられた。人間の棋譜からの学習に加えて、自己対戦による強化学習も行われている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-33","exam":"g","unit":"g-u2","keyword":"アルファ碁 (AlphaGo)","type":"choice","syllabus_ref":"2.4","stem":"アルファ碁が強い囲碁AIを実現できた仕組みの総論として、適切なものはどれか。","choices":["局面の評価や次の一手の候補を出す深層ニューラルネットワーク（方策ネットワーク・価値ネットワーク）と、自己対戦による強化学習、先を読む木探索を組み合わせた","人間の名人の棋譜をすべて暗記し、対局中はその中から最も近い局面の手を選ぶだけの仕組みである","囲碁のすべての局面をあらかじめ計算し尽くし、完全な読み切りによって勝利した","ルールベースのエキスパートシステムとして、プロ棋士の知識を「もし〜ならば〜」の規則に書き下して推論した"],"answer":0,"explanation":"アルファ碁は、深層学習による局面の評価（価値ネットワーク）と着手の候補づけ（方策ネットワーク）に、自己対戦を通じた強化学習と、モンテカルロ木探索による先読みを組み合わせた。単一の技術ではなく、深層学習を中核に複数の手法を統合した点が特徴である。強化学習の仕組みの詳細は中項目29の範囲である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-34","exam":"g","unit":"g-u2","keyword":"生成AI","type":"choice","syllabus_ref":"2.4","stem":"生成AIについての説明として、適切なものはどれか。","choices":["学習データの量を自動で増やすためだけに使われる、データ拡張の手法の総称である","文章・画像・音声などの新しいコンテンツを作り出すAIの総称で、大量のデータで学習した大規模なディープラーニングのモデルがその基盤となっている","人間の作業を自動化するルールベースのシステムの総称である","画像の分類精度を競う競技会で使われる評価指標の名称である"],"answer":1,"explanation":"生成AIは、学習したデータの傾向をもとに、文章や画像などの新しいコンテンツを生成するAIの総称である。大規模言語モデルや画像生成モデルが代表例で、いずれもディープラーニングの大規模モデルが基盤にある。コンテンツを生成する仕組みの詳細は大項目6の範囲である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-35","exam":"g","unit":"g-u2","keyword":"生成AI","type":"choice","syllabus_ref":"2.4","stem":"ある出版社では、記事のたたき台となる文章の下書きや、挿絵の候補画像を、短時間で多数用意したいと考えている。生成AIがこの場面で効果を発揮する理由として、適切なものはどれか。","choices":["生成AIは既存の文章や画像をそのまま複製して出力するため、作り直す手間がかからないから","生成AIはあらかじめ登録された定型文と定型画像の中から選んで出すだけなので、内容が常に正確だから","大量の文章や画像で学習したモデルが、指示に応じて新しい文章や画像を作り出せるため、下書きや候補を多数用意する作業を効率化できるから","生成AIを使えば、人間が内容を確認しなくても、そのまま出版できる品質が常に保証されるから"],"answer":2,"explanation":"生成AIは、学習した傾向をもとに新しいコンテンツを生成できるため、下書きや候補案を大量に用意する用途で効果を発揮する。ただし、出力の正確さや権利関係の確認は別途必要であり、生成されたものを無確認でそのまま使えるわけではない。なお、学習用のデータを生成・拡張する技術としてのデータ生成は中項目30の範囲であり、本問は利用者向けにコンテンツを作る場面を扱っている。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g2-36","exam":"g","unit":"g-u2","keyword":"ディープラーニング","type":"choice","syllabus_ref":"2.4","stem":"2010年代にディープラーニングが急速に発展した要因の組み合わせとして、適切なものはどれか。","choices":["人間の専門家が知識をルールとして書き下す作業が自動化され、エキスパートシステムが大規模化したこと","計算機の性能は変わらなかったが、少量のデータでも学習できる手法が中心になったこと","インターネットの普及で学習に使えるデータが減り、学習そのものが不要になったこと","大規模な学習データが集まるようになったこと、GPUなどによる計算資源の拡大、学習を安定させる手法の改良が重なったこと"],"answer":3,"explanation":"ディープラーニングの考え方自体は古くからあったが、発展を支えたのは、ImageNetのような大規模データの整備、並列計算に適したGPUの活用、学習手法の改良が重なったことである。データ・計算資源・手法の条件がそろったことで、多層のネットワークの学習が現実的になった。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目6「ディープラーニング」"},{"id":"g1-13","exam":"g","unit":"g-u1","keyword":"シンギュラリティ","type":"choice","syllabus_ref":"1.2","stem":"「シンギュラリティ（技術的特異点）」の説明として、適切なものはどれか。","choices":["AIが特定の課題で人間の能力を超えた時点を指す言葉である","人工知能の進歩が加速し、やがて人間の知能を超える知能が生まれ、社会に不可逆な変化が起きるとされる転換点のことである","コンピュータの処理速度が人間の脳の計算速度と等しくなった時点のことである","ロボットが人間の姿形を持つようになった段階のことである"],"answer":1,"explanation":"シンギュラリティは、AIが自己改善を通じて進歩を加速させ、人間の知能を超える知能が出現して社会が根本的に変わるとされる転換点。レイ・カーツワイルは著書『シンギュラリティは近い』（2005年）で、2045年頃に到来すると予測した。特定の課題で人間を超えることは現在の弱いAIでも起きており、それとは区別される。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-14","exam":"g","unit":"g-u1","keyword":"シンギュラリティ","type":"choice","syllabus_ref":"1.2","stem":"シンギュラリティをめぐる議論の位置づけとして、適切なものはどれか。","choices":["国際機関によって到来の年が公式に定められている","計算機の性能指標の一つであり、ベンチマークで測定できる","すでに到来したことが実験的に証明されている","到来の時期については専門家の間でも見解が分かれており、到来しないとする立場もある、将来予測をめぐる議論である"],"answer":3,"explanation":"シンギュラリティは将来についての予測であり、時期や到来の有無については専門家の間でも議論が続いている。カーツワイルの2045年という予測も一つの見解にすぎず、公式に定められたものではない。中項目2の目標である「汎用的な人工知能の実現可能性」をめぐる議論の一つとして位置づけられる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-15","exam":"g","unit":"g-u1","keyword":"ダートマス会議","type":"choice","syllabus_ref":"1.2","stem":"1956年に開かれた「ダートマス会議」についての説明として、適切なものはどれか。","choices":["「人工知能（artificial intelligence）」という言葉が提案され、AI研究の出発点とされる会議である","チューリングテストが初めて実施された会議である","ディープラーニングの手法が初めて発表された会議である","AIの倫理原則が国際的に合意された会議である"],"answer":0,"explanation":"1956年夏、米国のダートマス大学で開かれたワークショップ。ジョン・マッカーシーらによる提案書で「人工知能」という言葉が用いられ、AIという研究分野の出発点とされる。チューリングテストはチューリングが1950年の論文で提案したもので、この会議で実施されたものではない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-16","exam":"g","unit":"g-u1","keyword":"ダートマス会議","type":"choice","syllabus_ref":"1.2","stem":"ダートマス会議の提案書（1955年）についての説明として、適切なものはどれか。","choices":["マッカーシー、ミンスキー、ロチェスター、シャノンらの連名で、学習や知能の諸側面は原理的には機械で再現できるとの見通しのもと、約2か月間の共同研究として提案された","チューリング一人が執筆し、計算可能性の理論を議論する会議として提案された","企業が製品開発のために開いた会議で、参加者や内容は非公開だった","提案の時点で、機械が人間の知能を超える時期が具体的に決定された"],"answer":0,"explanation":"1955年の提案書は、マッカーシー（ダートマス大学）、ミンスキー（ハーバード大学）、ロチェスター（IBM）、シャノン（ベル研究所）の連名で、「知能のあらゆる側面は原理的には正確に記述でき、機械に模倣させることができる」という見通しを示し、1956年夏に約2か月間の研究会を開くことを提案した。機械が人間を超える時期の決定のような内容は含まれていない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-17","exam":"g","unit":"g-u1","keyword":"知識獲得のボトルネック","type":"choice","syllabus_ref":"1.2","stem":"「知識獲得のボトルネック」の説明として、適切なものはどれか。","choices":["コンピュータのメモリ容量が不足し、知識を保存できない問題である","知識が多すぎて、検索に時間がかかる問題である","専門家が引退して知識が失われることだけを指す言葉である","専門家の知識は暗黙的で言語化しにくい部分が多く、それを聞き出してルールの形に書き下す作業に多大な時間と労力がかかり、知識ベースの構築や更新が追いつかない問題である"],"answer":3,"explanation":"エキスパートシステムの開発では、専門家の知識をインタビューなどで引き出し、ルールとして記述する必要があった。知識の多くは暗黙知であり言語化が難しく、この獲得の工程がシステム構築の隘路（ボトルネック）となったことが、古典的AIの限界の一つとされる。知識工学の提唱者ファイゲンバウムが指摘した問題として知られる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-18","exam":"g","unit":"g-u1","keyword":"知識獲得のボトルネック","type":"choice","syllabus_ref":"1.2","stem":"ある病院向けに、ベテラン医師の診断知識をルール化した診断支援システムを構築する計画がある。開発が進むにつれ、医師への聞き取りとルールの記述・修正に膨大な工数がかかり、診療ガイドラインの改訂にも追随できなくなってきた。この状況が示す古典的AIの課題はどれか。","choices":["フレーム問題","シンボルグラウンディング問題","知識獲得のボトルネック","トイ・プロブレムへの批判"],"answer":2,"explanation":"専門家の知識を引き出してルール化する工程そのものに膨大な工数がかかり、知識の更新も追いつかない点が、知識獲得のボトルネックである。フレーム問題は関係する事柄だけを切り出す難しさ、シンボルグラウンディング問題は記号と実世界の意味の結びつきの問題であり、この場面の中心課題とは異なる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-19","exam":"g","unit":"g-u1","keyword":"統計的機械翻訳","type":"choice","syllabus_ref":"1.2","stem":"統計的機械翻訳が登場した背景と位置づけとして、適切なものはどれか。","choices":["文法規則の記述が自動化され、ルールベース方式の保守が不要になったことを受けて登場した方式である","ルールベース方式では規則と辞書の整備に限界があったため、人手で規則を書き下す代わりに、大量の対訳文から単語や句の対応を統計的に学習する方式として登場し、機械翻訳の主流になった","ニューラルネットワークの発展を受けて、ルールベース方式を改良した方式である","翻訳の需要が減ったため、少人数で運用できる方式として考案された"],"answer":1,"explanation":"機械翻訳は当初、文法規則と辞書を人手で記述するルールベース方式が中心だったが、例外への対応や保守に限界があった。統計的機械翻訳は、大量の対訳コーパスから対応関係を統計的に学習する方式として1990年代にIBMの研究などで本格化し、2000年代に主流となった。機械翻訳というタスク自体の総論は中項目27でも扱われるが、本問は古典的な言語処理の転換点としての位置づけを扱う。なお、統計の考え方を言語処理全般に用いる統計的自然言語処理（中項目5）とは対象が異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-20","exam":"g","unit":"g-u1","keyword":"統計的機械翻訳","type":"choice","syllabus_ref":"1.2","stem":"英語と日本語のように語順の異なる言語間で統計的機械翻訳を行う際、単語単位の対応だけでは不十分とされる理由として、適切なものはどれか。","choices":["単語の対応だけでは語順の並べ替えや、複数の単語がまとまって初めて決まる訳し分けを扱えないため、句（フレーズ）単位の対応や、訳文の並びの自然さを評価する仕組みと組み合わせる必要がある","単語単位の対応では、辞書の容量が不足するからである","単語は言語ごとに数が決まっていて、対応表が作れないからである","語順の違いは翻訳の品質に影響しないため、特別な理由は存在しない"],"answer":0,"explanation":"英語はSVO、日本語はSOVというように語順が異なる言語間では、単語を1対1で置き換えるだけでは正しい訳文にならない。統計的機械翻訳では、句単位の対応関係（翻訳モデル）に加え、訳文の単語の並びがその言語として自然かどうかを評価する言語モデルを組み合わせ、文全体として最も確からしい訳を選ぶ。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-21","exam":"g","unit":"g-u1","keyword":"ルールベース機械翻訳","type":"choice","syllabus_ref":"1.2","stem":"「ルールベース機械翻訳」の説明として、適切なものはどれか。","choices":["大量の対訳データから対応関係を統計的に学習する方式である","ニューラルネットワークが文全体の意味を捉えて翻訳する方式である","人間が文法の規則や単語の辞書をあらかじめ記述し、その規則に従って原文を解析し訳文を生成する方式である","利用者の翻訳履歴を蓄積し、似た文を再利用する方式である"],"answer":2,"explanation":"ルールベース機械翻訳は初期の機械翻訳の方式で、文法規則と対訳辞書を人間が記述し、規則に従って翻訳する。1954年のジョージタウン大学とIBMによるロシア語から英語への公開実験もこの方式だった。規則にない表現や例外への対応が課題となった。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-22","exam":"g","unit":"g-u1","keyword":"ルールベース機械翻訳","type":"choice","syllabus_ref":"1.2","stem":"ルールベース機械翻訳の課題として、適切なものはどれか。","choices":["学習データが不足すると翻訳の精度が下がること","計算資源が大量に必要で、個人のコンピュータでは動かないこと","翻訳結果の根拠を規則として確認できないこと","言語ごとに文法規則と辞書を人間が整備し続ける必要があり、例外や新しい表現への対応に多大な保守の手間がかかること"],"answer":3,"explanation":"ルールベース方式では、規則と辞書の整備・保守が人間の作業であり、例外処理が積み重なって保守が困難になる点が課題だった。逆に、翻訳の根拠が規則として明示される点はこの方式の特徴であり、課題ではない。学習データの量への依存は統計的機械翻訳側の性質である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-23","exam":"g","unit":"g-u1","keyword":"ローブナーコンテスト","type":"choice","syllabus_ref":"1.2","stem":"「ローブナーコンテスト（ローブナー賞）」の説明として、適切なものはどれか。","choices":["画像認識の精度を競うコンテストである","囲碁でAIと人間の王者が対決する大会である","チューリングテストの考え方を実装したコンテストで、審査員がテキストの対話相手が人間か機械かを見分けようとする中で、最も人間らしく応答したプログラムが評価される","ロボットの歩行性能を競うコンテストである"],"answer":2,"explanation":"ローブナーコンテストは1991年に始まった、チューリングテストを実装する形のコンテスト。ヒュー・ローブナーが創設し、審査員はテキストで対話して相手が人間かプログラムかを見分けようとする。最も人間らしいと判定されたプログラムが優勝する。チューリングテストそのものの定義は既存問題（g1-02）が扱っており、本問はその実装としてのコンテストを扱う。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-24","exam":"g","unit":"g-u1","keyword":"ローブナーコンテスト","type":"choice","syllabus_ref":"1.2","stem":"ローブナーコンテストをめぐる議論として、適切なものはどれか。","choices":["優勝したプログラムは、人間と同等の理解力を持つことが証明されたと広く認められている","対話をごまかしたり話題をそらしたりする表面的な振る舞いが有利になりやすく、「人間らしさ」の判定が必ずしも知能や理解の深さを示さないという批判がある","コンテストの結果により、チューリングテストは不要になったと結論づけられている","審査員はプログラムのソースコードを審査して優勝を決める"],"answer":1,"explanation":"ローブナーコンテストでは、審査員にいかに人間だと信じ込ませるかが競われるため、話題をそらすなどの表面的な振る舞いが有利になる場合がある。このため、優勝がそのまま意味の理解や汎用的な知能の証明にはならないという批判があり、チューリングテストの意義をめぐる議論の材料になっている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g2-37","exam":"g","unit":"g-u2","keyword":"意味ネットワーク","type":"choice","syllabus_ref":"2.2","stem":"意味ネットワークについての説明として、適切なものはどれか。","choices":["概念をノードとし、概念どうしの関係をラベル付きのリンクで結んで知識を表現する方法であり、is-a のような関係を通じて、上位概念の性質を下位概念が受け継ぐ（継承）ことができる","専門家の知識を「もし〜ならば〜」というルールの集まりとして記述し、推論に使う知識表現の方法である","大量のデータから統計的にパターンを学習し、分類や予測を行う方法である","初期状態から目標状態までの状態の移り変わりを木構造で表し、解を探索する方法である"],"answer":0,"explanation":"意味ネットワークは、概念とその間の関係をネットワーク状に結んだ知識表現である。is-a 関係で結ばれた下位概念は上位概念の性質を受け継ぐため、知識を効率よく記述できる。ルールの集まりとして知識を記述するのはルールベースの知識表現であり、エキスパートシステムで用いられた。状態の移り変わりを木で表すのは探索木（中項目3「探索・推論」）であり、意味ネットワークとは別のものである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-38","exam":"g","unit":"g-u2","keyword":"is-aの関係・has-aの関係・part-ofの関係","type":"choice","syllabus_ref":"2.2","stem":"知識表現における関係のあてはめとして、正しい組み合わせはどれか。「犬は哺乳類である」「自動車はエンジンを持つ」「エンジンは自動車の一部である」の3つの文が表す関係を、この順に並べたものはどれか。","choices":["part-ofの関係・is-aの関係・has-aの関係","is-aの関係・has-aの関係・part-ofの関係","has-aの関係・part-ofの関係・is-aの関係","is-aの関係・part-ofの関係・has-aの関係"],"answer":1,"explanation":"is-a の関係は、下位の概念が上位の概念の一種であることを表す（犬は哺乳類の一種）。has-a の関係は、全体が部分を持つことを表す（自動車はエンジンを持つ）。part-of の関係は、部分が全体の一部であることを表す（エンジンは自動車の一部）。has-a と part-of は、全体と部分の関係を逆向きに見たものである。3つの関係を区別できることが、意味ネットワークなどで知識を正しく記述する前提になる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-39","exam":"g","unit":"g-u2","keyword":"意味ネットワーク","type":"choice","syllabus_ref":"2.2","stem":"ある意味ネットワークには、「鳥 is-a 動物」「鳥 has-a 羽」「ペンギン is-a 鳥」「ペンギン は 飛ばない」という知識が記述されている。is-a 関係による継承だけから導ける結論として、適切なものはどれか。","choices":["ペンギンは飛ぶことができる","ペンギンは動物ではない","ペンギンは羽を持つ","ペンギンは鳥ではない"],"answer":2,"explanation":"ペンギンは鳥の一種（is-a）であるため、鳥の性質である「羽を持つ」を継承によって受け継ぐ。「飛ぶ」という性質はこのネットワークには記述されていないため、継承からは導けない。また「飛ばない」という例外がペンギン自身に明示されている場合は、上位概念から継承される性質より個別の記述が優先される扱いになる。このように、継承は知識の記述を省力化する一方で、例外の扱いが知識表現の論点になる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-40","exam":"g","unit":"g-u2","keyword":"マイシン(MYCIN)・DENDRAL","type":"choice","syllabus_ref":"2.2","stem":"初期のエキスパートシステムの代表例である MYCIN と DENDRAL の説明の組み合わせとして、正しいものはどれか。","choices":["MYCIN は有機化合物の化学構造の推定を行い、DENDRAL は血液感染症の診断を行った","MYCIN は血液感染症の診断を行い、DENDRAL は将棋の対局を行った","MYCIN は自然言語による対話を行い、DENDRAL は有機化合物の化学構造の推定を行った","MYCIN は血液感染症の診断と治療薬の選択を支援し、DENDRAL は質量分析のデータから有機化合物の化学構造を推定した"],"answer":3,"explanation":"MYCIN は1970年代にスタンフォード大学で開発されたエキスパートシステムで、血液感染症の診断と抗生物質の選択を支援した。DENDRAL は1960年代後半から同じくスタンフォード大学で開発され、質量分析のデータから有機化合物の化学構造を推定したもので、エキスパートシステムの先駆けとされる。自然言語による対話を行った初期のシステムは ELIZA である。エキスパートシステムそのものの定義は既存問題（g1-06）で扱われており、本問はその代表例2つを対象とする。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-41","exam":"g","unit":"g-u2","keyword":"イライザ(ELIZA)","type":"choice","syllabus_ref":"2.2","stem":"イライザ（ELIZA）についての説明として、適切なものはどれか。","choices":["1960年代にワイゼンバウムが開発した初期の自然言語対話システムであり、相手の発言に含まれるキーワードを拾い、決められた型にはめ直して応答を返すことで、セラピストとの会話らしく見せた","大量の文章データを統計的に学習し、文脈に応じた応答文を生成する現代の大規模言語モデルである","専門家の診断知識をルールとして蓄え、感染症の診断を行ったエキスパートシステムである","クイズ番組で人間のチャンピオンに勝利した質問応答システムである"],"answer":0,"explanation":"ELIZA は1960年代半ばにジョセフ・ワイゼンバウムが開発した対話システムである。来談者中心療法のセラピストを模したプログラム（DOCTOR）が知られ、仕組みはキーワードの照合と文の組み換えという単純なものだったが、利用者はしばしば本当に理解されているかのように感じた。意味を理解していない仕組みでも、人間が意味を読み取ってしまう点が、知能や理解をめぐる論点になった。感染症の診断を行ったのは MYCIN、クイズ番組で勝利したのはワトソンである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-42","exam":"g","unit":"g-u2","keyword":"インタビューシステム","type":"choice","syllabus_ref":"2.2","stem":"エキスパートシステムの構築におけるインタビューシステムの役割として、適切なものはどれか。","choices":["完成したエキスパートシステムの利用者に、満足度を尋ねるアンケートを実施する仕組みである","専門家との質問と回答のやり取りを対話形式で進め、専門家の知識や判断の手順を引き出して、知識ベースの構築を支援する仕組みである","利用者の症状を聞き取り、その場で診断を実行する仕組みである","専門家の代わりに推論エンジンとして動作する仕組みである"],"answer":1,"explanation":"インタビューシステムは、知識獲得の手段の一つである。専門家の知識は暗黙的で、そのままではルールとして言語化しにくい（知識獲得のボトルネック、中項目2「人工知能分野で議論される問題」）。インタビューシステムは、対話の流れに沿って質問を投げかけ、回答を引き出すことで、知識ベースに登録する知識の獲得を支援する。診断や推論そのものを実行するのはエキスパートシステム本体の役割であり、インタビューシステムはその構築の前段に位置する。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-43","exam":"g","unit":"g-u2","keyword":"Cycプロジェクト","type":"choice","syllabus_ref":"2.2","stem":"Cyc プロジェクトについての説明として、適切なものはどれか。","choices":["Web上の情報を自動で収集し、検索エンジンの索引を作るプロジェクトである","人間の会話を大量に記録し、統計的に応答の仕方を学ぶプロジェクトである","人間が当たり前に持っている常識的な知識を、コンピュータが扱える形で大規模に記述し、蓄積しようとするプロジェクトであり、1980年代にレナートらによって始められた","大学入試の問題を解くAIを開発する日本のプロジェクトである"],"answer":2,"explanation":"Cyc プロジェクトは、1984年にダグラス・レナートらによって始められた、常識知識の大規模な知識ベース化の試みである。「火を触ると熱い」といった、人間にとって自明な知識を一つひとつ形式化して蓄積することで、コンピュータに常識的な推論をさせようとした。長年にわたって知識の記述が続けられたこと自体が、常識の範囲の広さと、知識を手作業で記述するアプローチの工数の大きさを示している。大学入試の問題を解く日本のプロジェクトは東ロボくんである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-44","exam":"g","unit":"g-u2","keyword":"セマンティックWeb","type":"choice","syllabus_ref":"2.2","stem":"セマンティック Web についての説明として、適切なものはどれか。","choices":["Webページの表示を高速化する技術の総称である","Web上の文章を自動で要約する技術である","検索エンジンがページの表示順位を決める仕組みの名称である","Web上の情報に、コンピュータが処理できる「意味」の情報（メタデータ）を付与し、情報どうしの関係を機械がたどって連携・活用できるようにしようとする構想であり、バーナーズ＝リーが提唱した"],"answer":3,"explanation":"セマンティック Web は、Web の創始者ティム・バーナーズ＝リーが提唱した構想である。人間が読んで理解するための現在の Web に対し、情報の意味や関係を機械が処理できる形で記述し、コンピュータ同士が情報を連携して活用できるようにすることを目指す。RDF による情報の記述や、概念と関係を体系化するオントロジー（既存問題 g1-09 で扱済み）が、その基盤となる技術である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-45","exam":"g","unit":"g-u2","keyword":"データマイニング","type":"choice","syllabus_ref":"2.2","stem":"データマイニングについての説明として、適切なものはどれか。","choices":["大量のデータの中から、それまで知られていなかった有用なパターンや関係、知識を発見する技術・取り組みである","データを暗号化して安全に保管する技術である","データを圧縮して保存に必要な容量を減らす技術である","Webページを自動で巡回して収集する技術である"],"answer":0,"explanation":"データマイニングは、鉱山から鉱石を掘り出すことの比喩で、蓄積された大量のデータから、価値のあるパターンや知識を掘り出す取り組みを指す。購買履歴から「一緒に買われやすい商品の組み合わせ」を見つけるといった活用が代表例である。発見のために機械学習などの手法が使われることもあるが、データマイニングの中心はあくまで知識の発見にある。Webページの自動収集はクローリングと呼ばれる別の技術である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-46","exam":"g","unit":"g-u2","keyword":"ウェブマイニング","type":"choice","syllabus_ref":"2.2","stem":"ウェブマイニングについての説明として、適切なものはどれか。","choices":["Webサイトの脆弱性を自動で探し出すセキュリティ検査のことである","Web上の文書や画像などの内容、ページどうしのリンク構造、利用者のアクセス履歴といった、Webに特有の情報を対象にデータマイニングを行うことである","Webページのデザインを自動で生成することである","暗号資産の採掘（マイニング）を Web ブラウザ上で行うことである"],"answer":1,"explanation":"ウェブマイニングは、データマイニングの対象を Web に特化したものである。対象は、ページの内容そのもの（ウェブコンテンツマイニング）、ページ間のリンクの構造（ウェブ構造マイニング）、利用者のアクセス履歴（ウェブ利用マイニング）に分けて考えられることが多い。データマイニング一般（g2-45）とは、対象を Web 特有の情報に限る点で区別される。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-47","exam":"g","unit":"g-u2","keyword":"Question-Answering・ワトソン","type":"choice","syllabus_ref":"2.2","stem":"Question-Answering（質問応答）と、それを代表するシステムであるワトソンについての説明として、正しいものはどれか。","choices":["質問応答とは画像の内容について質問に答える技術のことであり、ワトソンは将棋で人間の名人に勝利したシステムである","質問応答とは検索キーワードを自動で列挙する技術のことであり、ワトソンは検索エンジンの名称である","質問応答とは、自然言語で与えられた質問の意味を理解し、答えそのものを返す技術であり、IBMのワトソンはクイズ番組「Jeopardy!」で人間の歴代チャンピオンに勝利して注目された","質問応答とは音声で質問を受け付ける技術のことであり、ワトソンは自動運転の制御システムである"],"answer":2,"explanation":"Question-Answering（質問応答）は、関連する文書の一覧を返す検索とは異なり、質問に対する答えそのものを返す技術である。IBM のワトソンは、この質問応答の代表例であり、2011年にアメリカのクイズ番組「Jeopardy!」で人間の歴代チャンピオン2人に勝利した。言葉遊びや間接的な言い回しを含むクイズの質問を理解して答えたことが、自然言語処理の到達点として注目された。本問は、質問応答という技術とワトソンという代表例の両方を知らなければ正解に到達できない複合キーワードの問題である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g2-48","exam":"g","unit":"g-u2","keyword":"東ロボくん","type":"choice","syllabus_ref":"2.2","stem":"「東ロボくん」についての説明として、適切なものはどれか。","choices":["東京大学が開発した人型ロボットの名称である","クイズ番組で人間に勝利した IBM のシステムの日本版の名称である","東日本で稼働する配達ロボットの総称である","国立情報学研究所を中心に進められた「ロボットは東大に入れるか」というプロジェクトの愛称であり、大学入試の問題を解くAIの開発を通じて、AIにできることとできないことを明らかにしようとした"],"answer":3,"explanation":"東ロボくんは、2011年に始まった国立情報学研究所のプロジェクト「ロボットは東大に入れるか」の愛称である。新井紀子らが中心となり、大学入試の問題を解くAIの開発に取り組んだ。模擬試験では多くの私立大学に合格できる水準の成績を収めた一方で、問題文の意味を本当に理解して解くことの難しさが明らかになり、東京大学への合格という目標は達成されなかった。知識を蓄えて処理するだけでは届かない、意味の理解の壁を示した事例として位置づけられる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g3-13","exam":"g","unit":"g-u3","keyword":"サポートベクターマシン(SVM)","type":"choice","syllabus_ref":"3.1","stem":"サポートベクターマシン（SVM）についての説明として、適切なものはどれか。","choices":["2つのクラスのデータを分ける境界を引くとき、境界に最も近いデータ点（サポートベクトル）までの距離であるマージンが最大になるように境界を決める分類手法である","データをランダムに分割して多数の決定木を作り、投票で分類する手法である","損失関数の勾配に沿って弱い学習器を逐次追加していく手法である","ラベルのないデータを、似たもの同士のグループに分ける手法である"],"answer":0,"explanation":"SVM は、マージン最大化を原理とする分類手法である。境界の位置は、境界に最も近いデータ点であるサポートベクトルによって決まる。多数の決定木の投票はランダムフォレスト（既存問題 g3-10）、勾配に沿った逐次追加は勾配ブースティング、ラベルなしのグループ分けはクラスタリング（中項目8「教師なし学習」）であり、いずれも SVM とは異なる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-14","exam":"g","unit":"g-u3","keyword":"マージン最大化","type":"choice","syllabus_ref":"3.1","stem":"SVM では、分類境界を w・x＋b＝0 と表し、サポートベクトル上では w・x＋b の値が ＋1 または −1 になるよう正規化されているものとする。このとき、2つのクラスの間にあるマージン（境界を挟んだ帯の幅）は 2／||w|| で与えられる。w＝(3, 4) のとき、マージンの幅はいくつか。","choices":["0.2","0.4","2.5","5"],"answer":1,"explanation":"||w||＝√(3²＋4²)＝√25＝5 である。マージンの幅は 2／||w||＝2／5＝0.4 になる。0.2 は境界から片側のサポートベクトルまでの距離（1／||w||）であり、帯全体の幅ではない。マージンを大きく取ることは、未知のデータが境界の近くに来ても誤分類しにくくなることにつながり、これがマージン最大化の狙いである。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-15","exam":"g","unit":"g-u3","keyword":"カーネル・カーネルトリック","type":"choice","syllabus_ref":"3.1","stem":"SVM におけるカーネル関数とカーネルトリックについての説明の組み合わせとして、正しいものはどれか。","choices":["カーネル関数はデータを圧縮するための関数であり、カーネルトリックは圧縮したデータを元の形に戻す技法である","カーネル関数は、2つのデータを高次元空間へ写像したときの内積を与える関数であり、カーネルトリックは、データを実際に高次元空間へ写像してから学習する技法である","カーネル関数は、データを高次元空間へ写像したときの内積を、写像そのものを計算せずに求められる関数であり、カーネルトリックは、この内積だけを用いることで、元の空間では直線で分離できないデータでも、高次元空間で分離する場合と等価な計算を行う技法である","カーネル関数は学習データの誤差を測る関数であり、カーネルトリックは誤差の小さいデータだけを選んで学習する技法である"],"answer":2,"explanation":"元の空間では直線（超平面）で分離できないデータでも、高次元の特徴空間へ写像すれば分離できる場合がある。ただし写像そのものを計算すると計算量が膨らむ。SVM の学習や分類に必要なのは写像先での内積だけであり、カーネル関数はその内積を写像を経ずに計算できる。内積だけを使って等価な計算を行う技法がカーネルトリックである。代表的なカーネル関数には、多項式カーネルや RBF（ガウシアン）カーネルがある。なお、畳み込み層でフィルタの重み行列を指す「カーネル」（中項目18）とは別の概念である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-16","exam":"g","unit":"g-u3","keyword":"ロジスティック回帰","type":"choice","syllabus_ref":"3.1","stem":"ロジスティック回帰についての説明として、適切なものはどれか。","choices":["目的変数の値を、説明変数の一次式でそのまま予測する回帰手法である","データ同士の距離に基づいて、近くにあるデータの多数決でクラスを決める手法である","木構造の条件分岐をたどってクラスを決める手法である","説明変数の一次式をシグモイド関数に通すことで、あるクラスに属する確率を出力し、その確率をもとに分類を行う手法であり、名前に「回帰」と付くが主に分類に用いられる"],"answer":3,"explanation":"ロジスティック回帰は、一次式の値をそのまま出力するのではなく、シグモイド関数で 0 から 1 の範囲に収まる確率に変換して出力する点が特徴である。確率が 0.5 以上かどうかなどでクラスを判定するため、実質的には分類手法として使われる。一次式で値をそのまま予測するのは線形回帰、条件分岐をたどるのは決定木である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-17","exam":"g","unit":"g-u3","keyword":"ロジスティック回帰","type":"choice","syllabus_ref":"3.1","stem":"ロジスティック回帰では、説明変数の一次式の値 z をシグモイド関数 σ(z)＝1／(1＋e^(−z)) に通して、陽性のクラスに属する確率とする。z＝ln3（ln は自然対数）のとき、この確率はいくつか。ただし、e^(ln3)＝3 である。","choices":["0.75","0.5","0.25","0.9"],"answer":0,"explanation":"e^(−ln3)＝1／e^(ln3)＝1／3 である。したがって σ(ln3)＝1／(1＋1／3)＝3／4＝0.75 になる。なお z＝0 のときは σ(0)＝0.5 であり、z が大きくなるほど確率は 1 に近づく。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-18","exam":"g","unit":"g-u3","keyword":"決定木","type":"choice","syllabus_ref":"3.1","stem":"決定木についての説明として、適切なものはどれか。","choices":["多数のニューロンの層を重ね、誤差を逆伝播させて学習する手法である","特徴量についての条件（分岐）を木構造に組み立て、根から葉まで条件をたどることで分類や回帰を行う手法であり、判断の過程を人が読み取りやすい","クラス間のマージンが最大になる境界を引く手法である","データを似たもの同士のグループに自動で分ける手法である"],"answer":1,"explanation":"決定木は、「特徴量がこの値以上か」といった条件の分岐を積み重ねた木構造で予測を行う。どの条件で判断したかがそのまま読み取れるため、解釈しやすい手法として知られる。分岐を増やして木を深くしすぎると訓練データに適合しすぎる（過学習、中項目10「モデルの選択・評価」）ため、深さの制限などの調整が行われる。なお、状態の移り変わりを表す探索木（中項目3「探索・推論」）とは別のものである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-19","exam":"g","unit":"g-u3","keyword":"決定木","type":"choice","syllabus_ref":"3.1","stem":"決定木の分岐の良さを測る指標の一つであるジニ不純度は、1つのノードについて「1 −（各クラスの割合の2乗の和）」で定義される。あるノードに陽性6件・陰性2件のデータが含まれるとき、このノードのジニ不純度はいくつか。","choices":["0.25","0.625","0.375","0.75"],"answer":2,"explanation":"各クラスの割合は、陽性が 6／8＝0.75、陰性が 2／8＝0.25 である。ジニ不純度は 1 −（0.75²＋0.25²）＝1 −（0.5625＋0.0625）＝1 − 0.625＝0.375 になる。0.625 は割合の2乗の和そのもので、1 から引く前の値である。ジニ不純度は、ノード内のデータが1つのクラスだけなら 0 になり、クラスが均等に混ざるほど大きくなる。決定木の学習では、分岐によってジニ不純度が大きく下がる条件が選ばれる。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-20","exam":"g","unit":"g-u3","keyword":"勾配ブースティング","type":"choice","syllabus_ref":"3.1","stem":"勾配ブースティングについての説明として、適切なものはどれか。","choices":["ブートストラップサンプリングで作った複数のデータセットで学習器を並列に作り、結果を平均する手法である","前の学習器が間違えたデータの重みを大きくしながら学習器を逐次追加する手法であり、損失関数の勾配は用いない","1本の決定木を、ジニ不純度が 0 になるまで成長させる手法である","損失関数の負の勾配（現在の予測の誤差である残差に相当する量）を次の弱い学習器に学習させ、学習率を掛けて逐次足し合わせることで、損失を少しずつ減らしていくアンサンブル手法である"],"answer":3,"explanation":"勾配ブースティングはブースティングの一種だが、誤ったデータへの重み付けではなく、損失関数の負の勾配を次の学習器が近似する点に特徴がある。二乗誤差を損失とする場合は、負の勾配は残差（実測値と現在の予測の差）そのものになるため、「前の段階の予測の残差を次の木が学ぶ」と説明される。弱い学習器には決定木がよく使われる。既存問題 g3-11 はブースティング一般（誤りに重みを移す逐次追加）を扱っており、本問は勾配を用いる方式に絞って中心命題を分けている。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-21","exam":"g","unit":"g-u3","keyword":"自己回帰モデル(ARモデル)・ベクトル自己回帰モデル(VARモデル)","type":"choice","syllabus_ref":"3.1","stem":"時系列データの予測に用いられる自己回帰モデル（ARモデル）とベクトル自己回帰モデル（VARモデル）の説明の組み合わせとして、正しいものはどれか。","choices":["ARモデルは、ある変数の現在の値を、その変数自身の過去の値の線形結合で表して予測するモデルであり、VARモデルはこれを複数の変数に拡張し、各変数が他の変数の過去の値からも影響を受ける形で表すモデルである","ARモデルは複数の変数の相互作用を表すモデルであり、VARモデルは1つの変数の過去の値だけで予測するモデルである","ARモデルは、ラベルのないデータからグループ構造を見つけるモデルであり、VARモデルはそのグループの数を決めるモデルである","ARモデルは過去の値を使わず現在の値だけで予測するモデルであり、VARモデルは未来の値を使って現在の値を説明するモデルである"],"answer":0,"explanation":"ARモデルは「自己回帰」の名のとおり、変数の現在の値を、その変数自身の過去の値への回帰で表す時系列モデルである。VARモデルは ARモデルを多変量に拡張したもので、複数の変数が互いの過去の値の影響を受け合う形で表される。需要予測や経済指標の分析など、時間の順序を持つデータの予測に用いられる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-22","exam":"g","unit":"g-u3","keyword":"アンサンブル学習・バギング・ブートストラップサンプリング","type":"choice","syllabus_ref":"3.1","stem":"アンサンブル学習、その代表的な方式であるバギング、およびバギングで用いられるブートストラップサンプリングについての説明の組み合わせとして、正しいものはどれか。","choices":["アンサンブル学習は1つの学習器を大きく育てる考え方であり、バギングは学習器を逐次追加する方式、ブートストラップサンプリングは誤ったデータの重みを増やす方法である","アンサンブル学習は複数の学習器の結果を組み合わせて予測する考え方であり、バギングはその代表的な方式の一つで、ブートストラップサンプリング（学習データから重複を許して同じ件数をランダムに取り出す方法）で作った複数のデータセットごとに学習器を並列に学習させ、結果を平均や多数決で統合する","アンサンブル学習は複数の学習器を組み合わせる考え方であり、バギングはブートストラップサンプリングで作ったデータセットに学習器を逐次追加し、前の学習器の誤りを次で補う方式である","アンサンブル学習は学習データの次元を減らす考え方であり、バギングは特徴量をランダムに選ぶ方式、ブートストラップサンプリングはデータを k 個に分割する方法である"],"answer":1,"explanation":"アンサンブル学習は、複数の学習器の結果を組み合わせることで、1つの学習器よりも安定して精度の高い予測を目指す考え方である。バギングはその代表的な方式で、名前は Bootstrap Aggregating に由来する。ブートストラップサンプリングで元データから少しずつ異なるデータセットを複数作り、それぞれで学習器を並列に学習させて統合するため、予測のばらつき（分散）が下がり、過学習が抑えられる。ランダムフォレスト（既存問題 g3-10）は、バギングに特徴量のランダムな選択を加えた発展形である。逐次追加していくのはブースティング（既存問題 g3-11）であり、バギングとは進め方が逆である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-23","exam":"g","unit":"g-u3","keyword":"分類問題・回帰問題・多クラス分類","type":"choice","syllabus_ref":"3.1","stem":"教師あり学習の問題の種類のあてはめとして、正しい組み合わせはどれか。「明日の株価の値を予測する」「メールがスパムかどうかを判定する」「花の画像から、あやめの3つの品種（セトサ・バージニカ・バーシカラー）のどれかを当てる」の3つのタスクを、この順に並べたものはどれか。","choices":["分類問題・回帰問題・多クラス分類","回帰問題・多クラス分類・分類問題","回帰問題・分類問題・多クラス分類","多クラス分類・回帰問題・分類問題"],"answer":2,"explanation":"目的変数が連続した数値である場合は回帰問題、決まったカテゴリ（クラス）のどれかである場合は分類問題に分類される。株価の値の予測は回帰問題、スパムかどうかの判定は2つのクラスへの分類問題である。分類の中でも、3つ以上のクラスから1つを選ぶものは多クラス分類と呼ばれる。問題の種類を見分けることが、教師あり学習のモデル選択の出発点になる（シラバス中項目7の目標）。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-24","exam":"g","unit":"g-u3","keyword":"線形回帰・単回帰分析・重回帰分析","type":"choice","syllabus_ref":"3.1","stem":"線形回帰と、説明変数の数による呼び分けについての説明として、正しいものはどれか。","choices":["線形回帰は、目的変数と説明変数の関係を曲線で近似する手法の総称であり、説明変数が1つの場合を重回帰分析、2つ以上ある場合を単回帰分析という","線形回帰は、あるクラスに属する確率を予測する手法であり、説明変数が1つの場合を単回帰分析、2つ以上ある場合を重回帰分析という","線形回帰は、目的変数を説明変数の一次式で表す手法であり、説明変数の数によらず単回帰分析と呼ばれる","線形回帰は、目的変数を説明変数の一次式（線形結合）で表し、予測と実測の誤差が小さくなるように式の係数を決める手法であり、説明変数が1つの場合を単回帰分析、2つ以上ある場合を重回帰分析という"],"answer":3,"explanation":"線形回帰は、目的変数を説明変数の一次式で表す回帰の基本形であり、係数の決定には、予測と実測の誤差の二乗の和を最小にする最小二乗法が代表的に用いられる。説明変数が1つだけの場合は単回帰分析、2つ以上ある場合は重回帰分析と呼ばれる。クラスに属する確率を予測するのはロジスティック回帰であり、線形回帰とは出力の形が異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g1-25","exam":"g","unit":"g-u1","keyword":"AI効果","type":"choice","syllabus_ref":"1.1","stem":"AI効果についての説明として、適切なものはどれか。","choices":["コンピュータが、これまで知能が必要とされてきた課題をこなせるようになると、その達成は「本当の知能によるものではない」とみなされるようになり、知能と呼ぶ基準がまだ達成されていない課題へ移っていく現象である","人工知能の性能が向上するにつれて、学習に必要な計算量と消費電力が増大していく現象である","人工知能を業務に導入した組織で、生産性や売上が向上することである","人工知能が学習データに適合しすぎて、未知のデータに対する精度が下がってしまう現象である"],"answer":0,"explanation":"AI効果は、AIが何かを達成するたびに「それは本当の知能ではない」と評価が切り替わり、知能とみなす基準が未達成の課題へ移っていく現象を指す。ラリー・テスラーが述べたとされる「AIとは、まだ成し遂げられていないことである」という言葉（テスラーの定理）で知られる。チェスでコンピュータが世界チャンピオンに勝った際に「力任せの計算にすぎない」と受け止められたのが典型例である。学習データへの適合しすぎは過学習であり、中項目10「モデルの選択・評価」で扱う別の概念である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目1「人工知能の定義」"},{"id":"g1-26","exam":"g","unit":"g-u1","keyword":"AI効果","type":"choice","syllabus_ref":"1.1","stem":"次の出来事のうち、AI効果の例として最も適切なものはどれか。","choices":["音声認識がスマートフォンの標準機能として組み込まれ、多くの人が日常的に使うようになった","画像認識の精度が、学習データの増加とモデルの改良によって年々向上した","囲碁でコンピュータがトップ棋士に勝利したとき、「大量の計算をしているだけで、本当の知能とは言えない」という受け止めが広がった","機械翻訳の精度が上がり、翻訳者が担っていた仕事の一部が置き換えられた"],"answer":2,"explanation":"AI効果が指すのは、技術の普及や性能の向上そのものではなく、達成された能力が「本当の知能ではない」とみなされるようになる評価の変化である。トップ棋士への勝利が「計算にすぎない」と受け止められた例がこれに当たる。他の選択肢は、普及・性能向上・仕事の置き換えを述べており、知能と呼ぶ基準が移る現象ではない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目1「人工知能の定義」"},{"id":"g1-27","exam":"g","unit":"g-u1","keyword":"エージェント","type":"choice","syllabus_ref":"1.1","stem":"人工知能の分野でいう「エージェント」についての説明として、適切なものはどれか。","choices":["人間に代わって契約や交渉を行う業務だけを担うソフトウェアのことである","センサーを通じて環境の状態を知覚し、その情報に基づいて行動を選択し、アクチュエータ（動作機構）を通じて環境に働きかける存在のことである","大量の学習データを蓄積し、管理するためのデータベースのことである","人間の姿を模して作られたロボットのことだけを指す言葉である"],"answer":1,"explanation":"エージェントは、知覚と行動を通じて環境と相互作用する存在を指す、人工知能の基本概念である。身体を持つロボットも、ソフトウェアとして動作するものもエージェントになり得る。目標に対してより良い結果が得られるように行動を選ぶものを、合理的エージェントと呼ぶ。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目1「人工知能の定義」"},{"id":"g1-28","exam":"g","unit":"g-u1","keyword":"エージェント","type":"choice","syllabus_ref":"1.1","stem":"部屋の様子をセンサーで捉えながら移動し、ゴミを検知して吸い込み、バッテリーが減ると自分で充電台に戻るロボット掃除機がある。この掃除機をエージェントの観点から説明したものとして、適切なものはどれか。","choices":["センサーで環境を知覚してはいるが、あらかじめプログラムで決められた動作を行うものであるため、エージェントとは言えない","ゴミを吸い込むという物理的な仕事をする機械であるため、ロボットには分類されるが、エージェントの概念には含まれない","データを蓄積するだけの存在であり、環境に対して働きかけることはないため、エージェントとは言えない","センサーで部屋やゴミの状態を知覚し、「部屋をきれいにする」という目標に対して行動を選択し、車輪や吸引機構を通じて環境に働きかけるエージェントである"],"answer":3,"explanation":"エージェントかどうかは、姿や用途ではなく、知覚し、行動を選択し、環境へ働きかけるという関わり方で決まる。ロボット掃除機は、センサーで知覚し、充電台に戻るかどうかを含めて行動を選び、物理的に環境へ働きかけるため、エージェントの代表例である。ロボットであることとエージェントであることは矛盾しない。なお、知能と身体の関わりそのものを問う「身体性」は中項目2の問題（g1-10）で扱っている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目1「人工知能の定義」"},{"id":"g1-29","exam":"g","unit":"g-u1","keyword":"機械学習・ディープラーニング","type":"choice","syllabus_ref":"1.1","stem":"人工知能・機械学習・ディープラーニング（深層学習）の関係についての説明として、正しいものはどれか。","choices":["ディープラーニングは、多層のニューラルネットワークを用いる機械学習の一手法であり、機械学習は人工知能を実現するためのアプローチの一つである。したがって、ディープラーニングは機械学習に含まれ、機械学習は人工知能に含まれる","機械学習はディープラーニングの一種であり、人工知能は機械学習の一種である","人工知能・機械学習・ディープラーニングは、それぞれ重なりのない別々の技術分野である","ディープラーニングは人工知能には含まれるが、機械学習には含まれない独立した手法である"],"answer":0,"explanation":"3つの概念は包含関係にある。人工知能が最も広い概念であり、その実現アプローチの一つが機械学習、機械学習の中の一手法がディープラーニングである。エキスパートシステムのようなルールベースの手法は、人工知能ではあるが機械学習ではない。本問は「定義の包含関係」に絞ったもので、4レベルの分類は g1-07、機械学習そのものの説明は中項目5、ディープラーニングの発展は中項目6で扱っている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目1「人工知能の定義」"},{"id":"g1-30","exam":"g","unit":"g-u1","keyword":"人工知能","type":"choice","syllabus_ref":"1.1","stem":"人工知能（AI）とロボットの違いについての説明として、適切なものはどれか。","choices":["AIは人間の姿をした機械を指し、ロボットは人間の姿をしていない機械を指す","AIは知的な判断や学習を行うソフトウェア・仕組みの側を指し、ロボットはセンサーや駆動部を持ち物理的に動作する機械の側を指す。そのため、AIを搭載しないロボットも、身体を持たないAIも存在する","AIとロボットは同じものを指す言葉であり、両者に違いはない","ロボットは必ずAIを搭載しており、AIは必ずロボットの形で提供される"],"answer":1,"explanation":"AIは「知的な振る舞いを実現する仕組み」であり、ロボットは「物理的に動作する機械」である。決められた動作を繰り返すだけの産業用ロボットのようにAIを持たないロボットもあれば、対話ソフトウェアのように身体を持たないAIもある。両者が重なるのは、AIを搭載したロボットの場合である。人工知能に定まった定義はないことは g1-11 で扱っており、本問は2つの概念の区別に絞っている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目1「人工知能の定義」"},{"id":"g3-25","exam":"g","unit":"g-u3","keyword":"k-means法","type":"choice","syllabus_ref":"3.2","stem":"k-means法についての説明として、適切なものはどれか。","choices":["データを階層的に併合していき、樹形図で表されるクラスタ構造を作る手法である","あらかじめクラスタ数kを決め、各データを最も近い重心（中心）を持つクラスタへ割り当て、重心をクラスタ内のデータの平均で更新する手順を、割り当てが変わらなくなるまで繰り返す手法である","データの密度が高い領域をクラスタとして検出し、まばらな領域のデータを外れ値として扱う手法である","各データが複数のクラスタへ確率的に所属する度合いを求める手法である"],"answer":1,"explanation":"k-means法は、代表的な非階層型（分割型）のクラスタリング手法である。クラスタ数kを先に決め、「各データを最も近い重心のクラスタへ割り当てる」「重心を割り当てられたデータの平均位置へ移す」という2つの手順を繰り返すことで、クラスタ内のデータと重心との距離の合計が小さくなるような分け方に近づけていく。樹形図を作るのは階層型クラスタリングであり、本バッチのウォード法などで扱う。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-26","exam":"g","unit":"g-u3","keyword":"k-means法","type":"choice","syllabus_ref":"3.2","stem":"k-means法で、1次元のデータ 2、3、10、11 を2つのクラスタに分ける。初期の重心を2と10に置き、「各データを近い方の重心のクラスタへ割り当てる→重心をクラスタ内のデータの平均に更新する」という手順を1回行った後の、2つの重心の組として正しいものはどれか。","choices":["2と10","3と11","2.5と10.5","2.5と6.5"],"answer":2,"explanation":"割り当ては、2と3が重心2の側（距離はそれぞれ0と1で、重心10までより近い）、10と11が重心10の側になる。更新後の重心は各クラスタ内の平均なので、(2＋3)÷2＝2.5 と (10＋11)÷2＝10.5 になる。3と11は各クラスタの最大値であり、6.5は全データの平均で、いずれも重心の更新結果ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-27","exam":"g","unit":"g-u3","keyword":"ウォード法","type":"choice","syllabus_ref":"3.2","stem":"クラスタリングの手法の一つであるウォード法についての説明として、適切なものはどれか。","choices":["階層型クラスタリングの併合基準の一つで、2つのクラスタを併合したときにクラスタ内のばらつき（各データとそのクラスタの重心との距離の二乗和）の増加が最も小さくなる組み合わせを選んで併合していく方法である","あらかじめ決めたクラスタ数kに対して、重心を繰り返し更新していく方法である","各データ点の近傍の密度に基づいてクラスタを検出する方法である","データの分散が最も大きくなる軸を求めて低次元へ射影する方法である"],"answer":0,"explanation":"ウォード法は、凝集型の階層型クラスタリングで用いられる併合基準である。併合のたびに増えるクラスタ内平方和（ばらつき）を最小に抑える組み合わせから順に併合するため、比較的まとまりのよい（球形に近い）クラスタが得られやすい。重心を繰り返し更新するのは k-means法、分散が最大になる軸を求めるのは主成分分析である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-28","exam":"g","unit":"g-u3","keyword":"ウォード法・デンドログラム (樹形図)","type":"choice","syllabus_ref":"3.2","stem":"ウォード法による階層型クラスタリングの結果をデンドログラム（樹形図）で表した。図の読み方と結果の解釈として、適切なものはどれか。","choices":["縦軸の高さは、併合された順番の番号を表している","横に切る位置を低くするほど、得られるクラスタの数は少なくなる","ウォード法では併合の組み合わせが無作為に決まるため、同じデータでもデンドログラムは実行のたびに異なる形になる","縦軸の高さは併合の際のクラスタ内平方和の増加の大きさに対応し、ある高さで横に切ると、その時点で分かれている枝の数がそのままクラスタ数になる"],"answer":3,"explanation":"デンドログラムは、どのデータ（クラスタ）同士が、どの段階で併合されたかを枝のつながりで表した図である。ウォード法では縦軸の高さが併合によるクラスタ内平方和の増加に対応する。図をある高さで横に切ると、その高さより下でつながっている枝ごとのまとまりがクラスタとなり、切る位置が高いほどクラスタ数は少なく、低いほど多くなる。併合の順序は基準によって決定的に定まるため、実行のたびに形が変わることはない。本問は、ウォード法の併合基準とデンドログラムの読み方の両方を知らなければ正解に到達できない形にした複合である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-29","exam":"g","unit":"g-u3","keyword":"協調フィルタリング","type":"choice","syllabus_ref":"3.2","stem":"協調フィルタリングについての説明として、適切なものはどれか。","choices":["商品の説明文やジャンルなどの属性情報を分析して、特徴の似た商品を推薦する方法である","利用者の年齢や性別などの属性が近い利用者同士を集計し、その集団で人気の商品を推薦する方法である","多くの利用者の購買履歴や評価のデータから、好みの傾向が似た利用者同士の関係や、一緒に高く評価されることの多い商品同士の関係を見つけ、それをもとに推薦を行う方法である","新しい商品については過去のデータがなくても、内容の特徴から正確に推薦できる方法である"],"answer":2,"explanation":"協調フィルタリングは、商品の内容ではなく、利用者と商品の評価・購買の履歴そのものを使う推薦手法である。「この商品を買った人は、これも買っている」「あなたと好みの似た利用者は、これを高く評価した」という関係から推薦を決める。商品の特徴を使うのはコンテンツベースフィルタリングである。また、新しい利用者や商品については履歴がないため推薦が難しく、これはコールドスタート問題として知られる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-30","exam":"g","unit":"g-u3","keyword":"コンテンツベースフィルタリング","type":"choice","syllabus_ref":"3.2","stem":"コンテンツベースフィルタリングについての説明として、適切なものはどれか。","choices":["他の利用者の評価データを集め、好みの似た利用者が高く評価した商品を推薦する方法である","商品そのものの特徴（ジャンル、キーワード、出演者など）と、利用者が過去に好んだ商品の特徴とを照合し、特徴の似た商品を推薦する方法である","利用者がまだ評価していない商品については、特徴のデータがそろっていても推薦に使うことができない方法である","推薦の根拠は商品の価格帯のみであり、内容の特徴は一切使わない方法である"],"answer":1,"explanation":"コンテンツベースフィルタリングは、商品の内容的な特徴と、利用者の好みの特徴（過去に好んだ商品の特徴の集約）とを照合する推薦手法である。他の利用者のデータを必要としないため、評価がまだ付いていない新しい商品でも、特徴さえ分かれば推薦できる。一方で、過去に好んだものと特徴の似た商品ばかりが推薦されやすく、意外な発見につながりにくいという弱点がある。他の利用者の評価を使うのは協調フィルタリングである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-31","exam":"g","unit":"g-u3","keyword":"コールドスタート問題","type":"choice","syllabus_ref":"3.2","stem":"推薦システムにおけるコールドスタート問題についての説明として、適切なものはどれか。","choices":["新規の利用者や新規の商品については、購買履歴や評価などのデータが不足しているため、協調フィルタリングでは適切な推薦が難しくなる問題である","システムの起動直後は推薦モデルの読み込みに時間がかかり、応答が遅くなる問題である","利用者の数が増えすぎると、推薦のための計算量が膨大になる問題である","季節や流行の変化によって利用者の好みが移り変わり、過去のデータが当てにならなくなる問題である"],"answer":0,"explanation":"コールドスタート問題は、データがまだ蓄積されていない対象（新規登録した利用者、新しく追加された商品）に対して、履歴に基づく推薦が機能しない問題を指す。協調フィルタリングは履歴そのものを使うため、この問題の影響を直接受ける。対策として、登録時に好みを尋ねる、人気の商品を提示する、商品の特徴を使うコンテンツベースフィルタリングと組み合わせる、といった方法が取られる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-32","exam":"g","unit":"g-u3","keyword":"教師なし学習","type":"choice","syllabus_ref":"3.2","stem":"ある小売チェーンが、会員ごとの購入金額・来店頻度・購入カテゴリなどのデータを持っている。正解となるグループ分けは存在しないが、購買行動の似た会員同士をグループに分けて、グループごとに販促施策を変えたい。この目的に最も適したアプローチはどれか。","choices":["各会員の次回の購入金額を予測する回帰モデルを、正解ラベル付きのデータで学習させる","会員が優良顧客かどうかを分類するモデルを、過去の優良顧客のラベルを使って学習させる","会員の行動に対して報酬を与え、累積報酬が最大になる施策の選び方を試行錯誤で学習させる","ラベルのないデータに対してクラスタリングなどの教師なし学習を適用し、購買行動の似た会員同士をグループ化する"],"answer":3,"explanation":"教師なし学習は、正解ラベルを必要とせず、特徴量だけからデータの構造（似たもの同士のまとまりなど）を見つける学習である。あらかじめ正しいグループ分けが存在しない顧客のセグメンテーションは、その代表的な応用例である。回帰や分類はラベル付きデータを必要とする教師あり学習、報酬による試行錯誤は強化学習であり、目的が異なる。本問は中項目の目標「ビジネスにおける教師なし学習の応用例」に対応する応用問題として置いた。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-33","exam":"g","unit":"g-u3","keyword":"主成分分析 (PCA)","type":"choice","syllabus_ref":"3.2","stem":"主成分分析（PCA）についての説明として、適切なものはどれか。","choices":["データを似たもの同士のグループに分けるクラスタリングの手法である","元の特徴量の線形結合によって、データのばらつき（分散）が最も大きくなる方向（主成分）を順に求め、情報の損失を抑えながら、もとの特徴量より少ない軸でデータを表現し直す手法である","各文書が複数のトピックの混合で生成されると仮定する確率モデルである","データ同士の距離の関係を保ちながら、非線形な変換で2次元に配置する可視化の手法である"],"answer":1,"explanation":"主成分分析は、次元削減の代表的な手法である。第1主成分はデータの分散が最大になる方向、第2主成分はそれと直交する中で分散が最大になる方向、というように軸を順に取り、上位の主成分だけを使うことで、情報の損失を抑えながら特徴量の数を減らせる。既存の g3-12 は「次元削減の手法はどれか」という同定の問題であり、本問は主成分分析そのものの仕組みに絞って角度を分けた。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-34","exam":"g","unit":"g-u3","keyword":"特異値分解 (SVD)","type":"choice","syllabus_ref":"3.2","stem":"特異値分解（SVD）についての説明として、適切なものはどれか。","choices":["正方行列にだけ適用できる分解であり、固有値分解と全く同じものである","クラスタリングの際に、重心の初期位置を決めるための手法である","任意の行列を、直交行列・対角行列（特異値を並べたもの）・直交行列の積に分解する方法であり、特異値の大きい成分だけを残すことで、次元削減やノイズの除去に利用される","文書集合からトピックを抽出するための確率的な生成モデルである"],"answer":2,"explanation":"特異値分解は、正方でない行列にも適用できる行列の分解である。分解で得られる特異値は成分の重要度に対応し、小さい特異値の成分を落とすことで、元の行列を低いランクで近似できる。これが次元削減や推薦（評価行列の近似）などに応用される。主成分分析も、データ行列の特異値分解と深く関係している。文書の生成モデルとしてトピックを扱うのは潜在的ディリクレ配分法である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-35","exam":"g","unit":"g-u3","keyword":"t-SNE","type":"choice","syllabus_ref":"3.2","stem":"t-SNEについての説明として、適切なものはどれか。","choices":["高次元データの可視化に用いられる次元削減の手法で、近くにあるデータ同士の関係（局所的な構造）を保ちながら、データを2次元や3次元の平面上に配置する","データの分散が最大になる軸を、特徴量の線形結合として求める手法である","クラスタ数をあらかじめ決め、重心を繰り返し更新してデータを分ける手法である","任意の行列を3つの行列の積に分解する手法である"],"answer":0,"explanation":"t-SNEは、高次元のデータを人間が眺められる2次元・3次元に落とすための、非線形の次元削減手法である。元の空間で近いデータ同士は低次元でも近くに置かれるように設計されており、データのまとまり（クラスタ）の様子を目で確かめる用途で広く使われる。一方、離れたデータ同士の距離や、まとまり同士の位置関係は元の空間を忠実に表すとは限らない点に注意が要る。分散が最大の軸を求めるのは主成分分析、行列の積への分解は特異値分解である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-36","exam":"g","unit":"g-u3","keyword":"多次元尺度構成法 (MDS)","type":"choice","syllabus_ref":"3.2","stem":"多次元尺度構成法（MDS）についての説明として、適切なものはどれか。","choices":["文書に含まれる単語の出現の仕方から、文書のトピックを推定する方法である","クラスタ同士の併合の過程を樹形図として表す方法である","特徴量の分散が大きい順に主成分を抽出する方法である","対象同士の類似度や距離（非類似度）の情報だけをもとに、その距離関係をできるだけ再現するように、対象を低次元空間（主に2次元）に配置する方法である"],"answer":3,"explanation":"多次元尺度構成法は、対象同士の「どれくらい似ているか・離れているか」という関係のデータが出発点になる。元の特徴量そのものがなくても、距離や類似度の表さえあれば配置が作れるのが特徴で、ブランド同士のイメージの近さなどを地図のように表す用途で使われる。樹形図はデンドログラム、主成分の抽出は主成分分析、トピックの推定はトピックモデルの範囲である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-37","exam":"g","unit":"g-u3","keyword":"潜在的ディリクレ配分法 (LDA)","type":"choice","syllabus_ref":"3.2","stem":"潜在的ディリクレ配分法（LDA）についての説明として、適切なものはどれか。","choices":["各文書を、あらかじめ人間が用意したカテゴリのうちの1つに分類する、教師あり学習の手法である","文書中の単語の並び順を学習し、次に来る単語を予測する手法である","各文書が複数のトピックの混合で構成され、各トピックが単語の出現確率の分布を持つと仮定する確率的な生成モデルで、文書集合から潜在的なトピックを抽出するために用いられる","単語を低次元のベクトルに変換し、単語同士の意味の近さを表すための手法である"],"answer":2,"explanation":"LDAは、トピックモデルの代表的な手法である。「文書はトピックの混合割合を持ち、トピックごとに単語が出やすい・出にくいという分布がある」という生成の仮定を置き、観測された文書集合から、トピックの単語分布と文書のトピック混合を逆に推定する。1つの文書が複数のトピックを併せ持てる点が、1文書1カテゴリの分類とは異なる。単語のベクトル表現は中項目30「データ生成」側の範囲である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-38","exam":"g","unit":"g-u3","keyword":"トピックモデル","type":"choice","syllabus_ref":"3.2","stem":"トピックモデルについての説明として、適切なものはどれか。","choices":["ニュース記事を公開された日時の順に並べ替えるためのモデルである","大量の文書集合を分析し、各文書がどのような話題（トピック）の組み合わせで構成されているかを、人手でラベルを付けなくても抽出できるようにするモデルであり、潜在的ディリクレ配分法（LDA）が代表例である","文書の誤字や脱字を自動で見つけて修正するためのモデルである","利用者の評価データから、好みの似た利用者を探し出す推薦のためのモデルである"],"answer":1,"explanation":"トピックモデルは、文書集合に潜む話題の構造を、ラベルなしで抽出するためのモデルの総称である。ニュース記事の集合から「政治」「経済」「スポーツ」といった話題のまとまりと、各記事の話題の混合具合を自動で得る、といった使い方がされる。前の g3-37 が代表例である LDA の内部の生成の仮定を問うのに対し、本問はトピックモデルというモデル群そのものの役割に絞っている。利用者の評価から推薦するのは協調フィルタリングの範囲である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-39","exam":"g","unit":"g-u3","keyword":"マルコフ決定過程","type":"choice","syllabus_ref":"3.3","stem":"強化学習の問題設定の基礎となるマルコフ決定過程（MDP）についての説明として、適切なものはどれか。","choices":["正解ラベル付きのデータを、状態と正解の行動の組として集め、分類問題として解くための枠組みである","次の状態は、現在の状態と行動だけでなく、それまでの全ての状態と行動の履歴に依存すると仮定する枠組みである","エージェントが状態を観測して行動を選び、環境が次の状態と報酬を返すやり取りを、状態・行動・状態遷移確率・報酬で表した枠組みであり、次の状態は現在の状態と選んだ行動のみに依存する（マルコフ性）と仮定する","報酬を用いずに、観測データの特徴を圧縮して表現するための枠組みである"],"answer":2,"explanation":"マルコフ決定過程は、強化学習の標準的な問題設定を表す枠組みである。エージェントと環境が「状態の観測→行動の選択→環境からの報酬と次の状態」というやり取りを繰り返す様子を、状態・行動・遷移確率・報酬の組で記述する。マルコフ性とは「未来は、過去の履歴全体ではなく、現在の状態を通してのみ過去に依存する」という仮定であり、履歴全体への依存を仮定する設定はマルコフ決定過程そのものではない。正解ラベルを使うのは教師あり学習の枠組みである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-40","exam":"g","unit":"g-u3","keyword":"状態価値関数","type":"choice","syllabus_ref":"3.3","stem":"強化学習における状態価値関数 V(s) についての説明として、適切なものはどれか。","choices":["ある方策に従って行動し続けたときに、状態 s を起点として将来に得られると期待される割引累積報酬（各時点の報酬を割引率で割り引いて合計したもの）の期待値である","状態 s において、その場で即座に得られる報酬の値そのものである","状態 s へ遷移してくる確率を表す関数である","状態 s で取り得る行動の数を数える関数である"],"answer":0,"explanation":"状態価値関数は、方策の下での「その状態の良さ」を、将来の報酬の割引合計の期待値として表したものである。即時報酬だけではなく、その後に続く報酬も含めて評価する点が重要である。遷移確率は環境の側の性質であり、価値関数とは別のものである。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-41","exam":"g","unit":"g-u3","keyword":"行動価値関数","type":"choice","syllabus_ref":"3.3","stem":"強化学習における行動価値関数 Q(s, a) についての説明として、適切なものはどれか。","choices":["状態 s で行動 a が正解かどうかを、0 か 1 かで表す関数である","状態 s で行動 a を取った後、ある方策に従い続けたときに得られると期待される割引累積報酬の期待値であり、最適な行動価値関数が分かれば、各状態でその値が最大になる行動を選ぶことが最適な方策になる","状態 s で行動 a がこれまでに選ばれた回数を数える関数である","環境の遷移確率だけから決まり、報酬とは無関係に定まる関数である"],"answer":1,"explanation":"行動価値関数は、状態と行動の組に対する期待リターンを表す。状態価値関数が「その状態から方策に従った場合」を行動の選択まで含めて平均化して表すのに対し、行動価値関数は最初の行動を固定して評価する。Q 学習などの価値ベースの手法は、この行動価値関数を推定することで方策を導く。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-42","exam":"g","unit":"g-u3","keyword":"割引率","type":"choice","syllabus_ref":"3.3","stem":"強化学習の割引率 γ（0 ≦ γ ≦ 1）についての説明として、適切なものはどれか。","choices":["1回の更新で価値関数の推定値を書き換える割合を決める係数であり、学習率とも呼ばれる","割引率を大きくするほど、遠い将来の報酬は軽く扱われ、目先の報酬だけを重視する評価になる","割引率は 1 より大きい値を取るのが普通であり、将来の報酬ほど大きく評価される","将来に得られる報酬の価値を、現在の価値に換算するときの割り引きの度合いを決める係数であり、割引累積報酬は、各時点の報酬に γ の経過時間乗を掛けて合計して計算される"],"answer":3,"explanation":"割引率は、将来の報酬を現在価値に割り引くための係数である。γ が 1 に近いほど遠い将来の報酬まで重視し、γ が 0 に近いほど目先の報酬を重視する評価になる。価値関数の更新の歩幅を決めるのは学習率であり、割引率とは別の係数である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-43","exam":"g","unit":"g-u3","keyword":"割引率","type":"choice","syllabus_ref":"3.3","stem":"あるエージェントが、時刻 0、1、2 にそれぞれ報酬 1、2、4 を得た。時刻 t に得た報酬には割引率 γ の t 乗（γ^t）を掛けて合計するものとし、γ＝0.5 のとき、時刻 0 の時点から見た割引累積報酬として正しいものはどれか。","choices":["7","3","1.5","4"],"answer":1,"explanation":"各報酬に γ の経過時刻乗を掛けて合計する。1×（0.5 の 0 乗）＋ 2×（0.5 の 1 乗）＋ 4×（0.5 の 2 乗）＝ 1 ＋ 1 ＋ 1 ＝ 3 になる。7 は割引を全く掛けていない単純合計、1.5 は指数を 1 つずらしてしまった場合、4 は全ての将来報酬に一律で γ の 1 乗だけを掛けた場合の値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-44","exam":"g","unit":"g-u3","keyword":"Q 学習","type":"choice","syllabus_ref":"3.3","stem":"Q 学習についての説明として、適切なものはどれか。","choices":["方策をパラメータで表し、得られた累積報酬が大きくなる方向へ方策のパラメータを勾配法で更新する手法である","更新には、行動を決める方策に従って実際に次に取る行動の行動価値を使う手法である","行動価値関数 Q(s, a) を学習する手法で、更新には、実際に次に取る行動によらず、次の状態における行動価値の最大値を用いる。このため、行動を決める方策と学習対象の方策を分けることができる（オフポリシー）","環境の状態遷移確率と報酬のモデルを明示的に構築し、そのモデルを使って将来の計画を立てる手法である"],"answer":2,"explanation":"Q 学習は、行動価値関数を試行錯誤の経験から逐次更新する、モデルフリーでオフポリシーな TD 学習の代表的手法である。更新に次の状態での最大値を使う点が特徴で、ε-greedy 方策などで行動を選びながら、貪欲方策（最も価値の高い行動を選ぶ方策）を学習の対象にできる。実際に次に取る行動の行動価値を使うのは SARSA であり、方策のパラメータを勾配法で更新するのは方策勾配法である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-45","exam":"g","unit":"g-u3","keyword":"Q 学習","type":"choice","syllabus_ref":"3.3","stem":"Q 学習の更新は、Q(s, a) ← Q(s, a) ＋ α｛r ＋ γ ×（次の状態 s′ における行動価値の最大値）− Q(s, a)｝ という式で行われる。現在の Q(s, a)＝2.0、学習率 α＝0.5、得られた報酬 r＝1、次の状態における行動価値の最大値＝4.0、割引率 γ＝0.9 のとき、更新後の Q(s, a) の値として正しいものはどれか。","choices":["3.3","4.6","2.6","3.5"],"answer":0,"explanation":"まず更新の目標値は r ＋ γ × 最大値 ＝ 1 ＋ 0.9×4.0 ＝ 4.6 である。現在の値 2.0 との差は 4.6 − 2.0 ＝ 2.6 で、これに学習率 0.5 を掛けた 1.3 だけ現在の値を目標の側へ寄せるので、更新後は 2.0 ＋ 1.3 ＝ 3.3 になる。4.6 は目標値そのもの、2.6 は差（TD 誤差）そのものであり、3.5 は割引率を掛け忘れた場合の値である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-46","exam":"g","unit":"g-u3","keyword":"SARSA","type":"choice","syllabus_ref":"3.3","stem":"SARSA についての説明として、適切なものはどれか。","choices":["更新に次の状態における行動価値の最大値を用いるため、行動を決める方策と学習対象の方策を分けることができる手法である","方策をパラメータで表し、そのパラメータを勾配法で直接更新する手法である","環境の状態遷移と報酬のモデルを学習してから、そのモデルで計画を立てる手法である","行動価値関数を学習する手法で、更新には、行動を決める方策に従って実際に次に取る行動の行動価値を使う。名前は更新に使う状態・行動・報酬・次の状態・次の行動の組（S, A, R, S, A）に由来し、行動を決める方策そのものを評価・改善するオンポリシーな手法である"],"answer":3,"explanation":"SARSA は Q 学習と同じく行動価値関数を学ぶ TD 学習の手法だが、更新に「次に実際に取る行動」の価値を使う点が異なる。そのため、探索的な行動（ランダムに選んだ行動など）の影響も含めて方策を評価するオンポリシーな手法になる。最大値を使って方策を分けられるのは Q 学習である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-47","exam":"g","unit":"g-u3","keyword":"方策勾配法","type":"choice","syllabus_ref":"3.3","stem":"方策勾配法についての説明として、適切なものはどれか。","choices":["行動価値関数の推定値だけから、各状態で最も価値の高い行動を決める手法である","方策をパラメータで表し、期待される累積報酬が大きくなる方向へ方策のパラメータを勾配法で更新する手法であり、行動を確率的に選ぶ方策そのものを学習できる","環境の状態遷移確率のモデルを学習し、そのモデルで将来を予測しながら方策を決める手法である","各ステップで得られる即時報酬だけが最大になるように方策を更新する手法である"],"answer":1,"explanation":"方策勾配法は、価値関数を経由せずに方策そのものを最適化の対象とする手法の総称である。方策が確率的に行動を選ぶ形を直接扱えるため、連続的な行動空間など、行動価値の最大値を探すのが難しい場面にも適用しやすい。即時報酬ではなく、エピソードを通じた累積報酬の期待値を大きくすることが目的である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-48","exam":"g","unit":"g-u3","keyword":"REINFORCE","type":"choice","syllabus_ref":"3.3","stem":"REINFORCE についての説明として、適切なものはどれか。","choices":["行動価値関数を学習し、その値が最大になる行動を選ぶことで間接的に方策を決める手法である","1 ステップごとの報酬と状態遷移を使う TD 学習によって、価値関数を逐次更新する手法である","方策勾配法の代表的な手法で、エピソードを最後まで実行して得られた累積報酬（リターン）を使い、そのエピソードで選ばれた行動の系列の生じやすさを、リターンの大きさに応じて増減させる。更新にエピソードの終わりまで待つ必要がある、モンテカルロ的な方法である","価値関数を推定する部分と方策を更新する部分を組み合わせ、価値関数の評価を使って方策の更新を行う手法である"],"answer":2,"explanation":"REINFORCE は、方策勾配法の古典的で代表的な手法である。エピソード終了後に得られたリターンを使い、よい結果につながった行動の選択確率を上げ、悪かった行動の確率を下げる。価値関数を使わないため更新のばらつきが大きくなりやすく、リターンから基準値（ベースライン）を引くなどの工夫が知られている。価値関数を組み合わせるのは Actor-Critic である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-49","exam":"g","unit":"g-u3","keyword":"Actor-Critic","type":"choice","syllabus_ref":"3.3","stem":"Actor-Critic についての説明として、適切なものはどれか。","choices":["方策を更新する Actor（行動役）と、価値関数を推定して方策の出来を評価する Critic（評価役）を組み合わせた手法であり、Critic の評価を利用することで、方策の更新のばらつきを抑えることができる","2 体のエージェントが互いに競い合いながら学習する、マルチエージェント専用の手法である","行動価値関数の最大値だけを使って方策を決める、価値ベースの手法である","環境のモデルを Actor、方策を Critic と呼んで構築する、モデルベースの手法である"],"answer":0,"explanation":"Actor-Critic は、方策勾配法に価値関数の推定を組み合わせた手法である。Critic が推定する価値との差（優位さ）を使って Actor を更新することで、エピソードの終わりまで待つ REINFORCE よりも更新のばらつきを抑え、学習を進めやすくできる。深層強化学習の A3C なども、この考え方を基礎にしている。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-50","exam":"g","unit":"g-u3","keyword":"バンディットアルゴリズム","type":"choice","syllabus_ref":"3.3","stem":"バンディットアルゴリズム（多腕バンディット問題への解法）についての説明として、適切なものはどれか。","choices":["状態遷移のある環境で、長期的な方策を学習するための手法である","正解ラベル付きのデータから分類器を学習するための手法である","報酬の期待値が分からない複数の選択肢（スロットマシンの腕など）から繰り返し 1 つを選ぶ場面で、まだよく分かっていない選択肢を試す探索と、現時点で最良と思われる選択肢を使う活用のバランスを取りながら、累積報酬を大きくするための手法である","複数のエージェントが協調して一つの環境を学習するための手法である"],"answer":2,"explanation":"多腕バンディット問題は、状態遷移を考えない、強化学習の最も単純な設定である。行動の結果が次の状態に影響しないため、問題は「探索と活用のバランス」に絞られる。ε-greedy 方策や UCB 方策が代表的な解法であり、強化学習全般に通じる探索と活用の考え方の基礎になっている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-51","exam":"g","unit":"g-u3","keyword":"ε-greedy 方策","type":"choice","syllabus_ref":"3.3","stem":"ε-greedy 方策（イプシロン・グリーディ方策）についての説明として、適切なものはどれか。","choices":["常に、推定価値が最大の行動だけを選び続ける方策である","行動を常に完全にランダムに選ぶ方策である","各行動の推定価値に応じて、選択確率をなめらかに変える方策である","確率 ε でランダムな行動を選んで探索し、確率 1−ε で推定価値が最大の行動を選んで活用する方策であり、ε の大きさで探索と活用のバランスを調整する"],"answer":3,"explanation":"ε-greedy 方策は、探索と活用を切り替える最も単純な方策の一つである。常に最良の行動だけを選ぶと、まだ試していない行動の価値が分からないままになるため、一定の確率でランダムに行動を選んで探索する。学習の進行に合わせて ε を徐々に小さくしていく運用もよく行われる。推定価値に応じて確率をなめらかに変えるのは、ソフトマックス（ボルツマン）選択の説明である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-52","exam":"g","unit":"g-u3","keyword":"UCB 方策","type":"choice","syllabus_ref":"3.3","stem":"バンディット問題などで使われる UCB 方策（Upper Confidence Bound：信頼上限）についての説明として、適切なものはどれか。","choices":["選んだ回数が多い行動ほど、さらに優先して選ぶ方策である","各行動について、推定価値に「試した回数が少ないほど大きくなる不確実性の上乗せ分」を加えた値を比べ、最も大きな値の行動を選ぶ方策であり、十分に試されていない行動が自然に探索される","確率 ε でランダムな行動を選ぶ方策である","推定価値が最大の行動を常に選ぶ方策である"],"answer":1,"explanation":"UCB 方策は「不確実なものほど、楽観的に高く見積もる」という考え方に基づく。試行回数が少ない行動は推定値の不確実性が大きいため上乗せ分が大きくなり、選ばれやすくなる。選ばれて試行回数が増えると上乗せ分は小さくなり、推定価値そのもので比べられるようになる。ランダムに選ぶのは ε-greedy 方策である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-53","exam":"g","unit":"g-u3","keyword":"強化学習","type":"choice","syllabus_ref":"3.3","stem":"ビジネスにおける強化学習の応用の説明として、適切なものはどれか。","choices":["空調や設備の制御、倉庫内ロボットの動き方のように、ある行動の結果が次の状況に影響し、長期的な効率や成果が問題になる場面で、試行錯誤を通じて望ましい動き方（方策）を学ばせる応用がある","正解ラベル付きの過去の画像データが大量にある不良品判定に使うことが、代表的な応用である","ラベルのない顧客データを似た者同士のグループに分けることが、代表的な応用である","強化学習はゲームの分野でのみ使われており、現実の業務には応用できない"],"answer":0,"explanation":"強化学習が力を発揮するのは、行動が将来の状況に影響する逐次的な意思決定の場面である。設備制御やロボット制御のほか、推薦や広告配信の最適化などにも応用されている。正解ラベル付きデータからの予測は教師あり学習、ラベルなしデータのグループ分けは教師なし学習の担当であり、強化学習の応用とは中心が異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-54","exam":"g","unit":"g-u3","keyword":"混同行列","type":"choice","syllabus_ref":"3.4","stem":"分類モデルの評価に使う混同行列についての説明として、適切なものはどれか。","choices":["予測したクラスと実際のクラスの組み合わせごとに件数を集計した表であり、真陽性・偽陽性・偽陰性・真陰性の4つの件数が読み取れ、適合率や再現率などの指標はこの表の件数から計算される","モデルのパラメータ同士の相関の強さを表した表である","訓練データとテストデータへの分割比率を決めるための表である","特徴量の重要度を大きい順に並べた表である"],"answer":0,"explanation":"混同行列は、二値分類であれば「実際に陽性／陰性」×「陽性と予測／陰性と予測」の2×2の表に件数を集計したものである。4つのマスが真陽性（TP）・偽陽性（FP）・偽陰性（FN）・真陰性（TN）に対応し、正解率・適合率・再現率・F値はいずれもこの件数の組み合わせで定義される。分類評価の土台になる表である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-55","exam":"g","unit":"g-u3","keyword":"真陽性・真陰性","type":"choice","syllabus_ref":"3.4","stem":"工場で製品の不良品検知モデルを使い、「不良品」を陽性、「正常品」を陰性と判定している。真陰性（TN）に当たるケースはどれか。","choices":["実際に不良品である製品を、不良品と判定した","実際に正常な製品を、正常と判定した","実際に正常な製品を、不良品と判定した","実際に不良品である製品を、正常と判定した"],"answer":1,"explanation":"真陰性は「実際は陰性（正常）で、予測も陰性（正常）」と、正しく陰性と判定できたケースである。実際に不良品を不良品と判定したものは真陽性、正常な製品を不良品と判定したものは偽陽性、不良品を正常と判定したもの（見逃し）は偽陰性に当たる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-56","exam":"g","unit":"g-u3","keyword":"偽陽性・偽陰性","type":"choice","syllabus_ref":"3.4","stem":"分類における偽陽性と偽陰性についての説明として、適切なものはどれか。","choices":["偽陽性は実際は陽性なのに陰性と判定する誤り、偽陰性は実際は陰性なのに陽性と判定する誤りである","偽陽性と偽陰性は、どちらも実際は陽性であるケースでの誤りを指す言葉である","偽陽性は実際は陰性なのに陽性と判定する誤り（統計的仮説検定の第1種の過誤に対応）であり、偽陰性は実際は陽性なのに陰性と判定する誤り（第2種の過誤に対応）である","偽陽性は訓練データでのみ起こり、偽陰性はテストデータでのみ起こる誤りである"],"answer":2,"explanation":"偽陽性（FP）は「実際は陰性なのに陽性と判定する」誤りで、実際には無いものを有ると言ってしまう第1種の過誤に対応する。偽陰性（FN）は「実際は陽性なのに陰性と判定する」誤りで、見逃しに当たる第2種の過誤に対応する。どちらの誤りをより避けたいかは、適用場面によって異なる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-57","exam":"g","unit":"g-u3","keyword":"正解率","type":"choice","syllabus_ref":"3.4","stem":"分類の評価指標「正解率」についての説明として、適切なものはどれか。","choices":["陽性と予測したもののうち、実際に陽性だった割合である","実際に陽性であるもののうち、正しく陽性と予測できた割合である","適合率と再現率の調和平均である","全体の件数のうち、正しく分類できた件数（真陽性と真陰性の合計）が占める割合であり、クラスの割合が大きく偏ったデータでは、多数派のクラスばかりを予測しても高い値になり得るため、評価指標として不十分な場合がある"],"answer":3,"explanation":"正解率は（TP＋TN）／全体 で計算され、分類全体の当たり具合を表す最も基本的な指標である。ただし、例えば陽性が全体の1%しかないデータでは、全て陰性と予測するだけでも正解率は99%になってしまう。このため、クラスが不均衡な場面では、適合率・再現率・F値などを併せて見る必要がある。陽性と予測したもののうち実際に陽性だった割合は適合率、実際に陽性のうち正しく予測できた割合は再現率である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-58","exam":"g","unit":"g-u3","keyword":"正解率","type":"choice","syllabus_ref":"3.4","stem":"ある二値分類モデルを100件のデータで評価したところ、真陽性（TP）が40件、偽陽性（FP）が10件、偽陰性（FN）が20件、真陰性（TN）が30件であった。このモデルの正解率として正しいものはどれか。","choices":["0.70","0.80","0.67","0.30"],"answer":0,"explanation":"正解率は、正しく分類できた件数（TP＋TN）を全体で割って計算する。（40＋30）／100＝0.70 である。0.80 は適合率（TP／（TP＋FP）＝40／50）、0.67 は再現率（TP／（TP＋FN）＝40／60≒0.67）、0.30 は誤り率（（FP＋FN）／100）に当たる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-59","exam":"g","unit":"g-u3","keyword":"ROC 曲線・AUC","type":"choice","syllabus_ref":"3.4","stem":"ROC曲線とAUCについての説明として、適切なものはどれか。","choices":["ROC曲線は学習率を変えながら損失の変化を描いた曲線であり、AUCはその最終値である","ROC曲線は、陽性と判定するしきい値を様々に変えながら、縦軸に真陽性率、横軸に偽陽性率を取って描いた曲線であり、AUCはその曲線の下の面積を表す。AUCが1に近いほど識別性能が高く、0.5はランダムな分類と同程度であることを示す","AUCは正解率そのものであり、選んだしきい値によって値が決まる","ROC曲線は回帰モデルの誤差の分布を描いたものであり、分類には使われない"],"answer":1,"explanation":"ROC曲線は、しきい値を動かしたときの真陽性率（再現率）と偽陽性率（FP／（FP＋TN））の組み合わせをプロットしたもので、特定のしきい値に依存しない形で分類モデルの識別性能を表す。AUC（曲線下面積）は0.5〜1の値を取り、1が完全な識別、0.5がランダムな分類と同程度であることを意味する。正解率とは別の指標である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-60","exam":"g","unit":"g-u3","keyword":"平均二乗誤差 (MSE)","type":"choice","syllabus_ref":"3.4","stem":"回帰モデルの評価に平均二乗誤差（MSE）を使うときの、値の解釈についての説明として、適切なものはどれか。","choices":["MSEが1未満であれば、予測対象やデータによらず、十分に精度の高いモデルだと判断できる","異なるテストデータで測ったMSE同士でも、値の小さい方のモデルが常により優れていると判断できる","同じテストデータ・同じ予測対象で比べる場合に限り、MSEが小さいモデルほど誤差が小さいと判断できる。値そのものに絶対的な良し悪しの基準はなく、データや予測対象の尺度が異なれば、値をそのまま比べることはできない","MSEは予測対象の単位や尺度の影響を受けないため、金額を予測するモデルと気温を予測するモデルのMSEをそのまま比較できる"],"answer":2,"explanation":"MSEの値は、予測対象の尺度やデータのばらつきによって水準が大きく変わる。そのため、MSEによるモデル比較が意味を持つのは、同じテストデータ・同じ予測対象で評価した場合に限られ、その場合でも判断できるのは大小の相対的な関係だけである。「MSEがこれ以下なら良いモデル」といった絶対的な基準は存在せず、別のデータや別の予測対象で測った値と直接比べることもできない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-61","exam":"g","unit":"g-u3","keyword":"二乗平均平方根誤差 (RMSE)","type":"choice","syllabus_ref":"3.4","stem":"二乗平均平方根誤差（RMSE）についての説明として、適切なものはどれか。","choices":["平均絶対値誤差（MAE）の平方根を取ったものである","誤差の絶対値を平均した後に平方根を取ったものである","分類モデルの正解率を誤差の形に換算した指標である","平均二乗誤差（MSE）の平方根であり、二乗によって変わってしまった単位が元に戻るため、誤差の大きさを予測対象と同じ単位で直感的に把握できる"],"answer":3,"explanation":"RMSEはMSEの平方根である。MSEは誤差を二乗して平均するため単位も二乗になってしまうが、平方根を取ることで予測対象（売上金額や気温など）と同じ単位に戻り、「平均的にどれくらい外しているか」を元の量の尺度で読み取れる。MAEとは別の指標であり、MAEの平方根ではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-62","exam":"g","unit":"g-u3","keyword":"平均絶対値誤差 (MAE)","type":"choice","syllabus_ref":"3.4","stem":"ある回帰モデルの4件の予測について、実測値が 5、8、6、9、予測値が 7、5、7、7 であった。平均絶対値誤差（MAE）として正しいものはどれか。","choices":["2.0","4.5","0.5","8"],"answer":0,"explanation":"MAEは誤差の絶対値の平均である。各件の誤差の絶対値は｜5−7｜＝2、｜8−5｜＝3、｜6−7｜＝1、｜9−7｜＝2 で、合計8を4件で割って 2.0 になる。4.5 は二乗して平均したMSE（（4＋9＋1＋4）／4）、0.5 は符号付きの誤差をそのまま平均した値、8 は絶対値の合計（平均していない値）に当たる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-63","exam":"g","unit":"g-u3","keyword":"赤池情報量規準 (AIC)","type":"choice","syllabus_ref":"3.4","stem":"赤池情報量規準（AIC）についての説明として、適切なものはどれか。","choices":["値が大きいモデルほど良いモデルだと判断する規準である","モデルのデータへの当てはまりの良さと、モデルの複雑さのバランスを取るための規準であり、候補モデルの中で値が小さいモデルほど良いと判断する","データを訓練用と検証用に分割せずに正解率を求めるための手法である","パラメータの数が多いモデルを常に優先するための規準である"],"answer":1,"explanation":"AICは、統計モデルの選択に使う情報量規準の一つである。当てはまりの良さだけを追うとパラメータの多い複雑なモデルが選ばれ過学習につながるため、当てはまりの良さから複雑さの分を差し引いて評価し、値が小さいモデルを選ぶ。当てはまりの良さと複雑さのバランスを取る、という発想が情報量規準に共通する考え方である。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-64","exam":"g","unit":"g-u3","keyword":"ベイズ情報量規準 (BIC)","type":"choice","syllabus_ref":"3.4","stem":"ベイズ情報量規準（BIC）についての説明として、適切なものはどれか。","choices":["AICと全く同じ計算式で求められ、名称だけが異なる規準である","分類モデルの混同行列の件数から計算される指標である","モデルの当てはまりの良さと複雑さのバランスを取る規準で、AICと同様に値が小さいモデルほど良いとされるが、複雑さへのペナルティにデータの件数が関わるため、データ件数が多い場合にはAICよりも単純なモデルが選ばれやすい","交差検証の一種であり、データをベイズ推定によって分割する手法である"],"answer":2,"explanation":"BICもAICと同じ情報量規準の仲間で、当てはまりの良さと複雑さのバランスを取り、値が小さいモデルを選ぶ。AICとの違いは複雑さへのペナルティの付け方で、BICではペナルティにデータ件数の対数が関わるため、データが多いほど複雑なモデルへのペナルティが相対的に重くなり、単純なモデルが選ばれやすくなる。検証手法ではなく、モデル選択の規準である。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-65","exam":"g","unit":"g-u3","keyword":"オッカムの剃刀","type":"choice","syllabus_ref":"3.4","stem":"モデル選択における「オッカムの剃刀」の考え方として、適切なものはどれか。","choices":["説明力が同程度であれば、より複雑なモデルを選ぶべきだという考え方である","データに完全に適合するまでパラメータを増やし続けるべきだという考え方である","評価指標の値が最も大きいモデルを、理由を問わず選ぶべきだという考え方である","同程度にデータを説明できるモデルが複数あるなら、不必要な複雑さや仮定はそぎ落とし、より単純なモデルを選ぶべきだという考え方である"],"answer":3,"explanation":"オッカムの剃刀は「同等に説明できるなら、より単純な方を選ぶ」という原則である。モデル選択では、予測性能が同程度なら単純なモデルを選ぶ指針となり、過学習の回避や解釈のしやすさにもつながる。情報量規準（AIC・BIC）が複雑さにペナルティを与える考え方も、この原則と通じている。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-66","exam":"g","unit":"g-u3","keyword":"ホールドアウト検証","type":"choice","syllabus_ref":"3.4","stem":"ホールドアウト検証についての説明として、適切なものはどれか。","choices":["データを訓練用と検証用（テスト用）に分割し、訓練用で学習したモデルを、学習に使っていない検証用で評価する方法であり、分割の仕方によって評価結果が左右され得る","データをk個に分割し、検証用を順に変えながらk回学習と評価を行う方法である","全データを訓練に使い、訓練データ上での誤差の小ささでモデルを評価する方法である","データを人工的に増やして学習を安定させる方法である"],"answer":0,"explanation":"ホールドアウト検証は、データを訓練用と検証用に分けておき、学習に使わなかった検証用データで汎化性能を見積もる、最も単純な検証方法である。手軽な反面、どのデータを検証用に回すかで結果が変わりやすく、データが少ない場合は評価が不安定になりやすい。検証用を順に変えてk回評価するのは交差検証である。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-67","exam":"g","unit":"g-u3","keyword":"汎化性能","type":"choice","syllabus_ref":"3.4","stem":"訓練誤差と汎化誤差についての説明として、適切なものはどれか。","choices":["訓練誤差は未知のデータに対する誤差、汎化誤差は訓練データに対する誤差を指す","訓練誤差は学習に使った訓練データに対する誤差、汎化誤差はまだ見ていない未知のデータに対する誤差を指し、モデルの選択や評価では汎化誤差が小さいこと、すなわち汎化性能が高いことが目標になる","訓練誤差と汎化誤差は、定義上つねに同じ値になる","汎化誤差は、訓練を繰り返して訓練誤差を下げるほど必ず大きくなる"],"answer":1,"explanation":"訓練誤差は手元の訓練データへの当てはまりを表し、汎化誤差は未知のデータへの当てはまりを表す。訓練誤差だけを下げ続けると過学習によって汎化誤差が悪化し得るため、モデル選択では検証用のデータで汎化誤差の見積もりを取り、それが小さいモデルを選ぶ。汎化性能とは、未知のデータに対してうまく働く能力のことである。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-68","exam":"g","unit":"g-u3","keyword":"モデルの選択・評価","type":"choice","syllabus_ref":"3.4","stem":"がん検診を支援するAIモデルを評価する場面を考える。陽性（がんの疑い）の人は全体のごく一部であり、病気の人を見逃すこと（偽陰性）の不利益が特に大きい。この場面での評価の進め方として、最も適切なものはどれか。","choices":["正解率だけを確認すればよい。陽性が少数派でも、正解率が高ければ見逃しは少ないはずである","偽陽性をゼロにすることだけを目標にし、適合率だけを最大化するモデルを選ぶ","見逃しの少なさに直結する再現率を重視して評価し、適合率とのバランスをF値などでも確認しながらモデルを選ぶ","訓練データでの誤差が最も小さいモデルを選ぶ"],"answer":2,"explanation":"陽性がごく一部のデータでは、全て陰性と予測しても正解率は高くなってしまい、見逃しの多さが正解率に表れない。見逃し（偽陰性）を避けたい場面では、実際に陽性の人をどれだけ拾えたかを表す再現率が中心の指標になる。ただし再現率だけを追うと偽陽性が増えて適合率が下がるため、F値などでバランスも確認するのが適切である。訓練誤差の小ささは未知データでの性能を保証しない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g9-01","exam":"g","unit":"g-u9","keyword":"個人情報","type":"choice","syllabus_ref":"9.1","stem":"個人情報保護法における「個人情報」の説明として、正しいものはどれか。","choices":["生存する個人に関する情報であって、氏名や生年月日などにより特定の個人を識別できるもの","死亡した個人に関する情報も含め、あらゆる個人に関する情報","法人が保有する顧客データベース全体を指すもの","本人が公表に同意した情報だけを指すもの"],"answer":0,"explanation":"個人情報は、生存する個人に関する情報で、当該情報に含まれる氏名・生年月日その他の記述等により特定の個人を識別できるもの（他の情報と容易に照合でき、それにより識別できるものを含む）。死者に関する情報は原則として対象にならない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-02","exam":"g","unit":"g-u9","keyword":"個人データ","type":"choice","syllabus_ref":"9.1","stem":"「個人データ」の説明として、正しいものはどれか。","choices":["本人の同意を得て取得した個人情報のこと","匿名加工された個人情報のこと","個人情報データベース等を構成する個人情報のこと","事業者が開示請求に応じる義務のある個人情報のこと"],"answer":2,"explanation":"個人データは、個人情報データベース等（検索できるように体系的に構成された個人情報の集合物）を構成する個人情報のこと。個人情報のうち、データベース化されたものが個人データに当たる。開示請求の対象になるのは、その一部である保有個人データ。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-03","exam":"g","unit":"g-u9","keyword":"保有個人データ","type":"choice","syllabus_ref":"9.1","stem":"「保有個人データ」に関する説明として、正しいものはどれか。","choices":["事業者が保有する全ての個人データのこと","個人データのうち、事業者が開示や訂正、利用停止などを行う権限を持ち、本人が請求できる対象となるもの","国や地方公共団体だけが保有できる個人データのこと","6か月を超えて保存される個人データのこと"],"answer":1,"explanation":"保有個人データは、個人データのうち、事業者が開示・内容の訂正・利用停止等を行うことのできる権限を有するもの。本人は事業者に対し、開示や訂正、利用停止を請求できる。かつてあった「6か月以内に消去するものは除く」という短期保存の除外は、令和2年改正で削除された。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-04","exam":"g","unit":"g-u9","keyword":"要配慮個人情報","type":"choice","syllabus_ref":"9.1","stem":"「要配慮個人情報」に当たるものはどれか。","choices":["氏名と住所","メールアドレス","購買履歴","病歴や犯罪の経歴"],"answer":3,"explanation":"要配慮個人情報は、本人の人種、信条、社会的身分、病歴、犯罪の経歴、犯罪により害を被った事実など、不当な差別や偏見その他の不利益が生じないよう、取扱いに特に配慮を要する情報。原則として、あらかじめ本人の同意がなければ取得できない。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-05","exam":"g","unit":"g-u9","keyword":"個人識別符号","type":"choice","syllabus_ref":"9.1","stem":"「個人識別符号」の説明として、正しいものはどれか。","choices":["指紋や顔の特徴を変換したデータ、旅券番号や運転免許証番号など、それ自体で特定の個人を識別できる符号","個人を識別するために事業者が独自に付ける会員番号のこと","パスワードや暗証番号のこと","法人に割り当てられる法人番号のこと"],"answer":0,"explanation":"個人識別符号は、身体の一部の特徴を電子計算機での処理用に変換した符号（指紋データ、顔認証データなど）と、旅券番号・運転免許証番号・基礎年金番号などの公的な番号で、政令で定められている。それ自体が個人情報に当たる。事業者が独自に付ける会員番号は、個人識別符号そのものではない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-06","exam":"g","unit":"g-u9","keyword":"仮名加工情報","type":"choice","syllabus_ref":"9.1","stem":"「仮名加工情報」の説明として、正しいものはどれか。","choices":["特定の個人を識別できないよう加工し、復元も不可能にした情報で、第三者提供が自由にできる","加工前の個人情報と自由に照合してよい情報","他の情報と照合しない限り特定の個人を識別できないよう加工した情報で、内部の分析などに使えるが、第三者への提供は原則としてできない","本人の同意があれば加工せずに提供できる情報"],"answer":2,"explanation":"仮名加工情報は、他の情報と照合しない限り特定の個人を識別できないように個人情報を加工して得られる情報。利用目的の変更の制限が緩和され、内部分析などに使いやすい一方、識別のために他の情報と照合することは禁止され、第三者提供も原則としてできない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-07","exam":"g","unit":"g-u9","keyword":"匿名加工情報","type":"choice","syllabus_ref":"9.1","stem":"「匿名加工情報」の説明として、正しいものはどれか。","choices":["氏名だけを削除すれば、他の項目が残っていても匿名加工情報になる","特定の個人を識別できないように加工し、加工前の個人情報を復元できないようにした情報","本人の同意がなければ作成できない情報","作成した事業者だけが永久に保有しなければならない情報"],"answer":1,"explanation":"匿名加工情報は、個人情報の区分に応じて定められた措置を講じて、特定の個人を識別することができず、元の個人情報を復元することもできないようにしたもの。本人の同意なく作成・第三者提供ができる代わりに、作成時に加工した情報の項目を公表するなどの義務がある。氏名だけの削除では足りない。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-08","exam":"g","unit":"g-u9","keyword":"仮名加工情報・匿名加工情報","type":"choice","syllabus_ref":"9.1","stem":"仮名加工情報と匿名加工情報の違いとして、正しいものはどれか。","choices":["仮名加工情報は第三者提供できるが、匿名加工情報はできない","匿名加工情報は他の情報と照合すれば個人を識別できる","仮名加工情報は復元できないが、匿名加工情報は復元できる","匿名加工情報は復元できない水準まで加工され第三者提供ができるが、仮名加工情報は照合しない限り識別できない水準の加工で、第三者提供は原則できない"],"answer":3,"explanation":"違いは加工の水準と提供の可否。匿名加工情報は、識別も復元もできない水準まで加工する代わりに第三者提供ができる。仮名加工情報は、削除した情報等と照合すれば識別し得る水準の加工で、照合自体が禁止され、第三者提供も原則として認められない。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-09","exam":"g","unit":"g-u9","keyword":"第三者提供","type":"choice","syllabus_ref":"9.1","stem":"個人情報取扱事業者が個人データを第三者に提供する場合の原則として、正しいものはどれか。","choices":["あらかじめ本人の同意を得なければならない","提供した後に本人へ通知すればよい","利用目的の範囲内の提供であれば同意は不要である","提供先が法人であれば同意は不要である"],"answer":0,"explanation":"個人データの第三者提供は、原則としてあらかじめ本人の同意が必要。法令に基づく場合や、人の生命・身体・財産の保護のために必要で本人の同意を得ることが困難な場合などは例外になる。なお、委託や事業の承継、共同利用に伴う提供は「第三者」への提供に当たらない扱いがある。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-10","exam":"g","unit":"g-u9","keyword":"委託","type":"choice","syllabus_ref":"9.1","stem":"個人データの取扱いを外部の事業者に委託する場合について、正しいものはどれか。","choices":["委託先への提供も第三者提供に当たり、常に本人の同意が必要である","利用目的の達成に必要な範囲で委託する場合は第三者提供に当たらず、委託先に対する監督が求められる","委託先は個人情報保護法の規制を受けない","委託契約を結べば、委託先の管理は不要になる"],"answer":1,"explanation":"委託に伴う個人データの提供は、「第三者」への提供に当たらないため、本人の同意は不要。その代わり、委託元には委託先に対する必要かつ適切な監督（契約の締結や安全管理措置の確認など）が求められる。委託先自身も、委託の範囲で法の規制を受ける。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-11","exam":"g","unit":"g-u9","keyword":"利用目的","type":"choice","syllabus_ref":"9.1","stem":"個人情報の「利用目的」に関するルールとして、正しいものはどれか。","choices":["利用目的は社内だけで決めればよく、本人に知らせる必要はない","利用目的は後から自由に変更できる","利用目的をできる限り特定し、取得に際して本人へ通知または公表しなければならない","利用目的を超えて利用する場合でも、事後に通知すれば足りる"],"answer":2,"explanation":"事業者は利用目的をできる限り特定しなければならず、個人情報を取得する際は、あらかじめ利用目的を公表するか、取得後速やかに本人へ通知・公表する。利用目的の変更は変更前の目的と関連性のある範囲に限られ、利用目的を超えた利用には、原則としてあらかじめ本人の同意が必要。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g9-12","exam":"g","unit":"g-u9","keyword":"GDPR","type":"choice","syllabus_ref":"9.1","stem":"GDPR（EU一般データ保護規則）に関する説明として、正しいものはどれか。","choices":["EU域内に拠点がある企業だけに適用される規則である","日本の個人情報保護法とは無関係で、日本企業には一切適用されない","違反しても制裁金は科されない、努力目標の規則である","EU域内の個人に商品やサービスを提供する場合などは日本の事業者にも適用されることがあり、日本はEUから十分性認定を受けている"],"answer":3,"explanation":"GDPRには域外適用があり、EU域内のデータ主体（個人）に商品・サービスを提供したり、その行動を監視したりする域外の事業者も対象になり得る。日本は2019年にEUから十分性認定を受け、相互に円滑な個人データの移転が認められている。違反には高額な制裁金が科され得る。","difficulty":3,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目9「AIに関する法律と契約」中項目38「個人情報保護法」"},{"id":"g1-01","exam":"g","unit":"g-u1","keyword":"強いAI・弱いAI","type":"choice","syllabus_ref":"1.2","stem":"「強いAI」の説明として、最も適切なものはどれか。","choices":["特定の課題に特化して処理するAI","人間のように意識や理解を持つAIを目指す考え方","大量のデータを高速に処理するAI","ルールベースで動作するAI"],"answer":1,"explanation":"強いAIは、人間と同等の知能や意識・理解の実現を目指す考え方。現在の実用AIはいずれも、特定課題に特化した弱いAIに分類される。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-02","exam":"g","unit":"g-u1","keyword":"チューリングテスト","type":"choice","syllabus_ref":"1.2","stem":"チューリングテストの説明として、正しいものはどれか。","choices":["機械の計算速度を人間と比較するテスト","判定者が機械と人間を見分けられなければ、機械に知能があるとするテスト","AIが資格試験に合格できるかを測るテスト","ロボットの運動性能を測るテスト"],"answer":1,"explanation":"アラン・チューリングが提案した「模倣ゲーム」。テキストの応答だけで判定者が機械を見分けられなければ、その機械は知的であるとする考え方。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-03","exam":"g","unit":"g-u1","keyword":"フレーム問題","type":"choice","syllabus_ref":"1.2","stem":"フレーム問題が指す困難はどれか。","choices":["画像のフレームレートが不足する問題","状況が変化したとき、関係する事柄だけを切り出して扱うことの難しさ","学習データの量が多すぎる問題","計算資源が不足する問題"],"answer":1,"explanation":"行動のたびに「何が変わり、何が変わらないか」を全て列挙することはできない。関係することだけを有限の手続きで切り出す難しさがフレーム問題。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-04","exam":"g","unit":"g-u1","keyword":"記号接地問題","type":"choice","syllabus_ref":"1.2","stem":"記号接地問題（シンボルグラウンディング問題）の説明として、正しいものはどれか。","choices":["記号の数が不足して表現できない問題","記号そのものと、実世界の対象や意味をどう結びつけるかという問題","暗号化した記号を復号できない問題","記号の入力が遅いという問題"],"answer":1,"explanation":"コンピュータが扱う記号は、実世界の意味と結びついて初めて「理解」につながる。記号と意味の対応づけの難しさを指す。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-05","exam":"g","unit":"g-u1","keyword":"中国語の部屋","type":"choice","syllabus_ref":"1.2","stem":"「中国語の部屋」（サールの思考実験）が批判の対象とした考え方はどれか。","choices":["機械は計算が遅いので知能を持てない","記号の操作規則に従うだけでは、意味の理解は生まれない","AIには身体が必要である","学習データは人間が作るべきである"],"answer":1,"explanation":"中国語を理解しない人が規則書どおりに記号を操作して正しく応答できても、中国語を「理解」したことにはならない、という思考実験。強いAIへの批判として知られる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-06","exam":"g","unit":"g-u2","keyword":"エキスパートシステム","type":"choice","syllabus_ref":"2.2","stem":"エキスパートシステムの説明として、正しいものはどれか。","choices":["専門家の知識をルールとして蓄え、推論によって問題を解く初期のAIシステム","大量のデータから自動で学習するシステム","人間の脳を模した回路の総称","強化学習でゲームを解くシステム"],"answer":0,"explanation":"1970年代に実用化された古典的AIの代表。感染症診断のMYCINや化学構造解析のDENDRALが知られる。知識の獲得が手作業である点が限界となった。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g1-07","exam":"g","unit":"g-u1","keyword":"人工知能のレベル","type":"choice","syllabus_ref":"1.1","stem":"シラバスが示す人工知能のレベルの分類で、レベル3に当たるものはどれか。","choices":["単純な制御プログラム","古典的な人工知能（探索・推論など）","機械学習を用いるもの","深層学習を用いるもの"],"answer":2,"explanation":"レベル1＝単純な制御、レベル2＝古典的AI、レベル3＝機械学習、レベル4＝深層学習、という段階的な整理がシラバスの見方。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目1「人工知能の定義」"},{"id":"g1-08","exam":"g","unit":"g-u1","keyword":"トイプロブレム","type":"choice","syllabus_ref":"1.2","stem":"トイプロブレム（おもちゃの問題）への批判として、正しいものはどれか。","choices":["問題が難しすぎて誰も解けない","現実を単純化しすぎた課題で解けても、実世界の問題には通用しない","計算量が小さすぎて測定できない","ルールが公開されていない"],"answer":1,"explanation":"パズルのような限定された課題設定では解法が成立しても、現実の複雑な問題にはそのまま適用できない、という古典的AIへの批判。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-09","exam":"g","unit":"g-u2","keyword":"オントロジー","type":"choice","syllabus_ref":"2.2","stem":"知識表現におけるオントロジーの説明として、正しいものはどれか。","choices":["データを圧縮する手法","対象領域の概念とその関係を体系的に記述した枠組み","ニューラルネットワークの層の名前","学習率の調整方法"],"answer":1,"explanation":"オントロジーは、概念や用語の意味と関係を共有可能な形で記述したもの。知識表現やセマンティックWebの基盤になった。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目2「人工知能をめぐる動向」中項目4「知識表現とエキスパートシステム」"},{"id":"g1-10","exam":"g","unit":"g-u1","keyword":"身体性","type":"choice","syllabus_ref":"1.2","stem":"人工知能をめぐる「身体性」の論点として、正しいものはどれか。","choices":["AIには必ず人型の外見が必要である","知能は、身体を通じた環境との相互作用と切り離せないのではないかという論点","計算は身体のある場所でしか行えない","ロボットは人間より速く動けるべきだという論点"],"answer":1,"explanation":"記号操作だけの知能観への批判の一つ。環境との相互作用を通じて意味や概念が形づくられる、という見方につながる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g1-11","exam":"g","unit":"g-u1","keyword":"人工知能の定義","type":"choice","syllabus_ref":"1.1","stem":"シラバスにおける人工知能の定義の扱いとして、正しいものはどれか。","choices":["国際規格で唯一の定義が定められている","定まった定義はなく、研究者によって解釈が異なる","法律で定義が定められている","計算機学会が毎年定義を改訂している"],"answer":1,"explanation":"人工知能に確立した唯一の定義はない、というのがシラバスの出発点。実現方法や対象によって複数の捉え方がある。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目1「人工知能の定義」"},{"id":"g1-12","exam":"g","unit":"g-u1","keyword":"弱いAI","type":"choice","syllabus_ref":"1.2","stem":"現在の画像認識や音声認識などの実用AIは、強いAI・弱いAIの区分ではどちらに当たるか。","choices":["強いAI","弱いAI","どちらにも当たらない","中間のAIという正式な区分がある"],"answer":1,"explanation":"現在の実用AIは、特定の課題に特化し、人間のような汎用の理解や意識を持たないため、弱いAIに分類される。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目1「人工知能とは」中項目2「人工知能分野で議論される問題」"},{"id":"g3-01","exam":"g","unit":"g-u3","keyword":"教師あり学習","type":"choice","syllabus_ref":"3.1","stem":"教師あり学習の説明として、正しいものはどれか。","choices":["正解ラベルのないデータから構造を見つける学習","入力と正解（ラベル）の組から、予測の仕方を学ぶ学習","報酬をもとに試行錯誤で学ぶ学習","データの次元を減らす処理"],"answer":1,"explanation":"教師あり学習は、入力と正解ラベルのペアから学ぶ。代表的なタスクは分類と回帰。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-02","exam":"g","unit":"g-u3","keyword":"クラスタリング","type":"choice","syllabus_ref":"3.2","stem":"クラスタリングは、どの学習の枠組みに分類されるか。","choices":["教師あり学習","教師なし学習","強化学習","転移学習"],"answer":1,"explanation":"クラスタリングはラベルなしデータのグループ分けで、教師なし学習の代表例。k-means法などが知られる。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"},{"id":"g3-03","exam":"g","unit":"g-u3","keyword":"強化学習","type":"choice","syllabus_ref":"3.3","stem":"強化学習の説明として、正しいものはどれか。","choices":["正解データを丸暗記する学習","エージェントが環境と相互作用し、得られる報酬が大きくなる行動を学ぶ学習","人間が全ての手順をプログラムする手法","データを圧縮して保存する手法"],"answer":1,"explanation":"強化学習では、エージェントが行動→環境の変化→報酬のフィードバックを繰り返し、累積報酬が最大になる方策を学ぶ。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目9「強化学習」"},{"id":"g3-04","exam":"g","unit":"g-u3","keyword":"過学習","type":"choice","syllabus_ref":"3.4","stem":"過学習（オーバーフィッティング）の説明として、正しいものはどれか。","choices":["学習が途中で止まってしまうこと","訓練データに適合しすぎて、未知のデータに対する精度が下がること","データ量が多すぎて保存できないこと","学習率が大きすぎて発散すること"],"answer":1,"explanation":"モデルが訓練データの細部やノイズまで覚え込むと、汎化性能が落ちる。これが過学習。","difficulty":1,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-05","exam":"g","unit":"g-u3","keyword":"過学習の対策","type":"choice","syllabus_ref":"3.4","stem":"過学習への対策として、適切でないものはどれか。","choices":["正則化を入れる","学習データを増やす・データ拡張を行う","交差検証で汎化性能を測る","訓練データでの精度だけを見て、モデルの複雑さを上げ続ける"],"answer":3,"explanation":"訓練精度だけを追って複雑さを上げると過学習が進む。正則化、データの増加、検証による確認が代表的な対策。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-06","exam":"g","unit":"g-u3","keyword":"適合率","type":"choice","syllabus_ref":"3.4","stem":"分類の評価指標「適合率（Precision）」の定義はどれか。","choices":["実際の陽性のうち、正しく陽性と予測できた割合","陽性と予測したもののうち、実際に陽性だった割合","全体のうち正解した割合","陽性と陰性を取り違えた割合"],"answer":1,"explanation":"適合率＝TP／(TP＋FP)。「陽性と言ったものがどれだけ当たっていたか」を表す。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-07","exam":"g","unit":"g-u3","keyword":"再現率","type":"choice","syllabus_ref":"3.4","stem":"「再現率（Recall）」の定義はどれか。","choices":["陽性と予測したもののうち、実際に陽性だった割合","全体のうち正解した割合","実際に陽性であるもののうち、正しく陽性と予測できた割合","陰性と予測したもののうち、実際に陰性だった割合"],"answer":2,"explanation":"再現率＝TP／(TP＋FN)。「本当の陽性をどれだけ取りこぼさなかったか」を表す。見逃しが問題になる場面で重視される。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-08","exam":"g","unit":"g-u3","keyword":"F値","type":"choice","syllabus_ref":"3.4","stem":"F値（F1スコア）の説明として、正しいものはどれか。","choices":["適合率と再現率の算術平均","適合率と再現率の調和平均","正解率と再現率の積","誤り率の逆数"],"answer":1,"explanation":"F値は適合率と再現率の調和平均。どちらか一方が低いとF値も低くなるため、両者のバランスを見る指標として使われる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-09","exam":"g","unit":"g-u3","keyword":"交差検証","type":"choice","syllabus_ref":"3.4","stem":"k分割交差検証の説明として、正しいものはどれか。","choices":["データをk個に分割し、1つを検証用に回しながらk回学習と評価を行う","k種類のモデルを同時に学習する","データをk倍に増やす","学習をk回やり直して最後の結果だけを使う"],"answer":0,"explanation":"データをk分割し、検証用を順に変えてk回評価することで、データの偏りに左右されにくい汎化性能の見積もりが得られる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目10「モデルの選択・評価」"},{"id":"g3-10","exam":"g","unit":"g-u3","keyword":"ランダムフォレスト","type":"choice","syllabus_ref":"3.1","stem":"ランダムフォレストの説明として、正しいものはどれか。","choices":["1本の深い決定木を高速化した手法","データと特徴量をランダムに選んで多数の決定木を作り、投票で決めるアンサンブル手法","木構造のデータを検索する手法","強化学習の一種"],"answer":1,"explanation":"ランダムフォレストはバギングの応用。複数の決定木の多数決で、過学習を抑えつつ精度を上げる。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-11","exam":"g","unit":"g-u3","keyword":"ブースティング","type":"choice","syllabus_ref":"3.1","stem":"ブースティングの特徴として、正しいものはどれか。","choices":["弱い学習器を並列に作って平均する","前の学習器が間違えたデータを重視しながら、弱い学習器を逐次追加していく","データを圧縮してから学習する","ラベルなしデータだけで学習する"],"answer":1,"explanation":"ブースティング（AdaBoost、勾配ブースティング等）は、誤りに重みを移しながら学習器を順に追加するアンサンブル手法。並列に作るバギングと対比される。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目7「教師あり学習」"},{"id":"g3-12","exam":"g","unit":"g-u3","keyword":"次元削減","type":"choice","syllabus_ref":"3.2","stem":"次元削減の手法として、正しいものはどれか。","choices":["主成分分析（PCA）","決定木","k近傍法","サポートベクターマシン"],"answer":0,"explanation":"主成分分析は、情報の損失を抑えながらデータの特徴量の数を減らす代表的な次元削減手法。決定木・k近傍法・SVMは分類等の手法。","difficulty":2,"origin":"original","source_ref":"JDLA G検定シラバス 第1.4版（2026-05-11）大項目3「機械学習の概要」中項目8「教師なし学習」"}];
